// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { EnumerableMapLib } from "@solady/utils/EnumerableMapLib.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IAccount } from "./interfaces/IAccount.sol";
import { IBrokerManager } from "./interfaces/IBrokerManager.sol";
import { ICollectFee } from "./interfaces/ICollectFee.sol";
import { IEmiter } from "./interfaces/IEmiter.sol";
import { IKeeperRegistry } from "./interfaces/IKeeperRegistry.sol";
import { IOrderManager } from "./interfaces/IOrderManager.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IPositionManager } from "./interfaces/IPositionManager.sol";
import { IRiskController } from "./interfaces/IRiskController.sol";
import { ITradingRouter } from "./interfaces/ITradingRouter.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { OrderBook, LibOrderMetadata } from "./libraries/OrderBook.sol";
import { LibPoolMetadata } from "./libraries/Pool.sol";
import { LibPositionMetadata } from "./libraries/Position.sol";
import { RiskHelper } from "./manager/risk-control/RiskHelper.sol";
import { BaseContractUpgradeable } from "./misc/base/BaseContractUpgradeable.sol";
import {
    Errors,
    OrderMetadata,
    OrderTPSLData,
    PoolMetadata,
    PositionMetadata,
    PositionKey,
    OrderId,
    OrderTypes,
    PoolId,
    PositionId,
    OrderType,
    Operation,
    TriggerType,
    TimeInForce,
    Direction,
    Constants
} from "./types/Types.sol";
import { TradeUtils } from "./utils/TradeUtils.sol";

/// @title OrderManager
/// @notice Manages order creation, modification, and execution
contract OrderManager is BaseContractUpgradeable, IOrderManager {
    using SafeERC20 for IERC20;
    using OrderBook for OrderBook.Data;
    using SafeCast for uint256;
    using LibOrderMetadata for OrderMetadata;
    using LibPoolMetadata for PoolMetadata;
    using LibPositionMetadata for PositionMetadata;
    using EnumerableMapLib for EnumerableMapLib.AddressToUint256Map;
    using EnumerableSetLib for EnumerableSetLib.Uint256Set;

    /// @notice Order book
    OrderBook.Data private _orderBook;
    /// @notice Mapping of position ID to active order IDs
    mapping(PositionId positionId => EnumerableSetLib.Uint256Set orderIds) private activeOrdersOfPosition;

    error InsufficientCollateral(uint256 required, uint256 available);
    error ExceedOrderSize(uint256 size);

    modifier ensureOrderExecutors() {
        _ensureOrderExecutors();
        _;
    }

    modifier ensureOrderExists(OrderId orderId) {
        _ensureOrderExists(orderId);
        _;
    }

    modifier onlyBroker() {
        _onlyBroker();
        _;
    }

    modifier onlyTradingRouter() {
        _onlyTradingRouter();
        _;
    }

    modifier onlyPoolConfigurator() {
        _onlyPoolConfigurator();
        _;
    }

    modifier onlyMatcher() {
        _onlyMatcher();
        _;
    }

    modifier onlyPositionManager() {
        _onlyPositionManager();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) external initializer {
        bytes32[] memory dependencies = new bytes32[](11);
        dependencies[0] = Identifier.POOL_MANAGER;
        dependencies[1] = Identifier.POSITION_MANAGER;
        dependencies[2] = Identifier.EMITER;
        dependencies[3] = Identifier.BROKER_MANAGER;
        dependencies[4] = Identifier.MATCHER;
        dependencies[5] = Identifier.RISK_CONTROLLER;
        dependencies[6] = Identifier.POOL_CONFIGURATOR;
        dependencies[7] = Identifier.EXECUTOR;
        dependencies[8] = Identifier.ACCOUNT;
        dependencies[9] = Identifier.TRADING_ROUTER;
        dependencies[10] = Identifier.KEEPER_REGISTRY;
        __BaseContractUpgradeable_init(addressManager, dependencies);
    }

    /// @inheritdoc IOrderManager
    function placeOrderWithSalt(
        uint64 userPositionSalt,
        OrderTypes.PlaceOrderParams calldata params
    ) external override onlyTradingRouter returns (OrderId orderId) {
        IPositionManager positionManager = _getPositionManager();
        PositionId positionId = PositionKey({ poolId: params.poolId, user: params.user, direction: params.direction, salt: userPositionSalt }).toId();
        orderId = _placeOrder(positionManager, params, positionId);
    }

    /// @inheritdoc IOrderManager
    function placeOrderWithPosition(
        PositionId positionId,
        OrderTypes.PlaceOrderParams calldata params
    ) external override onlyTradingRouter returns (OrderId orderId) {
        IPositionManager positionManager = _getPositionManager();
        require(positionManager.isPositionExists(positionId), Errors.InvalidParameter());
        orderId = _placeOrder(positionManager, params, positionId);
    }

    /// @inheritdoc IOrderManager
    function cancelOrder(OrderId orderId) external override onlyTradingRouter ensureOrderExists(orderId) {
        OrderMetadata memory order = _orderBook.getOrder(orderId);
        _cancelOrder(order, orderId, "USER CANCELLED");
    }

    /// @inheritdoc IOrderManager
    function cancelOrders(OrderId[] calldata orderIds) external override onlyTradingRouter {
        for (uint256 i = 0; i < orderIds.length; ++i) {
            _ensureOrderExists(orderIds[i]);

            OrderMetadata memory order = _orderBook.getOrder(orderIds[i]);
            _cancelOrder(order, orderIds[i], "USER CANCELLED");
        }
    }

    /// @inheritdoc IOrderManager
    function updateOrder(OrderTypes.UpdateOrderParams calldata params) external override onlyTradingRouter ensureOrderExists(params.orderId) {
        OrderMetadata storage order = _orderBook.loadOrder(params.orderId);

        _validateUpdateOrder(params, order.operation, order.direction, order.filledSize);
        _resolveAndCollectForwarderFee(order, order.positionId, order.poolId);

        order.updateMetadata(params.size, params.price);
        if (params.tpsl.tpSize > 0 || params.tpsl.slSize > 0) _updateOrderTPSL(order, params.orderId, params.tpsl);
        if (order.broker != params.broker) order.updateOrderBroker(params.broker);

        _getEmiter().emitOrderUpdated(
            IEmiter.OrderUpdatedParams({
                broker: order.broker,
                user: order.user,
                poolId: order.poolId,
                orderId: params.orderId,
                size: params.size,
                price: params.price,
                tpSize: params.tpsl.tpSize,
                tpPrice: params.tpsl.tpPrice,
                slSize: params.tpsl.slSize,
                slPrice: params.tpsl.slPrice
            })
        );
    }

    /// @inheritdoc IOrderManager
    function fillOrder(
        FillOrderParams calldata params
    ) external override onlyMatcher ensureOrderExists(params.orderId) returns (OrderId tpOrderId, OrderId slOrderId) {
        IEmiter emiter = _getEmiter();
        OrderMetadata memory order = _orderBook.getOrder(params.orderId);
        bool isFirstFill = order.filledSize == 0;

        order.filledSize = _orderBook.fillOrder(params.orderId, params.fillSize);
        if (isFirstFill && order.operation == Operation.Increase) {
            OrderTPSLData memory tpsl = _orderBook.getOrderTPSL(params.orderId);
            _orderBook.removeOrderTPSL(params.orderId);

            if (tpsl.tpSize > 0) {
                tpOrderId = _createStopOrder(emiter, order, params.positionId, true, tpsl.tpSize, tpsl.tpPrice);
            }
            if (tpsl.slSize > 0) {
                slOrderId = _createStopOrder(emiter, order, params.positionId, false, tpsl.slSize, tpsl.slPrice);
            }
        }

        if (order.size == order.filledSize || params.forceClose) {
            _removeOrder(params.orderId, params.positionId);
        }

        _getRiskController().recordLiquidityLock(
            order.poolId,
            params.fillPrice,
            RiskHelper.calculateOrderOpenInterest(order.operation, order.direction, params.fillSize, params.fillPrice)
        );

        emiter.emitOrderFilled(
            IEmiter.OrderFilledParams({
                broker: order.broker,
                user: order.user,
                poolId: order.poolId,
                positionId: params.positionId,
                orderId: params.orderId,
                orderType: order.orderType,
                orderSize: order.size,
                fillSize: params.fillSize,
                filledSize: order.filledSize,
                orderPrice: order.price,
                fillPrice: params.fillPrice,
                realizedPnl: params.realizedPnl,
                tradingFee: params.tradingFee,
                fundingFee: params.fundingFee,
                keeper: params.keeper
            })
        );
    }

    /// @inheritdoc IOrderManager
    function completeOrder(OrderId orderId, PositionId positionId) external override onlyMatcher ensureOrderExists(orderId) {
        _removeOrder(orderId, positionId);
    }

    /// @inheritdoc IOrderManager
    function uncompleteOrder(OrderId orderId, string calldata remark) external override ensureOrderExecutors ensureOrderExists(orderId) {
        _uncompleteOrder(orderId, remark);
    }

    /// @inheritdoc IOrderManager
    function uncompleteOrders(uint256[] calldata orderIds, string calldata remark) external override ensureOrderExecutors {
        for (uint256 i = 0; i < orderIds.length; ++i) {
            OrderId orderId = OrderId.wrap(orderIds[i]);
            _ensureOrderExists(orderId);
            _uncompleteOrder(orderId, remark);
        }
    }

    /// @inheritdoc IOrderManager
    function removePositionOrders(PositionId positionId) external override onlyPositionManager {
        uint256[] memory orderIds = activeOrdersOfPosition[positionId].values();
        for (uint256 i = 0; i < orderIds.length; ++i) {
            _uncompleteOrder(OrderId.wrap(orderIds[i]), "Position closed");
        }
        delete activeOrdersOfPosition[positionId];
    }

    /// @inheritdoc IOrderManager
    function saveAutoDecreaseOrder(
        address user,
        PoolId poolId,
        PositionId positionId,
        uint256 size,
        uint256 price,
        Direction direction
    ) external override onlyMatcher returns (OrderId orderId) {
        address broker = _getPositionManager().getPositionBroker(positionId);
        OrderMetadata memory order = OrderMetadata({
            user: user,
            poolId: poolId,
            positionId: positionId,
            collateralAmount: 0,
            size: size,
            price: price,
            filledSize: 0,
            orderType: OrderType.Market,
            triggerType: TriggerType.None,
            operation: Operation.Decrease,
            direction: direction,
            timeInForce: TimeInForce.IOC,
            slippagePct: 0,
            postOnly: false,
            createdAt: uint64(block.timestamp),
            broker: broker
        });

        orderId = _saveOrder(_getEmiter(), order, 0);
    }

    /// @inheritdoc IOrderManager
    function getOrder(OrderId orderId) external view override returns (OrderMetadata memory) {
        return _orderBook.getOrder(orderId);
    }

    /// @inheritdoc IOrderManager
    function getOrderWithTPSL(OrderId orderId) external view override returns (OrderMetadata memory, OrderTPSLData memory) {
        return _orderBook.getOrderWithTPSL(orderId);
    }

    /// @inheritdoc IOrderManager
    function getOrderTPSL(OrderId orderId) external view override returns (OrderTPSLData memory) {
        return _orderBook.getOrderTPSL(orderId);
    }

    /// @inheritdoc IOrderManager
    function isOrderOwner(OrderId orderId, address user) external view override returns (bool) {
        return _orderBook.getOrder(orderId).isOrderOwner(user);
    }

    /// @inheritdoc IOrderManager
    function isAllOrderOwner(OrderId[] calldata orderIds, address user) external view override returns (bool) {
        for (uint256 i = 0; i < orderIds.length; ++i) {
            if (!_orderBook.getOrder(orderIds[i]).isOrderOwner(user)) return false;
        }
        return true;
    }

    function _placeOrder(
        IPositionManager positionManager,
        OrderTypes.PlaceOrderParams calldata params,
        PositionId positionId
    ) internal returns (OrderId orderId) {
        if (params.orderType == OrderType.Conditional) revert Errors.InvalidParameter();

        IPoolManager poolManager = _getPoolManager();
        PoolMetadata memory pool = poolManager.getPool(params.poolId);
        PositionMetadata memory position = _validateOrder(positionManager, params, pool, positionId);

        IEmiter emiter = _getEmiter();
        OrderMetadata memory order = OrderMetadata({
            user: params.user,
            poolId: params.poolId,
            positionId: positionId,
            collateralAmount: params.collateralAmount,
            size: params.size,
            price: params.price,
            filledSize: 0,
            orderType: params.orderType,
            triggerType: params.triggerType,
            operation: params.operation,
            direction: params.direction,
            timeInForce: params.timeInForce,
            slippagePct: params.slippagePct,
            postOnly: params.postOnly,
            createdAt: uint64(block.timestamp),
            broker: params.broker
        });
        orderId = _saveOrder(emiter, order, params.leverage);

        _collectForwardFee(order, position, pool.quoteToken, pool.tradingVault);
        if (params.collateralAmount > 0) _getAccount().reserveForOrder(params.poolId, orderId, params.user, pool.quoteToken, params.collateralAmount);

        if (params.tpSize > 0 || params.slSize > 0) {
            OrderTPSLData memory tpsl;
            if (params.tpSize > 0) {
                tpsl.tpSize = params.tpSize;
                tpsl.tpPrice = params.tpPrice;
            }
            if (params.slSize > 0) {
                tpsl.slSize = params.slSize;
                tpsl.slPrice = params.slPrice;
            }
            _orderBook.setOrderTPSL(orderId, tpsl);

            emiter.emitOrderUpdated(
                IEmiter.OrderUpdatedParams({
                    broker: params.broker,
                    user: params.user,
                    poolId: params.poolId,
                    orderId: orderId,
                    size: params.size,
                    price: params.price,
                    tpSize: params.tpSize,
                    tpPrice: params.tpPrice,
                    slSize: params.slSize,
                    slPrice: params.slPrice
                })
            );
        }
    }

    /// @notice Uncomplete an order
    /// @param orderId Order ID to uncomplete
    /// @param remark Uncompletion reason
    function _uncompleteOrder(OrderId orderId, string memory remark) internal {
        OrderMetadata memory order = _orderBook.getOrder(orderId);
        _cancelOrder(order, orderId, remark);
    }

    /// @notice Cancel an order and refund collateral
    /// @param order Order metadata
    /// @param orderId Order ID to cancel
    /// @param remark Cancellation reason
    function _cancelOrder(OrderMetadata memory order, OrderId orderId, string memory remark) internal {
        _resolveAndCollectForwarderFee(order, order.positionId, order.poolId);

        // remove order from order book
        _removeOrder(orderId, order.positionId);
        if (order.collateralAmount > 0) _getAccount().releaseForCancelOrder(order.poolId, orderId, order.user, order.collateralAmount);

        _getEmiter().emitOrderCancelled(
            IEmiter.OrderCancelledParams({ broker: order.broker, user: order.user, poolId: order.poolId, orderId: orderId, remark: remark })
        );
    }

    /// @notice Create a take profit or stop loss order
    /// @return orderId Created order ID
    function _createStopOrder(
        IEmiter emiter,
        OrderMetadata memory order,
        PositionId positionId,
        bool isTakeProfit,
        uint256 size,
        uint256 price
    ) internal returns (OrderId orderId) {
        orderId = _saveOrder(
            emiter,
            OrderMetadata({
                user: order.user,
                poolId: order.poolId,
                positionId: positionId,
                collateralAmount: 0,
                size: size,
                price: price,
                filledSize: 0,
                orderType: OrderType.Stop,
                triggerType: TradeUtils.getTPSLTriggerType(order.direction, isTakeProfit),
                operation: Operation.Decrease,
                direction: order.direction,
                timeInForce: TimeInForce.IOC,
                slippagePct: order.slippagePct,
                postOnly: false,
                createdAt: uint64(block.timestamp),
                broker: order.broker
            }),
            0
        );
    }

    /// @notice Save an order to the order book and emit events
    /// @param order Order metadata to save
    /// @param leverage User leverage for the order
    /// @return orderId Generated order ID
    function _saveOrder(IEmiter emiter, OrderMetadata memory order, uint16 leverage) internal returns (OrderId orderId) {
        orderId = _orderBook.addOrder(order);
        _addOrderToPosition(order.positionId, orderId);
        emiter.emitOrderPlaced(
            IEmiter.OrderPlacedParams({
                broker: order.broker,
                user: order.user,
                poolId: order.poolId,
                positionId: order.positionId,
                orderId: orderId,
                orderType: order.orderType,
                operation: order.operation,
                direction: order.direction,
                triggerType: order.triggerType,
                collateralAmount: order.collateralAmount,
                size: order.size,
                price: order.price,
                tif: order.timeInForce,
                postOnly: order.postOnly,
                slippagePct: order.slippagePct,
                userLeverage: leverage
            })
        );
    }

    /// @notice Update an order's take profit or stop loss data
    function _updateOrderTPSL(OrderMetadata memory order, OrderId orderId, OrderTypes.UpdateOrderTPSLParams memory params) internal {
        require(params.tpSize <= order.size && params.slSize <= order.size, ExceedOrderSize(order.size));

        _orderBook.setOrderTPSL(
            orderId,
            OrderTPSLData({ tpSize: params.tpSize, tpPrice: params.tpPrice, slSize: params.slSize, slPrice: params.slPrice })
        );
    }

    /// @notice Remove an order from storage and position tracking
    /// @param orderId Order ID to remove
    /// @param positionId Position ID to remove order from active orders of position
    function _removeOrder(OrderId orderId, PositionId positionId) internal {
        _orderBook.removeOrder(orderId);
        _removeOrderFromPosition(positionId, orderId);
    }

    /// @notice Add an order to position tracking
    function _addOrderToPosition(PositionId positionId, OrderId orderId) internal {
        activeOrdersOfPosition[positionId].add(OrderId.unwrap(orderId));
    }

    /// @notice Remove an order from position tracking
    function _removeOrderFromPosition(PositionId positionId, OrderId orderId) internal {
        activeOrdersOfPosition[positionId].remove(OrderId.unwrap(orderId));
    }

    /// @notice Transfer tokens from user to contract
    /// @param user User address to transfer from
    /// @param token Token address to transfer
    /// @param amount Amount to transfer
    function _transferInFrom(address user, address token, uint256 amount) internal {
        IERC20(token).safeTransferFrom(user, address(this), amount);
    }

    /// @notice Validate order parameters against pool state
    function _validateOrder(
        IPositionManager positionManager,
        OrderTypes.PlaceOrderParams calldata params,
        PoolMetadata memory pool,
        PositionId positionId
    ) internal view returns (PositionMetadata memory position) {
        require(activeOrdersOfPosition[positionId].length() < Constants.MAX_ORDER_COUNT, Errors.ExceedMaxOrderCount());

        bool validPoolState = pool.isPoolInitialized() && (pool.isTrench() || (params.operation == Operation.Decrease && pool.isPreBench()));
        require(validPoolState, Errors.PoolNotActive(params.poolId));

        bool validOrder =
            params.size > 0 &&
                params.price > 0 &&
                params.slippagePct < Constants.SLIPPAGE_PRECISION &&
                (params.orderType != OrderType.Stop || params.operation == Operation.Decrease) &&
                (params.orderType == OrderType.Market || params.triggerType != TriggerType.None);
        require(validOrder, Errors.InvalidParameter());

        // Validate Limit Order trigger type
        if (params.orderType == OrderType.Limit) {
            bool validLimitTrigger = params.triggerType == TradeUtils.getOrderTriggerType(params.operation, params.direction);
            require(validLimitTrigger, Errors.InvalidTriggerType());
        }

        position = positionManager.getPosition(positionId);
        if (position.isInitialized()) {
            require(PoolId.unwrap(params.poolId) == PoolId.unwrap(position.poolId), Errors.InvalidPosition(positionId));
            require(params.direction == position.direction, Errors.InvalidPosition(positionId));
            address owner = positionManager.getPositionOwner(positionId);
            require(params.user == owner, Errors.NotPositionOwner());
        } else {
            require(params.operation == Operation.Increase, Errors.PositionNotInitialized(positionId));
        }

        _validateTpsl(params.operation, params.direction, params.size, params.price, params.tpSize, params.tpPrice, params.slSize, params.slPrice);
    }

    function _validateUpdateOrder(
        OrderTypes.UpdateOrderParams memory params,
        Operation operation,
        Direction direction,
        uint256 filledSize
    ) internal pure {
        require(params.size > filledSize && params.price > 0, Errors.InvalidParameter());

        OrderTypes.UpdateOrderTPSLParams memory tpsl = params.tpsl;
        _validateTpsl(operation, direction, params.size, params.price, tpsl.tpSize, tpsl.tpPrice, tpsl.slSize, tpsl.slPrice);
    }

    function _validateTpsl(
        Operation operation,
        Direction direction,
        uint256 orderSize,
        uint256 orderPrice,
        uint256 tpSize,
        uint256 tpPrice,
        uint256 slSize,
        uint256 slPrice
    ) internal pure {
        if (operation == Operation.Increase) {
            if (tpSize > 0) {
                bool validTp = tpSize <= orderSize && ((direction == Direction.Long) ? tpPrice > orderPrice : tpPrice < orderPrice);
                require(validTp, Errors.InvalidParameter());
            }
            if (slSize > 0) {
                bool validSl = slSize <= orderSize && ((direction == Direction.Long) ? slPrice < orderPrice : slPrice > orderPrice);
                require(validSl, Errors.InvalidParameter());
            }
        } else {
            require(tpSize == 0 && slSize == 0, Errors.InvalidParameter());
        }
    }

    function _resolveAndCollectForwarderFee(OrderMetadata memory order, PositionId positionId, PoolId poolId) internal {
        PositionMetadata memory position = _getPositionManager().getPosition(positionId);
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        _collectForwardFee(order, position, pool.quoteToken, pool.tradingVault);
    }

    function _collectForwardFee(OrderMetadata memory order, PositionMetadata memory position, address quoteToken, address tradingVault) internal {
        ITradingRouter tradingRouter = ITradingRouter(_getDependencyAddress(Identifier.TRADING_ROUTER));
        if (position.isInitialized()) {
            tradingRouter.collectForwardFeeIfNecessary(
                ICollectFee.FeeSource.Position,
                abi.encode(ICollectFee.PositionFeeParams({ positionId: order.positionId, feeToken: quoteToken, tradingVault: tradingVault }))
            );
        } else {
            tradingRouter.collectForwardFeeIfNecessary(
                ICollectFee.FeeSource.Account,
                abi.encode(ICollectFee.AccountFeeParams({ poolId: order.poolId, feeToken: quoteToken, user: order.user }))
            );
        }
    }

    function _ensurePoolExists(PoolId poolId) internal view {
        require(_getPoolManager().checkPoolExists(poolId), Errors.PoolNotExist(poolId));
    }

    function _ensureOrderExecutors() internal view {
        require(
            msg.sender == _getDependencyAddress(Identifier.POSITION_MANAGER) ||
                msg.sender == _getDependencyAddress(Identifier.EXECUTOR) ||
                IKeeperRegistry(_getDependencyAddress(Identifier.KEEPER_REGISTRY)).isKeeper(msg.sender),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _ensureOrderExists(OrderId orderId) internal view {
        require(_orderBook.checkOrderExists(orderId), Errors.OrderNotExist(orderId));
    }

    function _onlyBroker() internal view {
        require(IBrokerManager(_getDependencyAddress(Identifier.BROKER_MANAGER)).isActiveBroker(msg.sender), Errors.NotActiveBroker(msg.sender));
    }

    function _onlyPoolConfigurator() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POOL_CONFIGURATOR), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyMatcher() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.MATCHER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyPositionManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POSITION_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyTradingRouter() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.TRADING_ROUTER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getPositionManager() internal view returns (IPositionManager positionManager) {
        return IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getEmiter() internal view returns (IEmiter emiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }

    function _getRiskController() internal view returns (IRiskController riskController) {
        return IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER));
    }

    function _getAccount() internal view returns (IAccount account) {
        return IAccount(_getDependencyAddress(Identifier.ACCOUNT));
    }
}

