// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IEmiter } from "./interfaces/IEmiter.sol";
import { IKeeperRegistry } from "./interfaces/IKeeperRegistry.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IReservePool } from "./interfaces/IReservePool.sol";
import { IRoleManager } from "./interfaces/IRoleManager.sol";
import { ITradingVault } from "./interfaces/ITradingVault.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./misc/base/BaseContractUpgradeable.sol";
import { Errors, PoolMetadata, PoolId } from "./types/Types.sol";
import { PrecisionUtils } from "./utils/PrecisionUtils.sol";

/// @title ReservePool
/// @notice Manages protocol reserve funds and fee distribution
contract ReservePool is BaseContractUpgradeable, IReservePool {
    using SafeERC20 for IERC20;
    using PrecisionUtils for uint256;

    /// @notice Precision for ratio calculations (10000 = 100%)
    uint256 public constant RATIO_PRECISION = 1e4;

    /// @notice Configuration for splitting collected fees
    struct SplitConfig {
        // Ratio allocated to pool (basis points)
        uint16 poolRatio;
        // Ratio allocated to staking rewards (basis points)
        uint16 stakingRatio;
        // Ratio allocated to keeper rewards (basis points)
        uint16 keeperRatio;
        // Ratio allocated to treasury (basis points)
        uint16 treasuryRatio;
        // Ratio reserved for future use (basis points)
        uint16 reservedRatio;
        // Ratio allocated to ecosystem fund (basis points)
        uint16 ecoFundRatio;
    }

    /// @notice Split configuration by strategy ID
    mapping(uint8 strategyId => SplitConfig config) public strategySplitConfigs;
    /// @notice Strategy ID assigned to each pool
    mapping(PoolId poolId => uint8 strategyId) public poolStrategyIds;
    /// @notice Keeper rebates by keeper and token
    mapping(address keeper => mapping(address token => int256 rebates)) public keeperRebates;
    /// @notice Staking rebates by token
    mapping(address token => int256 stakingRebates) public stakingRebates;
    /// @notice Treasury rebates by token
    mapping(address token => int256 treasuryRebates) public treasuryRebates;
    /// @notice Reserved rebates by token
    mapping(address token => int256 reservedRebates) public reservedRebates;
    /// @notice Ecosystem fund rebates by token
    mapping(address token => int256 ecoFundRebates) public ecoFundRebates;
    /// @notice Settler debts by settler and token
    mapping(address settler => mapping(address token => uint256 debt)) public settlerDebts;

    mapping(PoolId poolId => mapping(address token => uint256 reserves)) public poolRiskReserves;

    /// @notice Emitted when split configuration is updated
    event SplitConfigUpdated(uint8 strategyId, SplitConfig config);
    /// @notice Emitted when pool strategy ID is updated
    event PoolStrategyIdUpdated(PoolId poolId, uint8 strategyId);

    /// @notice Emitted when liquidate pool debt
    event LiquidatePoolDebt(PoolId poolId, uint256 totalDebt, uint256 collateral);

    /// @notice Emitted when staking rebates are withdrawn
    event StakingRebatesWithdrawn(address token, uint256 amount, address recipient);
    /// @notice Emitted when treasury rebates are withdrawn
    event TreasuryRebatesWithdrawn(address token, uint256 amount, address recipient);
    /// @notice Emitted when reserved rebates are withdrawn
    event ReservedRebatesWithdrawn(address token, uint256 amount, address recipient);
    /// @notice Emitted when ecosystem fund rebates are withdrawn
    event EcoFundRebatesWithdrawn(address token, uint256 amount, address recipient);
    event RiskReservesDeposit(PoolId poolId, address token, uint256 amount, address user);
    event RiskReservesWithdrawn(PoolId poolId, address token, uint256 amount, address recipient);

    /// @notice Thrown when split configuration ratios don't sum to 100%
    error InvalidSplitConfig();
    /// @notice Thrown when insufficient balance for withdrawal
    error InsufficientBalance();
    /// @notice Thrown when amount is zero
    error InvalidAmount();

    modifier onlyRiskAdmin() {
        _onlyRiskAdmin();
        _;
    }

    modifier onlyFinanceAdmin() {
        _onlyFinanceAdmin();
        _;
    }

    modifier onlyTradingVault(PoolId poolId) {
        _onlyTradingVault(poolId);
        _;
    }

    modifier onlyKeeper() {
        _onlyKeeper();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the reserve pool contract
    /// @param addressManager Address manager contract address
    /// @param defaultSplitConfig Default split configuration for strategy 0
    function initialize(address addressManager, SplitConfig calldata defaultSplitConfig) external initializer {
        bytes32[] memory dependencies = new bytes32[](3);
        dependencies[0] = Identifier.POOL_MANAGER;
        dependencies[1] = Identifier.EMITER;
        dependencies[2] = Identifier.KEEPER_REGISTRY;
        __BaseContractUpgradeable_init(addressManager, dependencies);

        _setSplitConfig(0, defaultSplitConfig);
    }

    /// @notice Set split configuration for a strategy
    /// @param strategyId Strategy ID to configure
    /// @param config Split configuration (ratios must sum to 100%)
    function setSplitConfig(uint8 strategyId, SplitConfig calldata config) external onlyRiskAdmin {
        _setSplitConfig(strategyId, config);
    }

    /// @notice Set strategy ID for a pool
    /// @param poolId Pool ID to configure
    /// @param strategyId Strategy ID to assign
    function setPoolStrategyId(PoolId poolId, uint8 strategyId) external onlyRiskAdmin {
        poolStrategyIds[poolId] = strategyId;

        emit PoolStrategyIdUpdated(poolId, strategyId);
    }

    /// @notice Collect fees and split them according to pool strategy
    /// @param poolId Pool ID to collect fees for
    /// @param token Token address to collect
    /// @param amount Total amount to collect
    /// @param keeper Keeper address for rebate allocation
    /// @return poolAmount Amount allocated to pool
    function collect(PoolId poolId, address token, uint256 amount, address keeper) external override returns (uint256 poolAmount) {
        uint256 stakingAmount;
        uint256 keeperAmount;
        uint256 treasuryAmount;
        uint256 reservedAmount;
        uint256 ecoFundAmount;
        (poolAmount, stakingAmount, keeperAmount, treasuryAmount, reservedAmount, ecoFundAmount) = _computeSplitAmounts(poolId, amount);

        uint256 transferInAmount = amount - poolAmount;
        uint256 settlerDebt = settlerDebts[msg.sender][token];
        if (settlerDebt > 0) {
            if (settlerDebt >= transferInAmount) {
                settlerDebts[msg.sender][token] -= transferInAmount;
                transferInAmount = 0;
            } else {
                settlerDebts[msg.sender][token] = 0;
                transferInAmount -= settlerDebt;
            }
        }

        if (transferInAmount > 0) IERC20(token).safeTransferFrom(msg.sender, address(this), transferInAmount);

        keeperRebates[keeper][token] += int256(keeperAmount);
        stakingRebates[token] += int256(stakingAmount);
        treasuryRebates[token] += int256(treasuryAmount);
        reservedRebates[token] += int256(reservedAmount);
        ecoFundRebates[token] += int256(ecoFundAmount);

        _getEmiter().emitReserveRebateCollected(
            IEmiter.ReserveRebateCollectedParams({
                poolId: poolId,
                token: token,
                amount: amount,
                keeper: keeper,
                poolAmount: poolAmount,
                stakingAmount: stakingAmount,
                keeperAmount: keeperAmount,
                treasuryAmount: treasuryAmount,
                reservedAmount: reservedAmount,
                ecoFundAmount: ecoFundAmount
            })
        );
    }

    /// @notice Collect fees to treasury
    function collectToTreasury(PoolId poolId, address token, uint256 amount) external override {
        require(amount > 0, InvalidAmount());
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        treasuryRebates[token] += int256(amount);

        _getEmiter().emitReserveRebateCollected(
            IEmiter.ReserveRebateCollectedParams({
                poolId: poolId,
                token: token,
                amount: amount,
                keeper: address(0),
                poolAmount: 0,
                stakingAmount: 0,
                keeperAmount: 0,
                treasuryAmount: amount,
                reservedAmount: 0,
                ecoFundAmount: 0
            })
        );
    }

    /// @notice Disburse fees according to pool strategy
    /// @param poolId Pool ID to disburse fees for
    /// @param token Token address to disburse
    /// @param amount Total amount to disburse
    /// @param keeper Keeper address for rebate deduction
    /// @return poolAmount Amount allocated to pool
    function disburse(
        PoolId poolId,
        address token,
        uint256 amount,
        address keeper
    ) external override onlyTradingVault(poolId) returns (uint256 poolAmount) {
        uint256 stakingAmount;
        uint256 keeperAmount;
        uint256 treasuryAmount;
        uint256 reservedAmount;
        uint256 ecoFundAmount;
        (poolAmount, stakingAmount, keeperAmount, treasuryAmount, reservedAmount, ecoFundAmount) = _computeSplitAmounts(poolId, amount);

        keeperRebates[keeper][token] -= int256(keeperAmount);
        stakingRebates[token] -= int256(stakingAmount);
        treasuryRebates[token] -= int256(treasuryAmount);
        reservedRebates[token] -= int256(reservedAmount);
        ecoFundRebates[token] -= int256(ecoFundAmount);

        uint256 transferOutAmount = amount - poolAmount;
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (balance >= transferOutAmount) {
            IERC20(token).safeTransfer(msg.sender, transferOutAmount);
        } else {
            IERC20(token).safeTransfer(msg.sender, balance);
            settlerDebts[msg.sender][token] += transferOutAmount - balance;
        }

        _getEmiter().emitReserveRebateDisbursed(
            IEmiter.ReserveRebateDisbursedParams({
                poolId: poolId,
                token: token,
                amount: amount,
                keeper: keeper,
                poolAmount: poolAmount,
                stakingAmount: stakingAmount,
                keeperAmount: keeperAmount,
                treasuryAmount: treasuryAmount,
                reservedAmount: reservedAmount,
                ecoFundAmount: ecoFundAmount
            })
        );
    }

    function liquidatePoolDebt(PoolMetadata memory pool) external onlyKeeper {
        ITradingVault.DebtInfo memory debt = ITradingVault(pool.tradingVault).debtInfo();

        poolRiskReserves[pool.poolId][pool.baseToken] += debt.baseCollateral;
        poolRiskReserves[pool.poolId][pool.quoteToken] -= debt.totalDebt;

        IERC20(pool.quoteToken).forceApprove(pool.tradingVault, debt.totalDebt);
        uint256 beforeBalance = IERC20(pool.baseToken).balanceOf(address(this));
        ITradingVault(pool.tradingVault).repayCollateralTo();
        uint256 afterBalance = IERC20(pool.baseToken).balanceOf(address(this));

        emit LiquidatePoolDebt(pool.poolId, debt.totalDebt, afterBalance - beforeBalance);
    }

    function depositRiskReserves(PoolId poolId, address token, uint256 amount) external {
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        poolRiskReserves[poolId][token] += amount;

        emit RiskReservesDeposit(poolId, token, amount, msg.sender);
    }

    function withdrawRiskReserves(PoolId poolId, address token, uint256 amount, address recipient) external onlyFinanceAdmin {
        require(poolRiskReserves[poolId][token] >= amount, Errors.InsufficientRiskReserves());
        poolRiskReserves[poolId][token] -= amount;
        IERC20(token).safeTransfer(recipient, amount);

        emit RiskReservesWithdrawn(poolId, token, amount, recipient);
    }

    function withdrawStakingRebates(address token, uint256 amount, address recipient) external onlyFinanceAdmin {
        _ensureSufficientBalance(stakingRebates[token], amount);

        stakingRebates[token] -= int256(amount);
        IERC20(token).safeTransfer(recipient, amount);

        emit StakingRebatesWithdrawn(token, amount, recipient);
    }

    function withdrawTreasuryRebates(address token, uint256 amount, address recipient) external onlyFinanceAdmin {
        _ensureSufficientBalance(treasuryRebates[token], amount);

        treasuryRebates[token] -= int256(amount);
        IERC20(token).safeTransfer(recipient, amount);

        emit TreasuryRebatesWithdrawn(token, amount, recipient);
    }

    function withdrawReservedRebates(address token, uint256 amount, address recipient) external onlyFinanceAdmin {
        _ensureSufficientBalance(reservedRebates[token], amount);

        reservedRebates[token] -= int256(amount);
        IERC20(token).safeTransfer(recipient, amount);

        emit ReservedRebatesWithdrawn(token, amount, recipient);
    }

    function withdrawEcoFundRebates(address token, uint256 amount, address recipient) external onlyFinanceAdmin {
        _ensureSufficientBalance(ecoFundRebates[token], amount);

        ecoFundRebates[token] -= int256(amount);
        IERC20(token).safeTransfer(recipient, amount);

        emit EcoFundRebatesWithdrawn(token, amount, recipient);
    }

    /// @notice Get split configuration for a pool
    /// @param poolId Pool ID to query
    /// @return config Split configuration for the pool's strategy
    function getPoolSplitConfig(PoolId poolId) public view returns (SplitConfig memory config) {
        return strategySplitConfigs[poolStrategyIds[poolId]];
    }

    /// @notice Set split configuration for a strategy
    /// @param strategyId Strategy ID to configure
    /// @param config Split configuration to set
    function _setSplitConfig(uint8 strategyId, SplitConfig calldata config) internal {
        require(
            config.poolRatio + config.stakingRatio + config.keeperRatio + config.treasuryRatio + config.reservedRatio + config.ecoFundRatio ==
                RATIO_PRECISION,
            InvalidSplitConfig()
        );
        strategySplitConfigs[strategyId] = config;

        emit SplitConfigUpdated(strategyId, config);
    }

    /// @notice Compute split amounts for fee distribution
    /// @param poolId Pool ID to compute splits for
    /// @param amount Total amount to split
    /// @return poolAmount Amount allocated to pool
    /// @return stakingAmount Amount allocated to staking
    /// @return keeperAmount Amount allocated to keeper
    /// @return treasuryAmount Amount allocated to treasury
    /// @return reservedAmount Amount allocated to reserved
    /// @return ecoFundAmount Amount allocated to ecosystem fund
    function _computeSplitAmounts(
        PoolId poolId,
        uint256 amount
    )
        internal
        view
        returns (
            uint256 poolAmount,
            uint256 stakingAmount,
            uint256 keeperAmount,
            uint256 treasuryAmount,
            uint256 reservedAmount,
            uint256 ecoFundAmount
        )
    {
        SplitConfig memory splitConfig = getPoolSplitConfig(poolId);
        poolAmount = amount.mulPrecision(splitConfig.poolRatio, RATIO_PRECISION);
        stakingAmount = amount.mulPrecision(splitConfig.stakingRatio, RATIO_PRECISION);
        keeperAmount = amount.mulPrecision(splitConfig.keeperRatio, RATIO_PRECISION);
        treasuryAmount = amount.mulPrecision(splitConfig.treasuryRatio, RATIO_PRECISION);
        reservedAmount = amount.mulPrecision(splitConfig.reservedRatio, RATIO_PRECISION);
        ecoFundAmount = amount.mulPrecision(splitConfig.ecoFundRatio, RATIO_PRECISION);
    }

    /// @notice Ensure sufficient balance for withdrawal
    /// @param balance Current balance
    /// @param required Required amount
    function _ensureSufficientBalance(int256 balance, uint256 required) internal pure {
        if (balance < 0 || uint256(balance) < required) {
            revert InsufficientBalance();
        }
    }

    function _onlyRiskAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isRiskAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyFinanceAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isFinanceAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyTradingVault(PoolId poolId) internal view {
        require(_getPoolManager().getTradingVault(poolId) == msg.sender, Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyKeeper() internal view {
        require(
            IKeeperRegistry(_getDependencyAddress(Identifier.KEEPER_REGISTRY)).isKeeper(msg.sender),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getEmiter() internal view returns (IEmiter emiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }
}

