// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { ContextUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol";
import { EIP712Upgradeable } from "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IAddressManager } from "./../interfaces/IAddressManager.sol";
import { IBroker } from "./../interfaces/IBroker.sol";
import { IBrokerManager } from "./../interfaces/IBrokerManager.sol";
import { ICollectFee } from "./../interfaces/ICollectFee.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { ITradingRouter } from "./../interfaces/ITradingRouter.sol";
import { CompositeKey } from "./../libraries/CompositeKey.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { ERC2771ContextUpgradeable } from "./../router/ERC2771ContextUpgradeable.sol";
import { AssetClass, Constants, Errors, PoolId, FeeType } from "./../types/Types.sol";

/**
 * @title Broker
 * @notice Core broker contract for handling trading operations, fee management, and user interactions
 * @dev This contract manages trading orders, positions, fee collection, rebate distribution, and broker-specific
 * configurations. It supports multiple asset classes, custom fee tiers, and cryptographic signature verification
 * for fee data authentication.
 */
contract Broker is ERC2771ContextUpgradeable, Ownable2StepUpgradeable, EIP712Upgradeable, ReentrancyGuardUpgradeable, IBroker {
    using ECDSA for bytes32;
    using EnumerableSetLib for EnumerableSetLib.Uint256Set;
    using EnumerableSetLib for EnumerableSetLib.AddressSet;
    using SafeERC20 for IERC20;

    // EIP-712 typehash for user fee data signature verification
    // keccak256("
    //    UserFeeData(address user,uint64 nonce,uint64 deadline,uint8 tier,address referrer,uint32 totalReferralRebatePct,uint32 referrerRebatePct,uint64 expiry)
    // ");
    bytes32 public constant FEE_TYPEHASH = 0xec03eb922d8f2cb7de9f5811f43d3f01d1faa29b660a1f5bd4428626f3bccc8a;

    // Human-readable name of the broker
    string public override name;
    // Whether the broker is currently active and accepting trades
    bool public override isActive;
    // Mapping from user address to their fee data and signature information
    mapping(address user => UserFeeData feeData) public userFeeData;
    mapping(address user => uint64 nonce) public userNonces;
    // Mapping from user to token to their accumulated rebate amounts
    mapping(address user => mapping(address token => uint256 rebateAmount)) public userRebates;
    // Address of the address manager
    address public addressManager;

    // Set of authorized signers who can sign fee data
    EnumerableSetLib.AddressSet private _signers;
    // Mapping from asset class to base fee rates
    mapping(AssetClass assetClass => FeeRate feeRate) private _baseFeeRates;
    // Set of supported asset classes for this broker
    EnumerableSetLib.Uint256Set private _supportedAssetClasses;
    // Mapping from asset class and composite key to add-on fee configuration
    // Key structure: [riskTier (8 bits)][feeTier (8 bits)]
    // riskTier: 0-99 (recommended), feeTier: 0-9 (recommended)
    mapping(AssetClass assetClass => mapping(uint16 compositeKey => AddOnFeeTier fee)) private _addOnFeeTiers;
    // Mapping from token address to broker fee amount
    mapping(address token => uint256 addOnFee) private _brokerFees;
    // Set of available fee tiers
    // Key structure: [AssetClass (8 bits)][riskTier (8 bits)]
    mapping(uint16 compositeKey => EnumerableSetLib.Uint256Set tiers) private _activeFeeTierList;

    error InvalidFeeRate();
    error NotBrokerSigner(address signer);
    error ExpiredFeeData();
    error UnsupportedAssetClass(AssetClass assetClass);
    error InsufficientBalance();

    /**
     * @notice Emitted when broker status is updated
     * @param broker Address of the broker
     * @param isActive New active status
     */
    event BrokerStatusUpdated(address broker, bool isActive);

    /**
     * @notice Emitted when a user claims their rebates
     * @param user Address of the user claiming rebates
     * @param token Token address of the claimed rebates
     * @param amount Amount of rebates claimed
     */
    event RebateClaimed(address user, address token, uint256 amount);

    /**
     * @notice Emitted when a signer's authorization status is updated
     * @param signer Address of the signer
     * @param isSigner New authorization status
     */
    event SignerUpdated(address signer, bool isSigner);

    event BrokerFeesWithdrawn(address indexed broker, address token, uint256 amount, address recipient);

    modifier onlyBrokerManager() {
        _onlyBrokerManager();
        _;
    }

    modifier onlySigner() {
        _onlySigner();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @inheritdoc IBroker
    function initialize(
        address _addressManager,
        address owner,
        string calldata _brokerName,
        address[] calldata brokerSigners,
        AssetClass[] calldata assetClasses,
        FeeRate[] calldata baseFeeRates
    ) external initializer {
        require(assetClasses.length == baseFeeRates.length, InvalidFeeRate());

        addressManager = _addressManager;
        name = _brokerName;
        isActive = false;

        __Ownable2Step_init();
        __EIP712_init("Broker", "1.0");
        __ReentrancyGuard_init();
        __ERC2771ContextUpgradeable_init(_getAddress(Identifier.FORWARDER));
        _transferOwnership(owner);

        for (uint256 i = 0; i < brokerSigners.length; ++i) {
            _signers.add(brokerSigners[i]);
        }

        for (uint256 i = 0; i < assetClasses.length; ++i) {
            _baseFeeRates[assetClasses[i]] = baseFeeRates[i];
            _supportedAssetClasses.add(uint256(assetClasses[i]));
        }
    }

    /**
     * @notice Syncs base fee rates from BrokerManager default config for specified asset classes
     * @param assetClass Array of asset classes to sync
     * @dev Only callable by the contract owner
     */
    function syncAssetClass(AssetClass assetClass) external onlyOwner {
        IBrokerManager brokerManager = IBrokerManager(_getAddress(Identifier.BROKER_MANAGER));
        _supportedAssetClasses.add(uint256(assetClass));
        _baseFeeRates[assetClass] = brokerManager.getDefaultBaseFeeRate(assetClass);
    }

    /**
     * @notice Sets the authorization status of a signer
     * @param signer Address of the signer
     * @param isSigner Whether the signer should be authorized
     * @dev Only callable by the contract owner
     */
    function setSigner(address signer, bool isSigner) external onlyOwner {
        if (isSigner) {
            _signers.add(signer);
        } else {
            _signers.remove(signer);
        }

        emit SignerUpdated(signer, isSigner);
    }

    /**
     * @notice Batch update multiple fee tiers across different asset classes and risk tiers
     * @param params Array of parameters, each specifying asset class, risk tier, fee tier, and rate
     * @dev Only callable by the contract owner. Allows updating any combination of fee tiers in a single transaction.
     *      Each element is independent, enabling flexible updates across the entire fee structure.
     */
    function batchUpdateFeeTiers(IBroker.UpdateAddOnFeeTierParams[] calldata params) external onlyOwner {
        for (uint256 i = 0; i < params.length; ++i) {
            IBroker.UpdateAddOnFeeTierParams calldata param = params[i];
            _updateFeeTier(param.assetClass, param.riskTier, param.feeTier, param.addOnFeeRate.takerFeeRate, param.addOnFeeRate.makerFeeRate);
        }
    }

    /**
     * @notice Updates a single fee tier
     * @param assetClass Asset class for the fee tier
     * @param riskTier Risk tier for the fee tier
     * @param feeTier The fee tier number to update
     * @param feeRate The new fee rate configuration for the tier
     * @dev Only callable by the contract owner
     */
    function updateFeeTier(AssetClass assetClass, uint8 riskTier, uint8 feeTier, FeeRate memory feeRate) external onlyOwner {
        _updateFeeTier(assetClass, riskTier, feeTier, feeRate.takerFeeRate, feeRate.makerFeeRate);
    }

    /// @inheritdoc IBroker
    function updateBaseFeeRates(IBroker.UpdateBaseFeeRateParams[] calldata params) external override onlyBrokerManager {
        for (uint256 i = 0; i < params.length; ++i) {
            IBroker.UpdateBaseFeeRateParams calldata param = params[i];

            if (param.isEnable) {
                _supportedAssetClasses.add(uint256(param.assetClass));
                _baseFeeRates[param.assetClass] = param.baseFeeRate;
            } else {
                _supportedAssetClasses.remove(uint256(param.assetClass));
            }

            _emitFeeTierUpdated(
                param.assetClass,
                0,
                FeeType.BaseFee,
                0,
                param.baseFeeRate.takerFeeRate,
                int32(param.baseFeeRate.makerFeeRate),
                param.isEnable
            );
        }
    }

    /// @inheritdoc IBroker
    function updateBrokerStatus(bool active) external override onlyBrokerManager {
        isActive = active;
        emit BrokerStatusUpdated(address(this), active);
    }

    /**
     * @notice Callback function triggered when broker fees are collected
     * @param poolId The pool ID where the fee was generated
     * @param user The user who generated the fee
     * @param token The token in which the fee is paid
     * @param feeAmount The amount of fee collected
     * @return totalReferralRebate Total amount allocated for referral rebates
     * @return referrerRebate Amount allocated specifically for the referrer
     * @return referrer Address of the referrer receiving the rebate
     * @dev Processes fee distribution including referral rebates and broker fees
     */
    function onBrokerFee(
        PoolId poolId,
        address user,
        address token,
        uint256 feeAmount
    ) external override nonReentrant returns (uint256 totalReferralRebate, uint256 referrerRebate, address referrer) {
        if (IPoolManager(_getAddress(Identifier.POOL_MANAGER)).getTradingVault(poolId) != _msgSender())
            revert Errors.PermissionDenied(_msgSender(), address(this));
        if (feeAmount == 0) return (0, 0, address(0));

        UserFeeData memory feeData = userFeeData[user];

        uint256 brokerFee = feeAmount;
        uint256 totalReferralRebatePct = feeData.totalReferralRebatePct;
        if (totalReferralRebatePct > 0) {
            totalReferralRebate = (feeAmount * totalReferralRebatePct) / Constants.TRADING_FEE_RATE_PRECISION;
            referrerRebate = (feeAmount * feeData.referrerRebatePct) / Constants.TRADING_FEE_RATE_PRECISION;
            referrer = feeData.referrer;

            brokerFee -= totalReferralRebate;
            userRebates[user][token] += totalReferralRebate - referrerRebate;
            if (referrer != address(0)) userRebates[referrer][token] += referrerRebate;
        }

        _brokerFees[token] += brokerFee;
    }

    /**
     * @notice Sets fee data for a user with cryptographic signature verification
     * @dev Signature must be from an authorized signer and not expired
     */
    function setUserFeeData(SetUserFeeDataParams calldata params) public nonReentrant {
        UserFeeData calldata _userFeeData = params.feeData;
        address signer = _recoverSigner(params.user, params.nonce, params.deadline, _userFeeData, params.signature);
        require(_signers.contains(signer), NotBrokerSigner(signer));
        require(block.timestamp <= params.deadline, ExpiredFeeData());
        require(params.nonce == userNonces[params.user] + 1 && _userFeeData.referrer != params.user, Errors.InvalidParameter());
        require(
            _userFeeData.totalReferralRebatePct <= Constants.TRADING_FEE_RATE_PRECISION &&
                _userFeeData.referrerRebatePct <= _userFeeData.totalReferralRebatePct,
            Errors.InvalidParameter()
        );

        ++userNonces[params.user];
        userFeeData[params.user] = UserFeeData({
            tier: _userFeeData.tier,
            referrer: _userFeeData.referrer,
            totalReferralRebatePct: _userFeeData.totalReferralRebatePct,
            referrerRebatePct: _userFeeData.referrerRebatePct,
            expiry: _userFeeData.expiry
        });

        _getTradingRouter().collectForwardFeeIfNecessary(
            ICollectFee.FeeSource.Direct,
            abi.encode(ICollectFee.AddressFeeParams({ feeToken: address(0), user: _msgOrigin() }))
        );

        _emitUserFeeDataUpdated(signer, params.user, _userFeeData);
    }

    /**
     * @notice Claims rebates for multiple tokens in a single transaction
     * @param tokens Array of token addresses to claim rebates for
     */
    function claimRebates(address[] calldata tokens) external nonReentrant {
        for (uint256 i = 0; i < tokens.length; ++i) {
            _claimRebate(tokens[i]);
        }
    }

    /**
     * @notice Claims accumulated rebates for a specific token
     * @param token Address of the token to claim rebates for
     */
    function claimRebate(address token) external nonReentrant {
        _claimRebate(token);
    }

    /**
     * @notice Withdraws broker fees for a specific token
     * @param token Token address to withdraw fees for
     * @param amount Amount of fees to withdraw
     * @param recipient Recipient address to receive the fees
     */
    function withdrawBrokerFees(address token, uint256 amount, address recipient) external nonReentrant onlyOwner {
        require(_brokerFees[token] >= amount, InsufficientBalance());

        _brokerFees[token] -= amount;
        IERC20(token).safeTransfer(recipient, amount);

        emit BrokerFeesWithdrawn(address(this), token, amount, recipient);
    }

    /// @inheritdoc IBroker
    function checkAndResetExpiredTier(address user) external override {
        require(msg.sender == _getAddress(Identifier.MATCHER), Errors.PermissionDenied(msg.sender, address(this)));
        UserFeeData storage data = userFeeData[user];
        if (data.tier != 0 && data.expiry != 0 && block.timestamp > data.expiry) {
            data.tier = 0;
            data.expiry = 0;
        }
    }

    function domainSeparatorV4() external view returns (bytes32) {
        return _domainSeparatorV4();
    }

    /// @inheritdoc IBroker
    function getBaseFeeRate(AssetClass assetClass) external view override returns (FeeRate memory baseFeeRate) {
        return _baseFeeRates[assetClass];
    }

    /// @inheritdoc IBroker
    function getAddOnFeeTier(
        AssetClass assetClass,
        uint8 riskTier,
        uint8 feeTier
    ) public view override returns (uint32 takerFeeRate, uint32 makerFeeRate) {
        uint16 key = CompositeKey.pack(riskTier, feeTier);
        AddOnFeeTier memory addOnFeeTier = _addOnFeeTiers[assetClass][key];
        return (addOnFeeTier.takerFeeRate, addOnFeeTier.makerFeeRate);
    }

    /// @inheritdoc IBroker
    function activeFeeTiers(AssetClass assetClass, uint8 riskTier) external view override returns (uint256[] memory) {
        uint16 key = CompositeKey.pack(uint8(assetClass), riskTier);
        return _activeFeeTierList[key].values();
    }

    /// @inheritdoc IBroker
    function supportedAssetClasses() external view override returns (uint256[] memory) {
        return _supportedAssetClasses.values();
    }

    /// @inheritdoc IBroker
    function getUserFeeRate(
        address user,
        AssetClass assetClass,
        uint8 riskTier
    ) external view virtual override returns (uint32 takerFeeRate, int32 makerFeeRate, uint32 baseTakerFeeRate, uint32 baseMakerFeeRate) {
        return _getUserFeeRate(user, assetClass, riskTier);
    }

    function _claimRebate(address token) internal {
        uint256 rebateAmount = userRebates[_msgOrigin()][token];
        require(rebateAmount > 0, Errors.NoRebateToClaim());

        userRebates[_msgOrigin()][token] = 0;
        IERC20(token).safeTransfer(_msgOrigin(), rebateAmount);

        _getTradingRouter().collectForwardFeeIfNecessary(
            ICollectFee.FeeSource.Direct,
            abi.encode(ICollectFee.AddressFeeParams({ feeToken: address(0), user: _msgOrigin() }))
        );
        _emitClaimed(_msgOrigin(), token, rebateAmount);
    }

    function _getUserFeeRate(
        address user,
        AssetClass assetClass,
        uint8 riskTier
    ) internal view returns (uint32 takerFeeRate, int32 makerFeeRate, uint32 baseTakerFeeRate, uint32 baseMakerFeeRate) {
        if (!_supportedAssetClasses.contains(uint256(assetClass))) revert UnsupportedAssetClass(assetClass);

        uint8 userFeeTier = userFeeData[user].tier;
        uint16 key = CompositeKey.pack(uint8(assetClass), riskTier);
        if (userFeeTier != 0 && !_activeFeeTierList[key].contains(uint256(userFeeTier))) {
            userFeeTier = 0;
        }

        key = CompositeKey.pack(riskTier, userFeeTier);
        AddOnFeeTier memory addOnFee = _addOnFeeTiers[assetClass][key];
        FeeRate memory baseFeeRate = _baseFeeRates[assetClass];
        return (
            baseFeeRate.takerFeeRate + addOnFee.takerFeeRate,
            int32(baseFeeRate.makerFeeRate + addOnFee.makerFeeRate),
            baseFeeRate.takerFeeRate,
            baseFeeRate.makerFeeRate
        );
    }

    function _emitUserFeeDataUpdated(address signer, address user, UserFeeData memory feeData) internal {
        _getEmiter().emitUserFeeDataUpdated(
            IEmiter.UserFeeDataUpdatedParams({
                broker: address(this),
                signer: signer,
                user: user,
                tier: feeData.tier,
                referrer: feeData.referrer,
                totalReferralRebatePct: feeData.totalReferralRebatePct,
                referrerRebatePct: feeData.referrerRebatePct,
                expiry: feeData.expiry
            })
        );
    }

    function _emitFeeTierUpdated(
        AssetClass assetClass,
        uint8 riskTier,
        FeeType feeType,
        uint8 feeTier,
        uint32 takerFeeRate,
        int32 makerFeeRate,
        bool isEnabled
    ) internal {
        _getEmiter().emitTradingFeeTierUpdated(
            IEmiter.TradingFeeTierUpdatedParams({
                assetClass: assetClass,
                riskTier: riskTier,
                broker: address(this),
                feeType: feeType,
                feeTier: feeTier,
                takerFeeRate: takerFeeRate,
                makerFeeRate: makerFeeRate,
                isEnabled: isEnabled
            })
        );
    }

    function _emitClaimed(address user, address token, uint256 amount) internal virtual {
        emit RebateClaimed(user, token, amount);
    }

    /**
     * @notice Internal function to update a fee tier
     * @param assetClass Asset class for the fee tier
     * @param riskTier Risk tier for the fee tier
     * @param feeTier Fee tier number to update
     * @param takerFeeRate New taker fee rate for the tier
     * @param makerFeeRate New maker fee rate for the tier
     */
    function _updateFeeTier(AssetClass assetClass, uint8 riskTier, uint8 feeTier, uint32 takerFeeRate, uint32 makerFeeRate) internal {
        require(takerFeeRate < Constants.TRADING_FEE_RATE_PRECISION && makerFeeRate < Constants.TRADING_FEE_RATE_PRECISION, InvalidFeeRate());

        uint16 key = CompositeKey.pack(riskTier, feeTier);
        _addOnFeeTiers[assetClass][key] = AddOnFeeTier({ takerFeeRate: takerFeeRate, makerFeeRate: makerFeeRate });

        key = CompositeKey.pack(uint8(assetClass), riskTier);
        _activeFeeTierList[key].add(feeTier);

        _emitFeeTierUpdated(assetClass, riskTier, FeeType.AddOnFee, feeTier, takerFeeRate, int32(makerFeeRate), true);
    }

    /**
     * @notice Recovers the signer address from a signature for fee data
     * @param user User address in the signed data
     * @param deadline Deadline timestamp in the signed data
     * @param feeData Fee data that was signed
     * @param signature The cryptographic signature
     * @return Address of the signer
     */
    function _recoverSigner(
        address user,
        uint64 nonce,
        uint64 deadline,
        UserFeeData memory feeData,
        bytes memory signature
    ) internal view returns (address) {
        return _digest(user, nonce, deadline, feeData).recover(signature);
    }

    function _digest(address user, uint64 nonce, uint64 deadline, UserFeeData memory feeData) internal view returns (bytes32) {
        return
            _hashTypedDataV4(
                keccak256(
                    abi.encode(
                        FEE_TYPEHASH,
                        user,
                        nonce,
                        deadline,
                        feeData.tier,
                        feeData.referrer,
                        feeData.totalReferralRebatePct,
                        feeData.referrerRebatePct,
                        feeData.expiry
                    )
                )
            );
    }

    function _msgSender() internal view override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (address sender) {
        return ERC2771ContextUpgradeable._msgSender();
    }

    function _msgData() internal view override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (bytes calldata) {
        return ERC2771ContextUpgradeable._msgData();
    }

    function _contextSuffixLength() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (uint256) {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }

    function _onlyBrokerManager() internal view {
        if (_getAddress(Identifier.BROKER_MANAGER) != _msgSender()) revert Errors.PermissionDenied(_msgSender(), address(this));
    }

    function _onlySigner() internal view {
        if (!_signers.contains(_msgSender())) revert NotBrokerSigner(_msgSender());
    }

    function _getTradingRouter() internal view returns (ITradingRouter) {
        return ITradingRouter(_getAddress(Identifier.TRADING_ROUTER));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(_getAddress(Identifier.EMITER));
    }

    function _getAddress(bytes32 identifier) internal view returns (address) {
        return IAddressManager(addressManager).getAddress(identifier);
    }
}

