// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IMatcher } from "./../../interfaces/IMatcher.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { LibPositionMetadata } from "./../../libraries/Position.sol";
import { Errors, PositionMetadata, OrderId, PositionId, MatchType } from "./../../types/Types.sol";
import { IEarlyCloseFacet } from "./../interfaces/IEarlyCloseFacet.sol";
import { ExecutorBaseFacet } from "./ExecutorBaseFacet.sol";

/// @title EarlyCloseFacet
/// @notice Facet for early position closure execution
contract EarlyCloseFacet is ExecutorBaseFacet, IEarlyCloseFacet {
    using LibPositionMetadata for PositionMetadata;

    /// @inheritdoc IEarlyCloseFacet
    function earlyCloseExecute(EarlyCloseParams calldata params) external override onlyKeeper {
        IPositionManager positionManager = _getPositionManager();
        PositionMetadata memory position = positionManager.getPosition(params.positionId);
        require(position.size > 0, Errors.InvalidPosition(params.positionId));

        (uint256 rewindPrice, uint64 publishTime) = _getOracle().getRewindPrice(position.poolId);
        require(publishTime >= position.lastUpdateTime, Errors.InvalidRewindPrice());

        // Calculate early close price and check if should close
        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(position.poolId);
        (uint256 earlyClosePrice, bool shouldClose) = _shouldEarlyClose(position, oiTracker.tracker, rewindPrice);
        require(shouldClose, Errors.NotMeetEarlyCloseCriteria(params.positionId));

        uint256 executeSize = position.size;
        uint256 executePrice = earlyClosePrice;
        (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) = _earlyCloseExecute(
            positionManager,
            position,
            params.positionId,
            executePrice,
            executeSize
        );

        _getEmiter().emitExecutionMatched(
            IEmiter.ExecutionMatchedParams({
                poolId: position.poolId,
                triggerOrderIds: triggerOrderIds,
                matchedOrderIds: matchedOrderIds,
                matchType: MatchType.EarlyClose,
                price: executePrice
            })
        );
    }

    /// @notice Internal function to execute early close
    /// @param position Position to early close
    /// @param positionId ID of the position
    /// @param executePrice Execution price
    /// @param executeSize Execution size
    /// @return triggerOrderIds Array of trigger order IDs
    /// @return matchedOrderIds Array of matched order IDs
    function _earlyCloseExecute(
        IPositionManager positionManager,
        PositionMetadata memory position,
        PositionId positionId,
        uint256 executePrice,
        uint256 executeSize
    ) internal returns (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        address owner = positionManager.getPositionOwner(positionId);

        OrderId orderId;
        (orderId, triggerOrderIds, matchedOrderIds) = _getMatcher().createAndMatchPool(
            IMatcher.CreateOrderParams({
                poolId: position.poolId,
                positionId: positionId,
                owner: owner,
                direction: position.direction,
                isLiquidation: false
            }),
            executeSize,
            executePrice,
            msg.sender
        );

        _getEmiter().emitPositionEarlyClosed(
            IEmiter.PositionEarlyClosedParams({
                broker: position.broker,
                user: owner,
                poolId: position.poolId,
                positionId: positionId,
                orderId: orderId,
                positionSize: position.size,
                executeSize: executeSize,
                executePrice: executePrice
            })
        );
    }
}

