// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IAddressManager } from "./../../interfaces/IAddressManager.sol";
import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IFundingRate } from "./../../interfaces/IFundingRate.sol";
import { IKeeperRegistry } from "./../../interfaces/IKeeperRegistry.sol";
import { IMatcher } from "./../../interfaces/IMatcher.sol";
import { IOracle } from "./../../interfaces/IOracle.sol";
import { IOrderManager } from "./../../interfaces/IOrderManager.sol";
import { IPoolManager } from "./../../interfaces/IPoolManager.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { IRiskController } from "./../../interfaces/IRiskController.sol";
import { IRiskParameter } from "./../../interfaces/IRiskParameter.sol";
import { ITradingRouter } from "./../../interfaces/ITradingRouter.sol";
import { ExecuteHelper } from "./../../libraries/ExecuteHelper.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { PositionMetadata, Direction } from "./../../types/Types.sol";
import { LibExecutor } from "./../libraries/LibExecutor.sol";

/// @title ExecutorBaseFacet
/// @notice Base facet providing common functionality for executor facets
abstract contract ExecutorBaseFacet {
    /// @notice Error thrown when caller is not a keeper
    error OnlyKeeper();

    modifier onlyKeeper() {
        _onlyKeeper();
        _;
    }

    function _onlyKeeper() internal view {
        require(_isKeeper(msg.sender), OnlyKeeper());
    }

    /// @notice Check if position should be early closed based on preset price
    /// @dev Only triggers when tracker direction matches position direction:
    ///      - Long: tracker > 0 (net long OI)
    ///      - Short: tracker < 0 (net short OI)
    /// @param position Position metadata
    /// @param tracker OI tracker value
    /// @param marketPrice Current market price
    /// @return earlyClosePrice Early close price (0 if no preset price)
    /// @return shouldClose Whether position should be closed
    function _shouldEarlyClose(
        PositionMetadata memory position,
        int256 tracker,
        uint256 marketPrice
    ) internal pure returns (uint256 earlyClosePrice, bool shouldClose) {
        if (!ExecuteHelper.hasEarlyClosePrice(position, tracker)) return (0, false);

        earlyClosePrice = position.earlyClosePrice;
        // Long: close when price >= earlyClosePrice, Short: close when price <= earlyClosePrice
        shouldClose = position.direction == Direction.Long ? marketPrice >= earlyClosePrice : marketPrice <= earlyClosePrice;
    }

    /// @notice Check if an address is a registered keeper
    function _isKeeper(address _address) internal view returns (bool) {
        return IKeeperRegistry(_getDependencyAddress(Identifier.KEEPER_REGISTRY)).isKeeper(_address);
    }

    /// @notice Get dependency address from address manager
    function _getDependencyAddress(bytes32 identifier) internal view returns (address) {
        IAddressManager addressManager = IAddressManager(LibExecutor.getAddressManager());
        return addressManager.getAddress(identifier);
    }

    function _getTradingRouter() internal view returns (ITradingRouter) {
        return ITradingRouter(_getDependencyAddress(Identifier.TRADING_ROUTER));
    }

    function _getMatcher() internal view returns (IMatcher) {
        return IMatcher(_getDependencyAddress(Identifier.MATCHER));
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getOrderManager() internal view returns (IOrderManager) {
        return IOrderManager(_getDependencyAddress(Identifier.ORDER_MANAGER));
    }

    function _getPositionManager() internal view returns (IPositionManager) {
        return IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getRiskParameter() internal view returns (IRiskParameter) {
        return IRiskParameter(_getDependencyAddress(Identifier.RISK_PARAMETER));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }

    function _getOracle() internal view returns (IOracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }

    function _getRiskController() internal view returns (IRiskController) {
        return IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER));
    }

    function _getFundingRate() internal view returns (IFundingRate) {
        return IFundingRate(_getDependencyAddress(Identifier.FUNDING_RATE));
    }
}

