pragma solidity ^0.8.30;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IExecutor } from "./../../interfaces/IExecutor.sol";
import { IFundingRate } from "./../../interfaces/IFundingRate.sol";
import { IMatcher } from "./../../interfaces/IMatcher.sol";
import { IOracle } from "./../../interfaces/IOracle.sol";
import { IPoolManager } from "./../../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { IRiskParameter } from "./../../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../../interfaces/ITradingVault.sol";
import { ExecuteHelper } from "./../../libraries/ExecuteHelper.sol";
import { LibPositionMetadata } from "./../../libraries/Position.sol";
import { PositionHelper } from "./../../libraries/PositionHelper.sol";
import { TradingHelper } from "./../../libraries/TradingHelper.sol";
import {
    Errors,
    MarketMetadata,
    PoolMetadata,
    PositionMetadata,
    OrderId,
    PositionId,
    MatchType,
    Operation,
    Direction
} from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";
import { ILiquidationExecuteFacet } from "./../interfaces/ILiquidationExecuteFacet.sol";
import { ExecutorBaseFacet } from "./ExecutorBaseFacet.sol";

/// @title LiquidationExecuteFacet
/// @notice Facet for handling position liquidation execution
contract LiquidationExecuteFacet is ExecutorBaseFacet, ILiquidationExecuteFacet {
    using LibPositionMetadata for PositionMetadata;
    using PrecisionUtils for uint256;

    struct LiquidateADLParams {
        IPositionManager positionManager;
        PoolMetadata pool;
        PositionMetadata position;
        MarketMetadata market;
        PositionId positionId;
        address owner;
        uint256 liquidatePrice;
        uint256 liquidateSize;
        uint256 marketPrice;
    }

    /// @inheritdoc ILiquidationExecuteFacet
    function liquidateExecute(LiquidatePositionParams calldata params) external override onlyKeeper {
        IPositionManager positionManager = _getPositionManager();
        PositionMetadata memory position = positionManager.getPosition(params.positionId);
        require(position.size > 0, Errors.InvalidPosition(params.positionId));

        IPoolManager poolManager = _getPoolManager();
        PoolMetadata memory pool = poolManager.getPool(position.poolId);
        ITradingVault tradingVault = ITradingVault(pool.tradingVault);
        IOracle oracle = _getOracle();
        (uint256 rewindPrice, uint64 publishTime) = oracle.getRewindPrice(position.poolId);
        require(publishTime >= position.lastUpdateTime, Errors.InvalidRewindPrice());
        (uint256 marketPrice, ) = oracle.getMarketPrice(position.poolId);

        IFundingRate fundingRate = _getFundingRate();
        IRiskParameter.PoolConfigParams memory poolConfigParams = _getRiskParameter().getPoolConfigParams(position.riskTier);
        address owner = positionManager.getPositionOwner(params.positionId);
        (bool isHealthy, ) = PositionHelper.checkPositionHealthy(
            position,
            fundingRate,
            tradingVault,
            poolManager,
            positionManager,
            poolConfigParams,
            pool,
            params.positionId,
            rewindPrice,
            owner
        );
        require(!isHealthy, Errors.PositionRemainsHealthy(params.positionId));

        uint256 liquidatePrice = PositionHelper.calculateLiquidationPrice(
            position,
            fundingRate,
            tradingVault,
            poolManager,
            positionManager,
            poolConfigParams,
            pool,
            params.positionId,
            rewindPrice,
            owner
        );
        (MatchType matchType, OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) = _liquidateExecute(
            params.adlPositions,
            position,
            params.positionId,
            liquidatePrice,
            position.size,
            marketPrice
        );

        _getEmiter().emitExecutionMatched(
            IEmiter.ExecutionMatchedParams({
                poolId: position.poolId,
                triggerOrderIds: triggerOrderIds,
                matchedOrderIds: matchedOrderIds,
                matchType: matchType,
                price: liquidatePrice
            })
        );
    }

    /// @notice Internal function to execute liquidation
    /// @param adlPositions Array of ADL positions
    /// @param position Position to liquidate
    /// @param positionId ID of the position
    /// @param liquidatePrice Liquidate execution price
    /// @param liquidateSize Liquidate execution size
    /// @param marketPrice Market price
    /// @return matchType Type of match executed
    /// @return triggerOrderIds Array of trigger order IDs
    /// @return matchedOrderIds Array of matched order IDs
    function _liquidateExecute(
        IExecutor.ADLPositionParams[] calldata adlPositions,
        PositionMetadata memory position,
        PositionId positionId,
        uint256 liquidatePrice,
        uint256 liquidateSize,
        uint256 marketPrice
    ) internal returns (MatchType matchType, OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        IPositionManager positionManager = _getPositionManager();
        (, MarketMetadata memory market) = _getPoolManager().getPoolMarket(position.poolId);
        address owner = positionManager.getPositionOwner(positionId);

        PoolMetadata memory pool = _getPoolManager().getPool(position.poolId);
        OrderId liquidateOrderId;
        bool needADL = ExecuteHelper.needADL(positionManager, pool, position.direction, liquidateSize, liquidatePrice);
        if (needADL) {
            matchType = MatchType.LiquidationADL;
            (liquidateSize, liquidateOrderId, triggerOrderIds, matchedOrderIds) = _liquidateADL(
                LiquidateADLParams({
                    positionManager: positionManager,
                    pool: pool,
                    position: position,
                    market: market,
                    positionId: positionId,
                    owner: owner,
                    liquidatePrice: liquidatePrice,
                    liquidateSize: liquidateSize,
                    marketPrice: marketPrice
                }),
                adlPositions
            );
        } else {
            matchType = MatchType.Liquidation;
            (liquidateOrderId, triggerOrderIds, matchedOrderIds) = _getMatcher().createAndMatchPool(
                IMatcher.CreateOrderParams({
                    poolId: position.poolId,
                    positionId: positionId,
                    owner: owner,
                    direction: position.direction,
                    isLiquidation: true
                }),
                liquidateSize,
                liquidatePrice,
                msg.sender
            );
        }

        _getEmiter().emitPositionLiquidated(
            IEmiter.PositionLiquidatedParams({
                broker: position.broker,
                user: owner,
                poolId: position.poolId,
                positionId: positionId,
                orderId: liquidateOrderId,
                positionSize: position.size,
                liquidationSize: liquidateSize,
                liquidationPrice: liquidatePrice
            })
        );
    }

    function _liquidateADL(
        LiquidateADLParams memory params,
        IExecutor.ADLPositionParams[] calldata adlPositions
    ) internal returns (uint256 liquidationSize, OrderId liquidateOrderId, OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        (ExecuteHelper.ADLPositionExecute[] memory adlPositionExecutes, uint256 adlTotalNotional) = ExecuteHelper.calculateADLPositionExecute(
            ExecuteHelper.CalculateADLExecuteParams({
                positionManager: params.positionManager,
                fundingRate: _getFundingRate(),
                poolManager: _getPoolManager(),
                riskParameter: _getRiskParameter(),
                pool: params.pool,
                orderDirection: params.position.direction,
                orderId: OrderId.wrap(0),
                needAdlNotional: params.liquidateSize.mulPrice(params.liquidatePrice),
                marketPrice: params.marketPrice
            }),
            adlPositions
        );
        uint256 adlTotalSize = adlTotalNotional.divPrice(params.liquidatePrice);
        liquidationSize = adlTotalSize;

        IMatcher.MatchPoolExecuteParams memory matchPoolExecuteParams;
        if (adlTotalSize < params.liquidateSize) {
            matchPoolExecuteParams = _needPoolExecute(
                params.positionManager,
                params.pool,
                params.market,
                params.position.direction,
                params.liquidateSize - adlTotalSize,
                params.liquidatePrice
            );
            liquidationSize += matchPoolExecuteParams.executeSize;
        }

        (liquidateOrderId, triggerOrderIds, matchedOrderIds) = _getMatcher().createAndMatchAdlPositions(
            IMatcher.CreateOrderParams({
                poolId: params.position.poolId,
                positionId: params.positionId,
                owner: params.owner,
                direction: params.position.direction,
                isLiquidation: true
            }),
            IMatcher.MatchAdlPositionsParams({
                triggerOrderId: OrderId.wrap(0),
                adlPositionExecutes: adlPositionExecutes,
                executeSize: Math.min(adlTotalSize, params.liquidateSize),
                executePrice: params.liquidatePrice,
                keeper: msg.sender,
                matchPoolExecuteParams: matchPoolExecuteParams
            })
        );
    }

    function _needPoolExecute(
        IPositionManager positionManager,
        PoolMetadata memory pool,
        MarketMetadata memory market,
        Direction direction,
        uint256 executeSize,
        uint256 executePrice
    ) internal view returns (IMatcher.MatchPoolExecuteParams memory matchPoolExecuteParams) {
        uint256 availableLiquiditySize = TradingHelper.availableLiquiditySize(
            pool.poolId,
            IPoolVault(pool.poolVault),
            positionManager,
            market.baseReserveRatio,
            market.quoteReserveRatio,
            Operation.Decrease,
            direction,
            executePrice
        );
        uint256 poolExecuteSize = Math.min(availableLiquiditySize, executeSize);
        if (poolExecuteSize == 0) return matchPoolExecuteParams;

        matchPoolExecuteParams.needPoolExecute = true;
        matchPoolExecuteParams.isTriggerOrder = true;
        matchPoolExecuteParams.executeSize = poolExecuteSize;
        matchPoolExecuteParams.executePrice = executePrice;
        return matchPoolExecuteParams;
    }
}

