// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IDisputeCourt } from "./../../interfaces/IDisputeCourt.sol";
import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IMatcher } from "./../../interfaces/IMatcher.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { ExecuteHelper } from "./../../libraries/ExecuteHelper.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { Errors, PoolMetadata, PositionMetadata, OrderId, PoolId, PositionId } from "./../../types/Types.sol";
import { IRiskControlCloseFacet } from "./../interfaces/IRiskControlCloseFacet.sol";
import { ExecutorBaseFacet } from "./ExecutorBaseFacet.sol";

/// @title RiskControlCloseFacet
/// @notice Facet for closing risk control positions
contract RiskControlCloseFacet is ExecutorBaseFacet, IRiskControlCloseFacet {
    /// @inheritdoc IRiskControlCloseFacet
    function riskControlCloseExecute(RiskControlCloseParams calldata params) external override onlyKeeper {
        IPositionManager positionManager = _getPositionManager();
        IDisputeCourt disputeCourt = _getDisputeCourt();
        require(disputeCourt.canRiskControlClose(params.caseId), Errors.RiskCloseNotAllowed());

        for (uint256 i = 0; i < params.positionIds.length; ++i) {
            PositionId positionId = PositionId.wrap(params.positionIds[i]);
            PositionMetadata memory position = positionManager.getPosition(positionId);
            address owner = positionManager.getPositionOwner(positionId);

            // Skip invalid positions
            if (
                PoolId.unwrap(position.poolId) != PoolId.unwrap(params.poolId) ||
                position.size == 0 ||
                !disputeCourt.isCaseRespondents(params.caseId, owner)
            ) continue;

            _closePosition(position, positionId, owner);
        }
    }

    /// @notice Internal function to close a single position
    /// @param position Position metadata
    /// @param positionId Position ID
    /// @param owner Position owner
    function _closePosition(PositionMetadata memory position, PositionId positionId, address owner) internal {
        PoolMetadata memory pool = _getPoolManager().getPool(position.poolId);
        (uint256 marketPrice, ) = _getOracle().getMarketPrice(position.poolId);

        if (_checkADL(_getEmiter(), _getPositionManager(), pool, position, positionId, position.size, marketPrice, position.broker, owner)) return;

        (OrderId closeOrderId, , ) = _getMatcher().createAndMatchPool(
            IMatcher.CreateOrderParams({
                poolId: position.poolId,
                positionId: positionId,
                owner: owner,
                direction: position.direction,
                isLiquidation: false
            }),
            position.size,
            marketPrice,
            msg.sender
        );

        // Emit risk control close event
        _getEmiter().emitPositionRiskControlClosed(
            IEmiter.PositionRiskControlClosedParams({
                broker: position.broker,
                user: owner,
                poolId: position.poolId,
                positionId: positionId,
                orderId: closeOrderId,
                positionSize: position.size,
                executePrice: marketPrice,
                reason: "RiskControl"
            })
        );
    }

    function _checkADL(
        IEmiter emiter,
        IPositionManager positionManager,
        PoolMetadata memory pool,
        PositionMetadata memory position,
        PositionId positionId,
        uint256 executeSize,
        uint256 executePrice,
        address broker,
        address owner
    ) internal returns (bool interrupt) {
        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(pool.poolId);
        if (ExecuteHelper.hasEarlyClosePrice(position, oiTracker.tracker)) return false;

        if (!ExecuteHelper.needADL(positionManager, pool, position.direction, executeSize, executePrice)) return false;

        emiter.emitOrderMarkedADL(
            IEmiter.OrderMarkedADLParams({ broker: broker, user: owner, poolId: pool.poolId, orderId: OrderId.wrap(0), positionId: positionId })
        );
        return true;
    }

    function _getDisputeCourt() internal view returns (IDisputeCourt) {
        return IDisputeCourt(_getDependencyAddress(Identifier.DISPUTE_COURT));
    }
}

