// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

/// @title LibExecutor
/// @notice Storage library for Executor diamond
library LibExecutor {
    /// @notice Storage position to avoid collisions
    bytes32 public constant EXECUTOR_STORAGE_POSITION = keccak256("myx.executor.storage");

    error AlreadyInitialized();

    /// @notice Executor diamond storage
    /// @param addressManager Address manager for dependency injection
    /// @param initialized Whether storage is initialized
    struct ExecutorStorage {
        address addressManager;
        bool initialized;
    }

    /// @notice Get the executor storage
    /// @return es ExecutorStorage struct
    function executorStorage() internal pure returns (ExecutorStorage storage es) {
        bytes32 position = EXECUTOR_STORAGE_POSITION;
        assembly {
            es.slot := position
        }
    }

    /// @notice Initialize executor storage with address manager
    /// @param _addressManager Address of the address manager contract
    function initializeStorage(address _addressManager) internal {
        ExecutorStorage storage es = executorStorage();
        require(!es.initialized, AlreadyInitialized());

        es.addressManager = _addressManager;
        es.initialized = true;
    }

    /// @notice Get the address manager
    /// @return Address of the address manager
    function getAddressManager() internal view returns (address) {
        return executorStorage().addressManager;
    }

    /// @notice Check if storage is initialized
    /// @return True if initialized, false otherwise
    function isInitialized() internal view returns (bool) {
        return executorStorage().initialized;
    }
}

