pragma solidity ^0.8.30;

/******************************************************************************\
* Executor Diamond Initialization Contract
* Used to initialize state variables in the ExecutorDiamond during deployment or upgrade
/******************************************************************************/

import { IDiamondCut } from "./../../dependencies/EIP2535/interfaces/IDiamondCut.sol";
import { IDiamondLoupe } from "./../../dependencies/EIP2535/interfaces/IDiamondLoupe.sol";
import { IERC165 } from "./../../dependencies/EIP2535/interfaces/IERC165.sol";
import { IERC173 } from "./../../dependencies/EIP2535/interfaces/IERC173.sol";
import { LibDiamond } from "./../../dependencies/EIP2535/libraries/LibDiamond.sol";
import { IADLExecuteFacet } from "./../interfaces/IADLExecuteFacet.sol";
import { IEarlyCloseFacet } from "./../interfaces/IEarlyCloseFacet.sol";
import { IExecutorInitializeFacet } from "./../interfaces/IExecutorInitializeFacet.sol";
import { ILiquidationExecuteFacet } from "./../interfaces/ILiquidationExecuteFacet.sol";
import { IPoolCloseFacet } from "./../interfaces/IPoolCloseFacet.sol";
import { IPoolExecuteFacet } from "./../interfaces/IPoolExecuteFacet.sol";
import { IRiskControlCloseFacet } from "./../interfaces/IRiskControlCloseFacet.sol";
import { LibExecutor } from "./../libraries/LibExecutor.sol";

/// @title ExecutorInit
/// @notice Executor diamond initialization contract
contract ExecutorInit {
    /// @notice Initialize diamond with interfaces and storage
    /// @param addressManager Address of the address manager contract
    function init(address addressManager) external {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        // Add ERC165 and Diamond standard interfaces
        ds.supportedInterfaces[type(IERC165).interfaceId] = true;
        ds.supportedInterfaces[type(IDiamondCut).interfaceId] = true;
        ds.supportedInterfaces[type(IDiamondLoupe).interfaceId] = true;
        ds.supportedInterfaces[type(IERC173).interfaceId] = true;

        // Add Executor facet interfaces
        ds.supportedInterfaces[type(IPoolExecuteFacet).interfaceId] = true;
        ds.supportedInterfaces[type(IADLExecuteFacet).interfaceId] = true;
        ds.supportedInterfaces[type(ILiquidationExecuteFacet).interfaceId] = true;
        ds.supportedInterfaces[type(IEarlyCloseFacet).interfaceId] = true;
        ds.supportedInterfaces[type(IPoolCloseFacet).interfaceId] = true;
        ds.supportedInterfaces[type(IExecutorInitializeFacet).interfaceId] = true;
        ds.supportedInterfaces[type(IRiskControlCloseFacet).interfaceId] = true;

        // Initialize executor storage
        LibExecutor.initializeStorage(addressManager);
    }
}

