// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { IBrokerFeeCallback } from "../broker/IBrokerFeeCallback.sol";
import { AssetClass } from "./../types/Types.sol";

/**
 * @title IBroker
 * @notice Interface for broker contracts that handle trading operations and fee management
 */
interface IBroker is IBrokerFeeCallback {
    /**
     * @notice Fee rate configuration for an asset class
     * @param takerFeeRate Fee rate for takers (in basis points)
     * @param makerFeeRate Fee rate for makers (in basis points)
     */
    struct FeeRate {
        uint32 takerFeeRate;
        uint32 makerFeeRate;
    }

    /**
     * @notice Add-on fee tier configuration
     * @param takerFeeRate Additional taker fee rate (in basis points)
     * @param makerFeeRate Additional maker fee rate (in basis points)
     */
    struct AddOnFeeTier {
        uint32 takerFeeRate;
        uint32 makerFeeRate;
    }

    /**
     * @notice User-specific fee and referral data
     * @param tier Fee tier assigned to the user
     * @param referrer Address of the user's referrer
     * @param totalReferralRebatePct Total percentage of fees given as referral rebates
     * @param referrerRebatePct Percentage of total rebate given to the referrer
     */
    struct UserFeeData {
        uint8 tier;
        address referrer;
        uint32 totalReferralRebatePct;
        uint32 referrerRebatePct;
        uint64 expiry;
    }

    struct SetUserFeeDataParams {
        address user;
        uint64 nonce;
        uint64 deadline;
        UserFeeData feeData;
        bytes signature;
    }

    /**
     * @notice Parameters for updating a single base fee rate
     * @param assetClass Asset class to update
     * @param isEnable Whether the asset class should be enabled
     * @param baseFeeRate Base fee rate for the asset class
     */
    struct UpdateBaseFeeRateParams {
        AssetClass assetClass;
        bool isEnable;
        FeeRate baseFeeRate;
    }

    /**
     * @notice Parameters for updating a single add-on fee tier
     * @param assetClass Asset class for the fee tier
     * @param riskTier Risk tier for the fee tier
     * @param feeTier Fee tier number
     * @param addOnFeeRate Fee rate for the tier
     */
    struct UpdateAddOnFeeTierParams {
        AssetClass assetClass;
        uint8 riskTier;
        uint8 feeTier;
        FeeRate addOnFeeRate;
    }

    /**
     * @notice Initializes the broker contract
     * @param addressManager Address of the address manager contract
     * @param owner Address that will own this broker
     * @param brokerName Human-readable name for the broker
     * @param brokerSigners Array of authorized signer addresses
     * @param assetClasses Array of supported asset classes
     * @param baseFeeRates Array of base fee rates corresponding to asset classes
     */
    function initialize(
        address addressManager,
        address owner,
        string memory brokerName,
        address[] memory brokerSigners,
        AssetClass[] memory assetClasses,
        FeeRate[] memory baseFeeRates
    ) external;

    /**
     * @notice Returns the human-readable name of the broker
     * @return The broker's name
     */
    function name() external view returns (string memory);

    /**
     * @notice Returns whether the broker is currently active
     * @return True if the broker is active, false otherwise
     */
    function isActive() external view returns (bool);

    /**
     * @notice Returns the base fee rates for a specific asset class
     * @param assetClass Asset class
     * @return baseFeeRate Base fee rate for the asset class
     */
    function getBaseFeeRate(AssetClass assetClass) external view returns (FeeRate memory baseFeeRate);

    /**
     * @notice Returns the add-on fee rates for a specific tier
     * @param assetClass Asset class for the fee tier
     * @param riskTier Risk tier for the fee tier
     * @param feeTier The fee tier to query
     * @return takerFeeRate Add-on taker fee rate for the tier
     * @return makerFeeRate Add-on maker fee rate for the tier
     */
    function getAddOnFeeTier(AssetClass assetClass, uint8 riskTier, uint8 feeTier) external view returns (uint32 takerFeeRate, uint32 makerFeeRate);

    /**
     * @notice Returns all active fee tier numbers
     * @return Array of active fee tier numbers
     */
    function activeFeeTiers(AssetClass assetClass, uint8 riskTier) external view returns (uint256[] memory);

    /**
     * @notice Returns all supported asset classes
     * @return Array of supported asset class numbers
     */
    function supportedAssetClasses() external view returns (uint256[] memory);

    /**
     * @notice Gets the fee rates for a specific user and asset class
     * @param user Address of the user
     * @param assetClass Asset class for the fee calculation
     * @param riskTier Risk tier for the fee calculation
     * @return takerFeeRate Total taker fee rate for the user
     * @return makerFeeRate Total maker fee rate for the user (can be negative)
     * @return baseTakerFeeRate Base taker fee rate before add-ons
     * @return baseMakerFeeRate Base maker fee rate before add-ons
     */
    function getUserFeeRate(
        address user,
        AssetClass assetClass,
        uint8 riskTier
    ) external view returns (uint32 takerFeeRate, int32 makerFeeRate, uint32 baseTakerFeeRate, uint32 baseMakerFeeRate);

    /**
     * @notice Updates the broker's active status
     * @param active New active status for the broker
     * @dev Only callable by the broker manager
     */
    function updateBrokerStatus(bool active) external;

    /**
     * @notice Updates base fee rates for multiple asset classes
     * @param params Array of parameters, each containing asset class, enable flag, and fee rate
     * @dev Only callable by the broker manager. Each element is a complete update unit.
     */
    function updateBaseFeeRates(IBroker.UpdateBaseFeeRateParams[] calldata params) external;

    function checkAndResetExpiredTier(address user) external;
}

