// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { PoolId } from "./../types/Types.sol";

interface IExchange {
    struct ExchangeParams {
        PoolId poolId;
        uint256 sourceIn;
        uint256 minTargetOut;
        address recipient;
    }

    function getExchangeable(
        PoolId poolId,
        uint256 price
    ) external view returns (uint256 maxBaseIn, uint256 maxQuoteIn, uint256 maxBaseOut, uint256 maxQuoteOut);

    function getExchangeableBaseToken(PoolId poolId, uint256 price) external view returns (uint256 maxBaseIn, uint256 maxQuoteOut);

    function getExchangeableQuoteToken(PoolId poolId, uint256 price) external view returns (uint256 maxQuoteIn, uint256 maxBaseOut);

    function exchangeBaseToQuote(ExchangeParams calldata params) external returns (uint256 usedBase, uint256 receivedQuote);

    function exchangeQuoteToBase(ExchangeParams calldata params) external returns (uint256 usedQuote, uint256 receivedBase);
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { PoolId } from "./../types/Types.sol";

/**
 * @title IExchangeCallback
 * @notice Exchange callback interface for token exchange operations
 * @dev This interface is used when contracts need to request tokens from the caller.
 *      The caller implements this interface to handle token provision requests.
 */
interface IExchangeCallback {
    /**
     * @notice Callback function to handle token exchange requests
     * @param poolId The pool ID where the exchange is happening
     * @param tokenIn Address of the token that needs to be provided
     * @param requiredAmount Exact amount of tokens that must be transferred
     * @param data User-provided bytes forwarded to the callback for custom use
     * @dev Called by contracts when they need tokens from the caller.
     *      The implementer must transfer the exact required amount to the calling contract.
     */
    function onExchange(PoolId poolId, address tokenIn, uint256 requiredAmount, bytes calldata data) external;
}

