// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.24;

import { TxId, PoolId } from "../types/Types.sol";
import { IForwarder } from "./IForwarder.sol";
import { IOracle } from "./IOracle.sol";

/// @title IExecutionPool
interface IExecutionPool {
    struct PendingExecution {
        address from;
        address to;
        uint256 value;
        uint256 gas;
        uint256 gasEscrow;
        uint48 createdAt;
        uint48 deadline;
        bytes data;
    }

    event ExecutionSubmitted(TxId txId, PoolId[] poolId, address from, uint64 deadline);
    event ExecutionCancelled(TxId txId, string remark);
    event ExecutionExecuted(TxId[] txIds);
    event GasCollected(TxId[] txIds, uint256 gasAmount);
    event GracePeriodUpdated(uint64 gracePeriod);
    event GasEscrowSelectorUpdated(bytes4 selector, uint256 gasEscrow);
    event GasEscrowSelectorRemoved(bytes4 selector);
    event MaxPendingUpdated(uint256 maxPendingPerUser);

    error InvalidGasEscrow();
    error DeadlineInPast();
    error InvalidRequest();
    error InvalidDataLength();
    error PoolNotExists(PoolId);
    error SelectorNotRegistered(bytes4 selector);
    error ExecutionsNotExist(TxId txId);
    error TxIdAlreadyExists(TxId txId);
    error NotExecutionOwner(TxId txId);
    error ExecutionNotExpired(TxId txId);
    error ExecutionExpired(TxId txId);
    error MaxPendingExceeded();
    error InsufficientGasEscrow();
    error RefundFailed(TxId txId);
    error CollectFailed();
    error GracePeriodNotExpired();
    error RefundExceedsEscrow(uint256 refund, uint256 escrow);

    /// @notice Returns the stored PendingExecution for a given txId.
    function getExecutionRequest(TxId txId) external view returns (bool, IForwarder.ForwardRequestData memory);

    /// @notice Submit a new execution request with a fixed gas escrow.
    ///         msg.value must equal the contract's gasEscrow amount.
    /// @param txId Caller-provided unique identifier.
    /// @param execution ForwardRequestData to be relayed by the Forwarder.
    function submit(TxId txId, PendingExecution calldata execution, PoolId[] memory updatePricePoolIds) external payable;

    /// @notice Cancel a pending execution and reclaim the gas escrow.
    ///         Only callable by the original submitter.
    /// @param txId Execution ID to cancel.
    function cancel(TxId txId) external;

    /// @notice Allow anyone to execute a pending execution after the grace period has passed.
    ///         Updates oracle prices and delegates execution to the Forwarder.
    /// @param txId Execution ID to execute.
    /// @param params Oracle price update parameters (msg.value forwarded as oracle fee).
    function executePublic(
        TxId txId,
        IOracle.UpdateOraclePriceParams[] calldata params
    ) external payable;

    /// @notice Cancel an expired execution and refund the gas escrow to the original submitter.
    ///         Callable by the Forwarder once the execution's deadline has passed.
    /// @param txId Execution ID to cancel.
    function cancelExpired(TxId txId) external;

    /// @notice Batch-consume pending executions, collect escrowed ETH to Paymaster.
    ///         Only callable by the Forwarder.
    /// @param txIds Array of execution IDs to consume.
    function consumeExecutions(TxId[] calldata txIds) external;

    /// @notice Set the grace period before public execution is allowed.
    function setGracePeriod(uint64 _gracePeriod) external;

    /// @notice Set the gas escrow amount for a specific function selector.
    function setGasEscrowForSelector(bytes4 selector, uint256 escrow) external;

    /// @notice Remove the gas escrow configuration for a specific function selector.
    function removeGasEscrowForSelector(bytes4 selector) external;

    /// @notice Returns the gas escrow amount for a specific function selector.
    function getGasEscrowForSelector(bytes4 selector) external view returns (uint256);

    /// @notice Returns all registered selectors and their gas escrow amounts.
    function getAllGasEscrowSelectors() external view returns (bytes32[] memory selectors, uint256[] memory escrows);

    /// @notice Set the maximum number of pending executions per user.
    function setMaxPendingCount(uint256 _maxPendingCount) external;
}

