// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { OrderMetadata, OrderTPSLData, PoolId, PositionId, Direction, OrderId, OrderTypes } from "./../types/Types.sol";

/// @title IOrderManager
/// @notice Interface for order management functionality
interface IOrderManager {
    struct FillOrderParams {
        // Order ID to fill
        OrderId orderId;
        // Position ID associated with the order
        PositionId positionId;
        // Size of the fill
        uint256 fillSize;
        // Price at which order is filled
        uint256 fillPrice;
        // Realized profit/loss
        int256 realizedPnl;
        // Trading fee amount
        int256 tradingFee;
        // Funding fee amount
        int256 fundingFee;
        // Keeper address executing the order
        address keeper;
        // Whether this is a forced close
        bool forceClose;
    }

    /// @notice Place a new trading order using position salt
    /// @param userPositionSalt Unique salt value used to compute position ID
    /// @param params Parameters for the order to be placed
    /// @return orderId Created order ID
    /// @dev The PositionId is computed from PositionKey(poolId, user, direction, salt).
    ///      Use this function for new positions or when you know your position salt.
    function placeOrderWithSalt(uint64 userPositionSalt, OrderTypes.PlaceOrderParams calldata params) external returns (OrderId orderId);

    /// @notice Place a new trading order for an existing position
    /// @param positionId Position ID of the existing position to operate on
    /// @param params Parameters for the order to be placed
    /// @return orderId Created order ID
    /// @dev Use this function when you already have the PositionId (e.g., for transferred positions
    ///      or when querying existing positions). The position must already exist.
    ///      For new positions, use placeOrderWithSalt instead.
    function placeOrderWithPosition(PositionId positionId, OrderTypes.PlaceOrderParams calldata params) external returns (OrderId orderId);

    /// @notice Cancel an existing order
    /// @param orderId Order ID to cancel
    function cancelOrder(OrderId orderId) external;

    /// @notice Cancel multiple orders
    /// @param orderIds Array of order IDs to cancel
    function cancelOrders(OrderId[] calldata orderIds) external;

    /// @notice Update an existing order
    /// @param params Order update parameters
    function updateOrder(OrderTypes.UpdateOrderParams calldata params) external;

    /// @notice Fill an order with execution details
    /// @return tpOrderId Take profit order ID (if created)
    /// @return slOrderId Stop loss order ID (if created)
    function fillOrder(FillOrderParams calldata params) external returns (OrderId tpOrderId, OrderId slOrderId);

    /// @notice Complete an order execution
    function completeOrder(OrderId orderId, PositionId positionId) external;

    /// @notice Mark an order as incomplete
    /// @param orderId Order ID to mark as incomplete
    /// @param remark Reason for incompletion
    function uncompleteOrder(OrderId orderId, string calldata remark) external;

    /// @notice Mark multiple orders as incomplete
    /// @param orderIds Array of order IDs to mark as incomplete
    /// @param remark Reason for incompletion
    function uncompleteOrders(uint256[] calldata orderIds, string calldata remark) external;

    /// @notice Remove all orders for a position
    /// @param positionId Position ID to remove orders for
    function removePositionOrders(PositionId positionId) external;

    /// @notice Save an automatic decrease order (for liquidations/early close)
    /// @param user User address
    /// @param poolId Pool ID
    /// @param positionId Position ID
    /// @param size Order size
    /// @param price Order price
    /// @param direction Order direction
    /// @return orderId Created order ID
    function saveAutoDecreaseOrder(
        address user,
        PoolId poolId,
        PositionId positionId,
        uint256 size,
        uint256 price,
        Direction direction
    ) external returns (OrderId orderId);

    /// @notice Get order metadata
    /// @param orderId Order ID to query
    /// @return order Order metadata
    function getOrder(OrderId orderId) external view returns (OrderMetadata memory order);

    /// @notice Get order metadata with TP/SL data
    /// @param orderId Order ID to query
    /// @return order Order metadata
    /// @return tpsl TP/SL data
    function getOrderWithTPSL(OrderId orderId) external view returns (OrderMetadata memory order, OrderTPSLData memory tpsl);

    /// @notice Get TP/SL data for an order
    /// @param orderId Order ID to query
    /// @return tpsl TP/SL data
    function getOrderTPSL(OrderId orderId) external view returns (OrderTPSLData memory tpsl);

    /// @notice Check if user owns an order
    /// @param orderId Order ID to check
    /// @param user User address to check
    /// @return isOwner Whether user owns the order
    function isOrderOwner(OrderId orderId, address user) external view returns (bool isOwner);

    /// @notice Check if user owns all orders in array
    /// @param orderIds Array of order IDs to check
    /// @param user User address to check
    /// @return isOwner Whether user owns all orders
    function isAllOrderOwner(OrderId[] calldata orderIds, address user) external view returns (bool isOwner);
}

