// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { IOracle } from "./../interfaces/IOracle.sol";
import { MarketId, PoolId, OracleType } from "./../types/Types.sol";

/// @title Oracle
/// @notice Library for managing oracle price data and operations
library Oracle {
    using Oracle for Data;

    /// @notice Oracle storage data structure
    struct Data {
        // Maximum allowed price age in seconds
        uint32 _priceAge;
        // Market Quote Configuration
        mapping(MarketId marketId => IOracle.MarketQuoteConfig quoteConfig) _marketQuoteConfig;
        // Current prices by pool
        mapping(PoolId poolId => IOracle.Price price) _poolPrices;
        // Oracle feed ids by pool
        mapping(PoolId poolId => mapping(OracleType oracleType => bytes32 oracleFeedId)) _poolOracleFeedIds;
        // Active oracle by pool
        mapping(PoolId poolId => OracleType oracleType) _activeOracleType;
    }

    /// @notice Update maximum allowed price age
    /// @param self Oracle storage data
    /// @param priceAge New price age limit in seconds
    function updatePriceAge(Data storage self, uint32 priceAge) internal {
        self._priceAge = priceAge;
    }

    /// @notice Set oracle feed id for a pool
    /// @param self Oracle storage data
    /// @param poolId Pool to set oracle feed id for
    /// @param oracleType Oracle type to set oracle feed id for
    /// @param oracleFeedId Oracle feed id to set
    function setOracleFeedId(Data storage self, PoolId poolId, OracleType oracleType, bytes32 oracleFeedId) internal {
        self._poolOracleFeedIds[poolId][oracleType] = oracleFeedId;
    }

    /// @notice Set oracle feed id for a pool
    /// @param self Oracle storage data
    /// @param marketId Market to set for
    /// @param applyExchangeRate Exchange Rate to set state for
    /// @param minDeviationRatio min Deviation Ratio to set
    /// @param priceContract price Contract to set
    function setMarketQuoteConfiguration(
        Data storage self,
        MarketId marketId,
        bool applyExchangeRate,
        uint16 minDeviationRatio,
        uint64 heartbeat,
        address priceContract
    ) internal {
        self._marketQuoteConfig[marketId] = IOracle.MarketQuoteConfig({
            priceContract: priceContract,
            applyExchangeRate: applyExchangeRate,
            minDeviationRatio: minDeviationRatio,
            heartbeat: heartbeat
        });
    }

    /// @notice Set oracle feed id for a pool
    /// @param self Oracle storage data
    /// @param marketId Market to set for
    /// @param enable apply Exchange Rate to set
    function switchExchangeRateOnDeviation(Data storage self, MarketId marketId, bool enable) internal {
        self._marketQuoteConfig[marketId].applyExchangeRate = enable;
    }

    /// @notice Update price data for a pool
    /// @param self Oracle storage data
    /// @param poolId Pool to update price for
    /// @param oraclePrice Price from oracle source
    /// @param publishTime Timestamp of price publish
    function updatePrice(Data storage self, PoolId poolId, uint256 oraclePrice, uint64 publishTime) internal {
        self._poolPrices[poolId] = IOracle.Price({ oraclePrice: oraclePrice, publishTime: publishTime });
    }

    /// @notice Get current price age limit
    /// @param self Oracle storage data
    /// @return Maximum allowed price age in seconds
    function getPriceAge(Data storage self) internal view returns (uint32) {
        return self._priceAge;
    }

    /// @notice Get market quote configuration for a market
    /// @param self Oracle storage data
    /// @param marketId Market to get quote configuration for
    /// @return MarketQuoteConfig
    function getMarketQuoteConfig(Data storage self, MarketId marketId) internal view returns (IOracle.MarketQuoteConfig memory) {
        return self._marketQuoteConfig[marketId];
    }

    /// @notice Get oracle feed id for a pool
    /// @param self Oracle storage data
    /// @param poolId Pool to get oracle feed id for
    /// @param oracleType Oracle type to get oracle feed id for
    /// @return Oracle feed id
    function getOracleFeedId(Data storage self, PoolId poolId, OracleType oracleType) internal view returns (bytes32) {
        return self._poolOracleFeedIds[poolId][oracleType];
    }

    /// @notice Get current price data for a pool
    /// @param self Oracle storage data
    /// @param poolId Pool to get price for
    /// @return Current price data
    function getPrice(Data storage self, PoolId poolId) internal view returns (IOracle.Price memory) {
        return self._poolPrices[poolId];
    }

    /// @notice Get the active oracle type for a pool
    /// @param self Oracle storage data
    /// @param poolId Pool to get active oracle type for
    /// @return Active oracle type
    function getActiveOracleType(Data storage self, PoolId poolId) internal view returns (OracleType) {
        return self._activeOracleType[poolId];
    }

    /// @notice Check whether the given oracle type is the active oracle for a pool
    /// @param self Oracle storage data
    /// @param poolId Pool to check
    /// @param oracleType Oracle type to check
    /// @return True if the given oracle type is currently active
    function isOracleTypeActive(Data storage self, PoolId poolId, OracleType oracleType) internal view returns (bool) {
        return self._activeOracleType[poolId] == oracleType;
    }

    /// @notice Switch the active oracle type for a pool
    /// @param self Oracle storage data
    /// @param poolId Pool to switch active oracle type for
    /// @param oracleType New active oracle type
    function switchActiveOracleType(Data storage self, PoolId poolId, OracleType oracleType) internal {
        self._activeOracleType[poolId] = oracleType;
    }

    function resolveUpdatePriceParams(
        IOracle.UpdateOraclePriceParams[] calldata params
    ) internal pure returns (IOracle.UpdateMarketPriceParams[] memory resolved) {
        uint256 len = params.length;
        resolved = new IOracle.UpdateMarketPriceParams[](len);

        for (uint256 i; i < len; ++i) {
            resolved[i] = IOracle.UpdateMarketPriceParams({
                poolId: params[i].poolId,
                oracleType: params[i].oracleType,
                referencePrice: 0,
                oracleUpdateData: params[i].oracleUpdateData,
                publishTime: params[i].publishTime,
                roundId: 0
            });
        }
    }
}

