// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Constants, PositionMetadata, PoolMetadata, PositionId, Direction, Operation, PositionOIChange } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";
import { LibPositionMetadata } from "./Position.sol";
import { TradingHelper } from "./TradingHelper.sol";

/// @title PositionHelper
/// @notice Helper library for position operations
library PositionHelper {
    using LibPositionMetadata for PositionMetadata;
    using PrecisionUtils for uint256;
    using SignedMath for int256;

    function checkPositionHealthy(
        PositionMetadata memory position,
        IFundingRate fundingRate,
        ITradingVault tradingVault,
        IPoolManager poolManager,
        IPositionManager positionManager,
        IRiskParameter.PoolConfigParams memory poolConfig,
        PoolMetadata memory pool,
        PositionId positionId,
        uint256 price,
        address owner
    ) internal view returns (bool, uint256) {
        if (position.size == 0) return (true, 0);

        int256 equity = position.computeEquity(fundingRate, tradingVault, positionManager, pool, positionId, poolConfig.assetClass, price, owner);
        uint256 executionFee = poolManager.getPoolMarketExecutionFee(pool.poolId);
        if (equity <= int256(executionFee)) return (false, type(uint256).max);

        uint256 maintenanceMargin = position.computeMaintenanceMargin(pool, poolConfig.maintainMarginRate, price);
        uint256 marginRatio = (maintenanceMargin * Constants.MARGIN_RATIO_PRECISION) / (uint256(equity) - executionFee);
        return (marginRatio <= Constants.MARGIN_RATIO_PRECISION, marginRatio);
    }

    function checkLeverageHealthy(
        PositionMetadata memory position,
        IFundingRate fundingRate,
        ITradingVault tradingVault,
        IPoolManager poolManager,
        IPositionManager positionManager,
        IRiskParameter.PoolConfigParams memory poolConfig,
        PoolMetadata memory pool,
        PositionId positionId,
        uint256 price,
        address owner
    ) internal view returns (bool) {
        int256 equity = position.computeEquity(fundingRate, tradingVault, positionManager, pool, positionId, poolConfig.assetClass, price, owner);
        uint256 executionFee = poolManager.getPoolMarketExecutionFee(pool.poolId);
        if (equity <= int256(executionFee)) return false;

        uint256 notional = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, position.size.mulPrice(price));
        uint256 leverage = notional / (uint256(equity) - executionFee);
        return leverage <= uint256(poolConfig.leverage);
    }

    function calculateLiquidationPrice(
        PositionMetadata memory position,
        IFundingRate fundingRate,
        ITradingVault tradingVault,
        IPoolManager poolManager,
        IPositionManager positionManager,
        IRiskParameter.PoolConfigParams memory poolConfig,
        PoolMetadata memory pool,
        PositionId positionId,
        uint256 price,
        address owner
    ) internal view returns (uint256) {
        IPositionManager.OITracker memory oi = positionManager.getOITracker(position.poolId);
        PositionOIChange change = getExecuteOIChange(oi, Operation.Decrease, position.direction, position.size);
        int256 netCollateral = position.computeNetCollateral(
            fundingRate,
            tradingVault,
            pool,
            positionId,
            poolConfig.assetClass,
            change,
            price,
            owner
        );
        uint256 executionFee = poolManager.getPoolMarketExecutionFee(pool.poolId);
        if (netCollateral < int256(executionFee)) {
            return price;
        }

        uint8 quoteTokenDecimals = IERC20Metadata(pool.quoteToken).decimals();
        uint8 baseTokenDecimals = IERC20Metadata(pool.baseToken).decimals();

        uint256 effectiveCollateral = uint256(netCollateral) - executionFee;
        uint256 collateralWad = effectiveCollateral.toWad(quoteTokenDecimals);
        uint256 notionalWad = position.size.mulPrice(position.entryPrice).toWad(baseTokenDecimals);
        if (notionalWad == 0) return position.direction == Direction.Long ? 0 : type(uint256).max;

        uint256 ratioWad = collateralWad.divPrecision(notionalWad, 1e18);
        uint256 maintainMarginRateWad = uint256(poolConfig.maintainMarginRate).toWad(Constants.MARGIN_RATIO_DECIMALS);
        if (position.direction == Direction.Long) {
            if (ratioWad >= 1e18) return 0;
            return (position.entryPrice * (1e18 - ratioWad)) / (1e18 - maintainMarginRateWad);
        } else {
            return (position.entryPrice * (1e18 + ratioWad)) / (1e18 + maintainMarginRateWad);
        }
    }

    function getExecuteOIChange(
        IPositionManager.OITracker memory oi,
        Operation operation,
        Direction direction,
        uint256 executeSize
    ) internal pure returns (PositionOIChange oiChange) {
        int256 delta = int256(executeSize);
        if (operation == Operation.Decrease) {
            delta = -delta;
        }
        if (direction == Direction.Short) {
            delta = -delta;
        }

        int256 beforeTracker = oi.tracker;
        int256 afterTracker = beforeTracker + delta;
        return getOIChange(beforeTracker, afterTracker);
    }

    function getOIChange(int256 beforeTracker, int256 afterTracker) internal pure returns (PositionOIChange oiChange) {
        if (beforeTracker >= 0 && afterTracker >= 0) {
            oiChange = afterTracker > beforeTracker ? PositionOIChange.IncreaseLong : PositionOIChange.DecreaseLong;
        } else if (afterTracker <= 0 && beforeTracker <= 0) {
            oiChange = afterTracker < beforeTracker ? PositionOIChange.IncreaseShort : PositionOIChange.DecreaseShort;
        } else {
            oiChange = beforeTracker > 0 ? PositionOIChange.FlipLongToShort : PositionOIChange.FlipShortToLong;
        }
    }
}

