// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { Constants, PoolMetadata, PoolId, Operation, Direction } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";
import { TradeUtils } from "./../utils/TradeUtils.sol";

/// @title TradingHelper
/// @notice Helper library for trading calculations and token conversions
library TradingHelper {
    using PrecisionUtils for uint256;
    using PrecisionUtils for int256;
    using SignedMath for int256;
    using SafeCast for uint256;

    /**
     * @notice Converts an amount from one ERC20 token's decimal format to another.
     *
     * @dev This function normalizes the `source` token amount to 18 decimals (Wad),
     * then converts it to the `target` token's native decimal format.
     * It's useful for standardizing calculations between tokens with different decimals.
     *
     * Example:
     * - source = USDC (6 decimals), target = WETH (18 decimals), amount = 1_000_000 (1 USDC)
     * → returns: 1e18 (1 WETH-style unit)
     *
     * @param source   The ERC20 token address of the source asset
     * @param target   The ERC20 token address of the target asset
     * @param amount   The amount denominated in `source` token's native decimals
     * @return         The equivalent amount in `target` token's native decimals
     */
    function convertTokenAmount(address source, address target, uint256 amount) internal view returns (uint256) {
        uint8 targetDecimals = IERC20Metadata(target).decimals();
        return convertTokenToDecimals(source, targetDecimals, amount);
    }

    /// @notice Convert token amount to specific decimals
    /// @param source Source token address
    /// @param targetDecimals Target decimal precision
    /// @param amount Amount to convert
    /// @return Converted amount
    function convertTokenToDecimals(address source, uint8 targetDecimals, uint256 amount) internal view returns (uint256) {
        uint8 sourceDecimals = IERC20Metadata(source).decimals();
        return amount.toWad(sourceDecimals).fromWad(targetDecimals);
    }

    /// @notice Convert amount from specific decimals to target token format
    /// @param sourceDecimals Source decimal precision
    /// @param target Target token address
    /// @param amount Amount to convert
    /// @return Converted amount
    function convertTokenFromDecimals(uint8 sourceDecimals, address target, uint256 amount) internal view returns (uint256) {
        uint8 targetDecimals = IERC20Metadata(target).decimals();
        return amount.toWad(sourceDecimals).fromWad(targetDecimals);
    }

    /// @notice Convert amount from specific decimals to target token format
    /// @param sourceDecimals Source decimal precision
    /// @param targetDecimals Target decimal precision
    /// @param amount Amount to convert
    /// @return Converted amount
    function convertTokenAmount(uint8 sourceDecimals, uint8 targetDecimals, uint256 amount) internal pure returns (uint256) {
        return amount.toWad(sourceDecimals).fromWad(targetDecimals);
    }

    /// @notice Validate order size
    /// @param pool Pool metadata
    /// @param minTradeUsd Minimum trade size in USD
    /// @param orderSize Order size
    /// @param marketPrice Market price
    /// @return True if order size is valid
    function validateOrderSize(PoolMetadata memory pool, uint256 minTradeUsd, uint256 orderSize, uint256 marketPrice) internal view returns (bool) {
        uint256 minTradeSize = TradingHelper.convertTokenFromDecimals(
            Constants.USD_DECIMALS,
            pool.baseToken,
            minTradeUsd.divPrice(marketPrice)
        );
        return orderSize >= minTradeSize;
    }

    /// @notice Calculate PnL for a position
    /// @param poolMetadata Pool metadata containing token addresses
    /// @param entryPrice Position entry price
    /// @param exitPrice Position exit price
    /// @param size Position size
    /// @param isLong Whether position is long
    /// @return pnl Calculated profit/loss
    function calculatePNL(
        PoolMetadata memory poolMetadata,
        uint256 entryPrice,
        uint256 exitPrice,
        uint256 size,
        bool isLong
    ) internal view returns (int256 pnl) {
        int256 pnlSize = TradeUtils.calculatePNLSize(entryPrice, exitPrice, size, isLong);
        uint256 pnlAbs = convertTokenAmount(poolMetadata.baseToken, poolMetadata.quoteToken, pnlSize.abs());
        return pnlSize >= 0 ? pnlAbs.toInt256() : -pnlAbs.toInt256();
    }

    function calculateFundingFee(
        PoolMetadata memory poolMetadata,
        int256 accruedFundingTracker,
        uint256 positionSize,
        Direction direction
    ) internal view returns (int256) {
        int256 fundingFeeSize = TradeUtils.calculateFundingFeeSize(accruedFundingTracker, positionSize, direction);
        uint256 unsigned = convertTokenAmount(poolMetadata.baseToken, poolMetadata.quoteToken, fundingFeeSize.abs());
        return fundingFeeSize >= 0 ? unsigned.toInt256() : -unsigned.toInt256();
    }

    function makeableSize(IPositionManager positionManager, PoolId poolId, Operation operation, Direction direction) internal view returns (uint256) {
        IPositionManager.OITracker memory oi = positionManager.getOITracker(poolId);
        uint256 longTracker = oi.longSize;
        uint256 shortTracker = oi.shortSize;

        bool isBuy = TradeUtils.getOrderSide(operation, direction);
        if (isBuy) {
            return shortTracker > longTracker ? shortTracker - longTracker : 0;
        } else {
            return longTracker > shortTracker ? longTracker - shortTracker : 0;
        }
    }

    function availableLiquiditySize(
        PoolId poolId,
        IPoolVault poolVault,
        IPositionManager positionManager,
        uint32 baseReserveRatio,
        uint32 quoteReserveRatio,
        Operation operation,
        Direction direction,
        uint256 executePrice
    ) internal view returns (uint256 availableSize) {
        IPoolVault.PoolReserve memory reserve = poolVault.reserveInfo();
        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(poolId);

        bool isBuy = TradeUtils.getOrderSide(operation, direction);
        bool isLongBiased = oiTracker.tracker >= 0;

        uint8 baseDecimals = IERC20Metadata(poolVault.baseToken()).decimals();
        uint8 quoteDecimals = IERC20Metadata(poolVault.quoteToken()).decimals();

        uint256 availableSizeWad = _availableLiquiditySizeWad(
            reserve.baseTotalAmount.toWad(baseDecimals),
            reserve.quoteTotalAmount.toWad(quoteDecimals),
            reserve.baseReservedAmount.toWad(baseDecimals),
            reserve.quoteReservedAmount.toWad(quoteDecimals),
            baseReserveRatio,
            quoteReserveRatio,
            isLongBiased,
            oiTracker.tracker.toWad(baseDecimals),
            isBuy,
            executePrice
        );
        return availableSizeWad.fromWad(baseDecimals);
    }

    function _availableLiquiditySizeWad(
        uint256 baseTotalAmountWad,
        uint256 quoteTotalAmountWad,
        uint256 baseReservedAmountWad,
        uint256 quoteReservedAmountWad,
        uint32 baseReserveRatio,
        uint32 quoteReserveRatio,
        bool isLongBiased,
        int256 trackerWad,
        bool isBuy,
        uint256 executePrice
    ) private pure returns (uint256 availableSize) {
        uint256 unreservedBase = baseTotalAmountWad > baseReservedAmountWad ? baseTotalAmountWad - baseReservedAmountWad : 0;
        uint256 unreservedQuote = quoteTotalAmountWad > quoteReservedAmountWad ? quoteTotalAmountWad - quoteReservedAmountWad : 0;
        if (isLongBiased) {
            if (isBuy) {
                uint256 unreservedQuoteSize = unreservedQuote.divPrice(
                    executePrice.mulPrecision(quoteReserveRatio, Constants.RESERVE_RATIO_PRECISION)
                );
                availableSize = unreservedBase + unreservedQuoteSize;
            } else {
                uint256 quoteSize = quoteTotalAmountWad.divPrice(executePrice);
                uint256 baseSize = baseTotalAmountWad.divPrecision(baseReserveRatio, Constants.RESERVE_RATIO_PRECISION);
                availableSize = uint256(trackerWad) + quoteSize + baseSize;
            }
        } else {
            if (isBuy) {
                uint256 quoteSize = quoteTotalAmountWad.divPrice(executePrice.mulPrecision(quoteReserveRatio, Constants.RESERVE_RATIO_PRECISION));
                availableSize = trackerWad.abs() + baseTotalAmountWad + quoteSize;
            } else {
                uint256 unreservedQuoteSize = unreservedQuote.divPrice(executePrice);
                availableSize = unreservedQuoteSize + unreservedBase.divPrecision(baseReserveRatio, Constants.RESERVE_RATIO_PRECISION);
            }
        }
    }
}

