// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IAddressManager } from "./../interfaces/IAddressManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";

/// @title AddressManager
/// @notice Manages contract addresses and dependency injection
contract AddressManager is Ownable2StepUpgradeable, BaseContractUpgradeable, IAddressManager {
    using EnumerableSetLib for EnumerableSetLib.AddressSet;

    mapping(bytes32 identifier => address contractAddress) private _addresses;
    mapping(address contractAddress => bytes32 identifier) private _contractIdentifiers;
    EnumerableSetLib.AddressSet private _whitelistSwapRouter;

    error NotEmptyAddress();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner) public initializer {
        __Ownable2Step_init();
        __BaseContractUpgradeable_init(address(this), new bytes32[](0));

        _transferOwnership(initialOwner);
    }

    /// @inheritdoc IAddressManager
    function getRoleManager() external view override returns (address) {
        return _getAddress(Identifier.ROLE_MANAGER);
    }

    /// @inheritdoc IAddressManager
    function getAddresses(bytes32[] memory identifiers) external view override returns (address[] memory addresses) {
        addresses = new address[](identifiers.length);
        for (uint256 i = 0; i < identifiers.length; ++i) {
            addresses[i] = _getAddress(identifiers[i]);
        }
    }

    /// @inheritdoc IAddressManager
    function getAddress(bytes32 identifier) external view override returns (address) {
        return _getAddress(identifier);
    }

    /// @inheritdoc IAddressManager
    function getIdentifier(address contractAddress) external view override returns (bytes32) {
        return _contractIdentifiers[contractAddress];
    }

    /// @inheritdoc IAddressManager
    function setAddress(bytes32 identifier, address newAddress) external override onlyOwner {
        address oldAddress = _addresses[identifier];

        delete _addresses[_contractIdentifiers[oldAddress]];
        delete _contractIdentifiers[oldAddress];

        _addresses[identifier] = newAddress;
        _contractIdentifiers[newAddress] = identifier;
        emit AddressUpdated(identifier, oldAddress, newAddress);
    }

    function _getAddress(bytes32 identifier) internal view returns (address) {
        return _addresses[identifier];
    }
}

