// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { IAddressManager } from "./../interfaces/IAddressManager.sol";
import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { LibPositionMetadata } from "./../libraries/Position.sol";
import { PositionHelper } from "./../libraries/PositionHelper.sol";
import { PoolMetadata, PositionMetadata, PositionId } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";

contract ContractHelper {
    using PrecisionUtils for uint256;
    using SafeCast for uint256;
    using SafeERC20 for IERC20;
    using LibPositionMetadata for PositionMetadata;

    /// @notice Address manager contract address
    address public immutable ADDRESS_MANAGER;

    constructor(address addressManager) {
        ADDRESS_MANAGER = addressManager;
    }

    function checkPositionHealthy(PositionId positionId, uint256 price) external view returns (bool, uint256) {
        IPositionManager positionManager = IPositionManager(_getAddress(Identifier.POSITION_MANAGER));
        IPoolManager poolManager = IPoolManager(_getAddress(Identifier.POOL_MANAGER));
        IFundingRate fundingRate = IFundingRate(_getAddress(Identifier.FUNDING_RATE));
        IRiskParameter riskParameter = IRiskParameter(_getAddress(Identifier.RISK_PARAMETER));

        PositionMetadata memory position = positionManager.getPosition(positionId);
        address owner = positionManager.getPositionOwner(positionId);
        PoolMetadata memory pool = poolManager.getPool(position.poolId);
        ITradingVault tradingVault = ITradingVault(pool.tradingVault);
        IRiskParameter.PoolConfigParams memory poolConfigParams = riskParameter.getPoolConfigParams(position.riskTier);

        return
            PositionHelper.checkPositionHealthy(
                position,
                fundingRate,
                tradingVault,
                poolManager,
                positionManager,
                poolConfigParams,
                pool,
                positionId,
                price,
                owner
            );
    }

    function _getAddress(bytes32 identifier) internal view returns (address) {
        return IAddressManager(ADDRESS_MANAGER).getAddress(identifier);
    }
}

