// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { PoolId } from "./../types/Types.sol";
import { BaseContractUpgradeable } from "./base/BaseContractUpgradeable.sol";

/// @title Emiter
/// @notice Central event emission contract for protocol events
contract Emiter is BaseContractUpgradeable, IEmiter {
    using EnumerableSetLib for EnumerableSetLib.Bytes32Set;

    uint256 public sequencer;

    mapping(uint256 blockNumber => bool emitted) private _blockHeaderEmitted;
    EnumerableSetLib.Bytes32Set private _allowedIdentifiers;

    error NotAllowedIdentifier();

    modifier ensureBlockHeader() {
        _ensureBlockHeader();
        _;
    }

    modifier ensureAllowedContract() {
        _ensureAllowedContract();
        _;
    }

    modifier ensurePool(PoolId poolId) {
        _ensurePool(poolId);
        _;
    }

    modifier onlyDependencyManager() {
        _onlyDependencyManager();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        bytes32[] memory identifiers = new bytes32[](1);
        identifiers[0] = Identifier.POOL_MANAGER;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    function registerContract(bytes32[] calldata identifiers) external onlyDependencyManager {
        _registerDependencies(identifiers);
        for (uint256 i = 0; i < identifiers.length; ++i) {
            _allowedIdentifiers.add(identifiers[i]);
        }
    }

    function isBlockHeaderEmitted(uint256 blockNumber) external view returns (bool) {
        return _blockHeaderEmitted[blockNumber];
    }

    function emitMarketCreated(MarketCreatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit MarketCreated(
            params.marketId,
            params.deployer,
            params.quoteToken,
            params.baseReserveRatio,
            params.quoteReserveRatio,
            params.oracleFeeUsd,
            params.boostFeeUsd,
            params.boostRefundFeeUsd,
            params.poolPrimeThreshold,
            params.executionFee,
            params.maxExecutionFee,
            params.forwardFee,
            params.maxForwardFee
        );
    }

    function emitPoolDeployed(PoolDeployedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolDeployed(
            params.marketId,
            params.poolId,
            params.deployer,
            params.baseToken,
            params.quoteToken,
            params.basePoolToken,
            params.quotePoolToken
        );
    }

    function emitPoolPrimed(PoolPrimedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolPrimed(params.poolId, params.baseToken, params.quoteToken, params.baseAmount, params.quoteAmount);
    }

    function emitPoolBoosted(PoolBoostedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolBoosted(params.poolId, params.proposer, params.token, params.amount);
    }

    function emitPoolUnboosted(PoolUnboostedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolUnboosted(params.poolId, params.proposer, params.token, params.refundFee);
    }

    function emitPoolReprimed(PoolReprimedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolReprimed(params.poolId, params.primer, params.token, params.amount);
    }

    function emitPoolTrenchFailed(PoolTrenchFailedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolTrenchFailed(params.poolId, params.remark);
    }

    function emitPoolActivated(PoolActivatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolActivated(params.poolId, params.baseToken, params.quoteToken, params.oracleType, params.oracleFeedId);
    }

    function emitPoolPreDeactivated(PoolPreDeactivatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolPreDeactivated(params.poolId, params.remark);
    }

    function emitPoolDeactivated(PoolDeactivatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolDeactivated(params.poolId, params.baseToken, params.quoteToken, params.remark);
    }

    function emitPoolDeposited(PoolDepositedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolDeposited(
            params.poolId,
            params.user,
            params.recipient,
            params.underlyingToken,
            params.poolToken,
            params.underlyingIn,
            params.poolTokenOut,
            params.oraclePrice,
            params.exchangeRate,
            params.poolTokenPrice
        );
    }

    function emitPoolWithdrawn(PoolWithdrawnParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolWithdrawn(
            params.poolId,
            params.user,
            params.recipient,
            params.underlyingToken,
            params.poolToken,
            params.poolTokenIn,
            params.underlyingOut,
            params.rebateOut,
            params.oraclePrice,
            params.exchangeRate,
            params.poolTokenPrice
        );
    }

    function emitLiquidityStopOrderCreated(LiquidityStopOrderCreatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
