// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IBasePool } from "./../interfaces/IBasePool.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IExchange } from "./../interfaces/IExchange.sol";
import { IExchangeCallback } from "./../interfaces/IExchangeCallback.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IOracleReserve } from "./../interfaces/IOracleReserve.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { PoolMetadata, PoolId, PoolState } from "./../types/Types.sol";
import { BaseContractUpgradeable } from "./base/BaseContractUpgradeable.sol";

/// @title Exchange
/// @notice Contract for handling token exchanges between base and quote tokens
contract Exchange is BaseContractUpgradeable, ReentrancyGuardUpgradeable, IExchange, IExchangeCallback {
    using SafeERC20 for IERC20;

    /// @notice Error thrown when output amount is below minimum expected
    /// @param expected Expected minimum output amount
    /// @param actual Actual output amount received
    error ExceedMinOutput(uint256 expected, uint256 actual);
    error NotAllowedCaller(address caller);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the exchange contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) external initializer {
        __ReentrancyGuard_init();

        bytes32[] memory identifiers = new bytes32[](5);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.ORACLE;
        identifiers[2] = Identifier.ORACLE_RESERVE;
        identifiers[3] = Identifier.EMITER;
        identifiers[4] = Identifier.BASE_POOL;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @inheritdoc IExchange
    function getExchangeable(
        PoolId poolId,
        uint256 price
    ) external view override returns (uint256 maxBaseIn, uint256 maxQuoteIn, uint256 maxBaseOut, uint256 maxQuoteOut) {
        (maxBaseIn, maxQuoteOut) = getExchangeableBaseToken(poolId, price);
        (maxQuoteIn, maxBaseOut) = getExchangeableQuoteToken(poolId, price);
    }

    /// @inheritdoc IExchange
    function getExchangeableBaseToken(PoolId poolId, uint256 price) public view override returns (uint256 maxBaseIn, uint256 maxQuoteOut) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        (uint256 baseIn, uint256 quoteOut) = ITradingVault(pool.tradingVault).getExchangeableBaseProfit(price);
        maxBaseIn += baseIn;
        maxQuoteOut += quoteOut;

        (baseIn, quoteOut) = _getBasePool().getExchangeableProfit(poolId, price);
        maxBaseIn += baseIn;
        maxQuoteOut += quoteOut;
    }

    /// @inheritdoc IExchange
    function getExchangeableQuoteToken(PoolId poolId, uint256 price) public view override returns (uint256 maxQuoteIn, uint256 maxBaseOut) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        (uint256 quoteIn, uint256 baseOut) = _getOracleReserve().getExchangeableBaseFee(poolId);
        maxQuoteIn += quoteIn;
        maxBaseOut += baseOut;

        (quoteIn, baseOut) = ITradingVault(pool.tradingVault).getExchangeableBaseCollateral(price);
        maxQuoteIn += quoteIn;
        maxBaseOut += baseOut;
    }

    /// @inheritdoc IExchangeCallback
    function onExchange(PoolId poolId, address tokenIn, uint256 requiredAmount, bytes calldata /* data */) external override {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        require(
            msg.sender == address(_getOracleReserve()) || msg.sender == address(_getBasePool()) || msg.sender == pool.tradingVault,
            NotAllowedCaller(msg.sender)
        );
        IERC20(tokenIn).safeTransfer(msg.sender, requiredAmount);
    }

    /// @inheritdoc IExchange
    function exchangeBaseToQuote(ExchangeParams calldata params) external override nonReentrant returns (uint256 usedBase, uint256 receivedQuote) {
        return _exchangeBaseToQuote(params);
    }

    /// @inheritdoc IExchange
    function exchangeQuoteToBase(ExchangeParams calldata params) external override nonReentrant returns (uint256 usedQuote, uint256 receivedBase) {
        return _exchangeQuoteToBase(params);
    }

    /// @notice Exchange base tokens for quote tokens
    /// @param params Exchange parameters
    /// @return usedBase Amount of base tokens used
    /// @return receivedQuote Amount of quote tokens received
    function _exchangeBaseToQuote(ExchangeParams calldata params) internal returns (uint256 usedBase, uint256 receivedQuote) {
        PoolMetadata memory pool = _getPoolManager().getPool(params.poolId);
        uint256 oraclePrice = _getOracle().safeOraclePrice(params.poolId);

        IERC20(pool.baseToken).safeTransferFrom(msg.sender, address(this), params.sourceIn);

        ITradingVault tradingVault = ITradingVault(pool.tradingVault);
        (uint256 maxBaseIn, ) = tradingVault.getExchangeableBaseProfit(oraclePrice);
        uint256 exchanged = Math.min(params.sourceIn, maxBaseIn);
        if (exchanged > 0) {
            uint256 baseOut = tradingVault.exchangeBaseProfit(exchanged, params.minTargetOut, params.recipient, "0x");
            usedBase += exchanged;
            receivedQuote += baseOut;
        }

        if (params.sourceIn > usedBase) {
            IBasePool basePool = _getBasePool();
            (maxBaseIn, ) = basePool.getExchangeableProfit(params.poolId, oraclePrice);
            if (maxBaseIn > 0) {
                exchanged = Math.min(params.sourceIn - usedBase, maxBaseIn);
                uint256 baseOut = basePool.exchangeProfit(params.poolId, exchanged, params.minTargetOut, params.recipient, "0x");
                usedBase += exchanged;
                receivedQuote += baseOut;
            }
        }

        require(receivedQuote >= params.minTargetOut, ExceedMinOutput(params.minTargetOut, receivedQuote));
        if (params.sourceIn > usedBase) {
            IERC20(pool.baseToken).safeTransfer(msg.sender, params.sourceIn - usedBase);
        }

        _getEmiter().emitExchanged(
            IEmiter.ExchangedParams({
                user: msg.sender,
                source: pool.baseToken,
                target: pool.quoteToken,
                sourceAmount: usedBase,
                targetAmount: receivedQuote,
                price: oraclePrice
            })
        );
    }

    /// @notice Exchange quote tokens for base tokens
    /// @param params Exchange parameters
    /// @return usedQuote Amount of quote tokens used
    /// @return receivedBase Amount of base tokens received
    function _exchangeQuoteToBase(ExchangeParams calldata params) internal returns (uint256 usedQuote, uint256 receivedBase) {
        PoolMetadata memory pool = _getPoolManager().getPool(params.poolId);

        IERC20(pool.quoteToken).safeTransferFrom(msg.sender, address(this), params.sourceIn);

        (uint256 minQuoteIn, ) = _getOracleReserve().getExchangeableBaseFee(params.poolId);
        if (minQuoteIn > 0) {
            uint256 baseOut = _getOracleReserve().exchangeBaseFee(params.poolId, params.recipient, "0x");
            usedQuote += minQuoteIn;
            receivedBase += baseOut;
        }

        uint256 oraclePrice;
        if (params.sourceIn > usedQuote && (pool.state == PoolState.Trench || pool.state == PoolState.PreBench)) {
            oraclePrice = _getOracle().safeOraclePrice(params.poolId);
            (uint256 maxQuoteIn, ) = ITradingVault(pool.tradingVault).getExchangeableBaseCollateral(oraclePrice);
            if (maxQuoteIn > 0) {
                uint256 exchanged = Math.min(params.sourceIn - usedQuote, maxQuoteIn);
                uint256 baseOut = ITradingVault(pool.tradingVault).exchangeBaseCollateral(exchanged, 0, params.recipient, "0x");
                usedQuote += exchanged;
                receivedBase += baseOut;
            }
        }

        require(receivedBase >= params.minTargetOut, ExceedMinOutput(params.minTargetOut, receivedBase));
        if (params.sourceIn > usedQuote) {
            IERC20(pool.quoteToken).safeTransfer(msg.sender, params.sourceIn - usedQuote);
        }

        _getEmiter().emitExchanged(
            IEmiter.ExchangedParams({
                user: msg.sender,
                source: pool.quoteToken,
                target: pool.baseToken,
                sourceAmount: usedQuote,
                targetAmount: receivedBase,
                price: oraclePrice
            })
        );
    }

    /// @notice Get the pool manager contract
    /// @return poolManager Pool manager contract interface
    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(super._getDependencyAddress(Identifier.POOL_MANAGER));
    }

    /// @notice Get the oracle contract
    /// @return oracle Oracle contract interface
    function _getOracle() internal view returns (IOracle oracle) {
        return IOracle(super._getDependencyAddress(Identifier.ORACLE));
    }

    /// @notice Get the oracle reserve contract
    /// @return oracleReserve Oracle reserve contract interface
    function _getOracleReserve() internal view returns (IOracleReserve oracleReserve) {
        return IOracleReserve(super._getDependencyAddress(Identifier.ORACLE_RESERVE));
    }

    /// @notice Get the emitter contract
    /// @return emiter Emitter contract interface
    function _getEmiter() internal view returns (IEmiter emiter) {
        return IEmiter(super._getDependencyAddress(Identifier.EMITER));
    }

    /// @notice Get the base pool contract
    /// @return basePool Base pool contract interface
    function _getBasePool() internal view returns (IBasePool basePool) {
        return IBasePool(super._getDependencyAddress(Identifier.BASE_POOL));
    }
}

