// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { BaseContractUpgradeable } from "./base/BaseContractUpgradeable.sol";

/// @title Treasury
/// @notice Treasury contract for managing protocol funds
contract Treasury is Ownable2StepUpgradeable, BaseContractUpgradeable {
    using SafeERC20 for IERC20;

    /// @notice Error thrown when insufficient balance for withdrawal
    error InsufficientBalance();

    error TransferFailed();

    event Withdrawn(address token, uint256 amount, address recipient);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the treasury contract
    /// @param addressManager Address manager contract address
    /// @param owner Initial owner address
    function initialize(address addressManager, address owner) external initializer {
        __Ownable2Step_init();
        __BaseContractUpgradeable_init(addressManager, new bytes32[](0));

        _transferOwnership(owner);
    }

    /// @notice Withdraw tokens from treasury
    /// @param token Token address to withdraw
    /// @param amount Amount to withdraw
    /// @param recipient Recipient address
    function withdraw(address token, uint256 amount, address recipient) external onlyOwner {
        IERC20(token).safeTransfer(recipient, amount);
        emit Withdrawn(token, amount, recipient);
    }
}

