pragma solidity ^0.8.30;

import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { BaseContract } from "./BaseContract.sol";

/// @title BaseContractUpgradeable
/// @notice Base contract for upgradeable contracts with address management
abstract contract BaseContractUpgradeable is BaseContract, UUPSUpgradeable {
    modifier onlyProxyAdmin() {
        _onlyProxyAdmin();
        _;
    }

    function __BaseContractUpgradeable_init(address addressManager, bytes32[] memory initDependencies) internal onlyInitializing {
        __UUPSUpgradeable_init();

        __BaseContract_init(addressManager, initDependencies);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyProxyAdmin {}

    function _onlyProxyAdmin() internal view {
        require(msg.sender == _getAddressManager().getAddress(Identifier.PROXY_ADMIN), NotProxyAdmin());
    }
}

