pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IChainlinkAdapter } from "./../interfaces/IChainlinkAdapter.sol";
import { IOracleAdapter } from "./../interfaces/IOracleAdapter.sol";
import { IOracleRegistry } from "./../interfaces/IOracleRegistry.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors, OracleType } from "./../types/Types.sol";

contract OracleRegistry is BaseContractUpgradeable, ReentrancyGuardUpgradeable, IOracleRegistry {
    mapping(OracleType oracleType => address adapter) public oracleAdapterMap;

    event AdapterRegistered(OracleType oracleType, address adapter);

    modifier onlyOracleAdmin() {
        _onlyOracleAdmin();
        _;
    }

    modifier onlyOracle() {
        _onlyOracle();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        __ReentrancyGuard_init();

        bytes32[] memory identifiers = new bytes32[](1);
        identifiers[0] = Identifier.ORACLE;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    function registerAdapter(OracleType oracleType, address adapter) external onlyOracleAdmin {
        oracleAdapterMap[oracleType] = adapter;
        emit AdapterRegistered(oracleType, adapter);
    }

    function updateAdapterVerifyAddress(OracleType oracleType, address newVerifyAddress) external onlyOracleAdmin {
        IOracleAdapter(oracleAdapterMap[oracleType]).updateVerifyAddress(newVerifyAddress);
    }

    function setChainlinkPriceDecimals(bytes32 priceId, uint32 decimals) external onlyOracle {
        IChainlinkAdapter adapter = IChainlinkAdapter(oracleAdapterMap[OracleType.Chainlink]);
        adapter.setOraclePriceDecimals(priceId, decimals);
    }

    function getOracleAdapter(OracleType oracleType) external view returns (address adapter) {
        return oracleAdapterMap[oracleType];
    }

    function _onlyOracleAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isOracleAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyOracle() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.ORACLE), Errors.PermissionDenied(msg.sender, address(this)));
    }
}

