// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IExchangeCallback } from "./../interfaces/IExchangeCallback.sol";
import { IMarketManager } from "./../interfaces/IMarketManager.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IOracleReserve } from "./../interfaces/IOracleReserve.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { TokenConverter } from "./../libraries/TokenConverter.sol";
import { TradingHelper } from "./../libraries/TradingHelper.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors, Constants, PoolMetadata, OracleFeeState, PoolId } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";

contract OracleReserve is BaseContractUpgradeable, ReentrancyGuardUpgradeable, IOracleReserve {
    using TokenConverter for TokenConverter.ConvertInParams;
    using SafeERC20 for IERC20;
    using PrecisionUtils for uint256;

    mapping(PoolId poolId => OracleFee) private _poolOracleFee;

    mapping(PoolId poolId => BoostFee) private _poolBoostFee;
    mapping(address token => uint256 boostFee) private _boostFeeReserve;

    modifier onlyPoolManager() {
        _onlyPoolManager();
        _;
    }

    modifier onlyOracleAdmin() {
        _onlyOracleAdmin();
        _;
    }

    modifier onlyExchange() {
        _onlyExchange();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        __ReentrancyGuard_init();

        bytes32[] memory identifiers = new bytes32[](5);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.ORACLE;
        identifiers[2] = Identifier.RISK_PARAMETER;
        identifiers[3] = Identifier.MARKET_MANAGER;
        identifiers[4] = Identifier.EXCHANGE;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    function getPoolOracleFee(PoolId poolId) external view override returns (OracleFee memory) {
        return _poolOracleFee[poolId];
    }

    function getPoolBoostFee(PoolId poolId) external view override returns (BoostFee memory) {
        return _poolBoostFee[poolId];
    }

    function isBaseFeeSoldOut(PoolId poolId) external view override returns (bool) {
        OracleFee memory oracleFee = _poolOracleFee[poolId];
        return oracleFee.state == OracleFeeState.SoldOut;
    }

    function getExchangeableBaseFee(PoolId poolId) external view override returns (uint256 quoteIn, uint256 baseOut) {
        return _exchangeableBaseFee(poolId);
    }

    function withdrawOracleFee(address token, address to, uint256 amount) external onlyOracleAdmin {
        uint256 balanceOf = IERC20(token).balanceOf(address(this));
        require(amount <= balanceOf - _boostFeeReserve[token], PoolBoostReserveInsufficient());
        IERC20(token).safeTransfer(to, amount);
    }

    function claimBoostFee(PoolId poolId) external nonReentrant {
        (, address quoteToken) = _getPoolManager().getPairToken(poolId);
        BoostFee memory boostFee = _poolBoostFee[poolId];
        require(boostFee.proposer == msg.sender && boostFee.isClaimable, BoostFeeClaimFailed());
        require(_boostFeeReserve[quoteToken] >= boostFee.amount, PoolBoostReserveInsufficient());

        _boostFeeReserve[quoteToken] -= boostFee.amount;
        delete _poolBoostFee[poolId];
        IERC20(quoteToken).safeTransfer(msg.sender, boostFee.amount);
    }

    function chargeBoostFee(PoolId poolId, address proposer, uint256 quoteAmount) external onlyPoolManager {
        (, address quoteToken) = _getPoolManager().getPairToken(poolId);

        _boostFeeReserve[quoteToken] += quoteAmount;
        _poolBoostFee[poolId] = BoostFee({
            proposer: proposer,
            amount: quoteAmount,
            isClaimable: false
        });
        IERC20(quoteToken).safeTransferFrom(proposer, address(this), quoteAmount);
    }

    function confirmBoostFee(PoolId poolId, bool isAllow) external onlyPoolManager {
        PoolMetadata memory pool =_getPoolManager().getPool(poolId);
        BoostFee memory boostFee = _poolBoostFee[poolId];

        require(_boostFeeReserve[pool.quoteToken] >= boostFee.amount, PoolBoostReserveInsufficient());

        if (!isAllow) {
            uint256 boostRefundFeeUsd = _getMarketManager().getBoostRefundFee(pool.marketId);
            uint256 boostRefundFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, pool.quoteToken, boostRefundFeeUsd);

            _boostFeeReserve[pool.quoteToken] -= boostFee.amount - boostRefundFee;
            _poolBoostFee[poolId].amount = boostRefundFee;
            _poolBoostFee[poolId].isClaimable = true;
        } else {
            OracleFee storage oracleFee = _poolOracleFee[poolId];
            require(oracleFee.state == OracleFeeState.None, PoolOracleFeeCharged());
            oracleFee.state = OracleFeeState.SoldOut;
            oracleFee.primer = boostFee.proposer;
            oracleFee.quoteAmount += boostFee.amount;

            _boostFeeReserve[pool.quoteToken] -= boostFee.amount;
            delete _poolBoostFee[poolId];
        }
    }

    function chargeOracleFeeFromPoolVault(PoolId poolId, address poolVault, uint256 baseAmount, uint256 quoteAmount) external onlyPoolManager {
        OracleFee storage oracleFee = _poolOracleFee[poolId];
        require(oracleFee.state == OracleFeeState.None, PoolOracleFeeCharged());

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        IERC20(pool.baseToken).safeTransferFrom(poolVault, address(this), baseAmount);
        IERC20(pool.quoteToken).safeTransferFrom(poolVault, address(this), quoteAmount);

        oracleFee.state = baseAmount == 0 ? OracleFeeState.SoldOut : OracleFeeState.Charged;
        oracleFee.baseAmount += baseAmount;
        oracleFee.quoteAmount += quoteAmount;
    }

    function chargeOracleFeeFromPrimer(PoolId poolId, address primer, uint256 quoteAmount) external onlyPoolManager {
        OracleFee storage oracleFee = _poolOracleFee[poolId];
        require(oracleFee.state == OracleFeeState.None, PoolOracleFeeCharged());

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        IERC20(pool.quoteToken).safeTransferFrom(primer, address(this), quoteAmount);

        oracleFee.primer = primer;
        oracleFee.state = OracleFeeState.SoldOut;
        oracleFee.quoteAmount += quoteAmount;
    }

    function refreshOracleFee(PoolId poolId) external onlyPoolManager {
        OracleFee memory oracleFee = _poolOracleFee[poolId];
        require(oracleFee.state == OracleFeeState.SoldOut, PoolOracleFeeNotSoldOut());

        // oracle fee was already used
        delete _poolOracleFee[poolId];
    }

    function exchangeBaseFee(PoolId poolId, address recipient, bytes calldata data) external nonReentrant onlyExchange returns (uint256 baseOut) {
        OracleFee memory oracleFee = _poolOracleFee[poolId];
        require(oracleFee.state == OracleFeeState.Charged, PoolOracleFeeNotCharged());

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 oracleVerifyFeeUsd = _getMarketManager().getOracleFee(pool.marketId);
        uint256 oracleVerifyFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, pool.quoteToken, oracleVerifyFeeUsd);

        require(oracleVerifyFee >= oracleFee.quoteAmount, Errors.ExceedMaxExchangeableAmount());
        uint256 needAmount = oracleVerifyFee - oracleFee.quoteAmount;

        _poolOracleFee[poolId].state = OracleFeeState.SoldOut;

        IERC20(pool.baseToken).safeTransfer(recipient, oracleFee.baseAmount);

        uint256 balanceBefore = IERC20(pool.quoteToken).balanceOf(address(this));
        IExchangeCallback(msg.sender).onExchange(poolId, pool.quoteToken, needAmount, data);
        uint256 balanceAfter = IERC20(pool.quoteToken).balanceOf(address(this));
        require(balanceAfter - balanceBefore == needAmount, Errors.InsufficientReturnAmount(needAmount, balanceAfter - balanceBefore));

        emit OracleFeeExchanged(poolId, oracleFee.quoteAmount, oracleFee.baseAmount, recipient);
        return oracleFee.baseAmount;
    }

    function _exchangeableBaseFee(PoolId poolId) internal view returns (uint256 quoteIn, uint256 baseOut) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 oracleVerifyFeeUsd = _getMarketManager().getOracleFee(pool.marketId);
        uint256 oracleVerifyFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, pool.quoteToken, oracleVerifyFeeUsd);

        OracleFee memory oracleFee = _poolOracleFee[poolId];
        if (oracleFee.state != OracleFeeState.Charged) return (0, 0);
        baseOut = oracleFee.baseAmount;
        quoteIn = oracleVerifyFee - oracleFee.quoteAmount;
    }

    function _onlyPoolManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POOL_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyOracleAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isOracleAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyExchange() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.EXCHANGE), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getMarketManager() internal view returns (IMarketManager) {
        return IMarketManager(super._getDependencyAddress(Identifier.MARKET_MANAGER));
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(super._getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getOracle() internal view returns (IOracle) {
        return IOracle(super._getDependencyAddress(Identifier.ORACLE));
    }

    function _getRiskParameter() internal view returns (IRiskParameter) {
        return IRiskParameter(super._getDependencyAddress(Identifier.RISK_PARAMETER));
    }
}

