// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { IPythOracle } from "./../../interfaces/IPythOracle.sol";
import { BaseOracleAdapter } from "./BaseOracleAdapter.sol";

contract PythAdapter is BaseOracleAdapter {
    IPythOracle public pyth;

    error ArrayEmpty();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, address _pyth) public initializer {
        __OracleAdapter_init(addressManager);

        pyth = IPythOracle(_pyth);
    }

    function updateVerifyAddress(address newAddress) external onlyPriceAdapterRegistry {
        address oldAddress = address(pyth);
        pyth = IPythOracle(newAddress);
        emit VerifyAddressUpdated(oldAddress, newAddress);
    }

    function _getFee(bytes[] memory updateData) internal view override returns (uint256) {
        return pyth.getUpdateFee(updateData);
    }

    function _verify(
        bytes32[] memory priceIds,
        bytes[] memory updatePayloads,
        uint64[] memory publishTimes
    ) internal override returns (VerifiedPrice[] memory) {
        uint256 totalFee = pyth.getUpdateFee(updatePayloads);
        if (msg.value != totalFee) revert IncorrectFee(SafeCast.toUint160(totalFee));

        (uint64 min, uint64 max) = _getMinMax(publishTimes);

        IPythOracle.PriceFeed[] memory priceFeeds;
        try pyth.parsePriceFeedUpdates{ value: totalFee }(updatePayloads, priceIds, min, max) returns (IPythOracle.PriceFeed[] memory _priceFeeds) {
            priceFeeds = _priceFeeds;
        } catch {
            revert VerifyPriceFailed();
        }
        VerifiedPrice[] memory verifiedPrices = new VerifiedPrice[](priceFeeds.length);
        for (uint256 i = 0; i < priceFeeds.length; ++i) {
            IPythOracle.PriceFeed memory priceFeed = priceFeeds[i];

            IPythOracle.PythPrice memory pythPrice = priceFeed.price;
            uint256 decimals = pythPrice.expo < 0 ? uint256(uint32(-pythPrice.expo)) : uint256(uint32(pythPrice.expo));
            require(pythPrice.price >= 0, InvalidPrice());

            verifiedPrices[i] = VerifiedPrice({
                priceId: priceFeed.id,
                price: _returnPriceWithDecimals(int256(pythPrice.price), decimals),
                publishTime: uint64(priceFeed.price.publishTime)
            });
        }
        return verifiedPrices;
    }

    function _getMinMax(uint64[] memory array) internal pure returns (uint64 min, uint64 max) {
        if (!(array.length > 0)) revert ArrayEmpty();

        min = array[0];
        max = array[0];

        for (uint256 i = 1; i < array.length; ++i) {
            uint64 currentValue = array[i];
            if (currentValue < min) {
                min = currentValue;
            } else if (currentValue > max) {
                max = currentValue;
            }
        }
    }
}

