// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { TransientMapLib } from "../../libraries/TransientMapLib.sol";
import { PoolId } from "../../types/Types.sol";

abstract contract TransientPriceCache {
    using TransientMapLib for *;

    bytes32 private constant _CACHE_NS = keccak256("price.cache.transient.v1");

    /// @notice Cache calculated for a pool within current transaction to avoid repeated queries
    function _cachePrice(PoolId poolId, uint256 price) internal {
        TransientMapLib.set(_CACHE_NS, PoolId.unwrap(poolId), price);
    }

    function _getCachedPrice(PoolId poolId) internal view returns (uint256) {
        return TransientMapLib.get(_CACHE_NS, PoolId.unwrap(poolId));
    }

    function _hasCachedPrice(PoolId poolId) internal view returns (bool) {
        return TransientMapLib.get(_CACHE_NS, PoolId.unwrap(poolId)) > 0;
    }
}

