// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IMarketManager } from "./../interfaces/IMarketManager.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { Market } from "./../libraries/Market.sol";
import { MarketMetadata } from "./../libraries/Market.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { MarketKey } from "./../types/MarketKey.sol";
import { Errors, MarketId } from "./../types/Types.sol";

/// @title MarketManager
/// @notice Manages market creation, configuration, and metadata
contract MarketManager is BaseContractUpgradeable, IMarketManager {
    using Market for Market.Data;

    /// @notice Market data storage
    Market.Data private _marketData;

    event ExecutionFeeUpdated(MarketId marketId, uint256 oldExecutionFee, uint256 newExecutionFee);
    event ForwardFeeUpdated(MarketId marketId, uint256 oldForwardFee, uint256 newForwardFee);
    event MaxExecutionFeeUpdated(MarketId marketId, uint256 oldMaxExecutionFee, uint256 newMaxExecutionFee);
    event MaxForwardFeeUpdated(MarketId marketId, uint256 oldMaxForwardFee, uint256 newMaxForwardFee);
    event ReserveRatioUpdated(MarketId marketId, uint32 newBaseReserveRatio, uint32 newQuoteReserveRatio);
    event OracleFeeUpdated(MarketId marketId, uint64 newOracleFeeUsd);
    event PoolPrimeThresholdUpdated(MarketId marketId, uint128 newPoolPrimeThreshold);

    /// @notice Error thrown when quote token address is invalid
    error InvalidQuoteTokenAddress();
    /// @notice Error thrown when market already exists
    error MarketAlreadyExisted();
    /// @notice Error thrown when market not exists
    error MarketNotExisted();
    /// @notice Error thrown when ratio param is invalid
    error InvalidRatioParams();

    modifier onlyListingAdmin() {
        _onlyListingAdmin();
        _;
    }

    modifier onlyRiskAdmin() {
        _onlyRiskAdmin();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the market manager contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) external initializer {
        bytes32[] memory identifiers = new bytes32[](4);
        identifiers[0] = Identifier.EMITER;
        identifiers[1] = Identifier.BASE_POOL;
        identifiers[2] = Identifier.QUOTE_POOL;
        identifiers[3] = Identifier.ORACLE;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @inheritdoc IMarketManager
    function getOracleFee(MarketId marketId) external view returns (uint256) {
        return _marketData.getOracleVerificationFee(marketId);
    }

    function getBoostFee(MarketId marketId) external view returns (uint256) {
        return _marketData.getBoostFee(marketId);
    }

    function getBoostRefundFee(MarketId marketId) external view returns (uint256) {
        return _marketData.getBoostRefundFee(marketId);
    }

    /// @inheritdoc IMarketManager
    function getMarketIds() external view returns (bytes32[] memory) {
        return _marketData.getMarketIds();
    }

    /// @inheritdoc IMarketManager
    function getMarket(MarketId marketId) external view returns (MarketMetadata memory) {
        return _marketData.getMarket(marketId);
    }

    /// @inheritdoc IMarketManager
    function getExecutionFee(MarketId marketId) external view returns (uint256) {
        return _marketData.getExecutionFee(marketId);
    }

    /// @inheritdoc IMarketManager
    function getForwardFee(MarketId marketId) external view returns (uint256) {
        return _marketData.getForwardFee(marketId);
    }

    /// @inheritdoc IMarketManager
    function getExecutionFeeByToken(address quoteToken) external view returns (uint256) {
        return _marketData.getExecutionFeeByToken(quoteToken);
    }

    /// @inheritdoc IMarketManager
    function getForwardFeeByToken(address quoteToken) external view returns (uint256) {
        require(_marketData.marketExists(_marketData.getMarketIdByToken(quoteToken)), MarketNotExisted());
        return _marketData.getForwardFeeByToken(quoteToken);
    }

    /// @inheritdoc IMarketManager
    function marketExists(MarketId marketId) external view returns (bool) {
        return _marketData.marketExists(marketId);
    }

    function createMarket(DeployMarketParams calldata params, MarketQuoteParams calldata quoteParams) external onlyRiskAdmin {
        if (params.quoteToken == address(0)) revert InvalidQuoteTokenAddress();

        MarketKey memory marketKey = MarketKey({ chainId: params.chainId, quoteToken: params.quoteToken });
        MarketId marketId = marketKey.toId();

        require(!_marketData.marketExists(marketId), MarketAlreadyExisted());
        require(params.baseReserveRatio > 0 && params.quoteReserveRatio > 0, InvalidRatioParams());
        require(params.oracleFeeUsd > 0 && params.poolPrimeThreshold > 0, Errors.InvalidParameter());
        require(params.boostFeeUsd > 0 && params.boostFeeUsd >= params.boostRefundFeeUsd, Errors.InvalidParameter());
        require(IERC20Metadata(params.quoteToken).decimals() < 19, InvalidQuoteTokenAddress());

        _marketData.saveMarket(
            marketId,
            params.quoteToken,
            params.baseReserveRatio,
            params.quoteReserveRatio,
            params.oracleFeeUsd,
            params.boostFeeUsd,
            params.boostRefundFeeUsd,
            params.poolPrimeThreshold,
            params.executionFee,
            params.maxExecutionFee,
            params.forwardFee,
            params.maxForwardFee
        );

        _getOracle().setMarketQuoteConfiguration(
            marketId,
            IOracle.MarketQuoteConfig({
                priceContract: quoteParams.priceContract,
                applyExchangeRate: quoteParams.applyExchangeRate,
                minDeviationRatio: quoteParams.minDeviationRatio,
                heartbeat: quoteParams.heartbeat
            })
        );

        _getEmiter().emitMarketCreated(
            IEmiter.MarketCreatedParams({
                marketId: marketId,
                deployer: msg.sender,
                quoteToken: params.quoteToken,
                baseReserveRatio: params.baseReserveRatio,
                quoteReserveRatio: params.quoteReserveRatio,
                oracleFeeUsd: params.oracleFeeUsd,
                boostFeeUsd: params.boostFeeUsd,
                boostRefundFeeUsd: params.boostRefundFeeUsd,
                poolPrimeThreshold: params.poolPrimeThreshold,
                executionFee: params.executionFee,
                maxExecutionFee: params.maxExecutionFee,
                forwardFee: params.forwardFee,
                maxForwardFee: params.maxForwardFee
            })
        );
    }

    function updateMarketQuoteConfiguration(MarketId marketId, MarketQuoteParams calldata quoteParams) external onlyRiskAdmin {
        _getOracle().setMarketQuoteConfiguration(
            marketId,
            IOracle.MarketQuoteConfig({
                priceContract: quoteParams.priceContract,
                applyExchangeRate: quoteParams.applyExchangeRate,
                minDeviationRatio: quoteParams.minDeviationRatio,
                heartbeat: quoteParams.heartbeat
            })
        );
    }

    function updateReserveRatio(MarketId marketId, uint32 _baseReserveRatio, uint32 _quoteReserveRatio) external onlyRiskAdmin {
        _marketData.updateReserveRatio(marketId, _baseReserveRatio, _quoteReserveRatio);
        emit ReserveRatioUpdated(marketId, _baseReserveRatio, _quoteReserveRatio);
    }

    function updateOracleFee(MarketId marketId, uint64 _oracleFeeUsd) external onlyRiskAdmin {
        _marketData.updateOracleFee(marketId, _oracleFeeUsd);
        emit OracleFeeUpdated(marketId, _oracleFeeUsd);
    }

    function updatePoolPrimeThreshold(MarketId marketId, uint128 _poolPrimeThreshold) external onlyRiskAdmin {
        _marketData.updatePoolPrimeThreshold(marketId, _poolPrimeThreshold);
        emit PoolPrimeThresholdUpdated(marketId, _poolPrimeThreshold);
    }

    function updateExecutionFee(MarketId marketId, uint128 _executionFee) external onlyRiskAdmin {
        uint256 oldExecutionFee = _marketData.getExecutionFee(marketId);
        _marketData.updateExecutionFee(marketId, _executionFee);
        emit ExecutionFeeUpdated(marketId, oldExecutionFee, _executionFee);
    }

    function updateForwardFee(MarketId marketId, uint128 _forwardFee) external onlyRiskAdmin {
        uint256 oldForwardFee = _marketData.getForwardFee(marketId);
        _marketData.updateForwardFee(marketId, _forwardFee);
        emit ForwardFeeUpdated(marketId, oldForwardFee, _forwardFee);
    }

    function updateMaxExecutionFee(MarketId marketId, uint128 _maxExecutionFee) external onlyRiskAdmin {
        uint256 oldMaxExecutionFee = _marketData.getMaxExecutionFee(marketId);
        _marketData.updateMaxExecutionFee(marketId, _maxExecutionFee);
        emit MaxExecutionFeeUpdated(marketId, oldMaxExecutionFee, _maxExecutionFee);
    }

    function updateMaxForwardFee(MarketId marketId, uint128 _maxForwardFee) external onlyRiskAdmin {
        uint256 oldMaxForwardFee = _marketData.getMaxForwardFee(marketId);
        _marketData.updateMaxForwardFee(marketId, _maxForwardFee);
        emit MaxForwardFeeUpdated(marketId, oldMaxForwardFee, _maxForwardFee);
    }

    function _onlyListingAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isListingAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyRiskAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isRiskAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getOracle() internal view returns (IOracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(super._getDependencyAddress(Identifier.EMITER));
    }
}

