// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IPoolBase } from "./../interfaces/IPoolBase.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { TradingHelper } from "./../libraries/TradingHelper.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { PoolMetadata, PoolId, Direction, Errors } from "./../types/Types.sol";

abstract contract PoolBase is BaseContractUpgradeable, IPoolBase {
    using SignedMath for int256;

    // Precision used for exchange rate calculations (18 decimals)
    uint256 public constant EXCHANGE_RATE_PRECISION = 1e18;
    // Precision used for rebate index calculations (18 decimals)
    uint256 public constant REBATE_INDEX_PRECISION = 1e18;
    // Standard decimals for pool tokens
    uint8 public constant POOL_TOKEN_DECIMALS = 18;
    // Virtual liquidity offsets used to harden empty-pool pricing without minting dead shares.
    uint256 public constant VIRTUAL_SHARES = 1e3;
    uint256 public constant VIRTUAL_ASSETS = 1e3;

    function __PoolBase_init(address addressManager) internal onlyInitializing {
        bytes32[] memory identifiers = new bytes32[](7);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.ORACLE;
        identifiers[2] = Identifier.EMITER;
        identifiers[3] = Identifier.LIQUIDITY_ROUTER;
        identifiers[4] = Identifier.RISK_PARAMETER;
        identifiers[5] = Identifier.POSITION_MANAGER;
        identifiers[6] = Identifier.FUNDING_RATE;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @inheritdoc IPoolBase
    function getExchangeRate(PoolId poolId) public view override returns (uint256) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);
        return _getExchangeRate(pool, poolId, oraclePrice);
    }

    /// @inheritdoc IPoolBase
    function getExchangeRate(PoolId poolId, uint256 price) public view override returns (uint256) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        return _getExchangeRate(pool, poolId, price);
    }

    /// @inheritdoc IPoolBase
    function getPoolTokenPrice(PoolId poolId, uint256 price) public view override returns (uint256) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 exchangeRate = _getExchangeRate(pool, poolId, price);
        return _computePoolTokenPrice(pool, poolId, exchangeRate, price);
    }

    /// @inheritdoc IPoolBase
    function previewPoolTokenPrice(PoolId poolId) external view override returns (uint256) {
        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);
        return getPoolTokenPrice(poolId, oraclePrice);
    }

    /**
     * @notice Calculates pending pool PNL
     * @return unrealizedPnl Pending pool PNL
     * @return baseAmount Pending pool base pnl amount
     * @return quoteAmount Pending pool quote pnl amount
     */
    function _pendingPoolPNL(
        PoolMetadata memory pool,
        PoolId poolId,
        uint256 price
    ) internal view returns (int256 unrealizedPnl, int256 baseAmount, int256 quoteAmount) {
        IPositionManager.OITracker memory oi = _getPositionManager().getOITracker(poolId);
        unrealizedPnl = TradingHelper.calculatePNL(pool, oi.poolEntryPrice, price, oi.tracker.abs(), oi.tracker < 0);
        if (unrealizedPnl != 0) {
            (, uint256 quoteSize, uint256 baseSize) = IPoolVault(pool.poolVault).splitPoolProfits(unrealizedPnl.abs(), price);

            int256 sign = unrealizedPnl > 0 ? int256(1) : int256(-1);
            baseAmount = sign * int256(baseSize);
            quoteAmount = sign * int256(quoteSize);
        }

        uint256 fundingFee = _calculatePoolFundingFee(pool, oi, poolId, price);
        if (fundingFee > 0) {
            (, uint256 quoteSize, uint256 baseSize) = IPoolVault(pool.poolVault).splitPoolProfits(fundingFee, price);
            baseAmount += int256(baseSize);
            quoteAmount += int256(quoteSize);
        }
    }

    /**
     * @notice Gets the current exchange rate including pending profits
     * @param pool Pool metadata
     * @param poolId The pool ID
     * @param price Current price
     * @return Current exchange rate with pending profits included
     */
    function _getExchangeRate(PoolMetadata memory pool, PoolId poolId, uint256 price) internal view virtual returns (uint256);

    function _computePoolTokenPrice(
        PoolMetadata memory pool,
        PoolId poolId,
        uint256 exchangeRate,
        uint256 price
    ) internal view virtual returns (uint256);

    function _calculatePoolFundingFee(
        PoolMetadata memory pool,
        IPositionManager.OITracker memory oi,
        PoolId poolId,
        uint256 price
    ) internal view returns (uint256) {
        (IFundingRate.FundingRateData memory prev, IFundingRate.NextFundingRateInfo memory next) = _getFundingRate().getFundingRateInfo(
            poolId,
            price
        );
        int256 accruedFundingTracker = next.lastFundingFeeTracker - prev.tracker;
        int256 fundingFee = TradingHelper.calculateFundingFee(
            pool,
            accruedFundingTracker,
            oi.tracker.abs(),
            oi.tracker > 0 ? Direction.Short : Direction.Long // The LP’s position is on the opposite side of the user’s position.
        );
        // pool funding fee will not be negative, only a defensive measure.
        require(fundingFee >= 0, Errors.PoolFundingFeeNotPositive());
        return uint256(fundingFee);
    }

    /**
     * @notice Calculates rebates earned by a user based on index difference
     * @param rebateIndex Current global rebate index
     * @param userIndex User's last recorded rebate index
     * @param userBalance User's token balance or share
     * @return Amount of rebates earned
     */
    function _getRebates(uint256 rebateIndex, uint256 userIndex, uint256 userBalance) internal pure returns (uint256) {
        return ((rebateIndex - userIndex) * userBalance) / (10 ** POOL_TOKEN_DECIMALS) / REBATE_INDEX_PRECISION;
    }

    function _virtualizedExchangeRate(uint256 normalizedAssets, uint256 totalSupply) internal pure returns (uint256) {
        return ((normalizedAssets + VIRTUAL_ASSETS) * EXCHANGE_RATE_PRECISION) / (totalSupply + VIRTUAL_SHARES);
    }

    function _isLiquidityRouter(address sender) internal view returns (bool) {
        return sender == _getDependencyAddress(Identifier.LIQUIDITY_ROUTER);
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getPositionManager() internal view returns (IPositionManager) {
        return IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getOracle() internal view returns (IOracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }

    function _getRiskParameter() internal view returns (IRiskParameter) {
        return IRiskParameter(_getDependencyAddress(Identifier.RISK_PARAMETER));
    }

    function _getFundingRate() internal view returns (IFundingRate) {
        return IFundingRate(_getDependencyAddress(Identifier.FUNDING_RATE));
    }
}

