// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { BeaconProxy } from "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { IPoolFactory } from "./../interfaces/IPoolFactory.sol";
import { IPoolToken } from "./../interfaces/IPoolToken.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors, PoolId } from "./../types/Types.sol";

/// @title PoolFactory
/// @notice Factory contract for deploying pool components including pool tokens, vaults
contract PoolFactory is BaseContractUpgradeable, IPoolFactory {
    /// @notice Emitted when a new pool token is created
    /// @param poolId Pool ID for the created token
    /// @param underlyingToken Address of the underlying token
    /// @param beacon Beacon address used for the proxy
    /// @param poolToken Address of the created pool token
    event PoolTokenCreated(PoolId indexed poolId, address indexed underlyingToken, address beacon, address poolToken);

    modifier onlyPoolManager() {
        _onlyPoolManager();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the pool factory contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) external initializer {
        bytes32[] memory dependencies = new bytes32[](5);
        dependencies[0] = Identifier.BASE_POOL_TOKEN_BEACON;
        dependencies[1] = Identifier.QUOTE_POOL_TOKEN_BEACON;
        dependencies[2] = Identifier.TRADING_VAULT_BEACON;
        dependencies[3] = Identifier.POOL_VAULT_BEACON;
        dependencies[4] = Identifier.POOL_MANAGER;
        __BaseContractUpgradeable_init(addressManager, dependencies);
    }

    /// @inheritdoc IPoolFactory
    function deployPoolComponents(
        PoolId poolId,
        address baseToken,
        address quoteToken
    ) external override onlyPoolManager returns (address poolVault, address tradingVault, address basePoolToken, address quotePoolToken) {
        poolVault = _deployPoolVault(poolId, baseToken, quoteToken);
        tradingVault = _deployTradingVault(poolId, baseToken, quoteToken);
        (basePoolToken, quotePoolToken) = _deployPoolTokens(poolId, baseToken, quoteToken);
    }

    /// @notice Deploy a pool vault contract using beacon proxy
    /// @param poolId Pool ID for the vault
    /// @param baseToken Base token address
    /// @param quoteToken Quote token address
    /// @return poolVault Address of the deployed pool vault
    function _deployPoolVault(PoolId poolId, address baseToken, address quoteToken) internal returns (address poolVault) {
        address beacon = _getDependencyAddress(Identifier.POOL_VAULT_BEACON);
        bytes memory initData = abi.encodeWithSelector(IPoolVault.initialize.selector, _getAddressManager(), poolId, baseToken, quoteToken);
        poolVault = address(new BeaconProxy(beacon, initData));
    }

    /// @notice Deploy a trading vault contract using beacon proxy
    /// @param poolId Pool ID for the vault
    /// @param baseToken Base token address
    /// @param quoteToken Quote token address
    /// @return tradingVault Address of the deployed trading vault
    function _deployTradingVault(PoolId poolId, address baseToken, address quoteToken) internal returns (address tradingVault) {
        address beacon = _getDependencyAddress(Identifier.TRADING_VAULT_BEACON);
        bytes memory initData = abi.encodeWithSelector(ITradingVault.initialize.selector, _getAddressManager(), poolId, baseToken, quoteToken);
        tradingVault = address(new BeaconProxy(beacon, initData));
    }

    function _deployPoolTokens(PoolId poolId, address baseToken, address quoteToken) private returns (address basePoolToken, address quotePoolToken) {
        string memory baseTokenSymbol = IERC20Metadata(baseToken).symbol();
        string memory quoteTokenSymbol = IERC20Metadata(quoteToken).symbol();

        basePoolToken = _deployBasePoolToken(
            poolId,
            baseToken,
            string(abi.encodePacked("MYX Finance ", baseTokenSymbol, "-", quoteTokenSymbol, " BasePool Token")),
            string(abi.encodePacked("m", baseTokenSymbol))
        );

        quotePoolToken = _deployQuotePoolToken(
            poolId,
            quoteToken,
            string(abi.encodePacked("MYX Finance ", baseTokenSymbol, "-", quoteTokenSymbol, " QuotePool Token")),
            string(abi.encodePacked("m", quoteTokenSymbol))
        );
    }

    function _deployBasePoolToken(PoolId poolId, address underlyingToken, string memory name, string memory symbol) internal returns (address) {
        address beacon = _getBasePoolTokenBeacon();
        return _deployPoolToken(beacon, poolId, underlyingToken, name, symbol);
    }

    function _deployQuotePoolToken(PoolId poolId, address underlyingToken, string memory name, string memory symbol) internal returns (address) {
        address beacon = _getQuotePoolTokenBeacon();
        return _deployPoolToken(beacon, poolId, underlyingToken, name, symbol);
    }

    function _deployPoolToken(
        address beacon,
        PoolId poolId,
        address underlyingToken,
        string memory name,
        string memory symbol
    ) internal returns (address) {
        bytes memory initData = abi.encodeWithSelector(
            IPoolToken.initialize.selector,
            address(_getAddressManager()),
            poolId,
            underlyingToken,
            name,
            symbol
        );

        BeaconProxy proxy = new BeaconProxy(beacon, initData);
        emit PoolTokenCreated(poolId, underlyingToken, beacon, address(proxy));

        return address(proxy);
    }

    function _onlyPoolManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POOL_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getBasePoolTokenBeacon() internal view returns (address) {
        return _getDependencyAddress(Identifier.BASE_POOL_TOKEN_BEACON);
    }

    function _getQuotePoolTokenBeacon() internal view returns (address) {
        return _getDependencyAddress(Identifier.QUOTE_POOL_TOKEN_BEACON);
    }
}

