// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IMarketManager } from "./../interfaces/IMarketManager.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IOracleReserve } from "./../interfaces/IOracleReserve.sol";
import { IPoolBase } from "./../interfaces/IPoolBase.sol";
import { IPoolConfigurator } from "./../interfaces/IPoolConfigurator.sol";
import { IPoolFactory } from "./../interfaces/IPoolFactory.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { MarketMetadata, LibMarketMetadata } from "./../libraries/Market.sol";
import { Pool, LibPoolMetadata } from "./../libraries/Pool.sol";
import { PoolMetadata } from "./../libraries/Pool.sol";
import { TradingHelper } from "./../libraries/TradingHelper.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { PoolKey } from "./../types/PoolKey.sol";
import { Constants, Errors, MarketId, PoolId, PoolState } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";

/// @title PoolManager
/// @notice Manages pool creation, configuration, and lifecycle
contract PoolManager is BaseContractUpgradeable, ReentrancyGuardUpgradeable, IPoolManager {
    using SafeERC20 for IERC20;
    using Pool for Pool.Data;
    using LibPoolMetadata for PoolMetadata;
    using PrecisionUtils for uint256;
    using Math for uint256;
    using LibMarketMetadata for MarketMetadata;

    /// @notice Pool data storage
    Pool.Data private _poolData;

    modifier ensureMarketExists(MarketId marketId) {
        _ensureMarketExists(marketId);
        _;
    }

    modifier ensurePoolExists(PoolId poolId) {
        _ensurePoolExists(poolId);
        _;
    }

    modifier onlyPoolConfigurator() {
        _onlyPoolConfigurator();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the pool manager contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) public initializer {
        __ReentrancyGuard_init();

        bytes32[] memory identifiers = new bytes32[](10);
        identifiers[0] = Identifier.MARKET_MANAGER;
        identifiers[1] = Identifier.EMITER;
        identifiers[2] = Identifier.RISK_PARAMETER;
        identifiers[3] = Identifier.ORACLE;
        identifiers[4] = Identifier.ORACLE_RESERVE;
        identifiers[5] = Identifier.POOL_FACTORY;
        identifiers[6] = Identifier.POOL_CONFIGURATOR;
        identifiers[7] = Identifier.POSITION_MANAGER;
        identifiers[8] = Identifier.BASE_POOL;
        identifiers[9] = Identifier.QUOTE_POOL;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @inheritdoc IPoolManager
    function checkPoolExists(PoolId poolId) external view returns (bool) {
        return _poolData.poolExists(poolId);
    }

    /// @inheritdoc IPoolManager
    function getPools() external view override returns (bytes32[] memory pools) {
        return _poolData.getPoolIds();
    }

    /// @inheritdoc IPoolManager
    function getPool(PoolId poolId) external view override returns (PoolMetadata memory) {
        return _poolData.getPool(poolId);
    }

    /// @inheritdoc IPoolManager
    function getMarketPool(MarketId marketId, address asset) external view override returns (PoolMetadata memory) {
        return _poolData.getMarketPool(marketId, asset);
    }

    /// @inheritdoc IPoolManager
    function getPoolMarketId(PoolId poolId) external view override returns (MarketId marketId) {
        marketId = _poolData.getPoolMarketId(poolId);
        return (marketId);
    }

    /// @inheritdoc IPoolManager
    function getPoolMarket(PoolId poolId) external view override returns (MarketId marketId, MarketMetadata memory) {
        marketId = _poolData.getPoolMarketId(poolId);
        return (marketId, _getMarketManager().getMarket(marketId));
    }

    /// @inheritdoc IPoolManager
    function getPoolMarketExecutionFee(PoolId poolId) external view override returns (uint256 executionFee) {
        MarketId marketId = _poolData.getPoolMarketId(poolId);
        return _getMarketManager().getExecutionFee(marketId);
    }

    /// @inheritdoc IPoolManager
    function getPoolMarketForwardFee(PoolId poolId) external view override returns (uint256 forwardFee) {
        MarketId marketId = _poolData.getPoolMarketId(poolId);
        return _getMarketManager().getForwardFee(marketId);
    }

    /// @inheritdoc IPoolManager
    function getPairToken(PoolId poolId) external view override returns (address baseToken, address quoteToken) {
        PoolMetadata memory pool = _poolData.getPool(poolId);
        return (pool.baseToken, pool.quoteToken);
    }

    function isPoolAddress(PoolId poolId, address addr) external view override returns (bool) {
        return _poolData.isPoolAddress(poolId, addr);
    }

    /// @inheritdoc IPoolManager
    function getPoolVault(PoolId poolId) external view override returns (address) {
        return _poolData.getPoolVault(poolId);
    }

    /// @inheritdoc IPoolManager
    function getTradingVault(PoolId poolId) external view override returns (address) {
        return _poolData.getTradingVault(poolId);
    }

    /// @inheritdoc IPoolManager
    function getPoolRiskTier(PoolId poolId) external view override returns (uint8) {
        return _poolData.getPoolRiskTier(poolId);
    }

    function deployPool(DeployPoolParams calldata params) external nonReentrant ensureMarketExists(params.marketId) {
        require(params.baseToken != address(0), Errors.InvalidBaseToken());

        PoolKey memory poolKey = PoolKey({ marketId: params.marketId, baseToken: params.baseToken });
        PoolId poolId = poolKey.toId();

        PoolMetadata memory poolMetadata = _poolData.getPool(poolId);
        MarketMetadata memory market = _getMarketManager().getMarket(params.marketId);
        require(market.isMarketInitialized(), Errors.MarketNotExist(params.marketId));
        require(!poolMetadata.isPoolInitialized(), Errors.PoolExists(poolId));
        require(params.baseToken != market.quoteToken, Errors.InvalidBaseToken());
        require(IERC20Metadata(params.baseToken).decimals() < 19, Errors.InvalidBaseToken());

        (address poolVault, address tradingVault, address basePoolToken, address quotePoolToken) = _getPoolFactory().deployPoolComponents(
            poolId,
            params.baseToken,
            market.quoteToken
        );

        _poolData.createPool(params.marketId, poolId, params.baseToken, market.quoteToken, basePoolToken, quotePoolToken, poolVault, tradingVault);

        _getEmiter().emitPoolDeployed(
            IEmiter.PoolDeployedParams({
                marketId: params.marketId,
                poolId: poolId,
                deployer: msg.sender,
                baseToken: params.baseToken,
                quoteToken: market.quoteToken,
                basePoolToken: basePoolToken,
                quotePoolToken: quotePoolToken
            })
        );
    }

    function boostPool(BoostPoolParams calldata params) external nonReentrant ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];
        MarketMetadata memory markInfo = _getMarketManager().getMarket(poolMetadata.marketId);

        require(poolMetadata.isCooked(), UnexpectedPoolState());
        uint256 boostFeeUsd = _getMarketManager().getBoostFee(poolMetadata.marketId);
        uint256 boostFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, poolMetadata.quoteToken, boostFeeUsd);

        _getOracleReserve().chargeBoostFee(params.poolId, msg.sender, boostFee);

        _poolData.updatePoolState(params.poolId, PoolState.Boosted);

        _getEmiter().emitPoolBoosted(
            IEmiter.PoolBoostedParams({ poolId: params.poolId, proposer: msg.sender, token: markInfo.quoteToken, amount: boostFee })
        );
    }

    function unboostPool(UnboostPoolParams calldata params) external nonReentrant ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];
        MarketMetadata memory markInfo = _getMarketManager().getMarket(poolMetadata.marketId);
        address proposer = _getOracleReserve().getPoolBoostFee(params.poolId).proposer;

        require(proposer == msg.sender, UnauthorizedUnboost());
        require(poolMetadata.isBoosted(), UnexpectedPoolState());
        uint256 boostRefundFeeUsd = _getMarketManager().getBoostRefundFee(poolMetadata.marketId);
        uint256 boostRefundFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, poolMetadata.quoteToken, boostRefundFeeUsd);
        _getOracleReserve().confirmBoostFee(params.poolId, false);

        _poolData.updatePoolState(params.poolId, PoolState.Cook);

        _getEmiter().emitPoolUnboosted(
            IEmiter.PoolUnboostedParams({ poolId: params.poolId, proposer: msg.sender, token: markInfo.quoteToken, refundFee: boostRefundFee })
        );
    }

    function reprimePool(RePrimePoolParams calldata params) external nonReentrant ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];
        MarketMetadata memory markInfo = _getMarketManager().getMarket(poolMetadata.marketId);

        require(poolMetadata.isBench(), UnexpectedPoolState());
        uint256 oracleFeeUsd = _getMarketManager().getOracleFee(poolMetadata.marketId);
        uint256 oracleFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, poolMetadata.quoteToken, oracleFeeUsd);

        _getOracleReserve().chargeOracleFeeFromPrimer(params.poolId, msg.sender, oracleFee);

        _poolData.updatePoolState(params.poolId, PoolState.Primed);

        _getEmiter().emitPoolReprimed(
            IEmiter.PoolReprimedParams({ poolId: params.poolId, primer: msg.sender, token: markInfo.quoteToken, amount: oracleFee })
        );
    }

    function primePoolFromBoost(PrimePoolFromBoostedParams calldata params) external onlyPoolConfigurator ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];
        MarketMetadata memory markInfo = _getMarketManager().getMarket(poolMetadata.marketId);

        require(poolMetadata.isBoosted(), UnexpectedPoolState());
        uint256 boostFeeUsd = _getMarketManager().getBoostFee(poolMetadata.marketId);
        uint256 boostFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, poolMetadata.quoteToken, boostFeeUsd);

        _getOracleReserve().confirmBoostFee(params.poolId, true);
        _poolData.updatePoolState(params.poolId, PoolState.Primed);

        _getEmiter().emitPoolPrimed(
            IEmiter.PoolPrimedParams({
                poolId: params.poolId,
                baseToken: poolMetadata.baseToken,
                quoteToken: markInfo.quoteToken,
                baseAmount: 0,
                quoteAmount: boostFee
            })
        );
    }

    function primePool(PrimePoolParams calldata params) external onlyPoolConfigurator ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];
        MarketMetadata memory markInfo = _getMarketManager().getMarket(poolMetadata.marketId);
        uint256 oracleFeeUsd = _getMarketManager().getOracleFee(poolMetadata.marketId);
        uint256 oracleFee = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, poolMetadata.quoteToken, oracleFeeUsd);

        require(poolMetadata.isCooked(), UnexpectedPoolState());

        if (!_checkPrimeable(poolMetadata, markInfo.poolPrimeThreshold, params.referencePrice)) revert LPNotFullyMinted();
        (uint256 baseAmount, uint256 quoteAmount) = IPoolVault(poolMetadata.poolVault).disburseToOracleReserve(oracleFee, params.referencePrice);

        _getOracleReserve().chargeOracleFeeFromPoolVault(params.poolId, poolMetadata.poolVault, baseAmount, quoteAmount);

        _poolData.updatePoolState(params.poolId, PoolState.Primed);

        _getEmiter().emitPoolPrimed(
            IEmiter.PoolPrimedParams({
                poolId: params.poolId,
                baseToken: poolMetadata.baseToken,
                quoteToken: markInfo.quoteToken,
                baseAmount: baseAmount,
                quoteAmount: quoteAmount
            })
        );
    }

    function trenchPool(TrenchPoolParams calldata params) external onlyPoolConfigurator ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];
        MarketMetadata memory markInfo = _getMarketManager().getMarket(poolMetadata.marketId);

        require(poolMetadata.isPrimed(), UnexpectedPoolState());
        require(_getOracleReserve().isBaseFeeSoldOut(params.poolId), BaseFeeNotSoldOut());

        _getOracleReserve().refreshOracleFee(params.poolId);

        _poolData.activatePool(params.poolId, params.riskTier);

        _getEmiter().emitPoolActivated(
            IEmiter.PoolActivatedParams({
                poolId: poolMetadata.poolId,
                baseToken: poolMetadata.baseToken,
                quoteToken: markInfo.quoteToken,
                oracleType: params.oracleType,
                oracleFeedId: params.oracleFeedId
            })
        );
    }

    function perBenchPool(PerBenchPoolParams calldata params) external onlyPoolConfigurator ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];
        require(poolMetadata.isTrench(), UnexpectedPoolState());

        _poolData.updatePoolState(params.poolId, PoolState.PreBench);

        _getEmiter().emitPoolPreDeactivated(IEmiter.PoolPreDeactivatedParams({ poolId: params.poolId, remark: params.remark }));
    }

    function benchPool(
        IOracle.UpdateOraclePriceParams[] calldata prices,
        BenchPoolParams calldata params
    ) external payable onlyPoolConfigurator ensurePoolExists(params.poolId) {
        PoolMetadata memory poolMetadata = _poolData._pools[params.poolId];

        if (poolMetadata.isBoosted()) {
            _getOracleReserve().confirmBoostFee(params.poolId, false);

            _getEmiter().emitPoolTrenchFailed(IEmiter.PoolTrenchFailedParams({ poolId: params.poolId, remark: params.remark }));
        } else if (poolMetadata.isPrimed()) {
            _getOracleReserve().refreshOracleFee(params.poolId);

            _getEmiter().emitPoolTrenchFailed(IEmiter.PoolTrenchFailedParams({ poolId: params.poolId, remark: params.remark }));
        } else if (poolMetadata.isPreBench()) {
            require(_checkPositionTracker(poolMetadata), PositionNotEmpty());
            require(_checkPoolDebt(poolMetadata), PoolDebtNotCleared());

            _getOracle().updatePrices{ value: msg.value }(prices);

            uint256 latestPrice = _getOracle().safeOraclePrice(params.poolId);
            IPoolBase(_getDependencyAddress(Identifier.BASE_POOL)).updatePool(params.poolId, latestPrice);
            IPoolBase(_getDependencyAddress(Identifier.QUOTE_POOL)).updatePool(params.poolId, latestPrice);
        }

        _poolData.updatePoolState(params.poolId, PoolState.Bench);

        _getEmiter().emitPoolDeactivated(
            IEmiter.PoolDeactivatedParams({
                poolId: params.poolId,
                baseToken: poolMetadata.baseToken,
                quoteToken: poolMetadata.quoteToken,
                remark: params.remark
            })
        );
    }

    function updatePoolCompoundEnabled(IPoolConfigurator.UpdatePoolCompoundEnabledParams[] calldata params) external onlyPoolConfigurator {
        for (uint256 i = 0; i < params.length; ++i) {
            if (!_poolData.poolExists(params[i].poolId)) continue;

            _poolData.updateCompoundEnabled(params[i].poolId, params[i].enabled);
        }
    }

    function updatePoolRiskTiers(IPoolConfigurator.UpdatePoolRiskTierParams[] calldata params) external onlyPoolConfigurator {
        IRiskParameter riskParameter = _getRiskParameter();
        for (uint256 i = 0; i < params.length; ++i) {
            if (!_poolData.poolExists(params[i].poolId)) continue;
            require(riskParameter.isValidRiskTier(params[i].riskTier), Errors.InvalidParameter());

            _poolData.updateRiskTier(params[i].poolId, params[i].riskTier);
        }
    }

    function _checkPrimeable(PoolMetadata memory poolMetadata, uint128 poolPrimeThreshold, uint256 initPrice) internal view returns (bool) {
        IPoolVault.PoolReserve memory reserveInfo = IPoolVault(poolMetadata.poolVault).reserveInfo();
        uint256 baseValueUsdWad = reserveInfo.baseTotalAmount.mulPrice(initPrice).toWad(IERC20Metadata(poolMetadata.baseToken).decimals());
        uint256 quoteValueUsdWad = reserveInfo.quoteTotalAmount.toWad(IERC20Metadata(poolMetadata.quoteToken).decimals());
        return baseValueUsdWad + quoteValueUsdWad >= uint256(poolPrimeThreshold).toWad(0);
    }

    function _checkPositionTracker(PoolMetadata memory poolMetadata) internal view returns (bool) {
        IPositionManager.OITracker memory oiTracker = _getPositionManager().getOITracker(poolMetadata.poolId);
        return oiTracker.longSize == 0 && oiTracker.shortSize == 0;
    }

    function _checkPoolDebt(PoolMetadata memory pool) internal view returns (bool) {
        ITradingVault.DebtInfo memory debtInfo = ITradingVault(pool.tradingVault).debtInfo();
        return debtInfo.totalDebt == 0;
    }

    function _ensureMarketExists(MarketId marketId) internal view {
        require(_getMarketManager().marketExists(marketId), Errors.MarketNotExist(marketId));
    }

    function _ensurePoolExists(PoolId poolId) internal view {
        require(_poolData.poolExists(poolId), Errors.PoolNotExist(poolId));
    }

    function _onlyPoolConfigurator() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POOL_CONFIGURATOR), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getMarketManager() internal view returns (IMarketManager) {
        return IMarketManager(super._getDependencyAddress(Identifier.MARKET_MANAGER));
    }

    function _getPoolFactory() internal view returns (IPoolFactory) {
        return IPoolFactory(super._getDependencyAddress(Identifier.POOL_FACTORY));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(super._getDependencyAddress(Identifier.EMITER));
    }

    function _getRiskParameter() internal view returns (IRiskParameter) {
        return IRiskParameter(super._getDependencyAddress(Identifier.RISK_PARAMETER));
    }

    function _getOracleReserve() internal view returns (IOracleReserve) {
        return IOracleReserve(super._getDependencyAddress(Identifier.ORACLE_RESERVE));
    }

    function _getPositionManager() internal view returns (IPositionManager) {
        return IPositionManager(super._getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getOracle() internal view returns (IOracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }
}

