// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IAddressManager } from "./../interfaces/IAddressManager.sol";
import { IEIP7702Delegation } from "./../interfaces/IEIP7702Delegation.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { Errors } from "./../types/Types.sol";

contract EIP7702Delegation is ReentrancyGuard, IEIP7702Delegation {
    using EnumerableSetLib for EnumerableSetLib.AddressSet;

    address public immutable ADDRESS_MANAGER;

    EnumerableSetLib.AddressSet private _allowedTargets;

    event AllowedTargetAdded(address target);
    event AllowedTargetRemoved(address target);

    modifier allowedTarget(address target) {
        _allowedTarget(target);
        _;
    }

    modifier onlySelfOrForwarder() {
        _onlySelfOrForwarder();
        _;
    }

    modifier onlyRiskAdmin() {
        _onlyRiskAdmin();
        _;
    }

    constructor(address addressManager) {
        ADDRESS_MANAGER = addressManager;
    }

    function getAllowedTargets() external view returns (address[] memory) {
        return _allowedTargets.values();
    }

    function isAllowedTarget(address target) external view returns (bool) {
        return _allowedTargets.contains(target);
    }

    function addAllowedTargets(address[] calldata targets) external onlyRiskAdmin {
        for (uint256 i; i < targets.length; ++i) {
            _allowedTargets.add(targets[i]);
            emit AllowedTargetAdded(targets[i]);
        }
    }

    function removeAllowedTargets(address[] calldata targets) external onlyRiskAdmin {
        for (uint256 i; i < targets.length; ++i) {
            _allowedTargets.remove(targets[i]);
            emit AllowedTargetRemoved(targets[i]);
        }
    }

    function updatePriceAndBatchExecute(SelfCallRequestData[] calldata bundleParams) external payable onlySelfOrForwarder nonReentrant {
        _safeCall(bundleParams[0].target, bundleParams[0].value, bundleParams[0].data);
        for (uint256 i = 1; i < bundleParams.length; ++i) {
            _safeCallWithoutValue(bundleParams[i].target, bundleParams[i].data);
        }
    }

    function selfExecute(SelfCallRequestData calldata params) public payable onlySelfOrForwarder nonReentrant {
        _safeCall(params.target, params.value, params.data);
    }

    function batchSelfExecute(SelfCallRequestData[] calldata bundleParams) external payable onlySelfOrForwarder nonReentrant {
        for (uint256 i = 0; i < bundleParams.length; ++i) {
            _safeCall(bundleParams[i].target, bundleParams[i].value, bundleParams[i].data);
        }
    }

    function _safeCallWithoutValue(address target, bytes memory data) internal allowedTarget(target) returns (bytes memory) {
        (bool success, bytes memory returnData) = target.call(data);

        if (!success) {
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }
        return returnData;
    }

    function _safeCall(address target, uint256 value, bytes memory data) internal allowedTarget(target) returns (bytes memory) {
        (bool success, bytes memory returnData) = target.call{ value: value }(data);

        if (!success) {
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }
        return returnData;
    }

    function _allowedTarget(address target) internal view {
        if (!_allowedTargets.contains(target)) revert NotAllowedTarget(target);
    }

    function _onlySelfOrForwarder() internal view {
        require(
            msg.sender == address(this) || msg.sender == IAddressManager(ADDRESS_MANAGER).getAddress(Identifier.FORWARDER),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _onlyRiskAdmin() internal view {
        require(
            IRoleManager(IAddressManager(ADDRESS_MANAGER).getRoleManager()).isRiskAdmin(msg.sender),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }
}

