// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.24;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { EnumerableMapLib } from "@solady/utils/EnumerableMapLib.sol";
import { IPoolManager } from "./../../src/interfaces/IPoolManager.sol";
import { IExecutionPool } from "./../interfaces/IExecutionPool.sol";
import { IForwarder } from "./../interfaces/IForwarder.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors, TxId, PoolId } from "./../types/Types.sol";

/// @title ExecutionPool
/// @notice Async execution pool for relayer-based order execution.
contract ExecutionPool is BaseContractUpgradeable, ReentrancyGuardUpgradeable, IExecutionPool {
    using EnumerableMapLib for EnumerableMapLib.Bytes32ToUint256Map;

    /// @notice Time window (seconds) after submission before public execution is allowed
    uint64 public gracePeriod;
    /// @notice Maximum number of pending executions allowed per user address
    uint256 public maxPendingCount;
    /// @notice Selector => gasEscrow amount mapping
    EnumerableMapLib.Bytes32ToUint256Map private _gasEscrowMap;
    /// @notice Current pending execution count per user
    mapping(address user => uint256 count) public pendingCount;
    /// @notice Stored pending executions indexed by user-provided TxId
    mapping(TxId txId => PendingExecution execution) private _executions;

    modifier onlyForwarder() {
        _onlyForwarder();
        _;
    }

    modifier onlyRiskAdmin() {
        _onlyRiskAdmin();
        _;
    }

    modifier checkPoolExists(PoolId[] memory updatePricePoolIds) {
        _checkPoolExists(updatePricePoolIds);
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, uint64 _gracePeriod) public initializer {
        gracePeriod = _gracePeriod;
        __ReentrancyGuard_init();

        bytes32[] memory identifiers = new bytes32[](3);
        identifiers[0] = Identifier.FORWARDER;
        identifiers[1] = Identifier.PAYMASTER;
        identifiers[2] = Identifier.POOL_MANAGER;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @inheritdoc IExecutionPool
    function getExecutionRequest(TxId txId) external view returns (bool isExpired, IForwarder.ForwardRequestData memory) {
        PendingExecution memory execution = _executions[txId];
        return ( execution.deadline < block.timestamp, IForwarder.ForwardRequestData({
            from: execution.from,
            to: execution.to,
            value: execution.value,
            gas: execution.gas,
            deadline: execution.deadline,
            data: execution.data,
            signature: ""
        }));
    }

    function setGracePeriod(uint64 _gracePeriod) external onlyRiskAdmin {
        gracePeriod = _gracePeriod;
        emit GracePeriodUpdated(_gracePeriod);
    }

    function setGasEscrowForSelector(bytes4 selector, uint256 escrow) external onlyRiskAdmin {
        _gasEscrowMap.set(bytes32(selector), escrow);
        emit GasEscrowSelectorUpdated(selector, escrow);
    }

    function removeGasEscrowForSelector(bytes4 selector) external onlyRiskAdmin {
        _gasEscrowMap.remove(bytes32(selector));
        emit GasEscrowSelectorRemoved(selector);
    }

    function getGasEscrowForSelector(bytes4 selector) external view returns (uint256) {
        return _gasEscrowMap.get(bytes32(selector));
    }

    function getAllGasEscrowSelectors() external view returns (bytes32[] memory selectors, uint256[] memory escrows) {
        selectors = _gasEscrowMap.keys();
        escrows = new uint256[](selectors.length);
        for (uint256 i = 0; i < selectors.length; ++i) {
            escrows[i] = _gasEscrowMap.get(selectors[i]);
        }
    }

    function setMaxPendingCount(uint256 _maxPendingCount) external onlyRiskAdmin {
        maxPendingCount = _maxPendingCount;
        emit MaxPendingUpdated(_maxPendingCount);
    }

    /// @inheritdoc IExecutionPool
    function submit(
        TxId txId,
        PendingExecution memory execution,
        PoolId[] memory updatePricePoolIds
    ) external payable nonReentrant checkPoolExists(updatePricePoolIds) {
        require(execution.data.length >= 4, InvalidDataLength());
        bytes32 selKey = bytes32(bytes4(execution.data));
        require(_gasEscrowMap.contains(selKey), SelectorNotRegistered(bytes4(execution.data)));
        require(msg.value == _gasEscrowMap.get(selKey), InvalidGasEscrow());
        require(execution.from == msg.sender, InvalidRequest());
        require(execution.deadline > block.timestamp, DeadlineInPast());
        require(_executions[txId].from == address(0), TxIdAlreadyExists(txId));
        require(pendingCount[msg.sender] < maxPendingCount, MaxPendingExceeded());

        execution.createdAt = uint48(block.timestamp);
        execution.gasEscrow = msg.value;
        _executions[txId] = execution;
        pendingCount[msg.sender]++;
        emit ExecutionSubmitted(txId, updatePricePoolIds, execution.from, execution.deadline);
    }

    /// @inheritdoc IExecutionPool
    function cancel(TxId txId) external nonReentrant {
        PendingExecution memory execution = _executions[txId];
        require(execution.from == msg.sender, NotExecutionOwner(txId));

        _cancel(txId, execution.from);
        emit ExecutionCancelled(txId, "User Cancelled");
    }

    function executePublic(
        TxId txId,
        IOracle.UpdateOraclePriceParams[] calldata params
    ) external payable {
        require(_executions[txId].createdAt + gracePeriod < block.timestamp,GracePeriodNotExpired());
        _getForwarder().executeForwarderTx{ value: msg.value }(txId, msg.sender, params);
    }

    /// @inheritdoc IExecutionPool
    function cancelExpired(TxId txId) external nonReentrant onlyForwarder {
        PendingExecution memory execution = _executions[txId];
        require(execution.from != address(0), ExecutionsNotExist(txId));
        require(execution.deadline < block.timestamp, ExecutionNotExpired(txId));

        _cancel(txId, execution.from);
        emit ExecutionCancelled(txId, "Expired");
    }

    /// @inheritdoc IExecutionPool
    function consumeExecutions(TxId[] calldata txIds) external nonReentrant onlyForwarder {
        uint256 gasAmount;
        for (uint256 i = 0; i < txIds.length; ++i) {
            PendingExecution memory execution = _executions[txIds[i]];
            require(execution.from != address(0), ExecutionsNotExist(txIds[i]));
            require(execution.deadline >= block.timestamp, ExecutionExpired(txIds[i]));
            gasAmount += execution.gasEscrow;
            delete _executions[txIds[i]];
            pendingCount[execution.from]--;
        }

        require(address(this).balance >= gasAmount, RefundExceedsEscrow(gasAmount, address(this).balance));
        emit GasCollected(txIds, gasAmount);

        (bool success, ) = _getPaymasterAddr().call{ value: gasAmount }("");
        require(success, CollectFailed());

        emit ExecutionExecuted(txIds);
    }

    function _cancel(TxId txId, address from) internal {
        uint256 escrow = _executions[txId].gasEscrow;
        require(address(this).balance >= escrow, InsufficientGasEscrow());
        delete _executions[txId];
        pendingCount[from]--;

        (bool success, ) = _getPaymasterAddr().call{ value: escrow }("");
        require(success, CollectFailed());
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getForwarder() internal view returns (IForwarder) {
        return IForwarder(_getDependencyAddress(Identifier.FORWARDER));
    }

    function _getPaymasterAddr() internal view returns (address) {
        return super._getDependencyAddress(Identifier.PAYMASTER);
    }

    function _checkPoolExists(PoolId[] memory poolIds) internal view {
        IPoolManager poolManager = _getPoolManager();
        for (uint256 i = 0; i < poolIds.length; ++i) {
            require(poolManager.checkPoolExists(poolIds[i]), PoolNotExists(poolIds[i]));
        }
    }

    function _onlyForwarder() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.FORWARDER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyRiskAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isRiskAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

}

