// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { ICollectFee } from "./../interfaces/ICollectFee.sol";
import { IExecutionPool } from "./../interfaces/IExecutionPool.sol";
import { IForwarder } from "./../interfaces/IForwarder.sol";
import { IMarketManager } from "./../interfaces/IMarketManager.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IPaymaster } from "./../interfaces/IPaymaster.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { ITradingRouter } from "./../interfaces/ITradingRouter.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors, TxId } from "./../types/Types.sol";
import { ERC2771ContextUpgradeable } from "./ERC2771ContextUpgradeable.sol";
import { ERC2771ForwarderUpgradeable } from "./ERC2771ForwarderUpgradeable.sol";

contract Forwarder is
    BaseContractUpgradeable,
    ERC2771ContextUpgradeable,
    ReentrancyGuardUpgradeable,
    ERC2771ForwarderUpgradeable,
    IForwarder,
    ICollectFee
{
    using EnumerableSetLib for EnumerableSetLib.AddressSet;
    using SafeERC20 for IERC20;

    /// @notice Whether forward mode is active
    bool private transient _forwardMode;
    /// @notice Token address to be collected for forward fee
    address private transient _designatedToken;
    /// @notice Balance of the designated token before collecting forward fee
    uint256 private transient _balanceBefore;

    uint256 public equilibriumGas;
    mapping(address relayer => address account) public originAccount;

    mapping(address account => EnumerableSetLib.AddressSet relayers) private userRelayers;
    EnumerableSetLib.AddressSet private _allowedAddress;
    EnumerableSetLib.AddressSet private _relayers;

    event RelayerAdded(address relayer);
    event RelayerRemoved(address relayer);

    modifier recordTokenBalance(address designatedToken) {
        _recordTokenBalance(designatedToken);
        _;
    }

    modifier allowedToTarget(address target) {
        _allowedToTarget(target);
        _;
    }

    modifier onlyRiskAdmin() {
        _onlyRiskAdmin();
        _;
    }

    modifier onlyRelayer() {
        _onlyRelayer();
        _;
    }

    modifier onlyRelayerOrExecutionPool() {
        _onlyRelayerOrExecutionPool();
        _;
    }

    modifier onlyTradingRouter() {
        _onlyTradingRouter();
        _;
    }

    modifier onlySelf() {
        _onlySelf();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, uint256 _equilibriumGas) public initializer {
        __ERC2771Forwarder_init("MYX Finance Forwarder");
        __ERC2771ContextUpgradeable_init(address(this));
        __ReentrancyGuard_init();

        equilibriumGas = _equilibriumGas;
        bytes32[] memory identifiers = new bytes32[](5);
        identifiers[0] = Identifier.PAYMASTER;
        identifiers[1] = Identifier.MARKET_MANAGER;
        identifiers[2] = Identifier.TRADING_ROUTER;
        identifiers[3] = Identifier.EXECUTION_POOL;
        identifiers[4] = Identifier.ORACLE;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @inheritdoc ICollectFee
    function getDesignatedToken() public view override returns (address) {
        return _designatedToken;
    }

    function inForwardMode() external view returns (bool) {
        return _forwardMode;
    }

    function isAllowedTargets(address contractAddr) external view returns (bool) {
        return _allowedAddress.contains(contractAddr);
    }

    function getAllowedTargets() external view returns (address[] memory) {
        return _allowedAddress.values();
    }

    function getRelayers() external view returns (address[] memory) {
        return _relayers.values();
    }

    function getEquilibriumGas() external view returns (uint256) {
        return equilibriumGas;
    }

    function getUserRelayers(address account) external view returns (address[] memory) {
        return userRelayers[account].values();
    }

    function isUserRelayerEnabled(address account, address relayer) external view returns (bool) {
        return userRelayers[account].contains(relayer);
    }

    function exitForwardMode() external onlyTradingRouter {
        _forwardMode = false;
    }

    function addAllowedTarget(address target) external onlyRiskAdmin {
        _allowedAddress.add(target);
        emit AddAllowedTarget(target);
    }

    function removeAllowedTarget(address target) external onlyRiskAdmin {
        _allowedAddress.remove(target);
        emit RemoveAllowedTarget(target);
    }

    function addRelayers(address[] calldata relayers) external onlyRiskAdmin {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.add(relayers[i]);
            emit RelayerAdded(relayers[i]);
        }
    }

    function removeRelayers(address[] calldata relayers) external onlyRiskAdmin {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.remove(relayers[i]);
            emit RelayerRemoved(relayers[i]);
        }
    }

    function updateEquilibriumGas(uint256 _equilibriumGas) external onlyRiskAdmin {
        uint256 oldEquilibriumGas = equilibriumGas;
        equilibriumGas = _equilibriumGas;
        emit UpdateEquilibriumGas(msg.sender, oldEquilibriumGas, _equilibriumGas);
    }

    function permitAndApproveForwarder(address relayer, bool enable, ERC20PermitParams[] calldata permitParams) external onlySelf {
        require(permitParams.length < 10, InconsistentParamsLength());

        for (uint256 i; i < permitParams.length; ++i) {
            try
                IERC20Permit(permitParams[i].token).permit(
                    permitParams[i].owner,
                    permitParams[i].spender,
                    permitParams[i].value,
                    permitParams[i].deadline,
                    permitParams[i].v,
                    permitParams[i].r,
                    permitParams[i].s
                )
            {} catch Error(string memory reason) {
                emit ERC20PermitFailed(permitParams[i].token, reason);
            } catch (bytes memory lowLevelData) {
                emit ERC20PermitLowLevelFailed(lowLevelData);
            }
        }
        _approveForwarder(_msgOrigin(), relayer, enable);

        ITradingRouter(_getDependencyAddress(Identifier.TRADING_ROUTER)).collectForwardFeeIfNecessary(
            ICollectFee.FeeSource.Direct,
            abi.encode(ICollectFee.AddressFeeParams({ feeToken: _designatedToken, user: _msgOrigin() }))
        );
    }

    function execute(IForwarder.ForwardRequestData calldata, address) public payable override {
        revert("Deprecated");
    }

    function executeBatch(IForwarder.ForwardRequestData[] calldata, address, address payable) public payable override {
        revert("Deprecated");
    }

    function executeForwarderTx(
        TxId txId,
        address operator,
        IOracle.UpdateOraclePriceParams[] calldata params
    ) external payable nonReentrant onlyRelayerOrExecutionPool {
        if( params.length > 0) _getMYXOracle().updatePrices{ value: msg.value }(params);

        IExecutionPool executionPool = _getExecutionPool();
        (bool isExpired, ForwardRequestData memory execution) = executionPool.getExecutionRequest(txId);
        if ( isExpired ) {
            executionPool.cancelExpired(txId);
            return;
        }
        require(_allowedAddress.contains(execution.to), NotAllowedTarget(execution.to));
        _executeTx(execution, execution.from);

        TxId[] memory txIds = new TxId[](1);
        txIds[0] = txId;
        executionPool.consumeExecutions(txIds);

        operator = msg.sender == address(executionPool) ? operator : msg.sender;
        _getPaymaster().sponsorGas(payable(operator), equilibriumGas);
    }

    function batchExecuteForwarderTx(
        TxId[] calldata txIds,
        IOracle.UpdateOraclePriceParams[] calldata params
    ) external payable nonReentrant onlyRelayer  {
        if( params.length > 0) _getMYXOracle().updatePrices{ value: msg.value }(params);

        IExecutionPool executionPool = _getExecutionPool();
        TxId[] memory executedTxIds = new TxId[](txIds.length);
        uint256 executedCount;

        for (uint256 i; i < txIds.length; ++i) {
            (bool isExpired, ForwardRequestData memory execution) = executionPool.getExecutionRequest(txIds[i]);
            if ( isExpired ) {
                executionPool.cancelExpired(txIds[i]);
                continue;
            }
            require(_allowedAddress.contains(execution.to), NotAllowedTarget(execution.to));
            _executeTx(execution, execution.from);
            executedTxIds[executedCount++] = txIds[i];
        }

        assembly {
            mstore(executedTxIds, executedCount)
        }

        if (executedCount > 0) executionPool.consumeExecutions(executedTxIds);
        _getPaymaster().sponsorGas(payable(msg.sender), equilibriumGas);
    }

    function executeForwarderWithPrice(
        address forwardFeeToken,
        ForwardRequestData calldata params,
        IOracle.UpdateOraclePriceParams[] calldata prices
    ) external payable nonReentrant recordTokenBalance(forwardFeeToken) onlyRelayer {
        _getMYXOracle().updatePrices{ value: msg.value }(prices);
        require(_allowedAddress.contains(params.to), NotAllowedTarget(params.to));
        address masterAccount = _masterAccount(params.from, params.data);

        ERC2771ForwarderUpgradeable.execute(params, masterAccount);
        _consumeForwardFee(params.from);
        _getPaymaster().sponsorGas(payable(msg.sender), equilibriumGas);
    }

    function executeForwarder(
        address forwardFeeToken,
        ForwardRequestData calldata params
    ) external payable nonReentrant recordTokenBalance(forwardFeeToken) onlyRelayer {
        require(_allowedAddress.contains(params.to), NotAllowedTarget(params.to));
        address masterAccount = _masterAccount(params.from, params.data);

        ERC2771ForwarderUpgradeable.execute(params, masterAccount);
        _consumeForwardFee(params.from);
        _getPaymaster().sponsorGas(payable(msg.sender), equilibriumGas);
    }

    function batchExecuteForwarder(
        address forwardFeeToken,
        ForwardRequestData[] calldata bundleParams
    ) external payable nonReentrant recordTokenBalance(forwardFeeToken) onlyRelayer {
        address from = _checkBundleValidity(bundleParams);
        address masterAccount = _masterAccount(from, bundleParams[0].data);

        ERC2771ForwarderUpgradeable.executeBatch(bundleParams, masterAccount, payable(msg.sender));
        _consumeForwardFee(from);
        _getPaymaster().sponsorGas(payable(msg.sender), equilibriumGas);
    }

    function _approveForwarder(address account, address relayer, bool enable) internal {
        if (enable) {
            require(originAccount[relayer] == address(0), RelayerRegistered(relayer));
            userRelayers[account].add(relayer);
            originAccount[relayer] = account;
        } else {
            bool result = userRelayers[account].remove(relayer);
            require(result, RemoveRelayerFailed());
            delete originAccount[relayer];
        }
        emit SetUserRelayer(account, relayer, enable);
    }

    function _checkBundleValidity(ForwardRequestData[] calldata bundleParams) internal view returns (address) {
        address expectedFrom = bundleParams[0].from;
        for (uint256 i = 0; i < bundleParams.length; ++i) {
            ForwardRequestData calldata req = bundleParams[i];
            require(req.from == expectedFrom, MismatchedSender(req.from));
            require(_allowedAddress.contains(req.to), NotAllowedTarget(req.to));
        }
        return expectedFrom;
    }

    function _consumeForwardFee(address from) internal {
        address sender = originAccount[from];
        address designatedToken = getDesignatedToken();

        uint256 balanceAfter = IERC20(designatedToken).balanceOf(address(_getPaymaster()));
        uint256 expectedFee = _getMarketManager().getForwardFeeByToken(designatedToken);
        require(balanceAfter == _balanceBefore + expectedFee, Errors.MismatchExecuteFee(_balanceBefore, balanceAfter, expectedFee));
        emit ChargeForwardFee(sender, designatedToken, expectedFee);
    }

    function _recordTokenBalance(address designatedToken) internal {
        _forwardMode = true;
        _designatedToken = designatedToken;
        _balanceBefore = IERC20(_designatedToken).balanceOf(address(_getPaymaster()));
    }

    function _masterAccount(address from, bytes memory data) internal view returns (address) {
        bytes4 selector;
        assembly {
            selector := mload(add(data, 32))
        }
        return selector == IForwarder.permitAndApproveForwarder.selector ? from : originAccount[from];
    }

    function _allowedToTarget(address target) internal view {
        if (!_allowedAddress.contains(target)) revert NotAllowedTarget(target);
    }

    function _onlyRiskAdmin() internal view {
        if (!IRoleManager(_getAddressManager().getRoleManager()).isRiskAdmin(msg.sender)) {
            revert Errors.PermissionDenied(msg.sender, address(this));
        }
    }

    function _onlySelf() internal view {
        if (msg.sender != address(this)) revert Errors.PermissionDenied(msg.sender, address(this));
    }

    function _onlyRelayer() internal view {
        require(_relayers.contains(msg.sender), Errors.OnlyRelayer());
    }

    function _onlyRelayerOrExecutionPool() internal view {
        require(_relayers.contains(msg.sender) || _msgSender() == _getDependencyAddress(Identifier.EXECUTION_POOL), Errors.PermissionDenied(_msgSender(), address(this)));
    }

    function _onlyTradingRouter() internal view {
        require(_msgSender() == _getDependencyAddress(Identifier.TRADING_ROUTER), Errors.PermissionDenied(_msgSender(), address(this)));
    }

    function _getMarketManager() internal view returns (IMarketManager) {
        return IMarketManager(_getDependencyAddress(Identifier.MARKET_MANAGER));
    }

    function _getPaymaster() internal view returns (IPaymaster) {
        return IPaymaster(super._getDependencyAddress(Identifier.PAYMASTER));
    }

    function _getExecutionPool() internal view returns (IExecutionPool) {
        return IExecutionPool(_getDependencyAddress(Identifier.EXECUTION_POOL));
    }

    function _getMYXOracle() internal view returns (IOracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }
}

