// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IBasePool } from "./../interfaces/IBasePool.sol";
import { ICollectFee } from "./../interfaces/ICollectFee.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IKeeperRegistry } from "../interfaces/IKeeperRegistry.sol";
import { ILiquidityRouter } from "./../interfaces/ILiquidityRouter.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IQuotePool } from "./../interfaces/IQuotePool.sol";
import { ITradingRouter } from "./../interfaces/ITradingRouter.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { ERC2771ContextUpgradeable } from "./../router/ERC2771ContextUpgradeable.sol";
import { PoolMetadata, PoolId, PoolType, TriggerType, Errors } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";

/**
 * @title LiquidityRouter
 * @notice Router contract for liquidity pool operations and take-profit/stop-loss order management
 * @dev This contract serves as the primary entry point for users to interact with liquidity pools, providing:
 * 1. Deposit and withdrawal operations for Base Pool and Quote Pool
 * 2. Creation, management and automated execution of TPSL (Take Profit Stop Loss) orders
 * 3. Asset exchange functionality during Base Pool withdrawals (Base token to Quote token)
 * 4. Price trigger validation and order execution mechanisms
 */
contract LiquidityRouter is BaseContractUpgradeable, ERC2771ContextUpgradeable, ReentrancyGuardUpgradeable, ILiquidityRouter {
    using EnumerableSetLib for EnumerableSetLib.Uint256Set;
    using SafeERC20 for IERC20;
    using PrecisionUtils for uint256;

    // Current TPSL order ID counter
    uint256 public currentOrderId;
    // Mapping from user address to their TPSL order ID set
    mapping(address user => EnumerableSetLib.Uint256Set orderIds) private _userTpslOrderIds;
    // Mapping from order ID to TPSL order data
    mapping(uint256 orderId => TpslData tpsl) private _tpslData;

    error InvalidAmount(uint256 amount);
    error InvalidTpsl(uint256 orderId);
    error NotReachedPrice(uint256 orderId, uint256 price, uint256 triggerPrice, TriggerType triggerType);
    error InsufficientQuoteIn(uint256 orderId, uint256 quoteIn, uint256 exchangeDelta);
    error SamePoolMigration(PoolId poolId);
    error SlippageExceeded(uint256 expected, uint256 actual);
    error InvalidLiquidityAmount();
    error DifferentMarket(PoolId fromPoolId, PoolId toPoolId);

    modifier onlyKeeper() {
        _onlyKeeper();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) external initializer {
        __ReentrancyGuard_init();

        bytes32[] memory dependencies = new bytes32[](8);
        dependencies[0] = Identifier.POOL_MANAGER;
        dependencies[1] = Identifier.BASE_POOL;
        dependencies[2] = Identifier.QUOTE_POOL;
        dependencies[3] = Identifier.EMITER;
        dependencies[4] = Identifier.ORACLE;
        dependencies[5] = Identifier.FORWARDER;
        dependencies[6] = Identifier.TRADING_ROUTER;
        dependencies[7] = Identifier.KEEPER_REGISTRY;
        __BaseContractUpgradeable_init(addressManager, dependencies);

        __ERC2771ContextUpgradeable_init(_getDependencyAddress(Identifier.FORWARDER));
    }

    /**
     * @notice Gets all TPSL order IDs for a user
     * @param user User address
     * @return Array of user's TPSL order IDs
     */
    function getUserTpslOrderIds(address user) external view returns (uint256[] memory) {
        return _userTpslOrderIds[user].values();
    }

    /**
     * @notice Gets detailed data for a TPSL order
     * @param orderId Order ID
     * @return TPSL order data
     */
    function getTpslData(uint256 orderId) external view returns (TpslData memory) {
        return _tpslData[orderId];
    }

    /// @inheritdoc ILiquidityRouter
    function depositBase(DepositParams calldata params) external override nonReentrant {
        _enforceForwardedRecipient(params.recipient);

        _getBasePool().deposit(params.poolId, params.amountIn, params.minAmountOut, _msgOrigin(), params.recipient);
        _createTpsl(params.tpslParams, _msgOrigin(), params.poolId, PoolType.Base);
        _collectForwardFee(params.poolId, _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function withdrawBase(WithdrawParams calldata params) external override nonReentrant {
        _enforceForwardedRecipient(params.recipient);

        _getBasePool().withdraw(params.poolId, params.amountIn, params.minAmountOut, _msgOrigin(), params.recipient);
        _collectForwardFee(params.poolId, _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function depositQuote(DepositParams calldata params) external override nonReentrant {
        _enforceForwardedRecipient(params.recipient);

        _getQuotePool().deposit(params.poolId, params.amountIn, params.minAmountOut, _msgOrigin(), params.recipient);
        _createTpsl(params.tpslParams, _msgOrigin(), params.poolId, PoolType.Quote);
        _collectForwardFee(params.poolId, _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function withdrawQuote(WithdrawParams calldata params) external override nonReentrant {
        _enforceForwardedRecipient(params.recipient);

        _getQuotePool().withdraw(params.poolId, params.amountIn, params.minAmountOut, _msgOrigin(), params.recipient);
        _collectForwardFee(params.poolId, _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function addTpsl(AddTpslParams calldata params) external override nonReentrant {
        _createTpsl(params.tpslParams, _msgOrigin(), params.poolId, params.poolType);
        _collectForwardFee(params.poolId, _msgOrigin());
    }

    /**
     * @notice Cancels a TPSL order
     * @param orderId Order ID to cancel
     * @dev Only the order owner can cancel the order
     */
    function cancelTpsl(uint256 orderId) external nonReentrant {
        TpslData memory tpsl = _tpslData[orderId];
        require(tpsl.user == _msgOrigin(), InvalidTpsl(orderId));

        _removeTpsl(orderId, _msgOrigin());

        _collectForwardFee(tpsl.poolId, _msgOrigin());
        _getEmiter().emitLiquidityStopOrderCancelled(
            IEmiter.LiquidityStopOrderCancelledParams({ orderId: orderId, poolId: tpsl.poolId, reason: "User Cancelled" })
        );
    }

    /// @inheritdoc ILiquidityRouter
    function migrateLiquidity(MigrateLiquidityParams calldata params) external override nonReentrant {
        require(PoolId.unwrap(params.fromPoolId) != PoolId.unwrap(params.toPoolId), SamePoolMigration(params.fromPoolId));
        require(params.amount > 0, InvalidLiquidityAmount());

        PoolMetadata memory fromPool = _getPoolManager().getPool(params.fromPoolId);
        PoolMetadata memory toPool = _getPoolManager().getPool(params.toPoolId);
        require(fromPool.quoteToken == toPool.quoteToken, DifferentMarket(params.fromPoolId, params.toPoolId));

        IQuotePool quotePool = _getQuotePool();

        (uint256 quoteTokensReceived, uint256 rebateOut) = quotePool.withdraw(params.fromPoolId, params.amount, 0, _msgOrigin(), address(this));

        IERC20(fromPool.quoteToken).forceApprove(address(quotePool), quoteTokensReceived);
        uint256 lpTokensReceived = quotePool.deposit(params.toPoolId, quoteTokensReceived, params.minLpOut, address(this), _msgOrigin());
        require(lpTokensReceived >= params.minLpOut, SlippageExceeded(params.minLpOut, lpTokensReceived));

        IERC20(fromPool.quoteToken).safeTransfer(_msgOrigin(), rebateOut);

        _collectForwardFee(params.fromPoolId, _msgOrigin());

        _getEmiter().emitLiquidityMigrated(
            IEmiter.LiquidityMigratedParams({
                user: _msgOrigin(),
                fromPoolId: params.fromPoolId,
                toPoolId: params.toPoolId,
                lpAmountIn: params.amount,
                lpAmountOut: lpTokensReceived
            })
        );
    }

    /// @inheritdoc ILiquidityRouter
    function claimBasePoolRebate(PoolId poolId, address recipient) external override nonReentrant {
        _enforceForwardedRecipient(recipient);

        _getBasePool().claimUserRebate(poolId, _msgOrigin(), recipient);
        _collectForwardFeeWithToken(address(0), _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function claimBasePoolRebates(PoolId[] calldata poolIds, address recipient) external override nonReentrant {
        _enforceForwardedRecipient(recipient);

        _getBasePool().claimUserRebates(poolIds, _msgOrigin(), recipient);
        _collectForwardFeeWithToken(address(0), _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function claimQuotePoolRebate(PoolId poolId, address recipient) external override nonReentrant {
        _enforceForwardedRecipient(recipient);

        _getQuotePool().claimUserRebate(poolId, _msgOrigin(), recipient);
        _collectForwardFeeWithToken(address(0), _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function claimQuotePoolRebates(PoolId[] calldata poolIds, address recipient) external override nonReentrant {
        _enforceForwardedRecipient(recipient);

        _getQuotePool().claimUserRebates(poolIds, _msgOrigin(), recipient);
        _collectForwardFeeWithToken(address(0), _msgOrigin());
    }

    /// @inheritdoc ILiquidityRouter
    function executeTpsl(
        uint256 orderId,
        uint256 quoteInIfNecessary,
        uint256 minOut
    ) external override onlyKeeper nonReentrant returns (uint256 baseOut, uint256 quoteOut) {
        return _executeTpsl(orderId, quoteInIfNecessary, minOut);
    }

    function _executeTpsl(uint256 orderId, uint256 quoteInIfNecessary, uint256 minOut) internal returns (uint256 baseOut, uint256 quoteOut) {
        TpslData memory tpsl = _tpslData[orderId];
        require(tpsl.amount > 0, InvalidTpsl(orderId));

        PoolMetadata memory pool = _getPoolManager().getPool(tpsl.poolId);
        uint256 oraclePrice = _getOracle().safeOraclePrice(tpsl.poolId);
        uint256 poolTokenPrice;
        bool interrupt;
        if (tpsl.poolType == PoolType.Base) {
            (interrupt, baseOut, poolTokenPrice) = _executeBase(pool, tpsl, oraclePrice, orderId, quoteInIfNecessary, minOut);
        } else {
            (interrupt, quoteOut, poolTokenPrice) = _executeQuote(pool, tpsl, orderId, oraclePrice, minOut);
        }
        if (interrupt) return (0, 0);

        _removeTpsl(orderId, tpsl.user);

        _collectForwardFee(tpsl.poolId, _msgOrigin());

        _getEmiter().emitLiquidityStopOrderExecuted(
            IEmiter.LiquidityStopOrderExecutedParams({
                orderId: orderId,
                poolId: tpsl.poolId,
                executor: _msgOrigin(),
                oraclePrice: oraclePrice,
                poolTokenPrice: poolTokenPrice
            })
        );
    }

    /**
     * @notice Executes TPSL order for Base pool, including asset exchange
     * @param pool Pool metadata
     * @param tpsl TPSL order data
     * @param oraclePrice Oracle price
     * @param orderId Order ID
     * @param quoteIn Amount of quote tokens for exchange
     * @param minBase Minimum base token output amount
     * @return interrupt Whether to interrupt the execution
     * @return baseOut Base token output amount
     * @return poolTokenPrice Pool token price
     */
    function _executeBase(
        PoolMetadata memory pool,
        TpslData memory tpsl,
        uint256 oraclePrice,
        uint256 orderId,
        uint256 quoteIn,
        uint256 minBase
    ) internal returns (bool interrupt, uint256 baseOut, uint256 poolTokenPrice) {
        IBasePool basePool = _getBasePool();
        poolTokenPrice = basePool.getPoolTokenPrice(tpsl.poolId, oraclePrice);
        _ensureExecutable(tpsl, orderId, poolTokenPrice);
        if (_ensureTPSLBalance(pool.basePoolToken, orderId, tpsl)) return (true, 0, 0);

        require(quoteIn >= tpsl.minQuoteOut, InsufficientQuoteIn(orderId, quoteIn, tpsl.minQuoteOut));
        IERC20(pool.quoteToken).safeTransferFrom(_msgOrigin(), address(this), quoteIn);

        uint256 rebateOut;
        (baseOut, rebateOut) = basePool.withdraw(tpsl.poolId, tpsl.amount, 0, tpsl.user, address(this));
        require(baseOut >= minBase, SlippageExceeded(minBase, baseOut));

        // Users are credited strictly with the expected amount,
        // while any excess is allocated as execution rewards to incentivize executors.
        IERC20(pool.quoteToken).safeTransfer(tpsl.user, rebateOut + tpsl.minQuoteOut);
        IERC20(pool.baseToken).safeTransfer(_msgOrigin(), baseOut);
        if (quoteIn > tpsl.minQuoteOut) {
            IERC20(pool.quoteToken).safeTransfer(_msgOrigin(), quoteIn - tpsl.minQuoteOut);
        }
    }

    /**
     * @notice Executes TPSL order for Quote pool
     * @param tpsl TPSL order data
     * @param orderId Order ID
     * @param oraclePrice Oracle price
     * @param minOut Minimum quote token output amount
     * @return interrupt Whether to interrupt the execution
     * @return quoteOut Quote token output amount
     * @return poolTokenPrice Pool token price
     */
    function _executeQuote(
        PoolMetadata memory pool,
        TpslData memory tpsl,
        uint256 orderId,
        uint256 oraclePrice,
        uint256 minOut
    ) internal returns (bool interrupt, uint256 quoteOut, uint256 poolTokenPrice) {
        IQuotePool quotePool = _getQuotePool();
        poolTokenPrice = quotePool.getPoolTokenPrice(tpsl.poolId, oraclePrice);
        _ensureExecutable(tpsl, orderId, poolTokenPrice);
        if (_ensureTPSLBalance(pool.quotePoolToken, orderId, tpsl)) return (true, 0, 0);

        uint256 rebateOut;
        (quoteOut, rebateOut) = quotePool.withdraw(tpsl.poolId, tpsl.amount, tpsl.minQuoteOut, tpsl.user, address(this));
        require(quoteOut >= minOut, SlippageExceeded(minOut, quoteOut));

        // Users are credited strictly with the expected amount,
        // while any excess is allocated as execution rewards to incentivize executors.
        IERC20(pool.quoteToken).safeTransfer(tpsl.user, rebateOut + tpsl.minQuoteOut);
        if (quoteOut > tpsl.minQuoteOut) {
            IERC20(pool.quoteToken).safeTransfer(_msgOrigin(), quoteOut - tpsl.minQuoteOut);
        }
    }

    /**
     * @notice Generates next TPSL order ID
     * @return New order ID
     */
    function _nextTpslOrderId() internal returns (uint256) {
        return ++currentOrderId;
    }

    /**
     * @notice Creates TPSL orders
     * @param params Array of TPSL parameters
     * @param user User address
     * @param poolId Pool ID
     * @param poolType Pool type
     */
    function _createTpsl(TpslParams[] memory params, address user, PoolId poolId, PoolType poolType) internal {
        if (params.length == 0) return;

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 userLPBalance;
        if (poolType == PoolType.Base) {
            userLPBalance = IERC20(pool.basePoolToken).balanceOf(user);
        } else {
            userLPBalance = IERC20(pool.quotePoolToken).balanceOf(user);
        }

        for (uint256 i = 0; i < params.length; ++i) {
            require(params[i].amount > 0 && params[i].amount <= userLPBalance, InvalidAmount(params[i].amount));

            uint256 orderId = _nextTpslOrderId();
            _userTpslOrderIds[user].add(orderId);

            _tpslData[orderId] = TpslData({
                user: user,
                poolId: poolId,
                poolType: poolType,
                amount: params[i].amount,
                triggerPrice: params[i].triggerPrice,
                triggerType: params[i].triggerType,
                minQuoteOut: params[i].minQuoteOut
            });

            _getEmiter().emitLiquidityStopOrderCreated(
                IEmiter.LiquidityStopOrderCreatedParams({
                    orderId: orderId,
                    user: user,
                    poolId: poolId,
                    poolType: poolType,
                    amount: params[i].amount,
                    triggerPrice: params[i].triggerPrice,
                    triggerType: params[i].triggerType,
                    minQuoteOut: params[i].minQuoteOut
                })
            );
        }
    }

    /**
     * @notice Validates if TPSL order is executable (price meets trigger condition)
     * @param tpsl TPSL order data
     * @param orderId Order ID
     * @param poolTokenPrice Current pool token price
     */
    function _ensureExecutable(TpslData memory tpsl, uint256 orderId, uint256 poolTokenPrice) internal pure {
        bool executable =
            (tpsl.triggerType == TriggerType.GTE && poolTokenPrice >= tpsl.triggerPrice) ||
                (tpsl.triggerType == TriggerType.LTE && poolTokenPrice <= tpsl.triggerPrice);
        require(executable, NotReachedPrice(orderId, poolTokenPrice, tpsl.triggerPrice, tpsl.triggerType));
    }

    function _ensureTPSLBalance(address token, uint256 orderId, TpslData memory tpsl) internal returns (bool interrupt) {
        uint256 balance = IERC20(token).balanceOf(tpsl.user);
        if (balance < tpsl.amount) {
            _removeTpsl(orderId, tpsl.user);
            _getEmiter().emitLiquidityStopOrderCancelled(
                IEmiter.LiquidityStopOrderCancelledParams({ orderId: orderId, poolId: tpsl.poolId, reason: "Insufficient balance" })
            );
            return true;
        }
    }

    /**
     * @notice Removes TPSL order
     * @param orderId Order ID
     * @param user User address
     */
    function _removeTpsl(uint256 orderId, address user) internal {
        _userTpslOrderIds[user].remove(orderId);
        delete _tpslData[orderId];
    }

    function _collectForwardFee(PoolId poolId, address account) internal {
        (, address token) = _getPoolManager().getPairToken(poolId);
        _collectForwardFeeWithToken(token, account);
    }

    function _collectForwardFeeWithToken(address token, address account) internal {
        ITradingRouter tradingRouter = ITradingRouter(_getDependencyAddress(Identifier.TRADING_ROUTER));

        tradingRouter.collectForwardFeeIfNecessary(
            ICollectFee.FeeSource.Direct,
            abi.encode(ICollectFee.AddressFeeParams({ feeToken: token, user: account }))
        );
    }

    function _onlyKeeper() internal view {
        require(
            IKeeperRegistry(_getDependencyAddress(Identifier.KEEPER_REGISTRY)).isKeeper(msg.sender),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getBasePool() internal view returns (IBasePool) {
        return IBasePool(_getDependencyAddress(Identifier.BASE_POOL));
    }

    function _getQuotePool() internal view returns (IQuotePool) {
        return IQuotePool(_getDependencyAddress(Identifier.QUOTE_POOL));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }

    function _getOracle() internal view returns (IOracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }
}

