// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IForwarder } from "./../interfaces/IForwarder.sol";
import { IPaymaster } from "./../interfaces/IPaymaster.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { TokenConverter } from "./../libraries/TokenConverter.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors } from "./../types/Types.sol";

contract Paymaster is BaseContractUpgradeable, Ownable2StepUpgradeable, IPaymaster {
    using SafeERC20 for IERC20;
    using EnumerableSetLib for EnumerableSetLib.AddressSet;

    uint256 public ETHWarningLine;
    EnumerableSetLib.AddressSet private _relayers;
    EnumerableSetLib.AddressSet private _allowedTargets;

    event RelayerAdded(address relayer);
    event RelayerRemoved(address relayer);
    event AllowedTargetAdded(address target);
    event AllowedTargetRemoved(address target);

    error TargetNotAllowed(address target);

    modifier onlyForwarder() {
        _onlyForwarder();
        _;
    }

    modifier onlyRelayer() {
        _onlyRelayer();
        _;
    }

    modifier onlyFinanceAdmin() {
        _onlyFinanceAdmin();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, uint256 _ETHWarningLine, address initialOwner) public initializer {
        bytes32[] memory identifiers = new bytes32[](1);
        identifiers[0] = Identifier.FORWARDER;
        __BaseContractUpgradeable_init(addressManager, identifiers);
        _transferOwnership(initialOwner);

        ETHWarningLine = _ETHWarningLine;
    }

    receive() external payable {}

    function getRelayers() external view returns (address[] memory) {
        return _relayers.values();
    }

    function addRelayers(address[] calldata relayers) external onlyOwner {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.add(relayers[i]);
            emit RelayerAdded(relayers[i]);
        }
    }

    function removeRelayers(address[] calldata relayers) external onlyOwner {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.remove(relayers[i]);
            emit RelayerRemoved(relayers[i]);
        }
    }

    function getAllowedTargets() external view returns (address[] memory) {
        return _allowedTargets.values();
    }

    function isAllowedTarget(address target) external view returns (bool) {
        return _allowedTargets.contains(target);
    }

    function addAllowedTargets(address[] calldata targets) external onlyOwner {
        for (uint256 i; i < targets.length; ++i) {
            _allowedTargets.add(targets[i]);
            emit AllowedTargetAdded(targets[i]);
        }
    }

    function removeAllowedTargets(address[] calldata targets) external onlyOwner {
        for (uint256 i; i < targets.length; ++i) {
            _allowedTargets.remove(targets[i]);
            emit AllowedTargetRemoved(targets[i]);
        }
    }

    function depositGas() external payable {
        require(msg.value > 0, InvalidAmount(msg.value));
        emit GasDeposited(msg.sender, msg.value);
    }

    function withdrawGas(address to, uint256 amount) external onlyOwner {
        (bool success, ) = payable(to).call{ value: amount }("");
        require(success, ETHTransferFailed(to, amount));
        emit GasWithdrawn(to, amount);
    }

    function updateETHWarningLine(uint256 _ETHWarningLine) external onlyOwner {
        uint256 oldLine = ETHWarningLine;
        ETHWarningLine = _ETHWarningLine;
        emit ETHWarningLineUpdated(oldLine, _ETHWarningLine);
    }

    function sponsorGas(address operator, uint256 amount) external onlyForwarder {
        uint256 balance = address(this).balance;
        if (balance < ETHWarningLine) emit InsufficientBalance(balance, ETHWarningLine);

        if (balance >= amount) {
            (bool success, ) = operator.call{ value: amount }("");
            require(success, ETHTransferFailed(operator, amount));
            emit GasSponsor(operator, amount);
        }
    }

    function rescueToken(address token, address to, uint256 amount) external onlyFinanceAdmin {
        if (token == address(0)) {
            (bool success, ) = payable(to).call{ value: amount }("");
            require(success, ETHTransferFailed(to, amount));
        } else {
            IERC20(token).safeTransfer(to, amount);
        }
    }

    function swapFeeToGas(TokenConverter.ConvertInParams calldata params) external onlyRelayer {
        require(_allowedTargets.contains(params.target), TargetNotAllowed(params.target));
        _swapFeeToGas(params);
    }

    function _swapFeeToGas(TokenConverter.ConvertInParams calldata params) internal {
        uint256 amountIn = IERC20(params.src).balanceOf(address(this));
        uint256 received = TokenConverter.convertToETH(params);
        emit FeeConverted(params.src, amountIn, received);
    }

    function _onlyForwarder() internal view {
        require(msg.sender == address(_getForwarder()), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyRelayer() internal view {
        require(_relayers.contains(msg.sender), Errors.OnlyRelayer());
    }

    function _onlyFinanceAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isFinanceAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getForwarder() internal view returns (IForwarder) {
        return IForwarder(super._getDependencyAddress(Identifier.FORWARDER));
    }
}

