// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { Constants } from "./../types/Types.sol";

/// @title PrecisionUtils
/// @notice Library for precision-aware arithmetic operations
library PrecisionUtils {
    using SignedMath for int256;

    /// @notice Multiply value by price with price precision
    /// @param value Value to multiply
    /// @param price Price to multiply by
    /// @return result Multiplication result with price precision applied
    function mulPrice(uint256 value, uint256 price) internal pure returns (uint256 result) {
        return mulPrecision(value, price, Constants.PRICE_PRECISION);
    }

    /// @notice Multiply signed value by price with price precision
    /// @param value Signed value to multiply
    /// @param price Price to multiply by
    /// @return result Signed multiplication result with price precision applied
    function signedMulPrice(int256 value, uint256 price) internal pure returns (int256 result) {
        uint256 absOut = mulPrice(value.abs(), price);
        if (value >= 0) {
            return int256(absOut);
        } else {
            return -int256(absOut);
        }
    }

    /// @notice Divide value by price with price precision
    /// @param value Value to divide
    /// @param price Price to divide by
    /// @return result Division result with price precision applied
    function divPrice(uint256 value, uint256 price) internal pure returns (uint256 result) {
        return divPrecision(value, price, Constants.PRICE_PRECISION);
    }

    /// @notice Divide value by price with price precision and round up
    /// @param value Value to divide
    /// @param price Price to divide by
    /// @return result Division result with price precision applied and rounded up
    function divPriceCeil(uint256 value, uint256 price) internal pure returns (uint256) {
        return divPrecisionCeil(value, price, Constants.PRICE_PRECISION);
    }

    /// @notice Multiply two values with custom precision
    /// @param x First value
    /// @param y Second value
    /// @param precision Precision to apply
    /// @return result Multiplication result with precision applied
    function mulPrecision(uint256 x, uint256 y, uint256 precision) internal pure returns (uint256 result) {
        return Math.mulDiv(x, y, precision);
    }

    /// @notice Multiply two values with custom precision and round up
    /// @param x First value
    /// @param y Second value
    /// @param precision Precision to apply
    /// @return result Multiplication result with precision applied and rounded up
    function mulPrecisionCeil(uint256 x, uint256 y, uint256 precision) internal pure returns (uint256) {
        return Math.mulDiv(x, y, precision, Math.Rounding.Ceil);
    }

    /// @notice Divide two values with custom precision
    /// @param x Numerator
    /// @param y Denominator
    /// @param precision Precision to apply
    /// @return result Division result with precision applied
    function divPrecision(uint256 x, uint256 y, uint256 precision) internal pure returns (uint256 result) {
        return Math.mulDiv(x, precision, y);
    }

    /// @notice Divide two values with custom precision and round up
    /// @param x Numerator
    /// @param y Denominator
    /// @param precision Precision to apply
    /// @return result Division result with precision applied and rounded up
    function divPrecisionCeil(uint256 x, uint256 y, uint256 precision) internal pure returns (uint256) {
        return Math.mulDiv(x, precision, y, Math.Rounding.Ceil);
    }

    /**
     * @notice Converts an amount from token's native decimals to 18-decimal fixed-point format (Wad).
     *
     * Example:
     * - amount = 1_000_000 (1 USDC), decimals = 6
     * → returns: 1e18 (Wad format)
     *
     * @param amount   The token amount in its native decimal format
     * @param decimals The number of decimals used by the token
     * @return The normalized amount in 18-decimal Wad format
     */
    function toWad(uint256 amount, uint8 decimals) internal pure returns (uint256) {
        return amount * (10 ** (18 - decimals));
    }

    function toWad(int256 amount, uint8 decimals) internal pure returns (int256) {
        uint256 unsigned = toWad(amount.abs(), decimals);
        return amount >= 0 ? int256(unsigned) : -int256(unsigned);
    }

    /**
     * @notice Converts an amount from 18-decimal fixed-point format (Wad) to token's native decimals.
     *
     * Example:
     * - wadAmount = 1e18 (Wad), decimals = 6
     * → returns: 1_000_000 (1 USDC)
     *
     * @param wadAmount The normalized amount in 18-decimal Wad format
     * @param decimals  The number of decimals used by the target token
     * @return The amount converted to the token's native decimal format
     */
    function fromWad(uint256 wadAmount, uint8 decimals) internal pure returns (uint256) {
        return wadAmount / (10 ** (18 - decimals));
    }

    /// @notice Convert amount from 18-decimal fixed-point format (Wad) to token's native decimals and round up
    function fromWadCeil(uint256 wadAmount, uint8 decimals) internal pure returns (uint256) {
        uint256 divisor = 10 ** (18 - decimals);
        return (wadAmount + divisor - 1) / divisor;
    }

    function fromWad(int256 wadAmount, uint8 decimals) internal pure returns (int256) {
        uint256 unsigned = fromWad(wadAmount.abs(), decimals);
        return wadAmount >= 0 ? int256(unsigned) : -int256(unsigned);
    }
}

