// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { Constants, Operation, Direction, TriggerType } from "./../types/Types.sol";
import { PrecisionUtils } from "./PrecisionUtils.sol";

/// @title TradeUtils
/// @notice Utility library for trading operations and calculations
library TradeUtils {
    using PrecisionUtils for uint256;

    /// @notice Determine if an order is a buy order
    /// @param operation Order operation (Increase/Decrease)
    /// @param direction Order direction (Long/Short)
    /// @return isBuy True if the order is a buy order
    function getOrderSide(Operation operation, Direction direction) internal pure returns (bool isBuy) {
        return (operation == Operation.Increase && direction == Direction.Long) || (operation == Operation.Decrease && direction == Direction.Short);
    }

    /// @notice Get the trigger type for an order based on operation and direction
    /// @param operation Order operation (Increase/Decrease)
    /// @param direction Order direction (Long/Short)
    /// @return triggerType The appropriate trigger type for the order
    function getOrderTriggerType(Operation operation, Direction direction) internal pure returns (TriggerType triggerType) {
        if (operation == Operation.Increase) {
            if (direction == Direction.Long) return TriggerType.LTE;
            else if (direction == Direction.Short) return TriggerType.GTE;
        } else if (operation == Operation.Decrease) {
            if (direction == Direction.Long) return TriggerType.GTE;
            else if (direction == Direction.Short) return TriggerType.LTE;
        }
    }

    /// @notice Get the trigger type for take profit or stop loss orders
    /// @param direction Order direction (Long/Short)
    /// @param isTakeProfit True for take profit, false for stop loss
    /// @return triggerType The appropriate trigger type for TPSL orders
    function getTPSLTriggerType(Direction direction, bool isTakeProfit) internal pure returns (TriggerType triggerType) {
        if (direction == Direction.Long) {
            return isTakeProfit ? TriggerType.GTE : TriggerType.LTE;
        } else {
            return isTakeProfit ? TriggerType.LTE : TriggerType.GTE;
        }
    }

    /// @notice Validate if order slippage is within acceptable range
    /// @param operation Order operation (Increase/Decrease)
    /// @param direction Order direction (Long/Short)
    /// @param orderPrice Order price
    /// @param marketPrice Current market price
    /// @param slippagePct Maximum allowed slippage percentage
    /// @return True if slippage is acceptable
    function validateOrderSlippage(
        Operation operation,
        Direction direction,
        uint256 orderPrice,
        uint256 marketPrice,
        uint16 slippagePct
    ) internal pure returns (bool) {
        bool isBuy = getOrderSide(operation, direction);
        if (isBuy) {
            return marketPrice <= (orderPrice * (Constants.SLIPPAGE_PRECISION + slippagePct)) / Constants.SLIPPAGE_PRECISION;
        } else {
            return marketPrice >= (orderPrice * (Constants.SLIPPAGE_PRECISION - slippagePct)) / Constants.SLIPPAGE_PRECISION;
        }
    }

    /// @notice Calculate the weighted average entry price for a position
    /// @param currentSize Current position size
    /// @param currentPrice Current entry price
    /// @param addedSize Additional size to add
    /// @param addedPrice Price for additional size
    /// @return Weighted average entry price
    function calculateEntryPrice(
        uint256 currentSize,
        uint256 currentPrice,
        uint256 addedSize,
        uint256 addedPrice,
        uint8 tokenDecimals
    ) internal pure returns (uint256) {
        uint256 totalSizeWad = (currentSize + addedSize).toWad(tokenDecimals);
        uint256 totalValueWad = currentSize.toWad(tokenDecimals).mulPrice(currentPrice) + addedSize.toWad(tokenDecimals).mulPrice(addedPrice);
        return totalValueWad.divPrice(totalSizeWad);
    }

    /// @notice Calculate profit and loss for a position
    /// @param entryPrice Position entry price
    /// @param exitPrice Position exit price
    /// @param size Position size
    /// @param isLong True if long position, false if short
    /// @return pnl Profit and loss amount (positive for profit, negative for loss)
    function calculatePNLSize(uint256 entryPrice, uint256 exitPrice, uint256 size, bool isLong) internal pure returns (int256 pnl) {
        uint256 priceDiff = entryPrice > exitPrice ? entryPrice - exitPrice : exitPrice - entryPrice;
        uint256 pnlAmount = size.mulPrice(priceDiff);
        bool isProfit = (isLong && exitPrice >= entryPrice) || (!isLong && entryPrice >= exitPrice);
        return isProfit ? int256(pnlAmount) : -int256(pnlAmount);
    }

    /// @notice Calculate funding fee for a position
    /// @param accruedFundingTracker Accumulated funding tracker
    /// @param positionSize Position size
    /// @param direction Position direction (Long/Short)
    /// @return Funding fee amount
    function calculateFundingFeeSize(int256 accruedFundingTracker, uint256 positionSize, Direction direction) internal pure returns (int256) {
        int256 signedTracker = direction == Direction.Long ? -accruedFundingTracker : accruedFundingTracker;
        return (signedTracker * int256(positionSize)) / int256(Constants.FUNDING_RATE_PRECISION);
    }
}

