pragma solidity ^0.8.20;

/// @title IAddressManager
/// @notice Interface for contract address management and dependency injection
interface IAddressManager {
    event AddressUpdated(bytes32 identifier, address oldAddress, address newAddress);

    /// @notice Get role manager contract address
    /// @return Role manager address
    function getRoleManager() external view returns (address);

    /// @notice Get contract addresses by identifiers
    /// @param identifiers Contract identifiers
    /// @return addresses Contract addresses
    function getAddresses(bytes32[] memory identifiers) external view returns (address[] memory addresses);

    /// @notice Get contract address by identifier
    /// @param identifier Contract identifier
    /// @return Contract address
    function getAddress(bytes32 identifier) external view returns (address);

    /// @notice Get contract identifier by address
    /// @param contractAddress Contract address
    /// @return Contract identifier
    function getIdentifier(address contractAddress) external view returns (bytes32);

    /// @notice Set contract address for identifier
    /// @param identifier Contract identifier
    /// @param newAddress New contract address
    function setAddress(bytes32 identifier, address newAddress) external;
}

myx-contract-v2/src/interfaces/IBasePool.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { PoolId } from "./../types/Types.sol";
import { IPoolBase } from "./IPoolBase.sol";

/**
 * @title IBasePool
 * @notice Interface for base pool contract handling base token liquidity provision
 */
interface IBasePool is IPoolBase {
    struct PoolData {
        // Global cumulative rebate index for quote token rebates
        uint256 rebateIndex;
        // Global cumulative rebate index for genesis quote token rebates
        uint256 genesisRebateIndex;
        // Accumulated exchangeable profits
        uint256 exchangeableProfits;
    }

    struct UserData {
        // User's last recorded global rebate index for quote token rebates
        uint256 index;
        // User's last recorded global rebate index for genesis quote token rebates
        uint256 genesisIndex;
        // Quote tokens accrued (but not yet claimed) since last index update
        uint256 accrued;
        // Genesis quote tokens accrued (but not yet claimed) since last index update
        uint256 genesisAccrued;
    }

    /**
     * @notice Initializes the BasePool contract
     * @param addressManager Address of the address manager contract
     */
    function initialize(address addressManager) external;

    /**
     * @notice Gets the pool data
     * @param poolId The pool ID to get the data for
     * @return Pool data
     */
    function getPoolData(PoolId poolId) external view returns (PoolData memory);

    /**
     * @notice Gets the user data
     * @param poolId The pool ID to get the data for
     * @param user The user to get the data for
     * @return User data
     */
    function getUserData(PoolId poolId, address user) external view returns (UserData memory);

    /**
     * @notice Previews the amount of base tokens that would be received for a base token deposit
     * @param poolId The pool ID to preview for
     * @param baseAmountIn Amount of base tokens to deposit
     * @param price Current price
     * @return Amount of LP tokens that would be minted
     */
    function previewLpAmountOut(PoolId poolId, uint256 baseAmountIn, uint256 price) external view returns (uint256);

    /**
     * @notice Previews the amount of base tokens that would be received for burning LP tokens
     * @param poolId The pool ID to preview for
     * @param lpAmountIn Amount of LP tokens to burn
     * @param price Current price
     * @return Amount of base tokens that would be received
     */
    function previewBaseAmountOut(PoolId poolId, uint256 lpAmountIn, uint256 price) external view returns (uint256);

    /**
     * @notice Calculates the maximum LP tokens that can be withdrawn from the pool, constrained by vault reserves
     * @param poolId The pool ID to check
     * @param price Current price
     * @return Maximum amount of LP tokens that can be withdrawn
     */
    function withdrawableLpAmount(PoolId poolId, uint256 price) external view returns (uint256);

    /**
     * @notice Previews the data for a user's withdrawal including base tokens and rebates
     * @param poolId The pool ID to preview for
     * @param lpAmountIn Amount of LP tokens to withdraw
     * @param user Address of the user
     * @param price Current price
     * @return baseAmountOut Amount of base tokens that would be received
     * @return rebateAmount Amount of rebates the user would receive
     */
    function previewUserWithdrawData(
        PoolId poolId,
        uint256 lpAmountIn,
        address user,
        uint256 price
    ) external view returns (uint256 baseAmountOut, uint256 rebateAmount);

    /**
     * @notice Calculates the pending rebates for a user
     * @param poolId The pool ID to check rebates for
     * @param user Address of the user
     * @param price Current price
     * @return rebates Amount of regular rebates pending
     * @return genesisRebates Amount of pending genesis rebates
     */
    function pendingUserRebates(PoolId poolId, address user, uint256 price) external view returns (uint256 rebates, uint256 genesisRebates);

    /**
     * @notice Previews the amount of base tokens that would be received for exchanging profits
     * @param poolId The pool ID to preview for
     * @param price Current price
     */
    function getExchangeableProfit(PoolId poolId, uint256 price) external view returns (uint256 baseIn, uint256 quoteOut);

    /**
     * @notice Previews the amount of base tokens that would be received for exchanging profits
     * @param poolId The pool ID to preview for
     */
    function previewExchangeableProfit(PoolId poolId) external view returns (uint256 baseIn, uint256 quoteOut);

    /**
     * @notice Deposits base tokens into the pool
     * @param poolId The pool ID to deposit into
     * @param amountIn Amount of base tokens to deposit
     * @param minAmountOut Minimum amount of LP tokens expected to receive
     * @param user Address of the user
     * @param recipient Address to receive the LP tokens
     */
    function deposit(PoolId poolId, uint256 amountIn, uint256 minAmountOut, address user, address recipient) external returns (uint256 amountOut);

    /**
     * @notice Withdraws base tokens from the pool
     * @param poolId The pool ID to withdraw from
     * @param amountIn Amount of LP tokens to withdraw
     * @param minAmountOut Minimum amount of base tokens expected to receive
     * @param user Address of the user
     * @param recipient Address to receive the withdrawn tokens and rebates
     */
    function withdraw(
        PoolId poolId,
        uint256 amountIn,
        uint256 minAmountOut,
        address user,
        address recipient
    ) external returns (uint256 amountOut, uint256 rebateOut);

    /**
     * @notice Exchanges profits for base tokens
     * @param poolId The pool ID to exchange profits from
     * @param baseIn Amount of base tokens to exchange
     * @param minQuoteOut Minimum amount of quote tokens expected to receive
     * @param recipient Address to receive the exchanged quote tokens
     * @param data User-provided bytes forwarded to the callback for custom use
     */
    function exchangeProfit(
        PoolId poolId,
        uint256 baseIn,
        uint256 minQuoteOut,
        address recipient,
        bytes calldata data
    ) external returns (uint256 quoteOut);

    /**
     * @notice Distributes profits to the pool and updates rebate indices
     * @param poolId The pool ID to distribute profits to
     * @param baseAmount Amount of base tokens distributed
     * @param quoteAmount Amount of quote tokens distributed for regular rebates
     * @param genesisAmount Amount of quote tokens distributed for genesis rebates
     * @param price Current oracle price used for calculations
     */
    function distribute(PoolId poolId, uint256 baseAmount, uint256 quoteAmount, uint256 genesisAmount, uint256 price) external;

    /**
     * @notice Claims rebates for a user
     * @param poolId The pool ID to claim rebates from
     * @param user Address of the user
     * @param recipient Address to receive the rebates
     * @return rebateOut Amount of rebates claimed
     */
    function claimUserRebate(PoolId poolId, address user, address recipient) external returns (uint256 rebateOut);

    /**
     * @notice Claims rebates for a user
     * @param poolIds The pool IDs to claim rebates from
     * @param user Address of the user
     * @param recipient Address to receive the rebates
     * @return rebateOut Amount of rebates claimed
     */
    function claimUserRebates(PoolId[] memory poolIds, address user, address recipient) external returns (uint256[] memory rebateOut);

    /**
     * @notice Updates receiver's weighted average rebate index on LP token transfer
     * @dev Called by PoolToken during transfer to maintain correct rebate accounting
     * @param poolId Pool identifier
     * @param from Address sending the LP tokens
     * @param to Address receiving the LP tokens
     * @param amount Amount of LP tokens being transferred
     * @param toBalanceBefore Receiver's LP balance before the transfer
     */
    function updateWeightedIndexOnTransfer(PoolId poolId, address from, address to, uint256 amount, uint256 toBalanceBefore) external;
}

