pragma solidity ^0.8.20;

import { PoolId } from "./../types/Types.sol";

/// @title IFundingRate
/// @notice Interface for funding rate management in perpetual contracts
interface IFundingRate {
    /// @notice Funding rate information for a pool
    /// @param tracker Cumulative funding rate tracker
    /// @param lastEpochTime Timestamp of last funding rate update
    struct FundingRateData {
        int256 tracker;
        uint64 lastEpochTime;
    }

    struct NextFundingRateInfo {
        int256 lastFundingFeeTracker;
        int256 nextFundingRate;
        uint64 nextEpochTime;
    }

    /// @notice Update funding rate for a pool
    /// @param poolId Pool ID to update
    /// @return lastFundingRateTracker Previous funding rate tracker value
    function updateFundingRate(PoolId poolId) external returns (int256 lastFundingRateTracker);

    /// @notice Get next funding rate for a pool
    /// @param poolId Pool ID to query
    /// @param price Current market price
    /// @return Next funding rate value
    function getNextFundingRate(PoolId poolId, uint256 price) external view returns (int256);

    /// @notice Get previous funding rate information
    /// @param poolId Pool ID to query
    /// @return Previous funding rate info
    function previousFundingRateInfo(PoolId poolId) external view returns (FundingRateData memory);

    /// @notice Get next funding rate information
    /// @param poolId Pool ID to query
    /// @param price Current market price
    function nextFundingRateInfo(PoolId poolId, uint256 price) external view returns (NextFundingRateInfo memory);

    /// @notice Get funding rate information
    /// @param poolId Pool ID to query
    /// @param price Current market price
    function getFundingRateInfo(PoolId poolId, uint256 price) external view returns (FundingRateData memory prev, NextFundingRateInfo memory next);
}

