pragma solidity ^0.8.20;

import { OracleType, MarketId, PoolId } from "./../types/Types.sol";

interface IOracle {
    event OracleAdminUpdated(address oldOracleAdmin, address newOracleAdmin);
    event PoolPriceUpdated(
        PoolId poolId,
        OracleType oracleType,
        address oracleAdapter,
        uint256 referencePrice,
        uint256 oraclePrice,
        uint64 publishTime
    );

    event PoolRewindPriceUpdated(PoolId poolId, OracleType oracleType, address oracleAdapter, uint256 oraclePrice, uint64 publishTime);

    event PriceAgeUpdated(uint256 oldAge, uint256 newAge);
    event RefundVerifyFee(address receiver, uint256 vaule);
    event MarketConfigurationUpdated(MarketId marketId, address priceContract, bool applyExchangeRate, uint16 maxDeviationRatio, uint64 heartbeat);
    event OracleFeedIdUpdated(PoolId poolId, OracleType oracleType, bytes32 oracleFeedId);
    event ActiveOracleTypeSwitched(PoolId poolId, OracleType newOracleType);
    event ExchangeRateApplied(MarketId marketId);
    event ExchangeRateDisabled(MarketId marketId);

    struct OracleFeedParameter {
        PoolId poolId;
        OracleType oracleType;
        bytes32 oracleFeedId;
        uint32 decimals;
        bool active;
    }

    struct Price {
        uint256 oraclePrice;
        uint64 publishTime;
    }

    struct UpdateOraclePriceParams {
        PoolId poolId;
        OracleType oracleType;
        uint64 publishTime;
        bytes oracleUpdateData;
    }

    struct UpdateMarketPriceParams {
        PoolId poolId;
        uint256 referencePrice;
        OracleType oracleType;
        uint64 publishTime;
        uint80 roundId;
        bytes oracleUpdateData;
    }

    /// @notice A live price update paired with its rewind-time counterpart for the same market.
    struct UpdatePriceWithRewindParams {
        UpdateMarketPriceParams livePrice;
        UpdateMarketPriceParams rewindPrice;
    }

    struct MarketQuoteConfig {
        address priceContract;
        bool applyExchangeRate;
        uint16 minDeviationRatio;
        uint64 heartbeat;
    }

    function updatePriceAge(uint32 age) external;

    function setMarketQuoteConfiguration(MarketId marketId, MarketQuoteConfig calldata config) external;

    function setOracleFeedParameter(OracleFeedParameter calldata param) external;

    function switchActiveOracleType(PoolId poolId, OracleType oracleType) external;

    function enableExchangeRateOnDeviation(MarketId marketId) external;

    function disableExchangeRateOnDeviation(MarketId marketId) external;

    function updatePrices(UpdateOraclePriceParams[] calldata params) external payable;

    function updatePrices(UpdateMarketPriceParams[] memory params) external payable;

    function updatePricesWithRewind(UpdatePriceWithRewindParams[] memory params) external payable;

    function getPriceAge() external view returns (uint32);

    function getPriceData(PoolId poolId) external view returns (Price memory);

    function latestOraclePrice(PoolId poolId) external view returns (uint256);

    function safeOraclePrice(PoolId poolId) external view returns (uint256);

    function getMarketPrice(PoolId poolId) external view returns (uint256 price, uint64 publishTime);

    /// @notice Read the keeper-pushed rewind price from transient storage. Reverts if no
    ///         rewind price was pushed in the current transaction.
    function getRewindPrice(PoolId poolId) external view returns (uint256 price, uint64 publishTime);

    function getActiveOracleType(PoolId poolId) external view returns (OracleType);
}

