// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { PositionMetadata, OrderId, PoolId, PositionId, PoolMetadata, Direction } from "./../types/Types.sol";

/// @title IPositionManager
/// @notice Interface for position management functionality
interface IPositionManager {
    /// @notice Open interest tracking structure
    struct OITracker {
        // Net position tracker (long - short)
        int256 tracker;
        // Total long position size
        uint256 longSize;
        // Total short position size
        uint256 shortSize;
        // Pool's average entry price
        uint256 poolEntryPrice;
    }

    /// @notice Parameters for executing user position changes
    struct ExecuteUserPositionParams {
        // Pool ID to execute on
        PoolId poolId;
        // Position to execute on
        PositionId positionId;
        // Size to execute
        uint256 executeSize;
        // Execution price
        uint256 executePrice;
        // Associated order ID
        OrderId orderId;
        // Keeper executing the operation
        address keeper;
        // Whether the execution is a match execution
        bool isMatchExecution;

        bool isLiquidation;
        // Whether pool reserves should be updated after this position update
        bool shouldUpdatePoolReserve;
    }

    /// @notice Get open interest tracker for a pool
    /// @param poolId Pool ID to query
    /// @return OI tracker data
    function getOITracker(PoolId poolId) external view returns (OITracker memory);

    /// @notice Get position metadata
    /// @param positionId Position ID to query
    /// @return Position metadata
    function getPosition(PositionId positionId) external view returns (PositionMetadata memory);

    /// @notice Get position metadata by token ID
    /// @param tokenId Token ID to query
    /// @return Position metadata
    function getPositionByTokenId(uint256 tokenId) external view returns (PositionMetadata memory);

    /// @notice Get position owner address
    /// @param positionId Position ID to query
    /// @return Owner address
    function getPositionOwner(PositionId positionId) external view returns (address);

    /// @notice Get position broker address
    /// @param positionId Position ID to query
    /// @return Broker address
    function getPositionBroker(PositionId positionId) external view returns (address);

    /// @notice Check if position exists
    /// @param positionId Position ID to query
    /// @return True if position exists, false otherwise
    function isPositionExists(PositionId positionId) external view returns (bool);

    /// @notice Get user pool position IDs
    /// @param user User address
    /// @param poolId Pool ID to query
    /// @return Position IDs
    function getUserPoolPositionIds(address user, PoolId poolId) external view returns (bytes32[] memory);

    /// @notice Prepare position for execution (create if needed, validate health)
    /// @param positionId Position ID
    /// @param pool Pool metadata
    /// @param direction Position direction
    /// @param user User address
    /// @param marketPrice Current market price
    /// @param broker Broker address
    /// @param ensureExists Whether position must already exist
    /// @param requireHealthy When true, revert if the position is unhealthy. When false, the
    ///        health check is still performed and the result is returned via `isHealthy`,
    ///        leaving callers free to fall back to a different settlement price.
    /// @return position Updated position metadata
    /// @return isHealthy Whether the position passes the maintenance-margin check at `marketPrice`
    function preparePosition(
        PositionId positionId,
        PoolMetadata memory pool,
        Direction direction,
        address user,
        uint256 marketPrice,
        address broker,
        bool ensureExists,
        bool requireHealthy
    ) external returns (PositionMetadata memory position, bool isHealthy);

    /// @notice Update position
    /// @param params Execution parameters
    function updatePosition(ExecuteUserPositionParams calldata params) external returns (int256 tradingFee, int256 fundingFee, int256 realizedPnl, int256 charge);

    /// @notice Update pool reserves from current open interest
    /// @param poolId Pool ID to update
    function updatePoolReserve(PoolId poolId) external;

    /// @notice Adjust position collateral
    /// @param positionId Position to adjust
    /// @param adjustAmount Amount to increase/decrease (negative to decrease)
    function adjustCollateral(PositionId positionId, int256 adjustAmount) external;

    /// @notice Close a position completely
    /// @param positionId Position ID to close
    /// @param poolId Pool ID
    /// @param price Current market price
    /// @param isLiquidation Whether the position is being liquidated
    function closePosition(
        PositionId positionId,
        PoolId poolId,
        uint256 price,
        bool isLiquidation,
        address owner
    ) external returns (uint256 returnBaseAmount, uint256 returnQuoteAmount);

    /// @notice Mint a position NFT
    /// @param positionId Position ID to mint
    /// @param recipient Recipient address
    function mintPositionNFT(PositionId positionId, address recipient) external returns (PositionId newPositionId, uint256 tokenId);
}

