// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { EnumerableMapLib } from "@solady/utils/EnumerableMapLib.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { MarketId, MarketMetadata } from "./../types/Types.sol";

/// @title Market
/// @notice Library for managing market data and operations
library Market {
    using EnumerableSetLib for EnumerableSetLib.Bytes32Set;
    using EnumerableMapLib for EnumerableMapLib.AddressToBytes32Map;
    using LibMarketMetadata for MarketMetadata;
    using Market for Data;

    /// @notice Market storage structure
    /// @param _marketIds Set of all market IDs
    /// @param _markets Mapping from market ID to market metadata
    struct Data {
        EnumerableSetLib.Bytes32Set _marketIds;
        EnumerableMapLib.AddressToBytes32Map _tokenMarketIds;
        mapping(MarketId marketId => MarketMetadata marketMetadata) _markets;
    }

    function saveMarket(
        Data storage self,
        MarketId marketId,
        address quoteToken,
        uint32 baseReserveRatio,
        uint32 quoteReserveRatio,
        uint64 oracleFeeUsd,
        uint64 boostFeeUsd,
        uint64 boostRefundFeeUsd,
        uint128 poolPrimeThreshold,
        uint128 executionFee,
        uint128 maxExecutionFee,
        uint128 forwardFee,
        uint128 maxForwardFee
    ) internal {
        self._markets[marketId] = MarketMetadata({
            quoteToken: quoteToken,
            baseReserveRatio: baseReserveRatio,
            quoteReserveRatio: quoteReserveRatio,
            oracleFeeUsd: oracleFeeUsd,
            boostFeeUsd: boostFeeUsd,
            boostRefundFeeUsd: boostRefundFeeUsd,
            poolPrimeThreshold: poolPrimeThreshold,
            executionFee: executionFee,
            maxExecutionFee: maxExecutionFee,
            forwardFee: forwardFee,
            maxForwardFee: maxForwardFee
        });

        self._marketIds.add(MarketId.unwrap(marketId));
        self._tokenMarketIds.set(quoteToken, MarketId.unwrap(marketId));
    }

    function marketExists(Data storage self, MarketId marketId) internal view returns (bool) {
        return self._marketIds.contains(MarketId.unwrap(marketId));
    }

    function getMarketIds(Data storage self) internal view returns (bytes32[] memory) {
        return self._marketIds.values();
    }

    function getMarket(Data storage self, MarketId marketId) internal view returns (MarketMetadata memory) {
        return self._markets[marketId];
    }

    function getMarketIdByToken(Data storage self, address token) internal view returns (MarketId) {
        return MarketId.wrap(self._tokenMarketIds.get(token));
    }

    function getMarketByToken(Data storage self, address token) internal view returns (MarketMetadata memory) {
        return self._markets[self.getMarketIdByToken(token)];
    }

    function getExecutionFee(Data storage self, MarketId marketId) internal view returns (uint128) {
        return self._markets[marketId].executionFee;
    }

    function getExecutionFeeByToken(Data storage self, address token) internal view returns (uint128) {
        return self._markets[self.getMarketIdByToken(token)].executionFee;
    }

    function getForwardFee(Data storage self, MarketId marketId) internal view returns (uint128) {
        return self._markets[marketId].forwardFee;
    }

    function getForwardFeeByToken(Data storage self, address token) internal view returns (uint128) {
        return self._markets[self.getMarketIdByToken(token)].forwardFee;
    }

    function getMaxExecutionFee(Data storage self, MarketId marketId) internal view returns (uint128) {
        return self._markets[marketId].maxExecutionFee;
    }

    function getMaxForwardFee(Data storage self, MarketId marketId) internal view returns (uint128) {
        return self._markets[marketId].maxForwardFee;
    }

    function getOracleVerificationFee(Data storage self, MarketId marketId) internal view returns (uint64) {
        return self._markets[marketId].oracleFeeUsd;
    }

    function getBoostFee(Data storage self, MarketId marketId) internal view returns (uint64) {
        return self._markets[marketId].boostFeeUsd;
    }

    function getBoostRefundFee(Data storage self, MarketId marketId) internal view returns (uint64) {
        return self._markets[marketId].boostRefundFeeUsd;
    }

    function updateReserveRatio(Data storage self, MarketId marketId, uint32 baseReserveRatio, uint32 quoteReserveRatio) internal {
        self._markets[marketId].baseReserveRatio = baseReserveRatio;
        self._markets[marketId].quoteReserveRatio = quoteReserveRatio;
    }

    function updateOracleFee(Data storage self, MarketId marketId, uint64 oracleFeeUsd) internal {
        self._markets[marketId].oracleFeeUsd = oracleFeeUsd;
    }

    function updatePoolPrimeThreshold(Data storage self, MarketId marketId, uint128 poolPrimeThreshold) internal {
        self._markets[marketId].poolPrimeThreshold = poolPrimeThreshold;
    }

    function updateExecutionFee(Data storage self, MarketId marketId, uint128 executionFee) internal {
        self._markets[marketId].executionFee = executionFee;
    }

    function updateForwardFee(Data storage self, MarketId marketId, uint128 forwardFee) internal {
        self._markets[marketId].forwardFee = forwardFee;
    }

    function updateMaxExecutionFee(Data storage self, MarketId marketId, uint128 maxExecutionFee) internal {
        self._markets[marketId].maxExecutionFee = maxExecutionFee;
    }

    function updateMaxForwardFee(Data storage self, MarketId marketId, uint128 maxForwardFee) internal {
        self._markets[marketId].maxForwardFee = maxForwardFee;
    }
}

library LibMarketMetadata {
    function isMarketInitialized(MarketMetadata memory self) internal pure returns (bool) {
        return self.quoteToken != address(0);
    }
}

