/// @title Constants
/// @notice Protocol-wide precision constants and configuration values
library Constants {
    uint256 public constant MAX_MARKET_ORDER_LIFETIME = 3 minutes;

    uint256 public constant MAX_ORDER_COUNT = 100;

    /// @notice Decimals for risk control slippage
    uint8 public constant RISK_SLIPPAGE_DECIMALS = 8;

    /// @notice Decimals for user slippage
    uint8 public constant SLIPPAGE_DECIMALS = 4;

    /// @notice Decimals for USD
    uint8 public constant USD_DECIMALS = 6;

    /// @notice Standard decimals for pool tokens
    uint8 internal constant POOL_TOKEN_DECIMALS = 18;

    /// @notice Decimals for price
    uint256 public constant PRICE_DECIMALS = 30;

    /// @notice Precision for price calculations (1e30)
    uint256 internal constant PRICE_PRECISION = 1e30;

    /// @notice Precision for user slippage calculations (1e4 = 10000 = 100%)
    uint256 internal constant SLIPPAGE_PRECISION = 1e4;

    /// @notice Precision for risk control slippage calculations (1e8 = 100000000 = 100%)
    uint256 internal constant RISK_SLIPPAGE_PRECISION = 1e8;

    /// @notice Precision for price deviation calculations (1e4 = 10000 = 100%)
    uint256 internal constant PRICE_DEVIATION_PRECISION = 1e4;

    /// @notice Precision for trading fee rate calculations (1e8 = 100000000 = 100%)
    uint256 internal constant TRADING_FEE_RATE_PRECISION = 1e8;

    /// @notice Precision for common configuration values (1e8)
    uint256 internal constant COMMON_CONFIG_PRECISION = 1e8;

    /// @notice Precision for reserve ratio calculations (1e2 = 100 = 100%)
    uint256 internal constant RESERVE_RATIO_PRECISION = 1e2;

    /// @notice Precision for liquidity ratio calculations (1e18)
    uint256 internal constant LIQUIDITY_RATIO_PRECISION = 1e18;

    /// @notice Precision for funding rate calculations (1e18)
    uint256 internal constant FUNDING_RATE_PRECISION = 1e18;
    uint8 internal constant FUNDING_RATE_DECIMALS = 18;

    /// @notice Precision for risk price range calculations (1e4 = 10000 = 100%)
    uint256 internal constant RISK_PRICE_RANGE_PRECISION = 1e4;

    /// @notice Precision for incentive rate calculations (1e4 = 10000 = 100%)
    uint256 internal constant INCENTIVE_RATE_PRECISION = 1e4;

    /// @notice Precision for margin ratio calculations (1e4 = 10000 = 100%)
    uint256 internal constant MARGIN_RATIO_PRECISION = 1e4;
    uint8 internal constant MARGIN_RATIO_DECIMALS = 4;

    /// @notice Precision for collateral ratio calculations (1e2 = 100 = 100%)
    uint256 internal constant COLLATERAL_RATIO_PRECISION = 1e2;

    /// @notice Precision for vote config calculations (1e4 = 10000 = 100%)
    uint256 internal constant VOTE_CONFIG_PRECISION = 1e4;

    /// @notice Precision for genesis rebate ratio calculations (1e4 = 10000 = 100%)
    uint256 internal constant GENESIS_REBATE_RATIO_PRECISION = 1e4;

    /// @notice Precision for market usd quote config calculations (1e4 = 10000 = 100%)
    uint256 internal constant USD_QUOTE_PRECISION = 1e4;
    uint256 internal constant USD_QUOTE_PRICE = 1;
}

