    error CaseDeadlineNotReached();
    error BondNotReleased();
    error BondZeroAmount();
    error CaseNotAccepted();
    error CaseAppealNotFinished();
    error NotCaseRespondent(CaseId caseId, address respondent);
    error CaseRespondentAppealed(CaseId caseId, address respondent);
    error UntrustfulVoting();
    error ResponseCountMismatch();
    error EthCallCountMismatch();
    error StaleEthCall();
    error InvalidSourceChain();
    error SignatureExpired();

    error TreeAlreadySet();
    error ReimbursementValidity(CaseId caseId);
    error AlreadyClaimed(CaseId caseId, address user);
    error AlreadyMinted();
    error InvalidProfitAmount();
    error InvalidAmount(CaseId caseId, address user);
