// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { MarketId, PoolId, PoolState, PositionId, OrderType, TriggerType, Operation, Direction, TimeInForce } from "./Types.sol";

/// @notice Market metadata structure
struct MarketMetadata {
    // Quote token address (e.g., USDC)
    address quoteToken;
    // Base asset reserve ratio
    uint32 baseReserveRatio;
    // Quote asset reserve ratio
    uint32 quoteReserveRatio;
    // Oracle update fee in USD
    uint64 oracleFeeUsd;
    // Boost fee in USD
    uint64 boostFeeUsd;
    // Boost refund fee in USD
    uint64 boostRefundFeeUsd;
    // Minimum liquidity threshold for pool priming
    uint128 poolPrimeThreshold;
    // Execution fee
    uint128 executionFee;
    // Maximum execution fee
    uint128 maxExecutionFee;
    // Forward fee
    uint128 forwardFee;
    // Maximum forward fee
    uint128 maxForwardFee;
}

/// @notice Pool metadata structure
struct PoolMetadata {
    // Market this pool belongs to
    MarketId marketId;
    // Unique pool identifier
    PoolId poolId;
    // Base asset token address (e.g., WETH)
    address baseToken;
    // Quote asset token address (e.g., USDC)
    address quoteToken;
    // Risk tier level
    uint8 riskTier;
    // Current pool state
    PoolState state;
    // Whether compounding is enabled
    bool compoundEnabled;
    // LP token for base asset
    address basePoolToken;
    // LP token for quote asset
    address quotePoolToken;
    // Pool vault contract address
    address poolVault;
    // Trading vault contract address
    address tradingVault;
}

/// @notice Order metadata structure
struct OrderMetadata {
    // Pool where order will be executed
    PoolId poolId;
    // Associated position ID
    PositionId positionId;
    // Collateral amount for the order
    uint256 collateralAmount;
    // Order size in base asset units
    uint256 size;
    // Order price
    uint256 price;
    // Amount already filled
    uint256 filledSize;
    // Order owner address
    address user;
    // Type of order (Market, Limit, etc.)
    OrderType orderType;
    // Trigger condition (None, Above, Below)
    TriggerType triggerType;
    // Operation type (Open, Close, Increase, Decrease)
    Operation operation;
    // Position direction (Long, Short)
    Direction direction;
    // Time validity (only IOC supported)
    TimeInForce timeInForce;
    // Maximum slippage tolerance in basis points
    uint16 slippagePct;
    // Whether order should only be maker
    bool postOnly;
    // Broker address for fee sharing
    address broker;
    // Order creation timestamp
    uint64 createdAt;
}

/// @notice Take Profit / Stop Loss order data
struct OrderTPSLData {
    // Take profit order size
    uint256 tpSize;
    // Take profit trigger price
    uint256 tpPrice;
    // Stop loss order size
    uint256 slSize;
    // Stop loss trigger price
    uint256 slPrice;
}

/// @notice Position metadata structure
struct PositionMetadata {
    // Pool where position exists
    PoolId poolId;
    // Position size in base asset units
    uint256 size;
    // Average entry price
    uint256 entryPrice;
    // Funding rate tracking index
    int256 fundingRateIndex;
    // Preset early close price (0 if not set)
    uint256 earlyClosePrice;
    // Position direction (Long, Short)
    Direction direction;
    // Risk tier level when position was opened
    uint8 riskTier;
    // Timestamp of last position update
    uint64 lastUpdateTime;
    // Broker address
    address broker;
}

