pragma solidity ^0.8.20;

import { PositionId, PoolId, Direction } from "./Types.sol";

using PositionIdLib for PositionKey global;
using PositionIdLib for NFTPositionKey global;

struct PositionKey {
    PoolId poolId;
    address user;
    uint64 salt;
    Direction direction;
}

struct NFTPositionKey {
    PoolId poolId;
    uint256 tokenId;
    Direction direction;
}

library PositionIdLib {
    function toId(PositionKey memory positionKey) internal pure returns (PositionId positionId) {
        assembly ("memory-safe") {
            positionId := keccak256(positionKey, 0x80)
        }
    }

    function toId(NFTPositionKey memory positionKey) internal pure returns (PositionId positionId) {
        assembly ("memory-safe") {
            positionId := keccak256(positionKey, 0x60)
        }
    }
}

