// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

import { GuardianSet, ICoreBridge } from "wormhole-sdk/interfaces/ICoreBridge.sol";

/// @title MockCoreBridge
/// @notice Minimal Wormhole CoreBridge mock for local testing.
/// Stores a fixed guardian set with known test private keys so CCQ responses
/// can be signed off-chain and verified by the real QueryResponseLib.
contract MockCoreBridge {
    address[] private _guardians;

    constructor(address[] memory guardians) {
        _guardians = guardians;
    }

    /// @notice Always returns guardian set index 0.
    function getCurrentGuardianSetIndex() external pure returns (uint32) {
        return 0;
    }

    /// @notice Returns the mock guardian set for any index.
    /// expirationTime = 0 means the set never expires.
    function getGuardianSet(uint32 /*index*/) external view returns (GuardianSet memory) {
        return GuardianSet({ keys: _guardians, expirationTime: 0 });
    }
}

