// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { Strings } from "@openzeppelin/contracts/utils/Strings.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IPoolExecuteFacet } from "./executor/interfaces/IPoolExecuteFacet.sol";
import { ICollectFee } from "./interfaces/ICollectFee.sol";
import { IExchange } from "./interfaces/IExchange.sol";
import { IExecutor } from "./interfaces/IExecutor.sol";
import { IKeeper } from "./interfaces/IKeeper.sol";
import { ILiquidityRouter } from "./interfaces/ILiquidityRouter.sol";
import { IMarketManager } from "./interfaces/IMarketManager.sol";
import { IOracle } from "./interfaces/IOracle.sol";
import { IOrderManager } from "./interfaces/IOrderManager.sol";
import { IPoolConfigurator } from "./interfaces/IPoolConfigurator.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IReservePool } from "./interfaces/IReservePool.sol";
import { ITradingVault } from "./interfaces/ITradingVault.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { TokenConverter } from "./libraries/TokenConverter.sol";
import { BaseContract } from "./misc/base/BaseContract.sol";
import { Errors, PoolMetadata, PoolState, PoolId, OrderId, PositionId, OrderMetadata, OrderType, Constants, Operation } from "./types/Types.sol";
import { PrecisionUtils } from "./utils/PrecisionUtils.sol";

/// @title Keeper
/// @notice Automated keeper for order execution and liquidations
contract Keeper is BaseContract, Ownable, ReentrancyGuard, Pausable, IKeeper, ICollectFee {
    using SafeERC20 for IERC20;
    using PrecisionUtils for uint256;
    using EnumerableSetLib for EnumerableSetLib.AddressSet;

    /// @notice Time window (seconds) after submission before public execution is allowed
    uint64 public gracePeriod;

    /// @notice Token address to be collected for executing fee
    address private transient _designatedToken;
    /// @notice Balance of the designated token before collecting execution fee
    uint256 private transient _balanceBefore;

    EnumerableSetLib.AddressSet private _relayers;
    EnumerableSetLib.AddressSet private _allowedTargets;

    /// @notice Emitted when order matching fails
    event MatchOrderFailed(OrderId triggerOrderId, OrderId matchedOrderId, string reason);
    /// @notice Emitted when pool execution fails
    event ExecuteOrderFailed(OrderId orderId, string reason);
    /// @notice Emitted when liquidation of a position fails
    event LiquidatePositionFailed(PositionId positionId, string reason);

    event RelayerAdded(address relayer);
    event RelayerRemoved(address relayer);
    event AllowedTargetAdded(address target);
    event AllowedTargetRemoved(address target);
    event GracePeriodUpdated(uint64 gracePeriod);

    error OrderNotExpired(OrderId orderId);
    error TargetNotAllowed(address target);
    error GracePeriodNotExpired();
    error OnlyMarketDecreaseOrder(OrderId orderId);

    modifier onlyRelayer() {
        _onlyRelayer();
        _;
    }

    modifier recordTokenBalance(address designatedToken) {
        _recordTokenBalance(designatedToken);
        _;
    }

    modifier withPricesAndRewind(IOracle.UpdatePriceWithRewindParams[] calldata priceUpdates) {
        _getOracle().updatePricesWithRewind{ value: msg.value }(priceUpdates);
        _;
    }

    constructor(address addressManager, address initialOwner) Ownable(initialOwner) initializer {
        bytes32[] memory dependencies = new bytes32[](9);
        dependencies[0] = Identifier.EXECUTOR;
        dependencies[1] = Identifier.ORACLE;
        dependencies[2] = Identifier.EXCHANGE;
        dependencies[3] = Identifier.ORDER_MANAGER;
        dependencies[4] = Identifier.POOL_MANAGER;
        dependencies[5] = Identifier.LIQUIDITY_ROUTER;
        dependencies[6] = Identifier.MARKET_MANAGER;
        dependencies[7] = Identifier.POOL_CONFIGURATOR;
        dependencies[8] = Identifier.RESERVE_POOL;
        __BaseContract_init(addressManager, dependencies);
    }

    receive() external payable {}

    /// @inheritdoc ICollectFee
    function getDesignatedToken() external view override returns (address) {
        return _designatedToken;
    }

    function getRelayers() external view returns (address[] memory) {
        return _relayers.values();
    }

    /// @notice Pause the keeper contract
    function pause() external onlyOwner {
        _pause();
    }

    /// @notice Unpause the keeper contract
    function unpause() external onlyOwner {
        _unpause();
    }

    function addRelayers(address[] calldata relayers) external onlyOwner {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.add(relayers[i]);
            emit RelayerAdded(relayers[i]);
        }
    }

    function removeRelayers(address[] calldata relayers) external onlyOwner {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.remove(relayers[i]);
            emit RelayerRemoved(relayers[i]);
        }
    }

    function setGracePeriod(uint64 _gracePeriod) external onlyOwner {
        gracePeriod = _gracePeriod;
        emit GracePeriodUpdated(_gracePeriod);
    }

    function getAllowedTargets() external view returns (address[] memory) {
        return _allowedTargets.values();
    }

    function isAllowedTarget(address target) external view returns (bool) {
        return _allowedTargets.contains(target);
    }

    function addAllowedTargets(address[] calldata targets) external onlyOwner {
        for (uint256 i; i < targets.length; ++i) {
            _allowedTargets.add(targets[i]);
            emit AllowedTargetAdded(targets[i]);
        }
    }

    function removeAllowedTargets(address[] calldata targets) external onlyOwner {
        for (uint256 i; i < targets.length; ++i) {
            _allowedTargets.remove(targets[i]);
            emit AllowedTargetRemoved(targets[i]);
        }
    }

    /// @notice Match two orders
    /// @param prices Oracle price update parameters
    /// @param param Match execute parameters
    function matchOrder(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        IPoolConfigurator.UpdatePoolRiskTierParams[] calldata riskParams,
        IExecutor.MatchExecuteParams calldata param
    ) external payable onlyRelayer nonReentrant whenNotPaused recordTokenBalance(param.executeFeeToken) {
        _getOracle().updatePrices{ value: msg.value }(prices);
        if (riskParams.length > 0) _getPoolConfigurator().updatePoolRiskTiers(riskParams);
        _tryMatchOrder(_getExecutor(), param);
    }

    function _tryMatchOrder(IExecutor executor, IExecutor.MatchExecuteParams calldata param) internal {
        try executor.matchExecute(param) {
            _consumeExecuteFee(param.executeFeeToken, 2);
        } catch Error(string memory _reason) {
            emit MatchOrderFailed(param.triggerOrderId, param.matchedOrderId, _reason);
        } catch (bytes memory returnData) {
            string memory errorStr = Strings.toHexString(returnData);
            emit MatchOrderFailed(param.triggerOrderId, param.matchedOrderId, errorStr);
        }
    }

    /// @notice Execute multiple pool orders in batch
    /// @param prices Oracle price update parameters
    /// @param params Array of pool execution parameters
    function executeOrders(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        IPoolConfigurator.UpdatePoolRiskTierParams[] calldata riskParams,
        IPoolExecuteFacet.PoolExecuteParams[] calldata params
    ) external payable onlyRelayer nonReentrant whenNotPaused {
        _getOracle().updatePrices{ value: msg.value }(prices);
        IExecutor executor = _getExecutor();
        if (riskParams.length > 0) _getPoolConfigurator().updatePoolRiskTiers(riskParams);

        for (uint256 i = 0; i < params.length; ++i) {
            _recordTokenBalance(params[i].executeFeeToken);
            _tryExecuteOrder(executor, params[i]);
        }
    }

    /// @notice Execute a single pool order
    /// @param prices Oracle price update parameters
    /// @param param Pool execution parameters
    function executeOrder(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        IPoolConfigurator.UpdatePoolRiskTierParams[] calldata riskParams,
        IPoolExecuteFacet.PoolExecuteParams calldata param
    ) external payable onlyRelayer nonReentrant whenNotPaused recordTokenBalance(param.executeFeeToken) {
        _getOracle().updatePrices{ value: msg.value }(prices);
        if (riskParams.length > 0) _getPoolConfigurator().updatePoolRiskTiers(riskParams);

        _tryExecuteOrder(_getExecutor(), param);
    }

    function _tryExecuteOrder(IExecutor executor, IPoolExecuteFacet.PoolExecuteParams memory param) internal {
        try executor.poolExecute(param) {
            _consumeExecuteFee(param.executeFeeToken, 1);
        } catch Error(string memory _reason) {
            emit ExecuteOrderFailed(param.orderId, _reason);
            _getOrderManager().uncompleteOrder(param.orderId, _reason);
        } catch (bytes memory returnData) {
            string memory errorStr = Strings.toHexString(returnData);
            emit ExecuteOrderFailed(param.orderId, errorStr);

            if (returnData.length >= 4) {
                (, bool isRetryable) = _isRetryableError(returnData);
                if (!isRetryable) _getOrderManager().uncompleteOrder(param.orderId, errorStr);
            }
        }
    }

    /// @notice Execute auto-deleveraging (ADL) operation
    /// @param prices Oracle price update parameters
    /// @param param ADL execution parameters
    function executeADL(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        IPoolConfigurator.UpdatePoolRiskTierParams[] calldata riskParams,
        IExecutor.ADLExecuteParams calldata param
    ) external payable onlyRelayer nonReentrant whenNotPaused recordTokenBalance(param.executeFeeToken) {
        _getOracle().updatePrices{ value: msg.value }(prices);
        if (riskParams.length > 0) _getPoolConfigurator().updatePoolRiskTiers(riskParams);

        _tryExecuteADL(_getExecutor(), param);
    }

    function _tryExecuteADL(IExecutor executor, IExecutor.ADLExecuteParams calldata param) internal {
        try executor.adlExecute(param) {
            _consumeExecuteFee(param.executeFeeToken, 1);
        } catch Error(string memory _reason) {
            emit ExecuteOrderFailed(param.orderId, _reason);
            _getOrderManager().uncompleteOrder(param.orderId, _reason);
        } catch (bytes memory returnData) {
            string memory errorStr = Strings.toHexString(returnData);
            emit ExecuteOrderFailed(param.orderId, errorStr);

            if (returnData.length >= 4) {
                (bytes4 selector, bool isRetryable) = _isRetryableError(returnData);
                if (isRetryable) {
                    // NoADLNeeded(uint256)
                    if (selector == 0xd4944235) {
                        _tryExecuteOrder(
                            executor,
                            IPoolExecuteFacet.PoolExecuteParams({ orderId: param.orderId, executeFeeToken: param.executeFeeToken })
                        );
                    }
                } else {
                    _getOrderManager().uncompleteOrder(param.orderId, errorStr);
                }
            }
        }
    }

    /**
     * @notice Batch execute liquidations for multiple positions
     * @dev CRITICAL: This function uses try-catch mechanism to ensure transaction won't revert,
     *      even if individual liquidation fails, it will continue processing other positions.
     *      This design ensures error information can be properly sent to off-chain systems via events,
     *      preventing the entire batch transaction from reverting and losing critical error information.
     * @param priceUpdates Live + rewind price update parameters paired per market
     * @param params Liquidation execution parameters array
     */
    function liquidatePositions(
        IOracle.UpdatePriceWithRewindParams[] calldata priceUpdates,
        IExecutor.LiquidatePositionParams[] calldata params
    ) external payable onlyRelayer nonReentrant whenNotPaused withPricesAndRewind(priceUpdates) {
        IExecutor executor = _getExecutor();

        // Process liquidation requests individually, use try-catch to ensure single failure won't affect entire batch
        // This guarantees error information for each liquidation can be properly sent via events
        for (uint256 i = 0; i < params.length; ++i) {
            try executor.liquidateExecute(params[i]) {} catch Error(string memory _reason) {
                emit LiquidatePositionFailed(params[i].positionId, _reason);
            } catch (bytes memory returnData) {
                emit LiquidatePositionFailed(params[i].positionId, Strings.toHexString(returnData));
            }
        }
    }

    /**
     * @notice Execute liquidation for a single position
     * @param priceUpdates Live + rewind price update parameters paired per market
     * @param param Liquidation execution parameters
     */
    function liquidatePosition(
        IOracle.UpdatePriceWithRewindParams[] calldata priceUpdates,
        IExecutor.LiquidatePositionParams calldata param
    ) external payable onlyRelayer nonReentrant whenNotPaused withPricesAndRewind(priceUpdates) {
        _getExecutor().liquidateExecute(param);
    }

    /// @notice Execute early close position operation
    /// @param priceUpdates Live + rewind price update parameters paired per market
    /// @param param Early close parameters
    function earlyClosePosition(
        IOracle.UpdatePriceWithRewindParams[] calldata priceUpdates,
        IExecutor.EarlyCloseParams calldata param
    ) external payable onlyRelayer nonReentrant whenNotPaused withPricesAndRewind(priceUpdates) {
        _getExecutor().earlyCloseExecute(param);
    }

    /// @notice Execute pool close position operation
    /// @param prices Oracle price update parameters
    /// @param param Pool close parameters
    function poolClosePosition(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        IExecutor.ClosePoolPositionsParams calldata param
    ) external payable onlyRelayer nonReentrant whenNotPaused {
        _getOracle().updatePrices{ value: msg.value }(prices);
        _getExecutor().poolCloseExecute(param);
    }

    /// @notice Execute risk control close position operation
    /// @param prices Oracle price update parameters
    /// @param param Risk control close parameters
    function riskControlClosePosition(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        IExecutor.RiskControlCloseParams calldata param
    ) external payable onlyRelayer nonReentrant whenNotPaused {
        _getOracle().updatePrices{ value: msg.value }(prices);
        _getExecutor().riskControlCloseExecute(param);
    }

    /// @notice Cancel expired orders
    /// @param orderIds Array of order IDs
    function cancelExpiredOrders(uint256[] calldata orderIds) external onlyRelayer nonReentrant {
        IOrderManager orderManager = _getOrderManager();
        for (uint256 i = 0; i < orderIds.length; i++) {
            OrderId orderId = OrderId.wrap(orderIds[i]);
            OrderMetadata memory order = orderManager.getOrder(orderId);
            require(
                order.orderType == OrderType.Market && block.timestamp > order.createdAt + Constants.MAX_MARKET_ORDER_LIFETIME,
                OrderNotExpired(orderId)
            );
        }
        orderManager.uncompleteOrders(orderIds, "EXPIRED ORDER");
    }

    function executeLPOrder(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        ExecuteLPOrderParams calldata params
    ) external payable onlyRelayer nonReentrant whenNotPaused {
        require(_allowedTargets.contains(params.target), TargetNotAllowed(params.target));
        _getOracle().updatePrices{ value: msg.value }(prices);

        ILiquidityRouter liquidityRouter = ILiquidityRouter(_getDependencyAddress(Identifier.LIQUIDITY_ROUTER));
        PoolMetadata memory pool = _getPoolManager().getPool(params.poolId);

        IERC20(pool.quoteToken).forceApprove(address(liquidityRouter), params.sourceIn);
        (uint256 baseOut, ) = liquidityRouter.executeTpsl(params.orderId, params.sourceIn, params.minTargetOut);
        if (baseOut > 0) {
            TokenConverter.convert(
                TokenConverter.ConvertInParams({
                    src: pool.baseToken,
                    target: params.target,
                    amount: baseOut,
                    minOut: params.minConvertOut,
                    data: params.convertData
                }),
                pool.quoteToken
            );
        }
    }

    /// @notice Withdraw tokens or ETH from the contract
    /// @param token Token address (address(0) for ETH)
    /// @param to Recipient address
    /// @param amount Amount to withdraw
    function withdraw(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        if (token == address(0)) {
            (bool success, ) = payable(to).call{ value: amount }("");
            require(success, Errors.TransferFailed());
        } else {
            IERC20(token).safeTransfer(to, amount);
        }
    }

    /// @notice Swap tokens to ETH using token converter
    /// @param params Token conversion parameters
    function swapToETH(TokenConverter.ConvertInParams calldata params) external onlyOwner nonReentrant {
        TokenConverter.convertToETH(params);
    }

    function buyQuote(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        ConvertAndExchangeParams calldata params
    ) external payable onlyRelayer nonReentrant {
        require(_allowedTargets.contains(params.target), TargetNotAllowed(params.target));
        _getOracle().updatePrices{ value: msg.value }(prices);

        IExchange exchange = _getExchange();
        PoolMetadata memory pool = _getPoolManager().getPool(params.poolId);

        uint256 amountOut = TokenConverter.convert(
            TokenConverter.ConvertInParams({
                src: pool.quoteToken,
                target: params.target,
                amount: params.maxConvertIn,
                minOut: params.sourceIn,
                data: params.convertData
            }),
            pool.baseToken
        );

        IERC20(pool.baseToken).forceApprove(address(exchange), amountOut);
        (uint256 usedBase, ) = exchange.exchangeBaseToQuote(
            IExchange.ExchangeParams({ poolId: params.poolId, sourceIn: amountOut, minTargetOut: params.minTargetOut, recipient: address(this) })
        );
        require(usedBase == amountOut, Errors.ConvertAmountMismatch(amountOut, usedBase));
    }

    function sellBase(
        IOracle.UpdateMarketPriceParams[] calldata prices,
        ExchangeAndConvertParams calldata params
    ) external payable onlyRelayer nonReentrant {
        require(_allowedTargets.contains(params.target), TargetNotAllowed(params.target));
        _getOracle().updatePrices{ value: msg.value }(prices);

        IExchange exchange = _getExchange();
        PoolMetadata memory pool = _getPoolManager().getPool(params.poolId);

        IERC20(pool.quoteToken).forceApprove(address(exchange), params.sourceIn);
        (, uint256 receivedBase) = exchange.exchangeQuoteToBase(
            IExchange.ExchangeParams({
                poolId: params.poolId,
                sourceIn: params.sourceIn,
                minTargetOut: params.minTargetOut,
                recipient: address(this)
            })
        );

        TokenConverter.convert(
            TokenConverter.ConvertInParams({
                src: pool.baseToken,
                target: params.target,
                amount: receivedBase,
                minOut: params.minConvertOut,
                data: params.convertData
            }),
            pool.quoteToken
        );
    }

    function liquidatePoolDebt(IOracle.UpdateMarketPriceParams[] calldata prices, PoolId poolId) external payable onlyRelayer nonReentrant {
        _getOracle().updatePrices{ value: msg.value }(prices);

        IReservePool reservePool = _getReservePool();
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        ITradingVault.DebtInfo memory debtInfo = ITradingVault(pool.tradingVault).debtInfo();
        require(pool.state == PoolState.PreBench, Errors.PoolNotInPreBenchState(poolId));

        uint256 quoteReserveAmount = reservePool.poolRiskReserves(poolId, pool.quoteToken);
        if (quoteReserveAmount >= debtInfo.totalDebt) {
            reservePool.liquidatePoolDebt(pool);
        } else {
            uint256 quoteKeeperAmount = IERC20(pool.quoteToken).balanceOf(address(this));
            require(quoteKeeperAmount >= debtInfo.totalDebt, Errors.InsufficientBalance(address(this), quoteKeeperAmount, debtInfo.totalDebt));

            IERC20(pool.quoteToken).forceApprove(pool.tradingVault, debtInfo.totalDebt);
            ITradingVault(pool.tradingVault).repayCollateralTo();
        }
    }

    function executeDecreaseMarketOrderPublic(IOracle.UpdateMarketPriceParams[] calldata prices, OrderId orderId) external payable nonReentrant {
        OrderMetadata memory order = _getOrderManager().getOrder(orderId);
        require(order.orderType == OrderType.Market && order.operation == Operation.Decrease, OnlyMarketDecreaseOrder(orderId));
        uint256 createdAt = order.createdAt;
        require(createdAt + gracePeriod < block.timestamp, GracePeriodNotExpired());

        _getOracle().updatePrices{ value: msg.value }(prices);

        address executeFeeToken;
        _recordTokenBalance(executeFeeToken);
        _tryExecuteOrder(_getExecutor(), IPoolExecuteFacet.PoolExecuteParams({ executeFeeToken: executeFeeToken, orderId: orderId }));
    }

    function _consumeExecuteFee(address designatedToken, uint256 multiplier) internal view {
        uint256 balanceAfter = IERC20(designatedToken).balanceOf(address(this));
        uint256 executionFee = _getMarketManager().getExecutionFeeByToken(designatedToken);
        uint256 expectedFee = executionFee * multiplier;
        require(balanceAfter == _balanceBefore + expectedFee, Errors.MismatchExecuteFee(_balanceBefore, balanceAfter, expectedFee));
    }

    /// @notice Check if the error is retryable
    function _isRetryableError(bytes memory returnData) internal pure returns (bytes4 selector, bool isRetryable) {
        assembly {
            selector := mload(add(returnData, 32))
        }

        if (
            selector == 0xe079169e || // NotReachedPrice(uint256,uint256,uint256,uint8)
            selector == 0x0fd8d29a || // InvalidADLPosition(uint256,uint256)
            selector == 0xd4944235 || // NoADLNeeded(uint256)
            selector == 0xd54d0fc4 || // InsufficientLiquidity(uint256,uint256,uint256)
            selector == 0x19abf40e || // StalePrice()
            selector == 0x00bfc921 || // InvalidPrice()
            selector == 0xfd0f789d // ExceedMaxPriceDeviation()
        ) {
            isRetryable = true;
        }
    }

    function _recordTokenBalance(address designatedToken) internal {
        _designatedToken = designatedToken;
        _balanceBefore = IERC20(designatedToken).balanceOf(address(this));
    }

    function _onlyRelayer() internal view {
        require(_relayers.contains(msg.sender), Errors.OnlyRelayer());
    }

    function _getExecutor() internal view returns (IExecutor) {
        return IExecutor(_getDependencyAddress(Identifier.EXECUTOR));
    }

    function _getOracle() internal view returns (IOracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }

    function _getExchange() internal view returns (IExchange) {
        return IExchange(_getDependencyAddress(Identifier.EXCHANGE));
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getMarketManager() internal view returns (IMarketManager) {
        return IMarketManager(_getDependencyAddress(Identifier.MARKET_MANAGER));
    }

    function _getOrderManager() internal view returns (IOrderManager) {
        return IOrderManager(_getDependencyAddress(Identifier.ORDER_MANAGER));
    }

    function _getPoolConfigurator() internal view returns (IPoolConfigurator) {
        return IPoolConfigurator(_getDependencyAddress(Identifier.POOL_CONFIGURATOR));
    }

    function _getReservePool() internal view returns (IReservePool) {
        return IReservePool(_getDependencyAddress(Identifier.RESERVE_POOL));
    }
}

