// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { EnumerableMapLib } from "@solady/utils/EnumerableMapLib.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IAccount } from "./interfaces/IAccount.sol";
import { ICollectFee } from "./interfaces/ICollectFee.sol";
import { IMarketManager } from "./interfaces/IMarketManager.sol";
import { IOrderManager } from "./interfaces/IOrderManager.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IRiskController } from "./interfaces/IRiskController.sol";
import { ITradingRouter } from "./interfaces/ITradingRouter.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./misc/base/BaseContractUpgradeable.sol";
import { ERC2771ContextUpgradeable } from "./router/ERC2771ContextUpgradeable.sol";
import { Errors, PoolId, OrderId, PoolMetadata, PositionId } from "./types/Types.sol";

contract Account is BaseContractUpgradeable, ERC2771ContextUpgradeable, IAccount {
    using SafeERC20 for IERC20;
    using EnumerableSetLib for EnumerableSetLib.Uint256Set;
    using EnumerableMapLib for EnumerableMapLib.AddressToUint256Map;

    mapping(address account => EnumerableMapLib.AddressToUint256Map userFreeAmount) private _userBalanceAmount;

    mapping(address account => mapping(address token => uint256 totalReserved)) private _userReservedAmount;
    mapping(address account => EnumerableSetLib.Uint256Set userOrders) private _userOrders;
    mapping(OrderId orderId => OrderReserve orderReserve) private _orderReserve;

    modifier onlyRiskController() {
        _onlyRiskController();
        _;
    }

    modifier onlyTradingVault(PoolId poolId) {
        _onlyTradingVault(poolId);
        _;
    }

    modifier onlyOrderManager() {
        _onlyOrderManager();
        _;
    }

    modifier onlyDisputeCourt() {
        _onlyDisputeCourt();
        _;
    }

    modifier onlyTradingRouter() {
        _onlyTradingRouter();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) external initializer {
        bytes32[] memory identifiers = new bytes32[](8);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.RISK_CONTROLLER;
        identifiers[2] = Identifier.POSITION_MANAGER;
        identifiers[3] = Identifier.ORDER_MANAGER;
        identifiers[4] = Identifier.MARKET_MANAGER;
        identifiers[5] = Identifier.FORWARDER;
        identifiers[6] = Identifier.TRADING_ROUTER;
        identifiers[7] = Identifier.DISPUTE_COURT;
        __BaseContractUpgradeable_init(addressManager, identifiers);

        __ERC2771ContextUpgradeable_init(_getDependencyAddress(Identifier.FORWARDER));
    }

    function getUserAsset(address account, address token) external view returns (uint256 amount) {
        (, amount) = _userBalanceAmount[account].tryGet(token);
    }

    function getPoolWithdrawableBaseToken(address account, PoolId poolId) external view returns (uint256 baseAmount) {
        (address baseToken, ) = _getPoolPairToken(poolId);
        uint256 baseReservedAmount = _userReservedAmount[account][baseToken];
        (, uint256 currentBaseAmount) = _userBalanceAmount[account].tryGet(baseToken);
        baseAmount = currentBaseAmount > baseReservedAmount ? currentBaseAmount - baseReservedAmount : 0;
    }

    function getUserAssets(address account) external view returns (AssetInfo[] memory) {
        address[] memory tokens = _userBalanceAmount[account].keys();
        AssetInfo[] memory assets = new AssetInfo[](tokens.length);
        for (uint256 i = 0; i < tokens.length; ++i) {
            assets[i] = AssetInfo({ asset: tokens[i], amount: _userBalanceAmount[account].get(tokens[i]) });
        }
        return assets;
    }

    function getTradableAmount(address account, PoolId poolId) public view returns (bool, uint256, uint256, uint256) {
        (, address token) = _getPoolPairToken(poolId);

        uint256 quoteReservedAmount = _userReservedAmount[account][token];
        (, uint256 balanceAmount) = _userBalanceAmount[account].tryGet(token);

        (bool profitIsReleased, uint256 tradableProfit) = _getRiskController().getTradableProfit(poolId, account);
        return (profitIsReleased, balanceAmount, tradableProfit, quoteReservedAmount);
    }

    function deposit(address account, address token, uint256 amount) external {
        _enforceForwardedRecipient(account);

        (, uint256 currentAmount) = _userBalanceAmount[account].tryGet(token);
        _userBalanceAmount[account].set(token, currentAmount + amount);

        IERC20(token).safeTransferFrom(_msgOrigin(), address(this), amount);
        _getTradingRouter().collectForwardFeeIfNecessary(
            ICollectFee.FeeSource.Direct,
            abi.encode(ICollectFee.AddressFeeParams({ feeToken: token, user: account }))
        );
        emit DepositToAccount(account, token, amount);
    }

    function settlementDeposit(
        PositionId positionId,
        address account,
        PoolMetadata memory pool,
        uint256 freeBaseAmount,
        uint256 freeQuoteAmount,
        uint256 receivedBaseAmount,
        uint256 receivedQuoteAmount
    ) external onlyRiskController {
        address tradingVault = pool.tradingVault;
        address baseToken = pool.baseToken;
        address quoteToken = pool.quoteToken;

        IERC20(quoteToken).safeTransferFrom(tradingVault, address(this), receivedQuoteAmount);
        (, uint256 currentQuoteAmount) = _userBalanceAmount[account].tryGet(quoteToken);
        _userBalanceAmount[account].set(quoteToken, currentQuoteAmount + freeQuoteAmount);

        if (receivedBaseAmount > 0) {
            IERC20(baseToken).safeTransferFrom(tradingVault, address(this), receivedBaseAmount);
            (, uint256 currentBaseAmount) = _userBalanceAmount[account].tryGet(baseToken);
            _userBalanceAmount[account].set(baseToken, currentBaseAmount + freeBaseAmount);
        }

        emit SettleToAccount(
            account,
            positionId,
            baseToken,
            quoteToken,
            freeBaseAmount,
            receivedBaseAmount - freeBaseAmount,
            freeQuoteAmount,
            receivedQuoteAmount - freeQuoteAmount
        );
    }

    function releaseFromProfitUnlock(address account, PoolId poolId, uint256 baseAmount, uint256 quoteAmount) external onlyRiskController {
        (address baseToken, address quoteToken) = _getPoolPairToken(poolId);

        (, uint256 currentQuoteAmount) = _userBalanceAmount[account].tryGet(quoteToken);
        _userBalanceAmount[account].set(quoteToken, currentQuoteAmount + quoteAmount);

        if (baseAmount > 0) {
            (, uint256 currentBaseAmount) = _userBalanceAmount[account].tryGet(baseToken);
            _userBalanceAmount[account].set(baseToken, currentBaseAmount + baseAmount);
            emit ReleaseProfit(account, baseToken, baseAmount);
        }

        emit ReleaseProfit(account, quoteToken, quoteAmount);
    }

    function updateAndWithdraw(address receiver, PoolId poolId, bool isQuoteToken, uint256 amount) external {
        _enforceForwardedRecipient(receiver);

        (address baseToken, address quoteToken) = _getPoolPairToken(poolId);
        address token = isQuoteToken ? quoteToken : baseToken;

        _getTradingRouter().collectForwardFeeIfNecessary(
            ICollectFee.FeeSource.Account,
            abi.encode(ICollectFee.AccountFeeParams({ poolId: poolId, feeToken: token, user: _msgOrigin() }))
        );

        uint256 totalReservedAmount = _userReservedAmount[_msgOrigin()][token];
        uint256 profitAmount = _getRiskController().checkAndReleaseProfitLock(poolId, _msgOrigin());

        (, uint256 currentAmount) = _userBalanceAmount[_msgOrigin()].tryGet(token);
        require(amount <= currentAmount + profitAmount - totalReservedAmount, Errors.AccountInsufficientFreeAmount());

        _userBalanceAmount[_msgOrigin()].set(token, currentAmount - amount);
        IERC20(token).safeTransfer(receiver, amount);
        emit WithdrawFromAccount(_msgOrigin(), token, amount);
    }

    function payWithProfitFirst(
        PoolId poolId,
        OrderId orderId,
        address account,
        address token,
        uint256 amount
    ) external onlyTradingVault(poolId) returns (uint256 usedFreeAmount, uint256 usedRestrictedAmount) {
        (usedFreeAmount, usedRestrictedAmount) = _checkUserTradableAmount(poolId, account, token, amount);

        if (OrderId.unwrap(orderId) != 0) {
            _releaseForOrder(poolId, orderId, account, token, amount);
        }

        uint256 totalReservedAmount = _userReservedAmount[account][token];
        (, uint256 currentAmount) = _userBalanceAmount[account].tryGet(token);
        require(usedFreeAmount <= currentAmount + usedRestrictedAmount - totalReservedAmount, Errors.AccountInsufficientFreeAmount());

        _userBalanceAmount[account].set(token, currentAmount - usedFreeAmount);

        IERC20(token).safeTransfer(_msgSender(), amount);
        emit PayWithProfitFirst(account, _msgSender(), poolId, token, usedFreeAmount, usedRestrictedAmount);
        return (usedFreeAmount, usedRestrictedAmount);
    }

    function payWithPrincipal(PoolId poolId, address account, address token, uint256 amount, address receiver) external onlyTradingRouter {
        (, uint256 balanceAmount, uint256 tradableProfit, uint256 quoteReservedAmount) = getTradableAmount(account, poolId);

        require(amount <= balanceAmount + tradableProfit - quoteReservedAmount, Errors.AccountInsufficientFreeAmount());
        _userBalanceAmount[account].set(token, balanceAmount - amount);

        IERC20(token).safeTransfer(receiver, amount);
        emit PayWithPrincipal(account, receiver, token, amount);
    }

    function reserveForOrder(PoolId poolId, OrderId orderId, address account, address token, uint256 amount) external onlyOrderManager {
        uint256 reservedAmount = _userReservedAmount[account][token];
        uint256 reservedAmountAfterOrder = reservedAmount + amount;

        (uint256 usedFreeAmount, uint256 usedRestrictedAmount) = _checkUserTradableAmount(poolId, account, token, reservedAmountAfterOrder);

        (, uint256 currentAmount) = _userBalanceAmount[account].tryGet(token);
        require(usedFreeAmount <= currentAmount + usedRestrictedAmount, Errors.AccountInsufficientFreeAmount());

        _userReservedAmount[account][token] = reservedAmountAfterOrder;
        _userOrders[account].add(OrderId.unwrap(orderId));
        _orderReserve[orderId] = OrderReserve({ reservedToken: token, reservedAmount: amount });
        emit ReserveForOrder(poolId, orderId, account, token, amount);
    }

    function releaseForCancelOrder(PoolId poolId, OrderId orderId, address account, uint256 amount) external onlyOrderManager {
        (, address quoteToken) = _getPoolPairToken(poolId);
        _releaseForOrder(poolId, orderId, account, quoteToken, amount);
    }

    function executeCompensation(PoolId poolId, address reimbursement, uint256 baseAmount, uint256 quoteAmount) external onlyDisputeCourt {
        (address baseToken, address quoteToken) = _getPoolPairToken(poolId);

        IERC20(baseToken).safeTransfer(reimbursement, baseAmount);
        IERC20(quoteToken).safeTransfer(reimbursement, quoteAmount);
        emit ExecuteCompensation(poolId, baseAmount, quoteAmount);
    }

    function _releaseForOrder(PoolId poolId, OrderId orderId, address account, address token, uint256 amount) internal {
        uint256 reservedAmount = _userReservedAmount[account][token];
        require(amount <= reservedAmount, Errors.AccountInsufficientReservedAmount());

        _userReservedAmount[account][token] = reservedAmount - amount;
        _userOrders[account].remove(OrderId.unwrap(orderId));
        delete _orderReserve[orderId];

        emit ReleaseForOrder(poolId, orderId, account, token, amount);
    }

    function _checkUserTradableAmount(
        PoolId poolId,
        address account,
        address token,
        uint256 amount
    ) internal returns (uint256 freeUsed, uint256 profitUsed) {
        uint256 tradableProfit = _getRiskController().checkAndReleaseProfitLock(poolId, account);

        (, uint256 balanceAmount) = _userBalanceAmount[account].tryGet(token);
        uint256 total = balanceAmount + tradableProfit;

        require(amount <= total, Errors.AccountInsufficientTradableAmount(total, amount));

        profitUsed = amount > tradableProfit ? tradableProfit : amount;
        freeUsed = amount - profitUsed;
    }

    function _getPoolPairToken(PoolId poolId) internal view returns (address baseToken, address quoteToken) {
        return _getPoolManager().getPairToken(poolId);
    }

    function _onlyRiskController() internal view {
        require(_msgSender() == _getDependencyAddress(Identifier.RISK_CONTROLLER), Errors.PermissionDenied(_msgSender(), address(this)));
    }

    function _onlyTradingVault(PoolId poolId) internal view {
        require(_msgSender() == _getPoolManager().getTradingVault(poolId), Errors.PermissionDenied(_msgSender(), address(this)));
    }

    function _onlyOrderManager() internal view {
        require(_msgSender() == _getDependencyAddress(Identifier.ORDER_MANAGER), Errors.PermissionDenied(_msgSender(), address(this)));
    }

    function _onlyDisputeCourt() internal view {
        require(_msgSender() == _getDependencyAddress(Identifier.DISPUTE_COURT), Errors.PermissionDenied(_msgSender(), address(this)));
    }

    function _onlyTradingRouter() internal view {
        require(_msgSender() == _getDependencyAddress(Identifier.TRADING_ROUTER), Errors.PermissionDenied(_msgSender(), address(this)));
    }

    function _getMarketManager() internal view returns (IMarketManager) {
        return IMarketManager(_getDependencyAddress(Identifier.MARKET_MANAGER));
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getTradingRouter() internal view returns (ITradingRouter) {
        return ITradingRouter(_getDependencyAddress(Identifier.TRADING_ROUTER));
    }

    function _getRiskController() internal view returns (IRiskController) {
        return IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER));
    }

    function _getOrderManager() internal view returns (IOrderManager) {
        return IOrderManager(_getDependencyAddress(Identifier.ORDER_MANAGER));
    }
}

