// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IBroker } from "./interfaces/IBroker.sol";
import { IMatcher } from "./interfaces/IMatcher.sol";
import { IOrderManager } from "./interfaces/IOrderManager.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IPositionManager } from "./interfaces/IPositionManager.sol";
import { IRiskController } from "./interfaces/IRiskController.sol";
import { ExecuteHelper } from "./libraries/ExecuteHelper.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./misc/base/BaseContractUpgradeable.sol";
import { Errors, OrderMetadata, PositionMetadata, OrderId, PoolId, PositionId, TimeInForce, Operation } from "./types/Types.sol";

/// @title Matcher
/// @notice Handles order matching and execution
contract Matcher is BaseContractUpgradeable, IMatcher {
    struct PostExecuteParams {
        OrderId orderId;
        PositionId positionId;
        uint256 executeSize;
        uint256 executePrice;
        int256 tradingFee;
        int256 fundingFee;
        int256 realizedPnl;
        int256 charge;
        address keeper;
        bool isLiquidation;
        bool forceCloseOrder;
        Operation operation;
        address broker;
        address user;
    }

    error InternalOnly();

    modifier onlyExecutor() {
        _onlyExecutor();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the matcher contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) external initializer {
        bytes32[] memory dependencies = new bytes32[](5);
        dependencies[0] = Identifier.EXECUTOR;
        dependencies[1] = Identifier.ORDER_MANAGER;
        dependencies[2] = Identifier.POSITION_MANAGER;
        dependencies[3] = Identifier.RISK_CONTROLLER;
        dependencies[4] = Identifier.POOL_MANAGER;
        __BaseContractUpgradeable_init(addressManager, dependencies);
    }

    /// @inheritdoc IMatcher
    function matchPool(
        OrderMetadata memory order,
        OrderId orderId,
        PositionId positionId,
        uint256 executeSize,
        uint256 executePrice,
        address keeper
    ) external override onlyExecutor returns (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        IOrderManager orderManager = _getOrderManager();

        _poolExecute(orderManager, order, orderId, positionId, executeSize, executePrice, keeper, false, true);

        triggerOrderIds = new OrderId[](1);
        triggerOrderIds[0] = orderId;
        matchedOrderIds = new OrderId[](0);
    }

    /// @inheritdoc IMatcher
    function createAndMatchPool(
        CreateOrderParams memory createParams,
        uint256 executeSize,
        uint256 executePrice,
        address keeper
    ) external override onlyExecutor returns (OrderId orderId, OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        IOrderManager orderManager = _getOrderManager();

        orderId = orderManager.saveAutoDecreaseOrder(
            createParams.owner,
            createParams.poolId,
            createParams.positionId,
            executeSize,
            executePrice,
            createParams.direction
        );
        OrderMetadata memory order = orderManager.getOrder(orderId);

        _poolExecute(orderManager, order, orderId, createParams.positionId, executeSize, executePrice, keeper, createParams.isLiquidation, true);

        triggerOrderIds = new OrderId[](1);
        triggerOrderIds[0] = orderId;
        matchedOrderIds = new OrderId[](0);
    }

    function matchOrder(
        MatchOrderParams memory params
    ) external override onlyExecutor returns (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        bool forceCloseTriggerOrder = params.triggerOrder.timeInForce == TimeInForce.IOC;
        bool forceCloseMatchedOrder = params.matchedOrder.timeInForce == TimeInForce.IOC;
        return
            _matchOrder(
                _getOrderManager(),
                params.triggerOrderId,
                params.triggerOrder,
                params.matchedOrderId,
                params.matchedOrder,
                params.matchSize,
                params.matchPrice,
                params.keeper,
                forceCloseTriggerOrder,
                forceCloseMatchedOrder,
                true
            );
    }

    function hybridMatchOrder(
        HybridMatchOrderParams memory params
    ) external override onlyExecutor returns (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        IOrderManager orderManager = _getOrderManager();

        // Determine force close flags: IOC orders should be force closed unless they need pool execution
        // If an order needs pool execution, don't force close it (it will be executed via pool)
        bool forceCloseTriggerOrder =
            params.triggerOrder.timeInForce == TimeInForce.IOC &&
                !(params.matchPoolExecuteParams.needPoolExecute && params.matchPoolExecuteParams.isTriggerOrder);
        bool forceCloseMatchedOrder =
            params.matchedOrder.timeInForce == TimeInForce.IOC &&
                !(params.matchPoolExecuteParams.needPoolExecute && !params.matchPoolExecuteParams.isTriggerOrder);
        (triggerOrderIds, matchedOrderIds) = _matchOrder(
            orderManager,
            params.triggerOrderId,
            params.triggerOrder,
            params.matchedOrderId,
            params.matchedOrder,
            params.matchSize,
            params.matchPrice,
            params.keeper,
            forceCloseTriggerOrder,
            forceCloseMatchedOrder,
            false
        );

        if (params.matchPoolExecuteParams.needPoolExecute) {
            // Select order and orderId based on which order needs pool execution
            OrderMetadata memory poolOrder = params.matchPoolExecuteParams.isTriggerOrder ? params.triggerOrder : params.matchedOrder;
            OrderId poolOrderId = params.matchPoolExecuteParams.isTriggerOrder ? params.triggerOrderId : params.matchedOrderId;

            try
                this._tryPoolExecute(
                    orderManager,
                    poolOrder,
                    poolOrderId,
                    poolOrder.positionId,
                    params.matchPoolExecuteParams.executeSize,
                    params.matchPoolExecuteParams.executePrice,
                    params.keeper,
                    false,
                    true
                )
            {} catch {
                bool originalForceClose = poolOrder.timeInForce == TimeInForce.IOC;
                bool sentForceClose = params.matchPoolExecuteParams.isTriggerOrder ? forceCloseTriggerOrder : forceCloseMatchedOrder;
                if (!sentForceClose && originalForceClose) {
                    orderManager.completeOrder(poolOrderId, poolOrder.positionId);
                }
            }
        }
        // Keep the matched leg synced if the optional pool leg reverted inside the try/catch.
        _getPositionManager().updatePoolReserve(params.triggerOrder.poolId);
    }

    /// @inheritdoc IMatcher
    function matchAdlPositions(
        MatchAdlPositionsParams memory params
    ) external override onlyExecutor returns (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        return
            _matchADLPositions(
                params.triggerOrderId,
                params.adlPositionExecutes,
                params.executeSize,
                params.executePrice,
                params.keeper,
                false,
                params.matchPoolExecuteParams
            );
    }

    /// @inheritdoc IMatcher
    function createAndMatchAdlPositions(
        CreateOrderParams memory createParams,
        MatchAdlPositionsParams memory matchParams
    ) external override onlyExecutor returns (OrderId orderId, OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        IOrderManager orderManager = _getOrderManager();
        orderId = orderManager.saveAutoDecreaseOrder(
            createParams.owner,
            createParams.poolId,
            createParams.positionId,
            matchParams.executeSize + matchParams.matchPoolExecuteParams.executeSize,
            matchParams.executePrice,
            createParams.direction
        );
        (triggerOrderIds, matchedOrderIds) = _matchADLPositions(
            orderId,
            matchParams.adlPositionExecutes,
            matchParams.executeSize,
            matchParams.executePrice,
            matchParams.keeper,
            createParams.isLiquidation,
            matchParams.matchPoolExecuteParams
        );
    }

    function _tryPoolExecute(
        IOrderManager orderManager,
        OrderMetadata memory order,
        OrderId orderId,
        PositionId positionId,
        uint256 executeSize,
        uint256 executePrice,
        address keeper,
        bool isLiquidation,
        bool shouldUpdatePoolReserve
    ) external {
        require(msg.sender == address(this), InternalOnly());
        _poolExecute(orderManager, order, orderId, positionId, executeSize, executePrice, keeper, isLiquidation, shouldUpdatePoolReserve);
    }

    function _matchADLPositions(
        OrderId triggerOrderId,
        ExecuteHelper.ADLPositionExecute[] memory adlPositionExecutes,
        uint256 executeSize,
        uint256 executePrice,
        address keeper,
        bool isLiquidation,
        MatchPoolExecuteParams memory matchPoolExecuteParams
    ) internal returns (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        IOrderManager orderManager = _getOrderManager();
        OrderMetadata memory triggerOrder = orderManager.getOrder(triggerOrderId);

        // Execute ADL positions
        matchedOrderIds = _executeADLPositions(orderManager, adlPositionExecutes, triggerOrder.poolId, keeper);
        // Execute trigger order
        bool forceCloseOrder = triggerOrder.timeInForce == TimeInForce.IOC && !(matchPoolExecuteParams.needPoolExecute);
        _matchedExecute(
            orderManager,
            triggerOrder,
            triggerOrderId,
            triggerOrder.positionId,
            executeSize,
            executePrice,
            keeper,
            isLiquidation,
            forceCloseOrder,
            false
        );

        if (matchPoolExecuteParams.needPoolExecute) {
            try
                this._tryPoolExecute(
                    orderManager,
                    triggerOrder,
                    triggerOrderId,
                    triggerOrder.positionId,
                    matchPoolExecuteParams.executeSize,
                    matchPoolExecuteParams.executePrice,
                    keeper,
                    isLiquidation,
                    true
                )
            {} catch {
                bool originalForceClose = triggerOrder.timeInForce == TimeInForce.IOC;
                if (!forceCloseOrder && originalForceClose) {
                    orderManager.completeOrder(triggerOrderId, triggerOrder.positionId);
                }
            }
        }
        // Keep the ADL/matched leg synced if the optional pool leg reverted inside the try/catch.
        _getPositionManager().updatePoolReserve(triggerOrder.poolId);

        triggerOrderIds = new OrderId[](1);
        triggerOrderIds[0] = triggerOrderId;
    }

    /// @notice Execute ADL positions for deleveraging
    /// @param orderManager Order manager contract
    /// @param adlPositionExecutes Array of ADL position executions (each carries its own settle price)
    /// @param poolId Pool ID for the positions
    /// @param keeper Keeper address
    /// @return orderIds Array of created order IDs
    function _executeADLPositions(
        IOrderManager orderManager,
        ExecuteHelper.ADLPositionExecute[] memory adlPositionExecutes,
        PoolId poolId,
        address keeper
    ) internal returns (OrderId[] memory orderIds) {
        orderIds = new OrderId[](adlPositionExecutes.length);
        for (uint256 i = 0; i < adlPositionExecutes.length; ++i) {
            ExecuteHelper.ADLPositionExecute memory adlPositionExecute = adlPositionExecutes[i];

            OrderId adlOrderId = orderManager.saveAutoDecreaseOrder(
                adlPositionExecute.owner,
                poolId,
                adlPositionExecute.positionId,
                adlPositionExecute.executeSize,
                adlPositionExecute.executePrice,
                adlPositionExecute.direction
            );

            OrderMetadata memory adlOrder = orderManager.getOrder(adlOrderId);
            _matchedExecute(
                orderManager,
                adlOrder,
                adlOrderId,
                adlPositionExecute.positionId,
                adlPositionExecute.executeSize,
                adlPositionExecute.executePrice,
                keeper,
                adlPositionExecute.isLiquidation,
                adlOrder.timeInForce == TimeInForce.IOC,
                false
            );

            orderIds[i] = adlOrderId;
        }
    }

    function _matchOrder(
        IOrderManager orderManager,
        OrderId triggerOrderId,
        OrderMetadata memory triggerOrder,
        OrderId matchedOrderId,
        OrderMetadata memory matchedOrder,
        uint256 matchSize,
        uint256 matchPrice,
        address keeper,
        bool forceCloseTriggerOrder,
        bool forceCloseMatchedOrder,
        bool shouldUpdatePoolReserve
    ) internal returns (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) {
        // Execute trigger order
        _matchedExecute(
            orderManager,
            triggerOrder,
            triggerOrderId,
            triggerOrder.positionId,
            matchSize,
            matchPrice,
            keeper,
            false,
            forceCloseTriggerOrder,
            false
        );
        // Execute matched order
        _matchedExecute(
            orderManager,
            matchedOrder,
            matchedOrderId,
            matchedOrder.positionId,
            matchSize,
            matchPrice,
            keeper,
            false,
            forceCloseMatchedOrder,
            false
        );
        if (shouldUpdatePoolReserve) _getPositionManager().updatePoolReserve(triggerOrder.poolId);

        triggerOrderIds = new OrderId[](1);
        triggerOrderIds[0] = triggerOrderId;
        matchedOrderIds = new OrderId[](1);
        matchedOrderIds[0] = matchedOrderId;
    }

    /// @notice Execute order with pool matching
    /// @param orderManager Order manager contract
    /// @param order Order metadata
    /// @param orderId Order ID to execute
    /// @param executeSize Size to execute
    /// @param executePrice Execution price
    /// @param keeper Keeper address
    function _poolExecute(
        IOrderManager orderManager,
        OrderMetadata memory order,
        OrderId orderId,
        PositionId positionId,
        uint256 executeSize,
        uint256 executePrice,
        address keeper,
        bool isLiquidation,
        bool shouldUpdatePoolReserve
    ) internal {
        IPositionManager positionManager = _getPositionManager();
        (int256 tradingFee, int256 fundingFee, int256 realizedPnl, int256 charge) = positionManager.updatePosition(
            IPositionManager.ExecuteUserPositionParams({
                poolId: order.poolId,
                positionId: positionId,
                executeSize: executeSize,
                executePrice: executePrice,
                orderId: orderId,
                keeper: keeper,
                isMatchExecution: false,
                isLiquidation: isLiquidation,
                shouldUpdatePoolReserve: shouldUpdatePoolReserve
            })
        );

        bool forceCloseOrder = order.timeInForce == TimeInForce.IOC;
        _postExecute(
            orderManager,
            positionManager,
            PostExecuteParams({
                orderId: orderId,
                positionId: positionId,
                executeSize: executeSize,
                executePrice: executePrice,
                keeper: keeper,
                isLiquidation: isLiquidation,
                tradingFee: tradingFee,
                fundingFee: fundingFee,
                realizedPnl: realizedPnl,
                charge: charge,
                forceCloseOrder: forceCloseOrder,
                operation: order.operation,
                broker: order.broker,
                user: order.user
            })
        );
    }

    /// @notice Execute order with matched order matching
    /// @param orderManager Order manager contract
    /// @param order Order metadata
    /// @param orderId Order ID to execute
    /// @param executeSize Size to execute
    /// @param executePrice Execution price
    /// @param keeper Keeper address
    function _matchedExecute(
        IOrderManager orderManager,
        OrderMetadata memory order,
        OrderId orderId,
        PositionId positionId,
        uint256 executeSize,
        uint256 executePrice,
        address keeper,
        bool isLiquidation,
        bool forceCloseOrder,
        bool shouldUpdatePoolReserve
    ) internal {
        IPositionManager positionManager = _getPositionManager();
        (int256 tradingFee, int256 fundingFee, int256 realizedPnl, int256 charge) = positionManager.updatePosition(
            IPositionManager.ExecuteUserPositionParams({
                poolId: order.poolId,
                positionId: positionId,
                executeSize: executeSize,
                executePrice: executePrice,
                orderId: orderId,
                keeper: keeper,
                isMatchExecution: true,
                isLiquidation: isLiquidation,
                shouldUpdatePoolReserve: shouldUpdatePoolReserve
            })
        );

        _postExecute(
            orderManager,
            positionManager,
            PostExecuteParams({
                orderId: orderId,
                positionId: positionId,
                executeSize: executeSize,
                executePrice: executePrice,
                keeper: keeper,
                isLiquidation: isLiquidation,
                tradingFee: tradingFee,
                fundingFee: fundingFee,
                realizedPnl: realizedPnl,
                charge: charge,
                forceCloseOrder: forceCloseOrder,
                operation: order.operation,
                broker: order.broker,
                user: order.user
            })
        );
    }

    function _postExecute(IOrderManager orderManager, IPositionManager positionManager, PostExecuteParams memory params) internal {
        orderManager.fillOrder(
            IOrderManager.FillOrderParams({
                orderId: params.orderId,
                positionId: params.positionId,
                keeper: params.keeper,
                fillSize: params.executeSize,
                fillPrice: params.executePrice,
                realizedPnl: params.realizedPnl,
                tradingFee: params.tradingFee,
                fundingFee: params.fundingFee,
                forceClose: params.forceCloseOrder
            })
        );

        PositionMetadata memory position = positionManager.getPosition(params.positionId);
        address owner = positionManager.getPositionOwner(params.positionId);
        IRiskController riskController = _getRiskController();
        (IRiskController.PositionRiskControlData memory collateralInfo, int256 profitChange) = riskController.chargePositionRiskControlData(
            position,
            params.positionId,
            owner,
            params.charge
        );

        if (position.size == 0) {
            (uint256 returnBaseAmount, uint256 returnQuoteAmount) = positionManager.closePosition(
                params.positionId,
                position.poolId,
                params.executePrice,
                params.isLiquidation,
                owner
            );

            riskController.closePositionRiskControlData(
                collateralInfo,
                position,
                params.positionId,
                params.isLiquidation,
                owner,
                returnBaseAmount,
                returnQuoteAmount,
                params.executePrice,
                profitChange
            );
        }

        if (params.operation == Operation.Increase && params.broker != address(0)) {
            IBroker(params.broker).checkAndResetExpiredTier(params.user);
        }
    }

    function _onlyExecutor() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.EXECUTOR), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getOrderManager() internal view returns (IOrderManager orderManager) {
        return IOrderManager(_getDependencyAddress(Identifier.ORDER_MANAGER));
    }

    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getPositionManager() internal view returns (IPositionManager positionManager) {
        return IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getRiskController() internal view returns (IRiskController riskController) {
        return IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER));
    }
}

wormhole-sdk/utils/EagerOps.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.4;

//see Optimization.md for rationale on avoiding short-circuiting
function eagerAnd(bool lhs, bool rhs) pure returns (bool ret) {
  /// @solidity memory-safe-assembly
  assembly {
    ret := and(lhs, rhs)
  }
}

//see Optimization.md for rationale on avoiding short-circuiting
function eagerOr(bool lhs, bool rhs) pure returns (bool ret) {
  /// @solidity memory-safe-assembly
  assembly {
    ret := or(lhs, rhs)
  }
}

wormhole-sdk/utils/Transfer.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.19;

import {IERC20} from "IERC20/IERC20.sol";
import {SafeERC20} from "SafeERC20/SafeERC20.sol";

error PaymentFailure(address target);

//Note: Always forwards all gas, so consider gas griefing attack opportunities by the recipient.
//Note: Don't use this method if you need events for 0 amount transfers.
function tokenOrNativeTransfer(address tokenOrZeroForNative, address to, uint256 amount) {
  if (amount == 0)
    return;

  if (tokenOrZeroForNative == address(0)) {
    (bool success, ) = to.call{value: amount}(new bytes(0));
    if (!success)
      revert PaymentFailure(to);
  }
  else
    SafeERC20.safeTransfer(IERC20(tokenOrZeroForNative), to, amount);
}

