// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IEmiter } from "./interfaces/IEmiter.sol";
import { IFundingRate } from "./interfaces/IFundingRate.sol";
import { IOracle } from "./interfaces/IOracle.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IPoolVault } from "./interfaces/IPoolVault.sol";
import { IPositionManager } from "./interfaces/IPositionManager.sol";
import { IRiskParameter } from "./interfaces/IRiskParameter.sol";
import { ITradingVault } from "./interfaces/ITradingVault.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { TradingHelper } from "./libraries/TradingHelper.sol";
import { BaseContractUpgradeable } from "./misc/base/BaseContractUpgradeable.sol";
import { Constants, PoolMetadata, PoolId, PoolState } from "./types/Types.sol";
import { PrecisionUtils } from "./utils/PrecisionUtils.sol";

/// @title FundingRate
/// @notice Manages funding rate calculations for perpetual positions
contract FundingRate is BaseContractUpgradeable, IFundingRate {
    using SignedMath for int256;
    using PrecisionUtils for int256;
    using PrecisionUtils for uint256;
    using SafeCast for uint256;

    uint8 private constant FUNDING_RATE_CONFIG_DECIMALS = 8;

    /// @notice Funding rate information storage by pool ID
    mapping(PoolId poolId => FundingRateData funding) private _fundingRateData;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the funding rate contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) external initializer {
        bytes32[] memory dependencies = new bytes32[](5);
        dependencies[0] = Identifier.POOL_MANAGER;
        dependencies[1] = Identifier.POSITION_MANAGER;
        dependencies[2] = Identifier.EMITER;
        dependencies[3] = Identifier.RISK_PARAMETER;
        dependencies[4] = Identifier.ORACLE;
        __BaseContractUpgradeable_init(addressManager, dependencies);
    }

    /// @inheritdoc IFundingRate
    function updateFundingRate(PoolId poolId) external override returns (int256 lastFundingRateTracker) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        if (pool.state == PoolState.Trench || pool.state == PoolState.PreBench) {
            IRiskParameter.FundingRateParams memory fundingRateParams = _getPoolFundingRateParams(pool.riskTier);
            uint256 price = IOracle(_getDependencyAddress(Identifier.ORACLE)).safeOraclePrice(poolId);

            uint64 duration = uint64(fundingRateParams.epochDuration);
            (uint64 epochs, uint64 lastEpochTime, int256 lastTracker, int256 fundingRate) = _pendingFundingRateInfo(pool, price, duration);
            if (epochs == 0) return lastTracker;

            FundingRateData storage fundingRateData = _fundingRateData[pool.poolId];
            uint64 previousEpochTime = fundingRateData.lastEpochTime;
            int256 prevFundingRateTracker = fundingRateData.tracker;
            fundingRateData.tracker = lastTracker;
            fundingRateData.lastEpochTime = lastEpochTime;

            // Immediately settle the pool's funding fee after updating the funding rate
            ITradingVault(pool.tradingVault).settlePoolFundingFee(price, prevFundingRateTracker, lastTracker);

            IEmiter(_getDependencyAddress(Identifier.EMITER)).emitFundingRateUpdated(
                IEmiter.FundingRateUpdatedParams({
                    epochs: epochs,
                    duration: duration,
                    previousEpochTime: previousEpochTime,
                    lastEpochTime: lastEpochTime,
                    poolId: pool.poolId,
                    fundingRate: fundingRate,
                    fundingRateTracker: lastTracker,
                    price: price
                })
            );
            return lastTracker;
        }
        return _fundingRateData[poolId].tracker;
    }

    /// @notice Get the next epoch time for a pool
    /// @param poolId Pool ID to query
    /// @return nextEpoch Next epoch timestamp
    function getNextEpochTime(PoolId poolId) external view returns (uint64 nextEpoch) {
        uint8 riskTier = _getPoolManager().getPoolRiskTier(poolId);
        IRiskParameter.FundingRateParams memory fundingRateParams = _getPoolFundingRateParams(riskTier);
        return _fundingRateData[poolId].lastEpochTime + fundingRateParams.epochDuration;
    }

    /// @inheritdoc IFundingRate
    function previousFundingRateInfo(PoolId poolId) public view returns (FundingRateData memory) {
        return _fundingRateData[poolId];
    }

    /// @inheritdoc IFundingRate
    function nextFundingRateInfo(PoolId poolId, uint256 price) public view returns (NextFundingRateInfo memory info) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        IRiskParameter.FundingRateParams memory fundingRateParams = _getPoolFundingRateParams(pool.riskTier);

        (, uint64 lastEpochTime, int256 lastTracker, int256 nextFundingRate) = _pendingFundingRateInfo(pool, price, fundingRateParams.epochDuration);
        info = NextFundingRateInfo({
            lastFundingFeeTracker: lastTracker,
            nextFundingRate: nextFundingRate,
            nextEpochTime: lastEpochTime + fundingRateParams.epochDuration
        });
    }

    /// @inheritdoc IFundingRate
    function getFundingRateInfo(PoolId poolId, uint256 price) external view returns (FundingRateData memory prev, NextFundingRateInfo memory next) {
        return (previousFundingRateInfo(poolId), nextFundingRateInfo(poolId, price));
    }

    /// @inheritdoc IFundingRate
    function getNextFundingRate(PoolId poolId, uint256 price) public view override returns (int256 fundingRate) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        return _nextFundingRate(pool, price);
    }

    function _nextFundingRate(PoolMetadata memory pool, uint256 price) internal view returns (int256 fundingRate) {
        if (pool.state == PoolState.Cook || pool.state == PoolState.Primed || pool.state == PoolState.Boosted) return 0;

        IPoolVault poolVault = IPoolVault(pool.poolVault);
        IRiskParameter.FundingRateParams memory fundingRateParams = _getPoolFundingRateParams(pool.riskTier);

        IPositionManager.OITracker memory openInterest = IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER)).getOITracker(
            pool.poolId
        );
        IPoolVault.PoolReserve memory poolReserve = poolVault.reserveInfo();

        uint256 baseTotal = poolReserve.baseTotalAmount;
        uint256 quoteToBaseSize = TradingHelper.convertTokenAmount(pool.quoteToken, pool.baseToken, poolReserve.quoteTotalAmount.divPrice(price));

        int256 ratio;
        int256 adjustment;
        if (openInterest.tracker != 0) {
            uint256 equilibriumRange = uint256(fundingRateParams.equilibriumRange).toWad(FUNDING_RATE_CONFIG_DECIMALS);
            int256 lowGrowthRate = int256(fundingRateParams.lowGrowthRate).toWad(FUNDING_RATE_CONFIG_DECIMALS);
            int256 highGrowthRate = int256(fundingRateParams.highGrowthRate).toWad(FUNDING_RATE_CONFIG_DECIMALS);

            ratio = (openInterest.tracker * 1e18) / (baseTotal + quoteToBaseSize).toInt256();
            int256 growthRate = ratio.abs() <= equilibriumRange ? lowGrowthRate : highGrowthRate;
            adjustment = (((ratio * ratio) / 2) * growthRate) / (1e18 * 1e18);
        }

        int256 maxRate = int256(fundingRateParams.maxRate).toWad(FUNDING_RATE_CONFIG_DECIMALS);
        fundingRate = ratio >= 0 ? SignedMath.min(adjustment, maxRate) : SignedMath.max(-adjustment, -maxRate);
        fundingRate /= int256(86400 / uint256(fundingRateParams.epochDuration));
        return fundingRate.fromWad(Constants.FUNDING_RATE_DECIMALS);
    }

    /// @notice Calculate pending funding rate information for a pool
    /// @return epochs Number of epochs since last update
    /// @return lastEpochTime Last epoch timestamp
    /// @return lastTracker Last funding rate tracker value
    /// @return fundingRate Calculated funding rate
    function _pendingFundingRateInfo(
        PoolMetadata memory pool,
        uint256 price,
        uint64 duration
    ) internal view returns (uint64 epochs, uint64 lastEpochTime, int256 lastTracker, int256 fundingRate) {
        if (duration == 0) return (0, 0, 0, 0);

        uint64 previousEpochTime = _fundingRateData[pool.poolId].lastEpochTime;
        int256 previousTracker = _fundingRateData[pool.poolId].tracker;
        uint64 blockTime = uint64(block.timestamp);
        if (blockTime - previousEpochTime < duration) {
            return (0, previousEpochTime, previousTracker, 0);
        }

        fundingRate = _nextFundingRate(pool, price);
        epochs = (blockTime - previousEpochTime) / duration;
        lastTracker = previousTracker + (fundingRate * int256(uint256(epochs))).signedMulPrice(price);
        lastEpochTime = (blockTime / duration) * duration;
    }

    function _getPoolFundingRateParams(uint8 riskTier) internal view returns (IRiskParameter.FundingRateParams memory params) {
        return IRiskParameter(_getDependencyAddress(Identifier.RISK_PARAMETER)).getFundingRateParams(riskTier);
    }

    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }
}

