// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { PoolId } from "./../types/Types.sol";
import { BaseContractUpgradeable } from "./base/BaseContractUpgradeable.sol";

/// @title Emiter
/// @notice Central event emission contract for protocol events
contract Emiter is BaseContractUpgradeable, IEmiter {
    using EnumerableSetLib for EnumerableSetLib.Bytes32Set;

    uint256 public sequencer;

    mapping(uint256 blockNumber => bool emitted) private _blockHeaderEmitted;
    EnumerableSetLib.Bytes32Set private _allowedIdentifiers;

    error NotAllowedIdentifier();

    modifier ensureBlockHeader() {
        _ensureBlockHeader();
        _;
    }

    modifier ensureAllowedContract() {
        _ensureAllowedContract();
        _;
    }

    modifier ensurePool(PoolId poolId) {
        _ensurePool(poolId);
        _;
    }

    modifier onlyDependencyManager() {
        _onlyDependencyManager();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        bytes32[] memory identifiers = new bytes32[](1);
        identifiers[0] = Identifier.POOL_MANAGER;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    function registerContract(bytes32[] calldata identifiers) external onlyDependencyManager {
        _registerDependencies(identifiers);
        for (uint256 i = 0; i < identifiers.length; ++i) {
            _allowedIdentifiers.add(identifiers[i]);
        }
    }

    function isBlockHeaderEmitted(uint256 blockNumber) external view returns (bool) {
        return _blockHeaderEmitted[blockNumber];
    }

    function emitMarketCreated(MarketCreatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit MarketCreated(
            params.marketId,
            params.deployer,
            params.quoteToken,
            params.baseReserveRatio,
            params.quoteReserveRatio,
            params.oracleFeeUsd,
            params.boostFeeUsd,
            params.boostRefundFeeUsd,
            params.poolPrimeThreshold,
            params.executionFee,
            params.maxExecutionFee,
            params.forwardFee,
            params.maxForwardFee
        );
    }

    function emitPoolDeployed(PoolDeployedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolDeployed(
            params.marketId,
            params.poolId,
            params.deployer,
            params.baseToken,
            params.quoteToken,
            params.basePoolToken,
            params.quotePoolToken
        );
    }

    function emitPoolPrimed(PoolPrimedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolPrimed(params.poolId, params.baseToken, params.quoteToken, params.baseAmount, params.quoteAmount);
    }

    function emitPoolBoosted(PoolBoostedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolBoosted(params.poolId, params.proposer, params.token, params.amount);
    }

    function emitPoolUnboosted(PoolUnboostedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolUnboosted(params.poolId, params.proposer, params.token, params.refundFee);
    }

    function emitPoolReprimed(PoolReprimedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolReprimed(params.poolId, params.primer, params.token, params.amount);
    }

    function emitPoolTrenchFailed(PoolTrenchFailedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolTrenchFailed(params.poolId, params.remark);
    }

    function emitPoolActivated(PoolActivatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolActivated(params.poolId, params.baseToken, params.quoteToken, params.oracleType, params.oracleFeedId);
    }

    function emitPoolPreDeactivated(PoolPreDeactivatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolPreDeactivated(params.poolId, params.remark);
    }

    function emitPoolDeactivated(PoolDeactivatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolDeactivated(params.poolId, params.baseToken, params.quoteToken, params.remark);
    }

    function emitPoolDeposited(PoolDepositedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolDeposited(
            params.poolId,
            params.user,
            params.recipient,
            params.underlyingToken,
            params.poolToken,
            params.underlyingIn,
            params.poolTokenOut,
            params.oraclePrice,
            params.exchangeRate,
            params.poolTokenPrice
        );
    }

    function emitPoolWithdrawn(PoolWithdrawnParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolWithdrawn(
            params.poolId,
            params.user,
            params.recipient,
            params.underlyingToken,
            params.poolToken,
            params.poolTokenIn,
            params.underlyingOut,
            params.rebateOut,
            params.oraclePrice,
            params.exchangeRate,
            params.poolTokenPrice
        );
    }

    function emitLiquidityStopOrderCreated(LiquidityStopOrderCreatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit LiquidityStopOrderCreated(
            params.orderId,
            params.user,
            params.poolId,
            params.poolType,
            params.amount,
            params.triggerPrice,
            params.triggerType,
            params.minQuoteOut
        );
    }

    function emitLiquidityStopOrderCancelled(LiquidityStopOrderCancelledParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit LiquidityStopOrderCancelled(params.orderId, params.poolId, params.reason);
    }

    function emitLiquidityStopOrderExecuted(LiquidityStopOrderExecutedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit LiquidityStopOrderExecuted(params.orderId, params.poolId, params.executor, params.oraclePrice, params.poolTokenPrice);
    }

    function emitLiquidityMigrated(LiquidityMigratedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit LiquidityMigrated(params.user, params.fromPoolId, params.toPoolId, params.lpAmountIn, params.lpAmountOut);
    }

    function emitOrderPlaced(OrderPlacedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit OrderPlaced(
            params.broker,
            params.user,
            params.poolId,
            params.positionId,
            params.orderId,
            params.orderType,
            params.operation,
            params.direction,
            params.triggerType,
            params.collateralAmount,
            params.size,
            params.price,
            params.tif,
            params.postOnly,
            params.slippagePct,
            params.userLeverage
        );
    }

    function emitOrderFilled(OrderFilledParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit OrderFilled(
            params.broker,
            params.user,
            params.poolId,
            params.positionId,
            params.orderId,
            params.orderType,
            params.orderSize,
            params.fillSize,
            params.filledSize,
            params.orderPrice,
            params.fillPrice,
            params.realizedPnl,
            params.tradingFee,
            params.fundingFee,
            params.keeper
        );
    }

    function emitOrderCancelled(OrderCancelledParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit OrderCancelled(params.broker, params.user, params.poolId, params.orderId, params.remark);
    }

    function emitOrderUpdated(OrderUpdatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit OrderUpdated(
            params.broker,
            params.user,
            params.poolId,
            params.orderId,
            params.size,
            params.price,
            params.tpSize,
            params.tpPrice,
            params.slSize,
            params.slPrice
        );
    }

    function emitCollateralAdjusted(CollateralAdjustedParams calldata params) external ensurePool(params.poolId) ensureBlockHeader {
        emit CollateralAdjusted(
            params.user,
            params.poolId,
            params.positionId,
            params.direction,
            params.beforeCollateralAmount,
            params.afterCollateralAmount
        );
    }

    function emitOrderMarkedADL(OrderMarkedADLParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit OrderMarkedADL(params.broker, params.user, params.poolId, params.orderId, params.positionId);
    }

    function emitPositionNFTMinted(PositionNFTMintedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PositionNFTMinted(params.poolId, params.oldPositionId, params.newPositionId, params.tokenId, params.owner, params.recipient);
    }

    function emitPositionTransfer(PositionTransferParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PositionTransfer(params.from, params.to, params.positionId);
    }

    function emitPositionUpdated(PositionUpdatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PositionUpdated(
            params.broker,
            params.owner,
            params.positionId,
            params.poolId,
            params.direction,
            params.orderId,
            params.beforeSize,
            params.afterSize,
            params.beforeCollateralAmount,
            params.afterCollateralAmount,
            params.entryPrice,
            params.fundingRateIndex,
            params.riskTier,
            params.earlyClosePrice
        );
    }

    function emitFundingRateUpdated(FundingRateUpdatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit FundingRateUpdated(
            params.epochs,
            params.duration,
            params.previousEpochTime,
            params.lastEpochTime,
            params.poolId,
            params.fundingRate,
            params.fundingRateTracker,
            params.price
        );
    }

    function emitPoolFundingFeeSettled(PoolFundingFeeSettledParams calldata params) external ensurePool(params.poolId) ensureBlockHeader {
        emit PoolFundingFeeSettled(
            params.poolId,
            params.prevFundingRateTracker,
            params.nextFundingRateTracker,
            params.price,
            params.direction,
            params.positionSize,
            params.fundingFee
        );
    }

    function emitPoolFundDistributed(PoolFundDistributedParams calldata params) external ensurePool(params.poolId) ensureBlockHeader {
        emit PoolFundDistributed(
            params.poolId,
            params.profits,
            params.genesisProfits,
            params.basePoolAmount,
            params.quotePoolAmount,
            params.genesisBasePoolAmount,
            params.genesisQuotePoolAmount,
            params.exchangedBaseFromProfits,
            params.exchangedBaseAmount
        );
    }

    function emitCollateralAccepted(CollateralAcceptedParams calldata params) external ensurePool(params.poolId) ensureBlockHeader {
        emit CollateralAccepted(
            params.poolId,
            params.quoteDebt,
            params.baseCollateral,
            params.quoteCollateral,
            params.redeemable,
            params.totalQuoteDebt,
            params.totalBaseCollateral
        );
    }

    function emitUserFeeSettlementAndDistributed(
        UserFeeSettlementAndDistributedParams calldata params
    ) external ensurePool(params.poolId) ensureBlockHeader {
        emit UserSettlementRecorded(
            params.user,
            params.poolId,
            params.orderId,
            params.charge,
            params.realizedPnl,
            params.tradingFee,
            params.fundingFee
        );
        emit FeeDistributed(
            params.user,
            params.orderId,
            params.poolId,
            params.tradingFeeRate,
            params.isMaker,
            params.tradingFee,
            params.baseTradingFee,
            params.brokerTradingFee,
            params.broker,
            params.referralRebate,
            params.referrerRebate,
            params.referrer,
            params.reserveFee
        );
    }

    function emitPoolSettlementRecorded(PoolSettlementRecordedParams calldata params) external ensurePool(params.poolId) ensureBlockHeader {
        emit PoolSettlementRecorded(params.poolId, params.orderId, params.poolEntryPrice, params.realizedPnl);
    }

    function emitPositionLiquidated(PositionLiquidatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PositionLiquidated(
            params.broker,
            params.user,
            params.poolId,
            params.positionId,
            params.orderId,
            params.positionSize,
            params.liquidationSize,
            params.liquidationPrice
        );
    }

    function emitExecutionMatched(ExecutionMatchedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit ExecutionMatched(params.poolId, params.triggerOrderIds, params.matchedOrderIds, params.matchType, params.price);
    }

    function emitReserveRebateCollected(ReserveRebateCollectedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit ReserveRebateCollected(
            params.poolId,
            params.token,
            params.amount,
            params.keeper,
            params.poolAmount,
            params.stakingAmount,
            params.keeperAmount,
            params.treasuryAmount,
            params.reservedAmount,
            params.ecoFundAmount
        );
    }

    function emitReserveRebateDisbursed(ReserveRebateDisbursedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit ReserveRebateDisbursed(
            params.poolId,
            params.token,
            params.amount,
            params.keeper,
            params.poolAmount,
            params.stakingAmount,
            params.keeperAmount,
            params.treasuryAmount,
            params.reservedAmount,
            params.ecoFundAmount
        );
    }

    function emitTradingFeeTierUpdated(TradingFeeTierUpdatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit TradingFeeTierUpdated(
            params.broker,
            params.feeType,
            params.assetClass,
            params.riskTier,
            params.feeTier,
            params.takerFeeRate,
            params.makerFeeRate,
            params.isEnabled
        );
    }

    function emitUserFeeDataUpdated(UserFeeDataUpdatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit UserFeeDataUpdated(
            params.broker,
            params.signer,
            params.user,
            params.tier,
            params.referrer,
            params.totalReferralRebatePct,
            params.referrerRebatePct,
            params.expiry
        );
    }

    function emitBrokerCreated(BrokerCreatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit BrokerCreated(params.broker, params.beacon, params.name, params.assetClasses, params.baseFeeRates);
    }

    function emitUserSpecialFeeTierUpdated(UserSpecialFeeTierUpdatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit UserSpecialFeeTierUpdated(params.broker, params.user, params.oldTier, params.newTier);
    }

    function emitReferralRebateClaimed(ReferralRebateClaimedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit ReferralRebateClaimed(params.user, params.token, params.amount);
    }

    function emitPoolRebateClaimed(PoolRebateClaimedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PoolRebateClaimed(params.poolId, params.user, params.recipient, params.amount);
    }

    function emitExchanged(ExchangedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit Exchanged(params.user, params.source, params.target, params.sourceAmount, params.targetAmount, params.price);
    }

    function emitPositionEarlyClosed(PositionEarlyClosedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PositionEarlyClosed(
            params.poolId,
            params.positionId,
            params.orderId,
            params.broker,
            params.user,
            params.positionSize,
            params.executeSize,
            params.executePrice
        );
    }

    function emitPositionForceClosed(PositionForceClosedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PositionForceClosed(
            params.poolId,
            params.positionId,
            params.orderId,
            params.broker,
            params.user,
            params.positionSize,
            params.executePrice,
            params.reason
        );
    }

    function emitPositionRiskControlClosed(PositionRiskControlClosedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit PositionRiskControlClosed(
            params.poolId,
            params.positionId,
            params.orderId,
            params.broker,
            params.user,
            params.positionSize,
            params.executePrice,
            params.reason
        );
    }

    function emitLiquidityLockUpdated(LiquidityLockUpdatedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit LiquidityLockUpdated(params.poolId, params.windowAnchor, params.priceFloor, params.priceCeiling, params.openInterest);
    }

    function emitPositionRiskControlDataUpdated(
        PositionRiskControlDataUpdatedParams calldata params
    ) external ensureAllowedContract ensureBlockHeader {
        emit PositionRiskControlDataUpdated(params.poolId, params.positionId, params.freeAmount, params.lockedAmount);
    }

    function emitPositionRiskControlDataMigrated(
        PositionRiskControlDataMigratedParams calldata params
    ) external ensureAllowedContract ensureBlockHeader {
        emit PositionRiskControlDataMigrated(params.from, params.to, params.fromId, params.toId);
    }

    function emitProfitLockReleased(ProfitLockReleasedParams calldata params) external ensureAllowedContract ensureBlockHeader {
        emit ProfitLockReleased(params.poolId, params.account, params.baseAmount, params.quoteAmount, params.positionIds);
    }

    function emitEnterDispute(PoolId poolId, uint256 caseNumber) external ensureAllowedContract ensureBlockHeader {
        emit EnterDispute(poolId, caseNumber);
    }

    function emitExitDispute(PoolId poolId, uint256 caseNumber) external ensureAllowedContract ensureBlockHeader {
        emit ExitDispute(poolId, caseNumber);
    }

    function emitPoolReserveChanged(PoolReserveChangedParams calldata params) external ensurePool(params.poolId) ensureBlockHeader {
        emit PoolReserveChanged(
            params.poolId,
            params.baseAmountDelta,
            params.quoteAmountDelta,
            params.baseTotalAmount,
            params.baseReservedAmount,
            params.quoteTotalAmount,
            params.quoteReservedAmount
        );
    }

    function _getBlockNumber() internal view returns (uint256 blockNumber) {
        // On Arbitrum, use ArbSys to get the correct L2 block number
        if (block.chainid == 42161 || block.chainid == 421614) {
            blockNumber = IArbSys(0x0000000000000000000000000000000000000064).arbBlockNumber();
        } else {
            blockNumber = block.number;
        }
    }

    function _emitBlockHeader(uint256 blockNumber) private {
        uint256 currentSequence = ++sequencer;
        _blockHeaderEmitted[blockNumber] = true;

        emit BlockHeader(blockNumber, block.timestamp, currentSequence);
    }

    function _ensureBlockHeader() internal {
        uint256 blockNumber = _getBlockNumber();
        if (!_blockHeaderEmitted[blockNumber]) {
            _emitBlockHeader(blockNumber);
        }
    }

    function _ensureAllowedContract() internal view {
        bytes32 identifier = _getAddressManager().getIdentifier(msg.sender);
        require(_allowedIdentifiers.contains(identifier), NotAllowedIdentifier());
    }

    function _ensurePool(PoolId poolId) internal view {
        require(_getPoolManager().isPoolAddress(poolId, msg.sender), NotAllowedIdentifier());
    }

    function _onlyDependencyManager() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isDependencyManager(msg.sender), NotDependencyManager());
    }

    function _getPoolManager() private view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }
}

interface IArbSys {
    function arbBlockNumber() external view returns (uint256);
}

