// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

/* solhint-disable no-unused-import */
// forge-lint: disable-start
import { AssetClass } from "./AssetClass.sol";
import { Constants } from "./Constants.sol";
import { CaseState, BondState, VotingOption, Resolution } from "./CourtTypes.sol";
import { Errors } from "./Errors.sol";
import { MarketMetadata, PoolMetadata, OrderMetadata, OrderTPSLData, PositionMetadata } from "./Metadata.sol";
import { OrderTypes } from "./OrderTypes.sol";
import { PositionKey, NFTPositionKey } from "./PositionKey.sol";
/* solhint-enable no-unused-import */
// forge-lint: disable-end

/// @notice Order ID type
type OrderId is uint256;
/// @notice Market ID type
type MarketId is bytes32;
/// @notice Pool ID type
type PoolId is bytes32;
/// @notice Position ID type
type PositionId is bytes32;
/// @notice Case ID type
type CaseId is uint256;
/// @notice Transaction ID type
type TxId is bytes32;

/// @notice Pool type (base or quote)
enum PoolType {
    Base,
    Quote
}

/// @notice Pool state (cook, primed, trench, pre-bench, bench)
enum PoolState {
    Cook,
    Boosted,
    Primed,
    Trench,
    PreBench,
    Bench
}

/// @notice Oracle type (none, chainlink, Pyth)
enum OracleType {
    None,
    Chainlink,
    Pyth
}

/// @notice Oracle fee state (none, charged, sold out)
enum OracleFeeState {
    None,
    Charged,
    SoldOut
}

/// @notice Order type (market, limit, stop, conditional)
enum OrderType {
    // Execute immediately at market price
    Market,
    // Execute when price reaches limit
    Limit,
    // Take-profit or Stop-loss order
    Stop,
    // Conditional order with triggers
    Conditional
}

/// @notice Trigger type for conditional orders
enum TriggerType {
    // No trigger condition
    None,
    // Greater than or equal to trigger price
    GTE,
    // Less than or equal to trigger price
    LTE
}

/// @notice Position operation type
enum Operation {
    // Add to existing position or open new
    Increase,
    // Reduce or close existing position
    Decrease
}

/// @notice Trading direction
enum Direction {
    // Buy/long position
    Long,
    // Sell/short position
    Short
}

/// @notice Time in force for orders
enum TimeInForce {
    // Immediate or Cancel
    IOC
}

/// @notice Fee type (base, add-on, special)
enum FeeType {
    // Base fee
    BaseFee,
    // Add-on fee
    AddOnFee,
    // Special fee
    SpecialFee
}

/// @notice Type of trade matching
enum MatchType {
    // Normal trader vs trader matching
    Match,
    // Trade against pool liquidity
    Pool,
    // Auto-deleveraging
    ADL,
    // Liquidation execution
    Liquidation,
    // Liquidation with ADL
    LiquidationADL,
    // Early position closure
    EarlyClose
}

/// @notice Position open interest change type
enum PositionOIChange {
    // Increase long open interest
    IncreaseLong,
    // Decrease long open interest
    DecreaseLong,
    // Increase short open interest
    IncreaseShort,
    // Decrease short open interest
    DecreaseShort,
    // Convert long to short position
    FlipLongToShort,
    // Convert short to long position
    FlipShortToLong
}

