// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IAccount } from "./interfaces/IAccount.sol";
import { IBroker } from "./interfaces/IBroker.sol";
import { IEmiter } from "./interfaces/IEmiter.sol";
import { IExchangeCallback } from "./interfaces/IExchangeCallback.sol";
import { IFundingRate } from "./interfaces/IFundingRate.sol";
import { IKeeperRegistry } from "./interfaces/IKeeperRegistry.sol";
import { IOracle } from "./interfaces/IOracle.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IPoolVault } from "./interfaces/IPoolVault.sol";
import { IPositionManager } from "./interfaces/IPositionManager.sol";
import { IReservePool } from "./interfaces/IReservePool.sol";
import { IRiskController } from "./interfaces/IRiskController.sol";
import { IRiskParameter } from "./interfaces/IRiskParameter.sol";
import { ITradingVault } from "./interfaces/ITradingVault.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { LibPositionMetadata } from "./libraries/Position.sol";
import { PositionHelper } from "./libraries/PositionHelper.sol";
import { TradingHelper } from "./libraries/TradingHelper.sol";
import { BaseContract } from "./misc/base/BaseContract.sol";
import {
    Constants,
    Errors,
    PoolMetadata,
    PoolId,
    PositionId,
    OrderId,
    PositionMetadata,
    Direction,
    Operation,
    PositionOIChange
} from "./types/Types.sol";
import { PrecisionUtils } from "./utils/PrecisionUtils.sol";
/// @title TradingVault
/// @notice Manages trading collateral and position settlements
contract TradingVault is BaseContract, ReentrancyGuardUpgradeable, ITradingVault {
    using SafeERC20 for IERC20;
    using SignedMath for int256;
    using PrecisionUtils for uint256;
    using LibPositionMetadata for PositionMetadata;
    using SafeCast for uint256;

    /// @notice Pool ID that this trading vault manages
    PoolId public poolId;
    /// @notice Base token address for this pool
    address public baseToken;
    /// @notice Quote token address for this pool
    address public quoteToken;

    /// @notice Pending profits awaiting distribution to pool vault
    PoolProfit private _pendingPoolProfitData;

    /// @notice Position collateral amounts by position ID
    mapping(PositionId positionId => uint256 collateralAmount) private _positionCollaterals;
    /// @notice Current debt information
    DebtInfo private _debtInfo;

    /// @notice Emitted when base collateral is exchanged
    event BaseCollateralExchanged(PoolId poolId, uint256 quoteIn, uint256 baseOut, uint256 oraclePrice, address recipient);
    /// @notice Emitted when pool profit is exchanged
    event PoolProfitExchanged(PoolId poolId, uint256 baseIn, uint256 quoteOut, uint256 oraclePrice, address recipient);

    /// @notice Thrown when base profit exceeds maximum allowed
    error ExceedMaxBaseProfit();
    /// @notice Thrown when insufficient pool profit for operation
    error InsufficientPoolProfit();
    /// @notice Thrown when exchange amount exceeds exchangeable amount
    error ExceedExchangeable();
    /// @notice Thrown when amount exceeds total debt
    error ExceedDebt(uint256 totalDebt, uint256 amount);
    /// @notice Thrown when amount exceeds base collateral
    error ExceedBaseCollateral(uint256 baseCollateral, uint256 amount);
    error NotEligibleForLiquidation();

    modifier onlyPositionManager() {
        _onlyPositionManager();
        _;
    }

    modifier onlyPoolVault() {
        _onlyPoolVault();
        _;
    }

    modifier onlyFundingRate() {
        _onlyFundingRate();
        _;
    }

    modifier onlyTradingRouter() {
        _onlyTradingRouter();
        _;
    }

    modifier onlyPool() {
        _onlyPool();
        _;
    }

    modifier onlyKeeperOrReservePool() {
        _onlyKeeperOrReservePool();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the trading vault contract
    /// @param addressManager Address manager contract address
    /// @param _poolId Pool ID this vault will manage
    /// @param _baseToken Base token address
    /// @param _quoteToken Quote token address
    function initialize(address addressManager, PoolId _poolId, address _baseToken, address _quoteToken) external initializer {
        __ReentrancyGuard_init();

        bytes32[] memory identifiers = new bytes32[](13);
        identifiers[0] = Identifier.POSITION_MANAGER;
        identifiers[1] = Identifier.POOL_MANAGER;
        identifiers[2] = Identifier.FUNDING_RATE;
        identifiers[3] = Identifier.RISK_PARAMETER;
        identifiers[4] = Identifier.EMITER;
        identifiers[5] = Identifier.ORACLE;
        identifiers[6] = Identifier.RESERVE_POOL;
        identifiers[7] = Identifier.RISK_CONTROLLER;
        identifiers[8] = Identifier.ACCOUNT;
        identifiers[9] = Identifier.TRADING_ROUTER;
        identifiers[10] = Identifier.BASE_POOL;
        identifiers[11] = Identifier.QUOTE_POOL;
        identifiers[12] = Identifier.KEEPER_REGISTRY;
        __BaseContract_init(addressManager, identifiers);

        poolId = _poolId;
        baseToken = _baseToken;
        quoteToken = _quoteToken;
    }

    /// @inheritdoc ITradingVault
    function getPositionCollateralAmount(PositionId positionId) external view override returns (uint256) {
        return _positionCollaterals[positionId];
    }

    /// @inheritdoc ITradingVault
    function debtInfo() external view override returns (DebtInfo memory) {
        return _debtInfo;
    }

    /// @inheritdoc ITradingVault
    function getExchangeableBaseCollateral(uint256 price) external view override returns (uint256 quoteIn, uint256 baseOut) {
        return _exchangeableBaseCollateral(price);
    }

    /// @inheritdoc ITradingVault
    function previewExchangeableBaseCollateral() external view override returns (uint256 quoteIn, uint256 baseOut) {
        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);
        return _exchangeableBaseCollateral(oraclePrice);
    }

    /// @inheritdoc ITradingVault
    function pendingPoolProfit() external view override returns (PoolProfit memory) {
        return _pendingPoolProfitData;
    }

    /// @inheritdoc ITradingVault
    function getExchangeableBaseProfit(uint256 price) external view override returns (uint256 baseIn, uint256 quoteOut) {
        return _exchangeableBaseProfit(price);
    }

    /// @inheritdoc ITradingVault
    function previewExchangeableBaseProfit() external view override returns (uint256 baseIn, uint256 quoteOut) {
        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);
        return _exchangeableBaseProfit(oraclePrice);
    }

    /// @inheritdoc ITradingVault
    function settlePoolFundingFee(
        uint256 price,
        int256 prevFundingRateTracker,
        int256 nextFundingRateTracker
    ) external override onlyFundingRate returns (uint256 poolFundingFee) {
        IPositionManager.OITracker memory oiTracker = _getPositionManager().getOITracker(poolId);
        int256 positionTracker = oiTracker.tracker;
        if (positionTracker == 0) return 0;

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        int256 accruedFundingTracker = nextFundingRateTracker - prevFundingRateTracker;
        uint256 poolPositionSize = positionTracker.abs();
        Direction direction = positionTracker > 0 ? Direction.Short : Direction.Long;
        int256 fundingFee = TradingHelper.calculateFundingFee(pool, accruedFundingTracker, poolPositionSize, direction);
        // pool funding fee will not be negative, only a defensive measure.
        require(fundingFee >= 0, Errors.PoolFundingFeeNotPositive());

        poolFundingFee = uint256(fundingFee);
        _pendingPoolProfitData.profits += poolFundingFee;

        _getEmiter().emitPoolFundingFeeSettled(
            IEmiter.PoolFundingFeeSettledParams({
                poolId: poolId,
                prevFundingRateTracker: prevFundingRateTracker,
                nextFundingRateTracker: nextFundingRateTracker,
                price: price,
                direction: direction,
                positionSize: poolPositionSize,
                fundingFee: poolFundingFee
            })
        );
    }

    /// @inheritdoc ITradingVault
    function chargeUserFees(
        ChargeUserFeesParams calldata params
    ) external override onlyPositionManager returns (int256 tradingFee, int256 fundingFee, int256 realizedPnl, int256 charge) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        PositionMetadata memory position = _getPositionManager().getPosition(params.positionId);
        IRiskParameter.RiskParamData memory riskParams = _getRiskParameter().getRiskParamData(position.riskTier);

        uint256 baseTradingFee;
        bool isMaker;
        int32 tradingFeeRate;
        (tradingFee, baseTradingFee, isMaker, tradingFeeRate) = _calculateTradingFee(
            pool,
            position.riskTier,
            riskParams,
            params.owner,
            position.broker,
            params.change,
            params.executeSize,
            params.executePrice
        );
        fundingFee = _calculateFundingFee(pool, position, params.executePrice);
        realizedPnl = params.operation == Operation.Decrease ? position.calculatePnl(pool, params.executeSize, params.executePrice) : int256(0);

        int256 chargeCollateral = fundingFee + realizedPnl - tradingFee;
        charge = params.isLiquidation ?  -int256(_positionCollaterals[params.positionId]) : chargeCollateral;
        _chargeCollateral(params.positionId, chargeCollateral);

        uint256 brokerFee;
        uint256 totalReferralRebate;
        uint256 referrerRebate;
        address referrer;
        int256 reserveFee;
        if (tradingFee > 0) {
            brokerFee = uint256(tradingFee) - baseTradingFee;
            IERC20(pool.quoteToken).safeTransfer(position.broker, brokerFee);
            (totalReferralRebate, referrerRebate, referrer) = IBroker(position.broker).onBrokerFee(
                pool.poolId,
                params.owner,
                pool.quoteToken,
                brokerFee
            );
            reserveFee = int256(baseTradingFee);
            _distributeTradingFee(pool, riskParams, baseTradingFee, params.keeper, params.isMatchExecution);
        } else {
            if (params.isMatchExecution) revert Errors.MatchNotSupported();
            reserveFee = tradingFee;
            IReservePool reservePool = _getReservePool();
            uint256 poolRebate = reservePool.disburse(poolId, pool.quoteToken, tradingFee.abs(), params.keeper);
            _expendPoolProfit(pool, poolRebate, params.executePrice);
        }

        _getEmiter().emitUserFeeSettlementAndDistributed(
            IEmiter.UserFeeSettlementAndDistributedParams({
                user: params.owner,
                poolId: poolId,
                orderId: params.orderId,
                charge: charge,
                tradingFee: tradingFee,
                fundingFee: fundingFee,
                realizedPnl: realizedPnl,
                tradingFeeRate: tradingFeeRate,
                isMaker: isMaker,
                baseTradingFee: baseTradingFee,
                brokerTradingFee: brokerFee,
                broker: position.broker,
                referralRebate: totalReferralRebate,
                referrerRebate: referrerRebate,
                referrer: referrer,
                reserveFee: reserveFee
            })
        );
    }

    /// @inheritdoc ITradingVault
    function chargePositionFees(PositionId positionId, address feeToken, uint256 feeAmount, address receiver) external override onlyTradingRouter {
        _chargeCollateral(positionId, -int256(feeAmount));
        IERC20(feeToken).safeTransfer(receiver, feeAmount);
    }

    /// @inheritdoc ITradingVault
    function settlePoolPNL(
        OrderId orderId,
        uint256 executeSize,
        uint256 executePrice,
        bool isLong,
        uint256 poolEntryPrice
    ) external override onlyPositionManager returns (int256 realizedPnl) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        realizedPnl = TradingHelper.calculatePNL(pool, poolEntryPrice, executePrice, executeSize, isLong);
        uint256 pnlAmount = realizedPnl.abs();
        if (realizedPnl > 0) {
            _pendingPoolProfitData.profits += pnlAmount;
        } else if (realizedPnl < 0) {
            _expendPoolProfit(pool, pnlAmount, executePrice);
        }

        _getEmiter().emitPoolSettlementRecorded(
            IEmiter.PoolSettlementRecordedParams({ poolId: poolId, orderId: orderId, poolEntryPrice: poolEntryPrice, realizedPnl: realizedPnl })
        );
    }

    /// @inheritdoc ITradingVault
    function depositCollateral(
        PositionId positionId,
        OrderId orderId,
        address owner,
        uint256 collateralAmount
    ) external override onlyPositionManager {
        _depositCollateralFromAccount(positionId, orderId, owner, collateralAmount);
    }

    /// @inheritdoc ITradingVault
    function adjustPositionCollateral(
        PoolMetadata memory pool,
        PositionMetadata memory position,
        PositionId positionId,
        address owner,
        int256 adjustAmount
    ) external override onlyPositionManager {
        IFundingRate fundingRate = _getFundingRate();
        IPositionManager positionManager = _getPositionManager();
        IPoolManager poolManager = _getPoolManager();
        ITradingVault tradingVault = ITradingVault(address(this));

        uint256 oraclePrice = IOracle(_getDependencyAddress(Identifier.ORACLE)).safeOraclePrice(position.poolId);
        IRiskParameter.PoolConfigParams memory poolConfig = _getRiskParameter().getPoolConfigParams(position.riskTier);

        uint256 beforeCollateral = _positionCollaterals[positionId];
        if (adjustAmount > 0) {
            _depositCollateralFromAccount(positionId, OrderId.wrap(0), owner, uint256(adjustAmount));
        } else {
            uint256 freeCollateralAmount = _getRiskController().getPositionRiskControlData(positionId).freeAmount;
            require(freeCollateralAmount >= adjustAmount.abs(), Errors.InsufficientCollateral(positionId, freeCollateralAmount));
            _withdrawCollateral(positionId, owner, adjustAmount.abs());

            require(
                PositionHelper.checkLeverageHealthy(
                    position,
                    fundingRate,
                    tradingVault,
                    poolManager,
                    positionManager,
                    poolConfig,
                    pool,
                    positionId,
                    oraclePrice,
                    owner
                ),
                Errors.ExceedMaxLeverage(positionId)
            );
        }
        uint256 afterCollateral = _positionCollaterals[positionId];

        (bool isHealthy, uint256 marginRatio) = PositionHelper.checkPositionHealthy(
            position,
            fundingRate,
            tradingVault,
            poolManager,
            positionManager,
            poolConfig,
            pool,
            positionId,
            oraclePrice,
            owner
        );
        require(isHealthy, Errors.PositionNotHealthy(positionId, marginRatio));

        IEmiter(_getDependencyAddress(Identifier.EMITER)).emitCollateralAdjusted(
            IEmiter.CollateralAdjustedParams({
                user: owner,
                poolId: position.poolId,
                positionId: positionId,
                direction: position.direction,
                beforeCollateralAmount: beforeCollateral,
                afterCollateralAmount: afterCollateral
            })
        );
    }

    /// @inheritdoc ITradingVault
    function migratePositionCollateral(PositionId from, PositionId to) external override onlyPositionManager {
        require(_positionCollaterals[to] == 0, Errors.AlreadyMigrated(from, to));

        _positionCollaterals[to] = _positionCollaterals[from];
        delete _positionCollaterals[from];
    }

    /// @inheritdoc ITradingVault
    function disburseCollateral(
        PositionId positionId,
        uint256 collateralAmount,
        uint256 price,
        bool isLiquidation
    ) external override onlyPositionManager returns (uint256 returnBaseAmount, uint256 returnQuoteAmount) {
        require(_positionCollaterals[positionId] >= collateralAmount, Errors.InsufficientCollateral(positionId, collateralAmount));

        _positionCollaterals[positionId] -= collateralAmount;

        IReservePool reservePool = _getReservePool();
        uint256 quoteBalance = IERC20(quoteToken).balanceOf(address(this));
        uint256 genesisProfits = _pendingPoolProfitData.genesisProfits;
        if (quoteBalance > genesisProfits) {
            returnQuoteAmount = Math.min(collateralAmount, quoteBalance - genesisProfits);
            if (returnQuoteAmount > 0) {
                _disburseToken(reservePool, quoteToken, returnQuoteAmount, isLiquidation);
            }
        }

        if (returnQuoteAmount < collateralAmount) {
            uint256 shortfall = collateralAmount - returnQuoteAmount;
            returnBaseAmount = TradingHelper.convertTokenAmount(quoteToken, baseToken, shortfall.divPrice(price));
            _disburseToken(reservePool, baseToken, returnBaseAmount, isLiquidation);

            _debtInfo.totalDebt -= shortfall;
            _debtInfo.baseCollateral -= returnBaseAmount;
            _redeemCollateral();
        }
    }

    /// @inheritdoc ITradingVault
    function acceptCollateral(uint256 debt, uint256 baseCollateral, uint256 quoteCollateral, uint256 redeemable) external override onlyPoolVault {
        if (baseCollateral > 0) IERC20(baseToken).safeTransferFrom(msg.sender, address(this), baseCollateral);
        IERC20(quoteToken).safeTransferFrom(msg.sender, address(this), quoteCollateral);

        _debtInfo.totalDebt += debt;
        if (baseCollateral > 0) _debtInfo.baseCollateral += baseCollateral;
        if (redeemable > 0) _redeemCollateral(redeemable);

        IEmiter(_getDependencyAddress(Identifier.EMITER)).emitCollateralAccepted(
            IEmiter.CollateralAcceptedParams({
                poolId: poolId,
                quoteDebt: debt,
                baseCollateral: baseCollateral,
                quoteCollateral: quoteCollateral,
                redeemable: redeemable,
                totalQuoteDebt: _debtInfo.totalDebt,
                totalBaseCollateral: _debtInfo.baseCollateral
            })
        );
    }

    /// @inheritdoc ITradingVault
    function repayCollateral(uint256 amount, uint256 /* price */) external override onlyPoolVault {
        DebtInfo memory debt = _debtInfo;
        require(debt.totalDebt >= amount, ExceedDebt(debt.totalDebt, amount));

        IERC20(quoteToken).safeTransferFrom(msg.sender, address(this), amount);
        _debtInfo.totalDebt -= amount;

        _redeemCollateral();
    }

    /// @inheritdoc ITradingVault
    function repayCollateralTo() external override onlyKeeperOrReservePool {
        uint256 price = _getOracle().safeOraclePrice(poolId);
        DebtInfo memory debt = _debtInfo;

        uint256 collateralValue = TradingHelper.convertTokenAmount(baseToken, quoteToken, debt.baseCollateral.mulPrice(price));
        require(collateralValue <= debt.totalDebt, NotEligibleForLiquidation());

        IERC20(quoteToken).safeTransferFrom(msg.sender, address(this), debt.totalDebt);

        _debtInfo.totalDebt = 0;
        _redeemCollateralTo(msg.sender);
    }

    /// @inheritdoc ITradingVault
    function distributePoolProfit(uint256 oraclePrice) external override onlyPool {
        PoolProfit memory profit = _pendingPoolProfitData;
        if (profit.profits == 0 && profit.genesisProfits == 0) return;

        _pendingPoolProfitData.profits = 0;
        _pendingPoolProfitData.genesisProfits = 0;

        _distributePoolProfit(profit, oraclePrice, 0, 0);
    }

    function exchangeBaseProfit(
        uint256 baseIn,
        uint256 minQuoteOut,
        address recipient,
        bytes calldata data
    ) external override nonReentrant returns (uint256 quoteOut) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        require(pool.compoundEnabled, Errors.PoolNotCompoundable(poolId));

        PoolProfit memory profit = _pendingPoolProfitData;
        require(profit.profits > 0, ExceedMaxBaseProfit());

        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);
        uint256 baseProfits = _calculateBaseProfit(IPoolVault(pool.poolVault), profit, oraclePrice);

        IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);
        quoteOut = TradingHelper.convertTokenAmount(
            pool.baseToken,
            pool.quoteToken,
            baseIn.mulPrice(
                oraclePrice.mulPrecision(
                    Constants.INCENTIVE_RATE_PRECISION + poolRiskConfig.exchangeIncentiveRate,
                    Constants.INCENTIVE_RATE_PRECISION
                )
            )
        );
        require(quoteOut <= baseProfits, ExceedMaxBaseProfit());
        require(quoteOut >= minQuoteOut, Errors.ExceedMinOutputAmount());

        _pendingPoolProfitData.profits = 0;
        _pendingPoolProfitData.genesisProfits = 0;

        IERC20(pool.quoteToken).safeTransfer(recipient, quoteOut);

        uint256 balanceBefore = IERC20(pool.baseToken).balanceOf(address(this));
        IExchangeCallback(msg.sender).onExchange(poolId, pool.baseToken, baseIn, data);
        uint256 balanceAfter = IERC20(pool.baseToken).balanceOf(address(this));
        require(balanceAfter - balanceBefore == baseIn, Errors.InsufficientReturnAmount(baseIn, balanceAfter - balanceBefore));

        _distributePoolProfit(profit, oraclePrice, baseIn, quoteOut);

        emit PoolProfitExchanged(poolId, baseIn, quoteOut, oraclePrice, recipient);
    }

    /// @inheritdoc ITradingVault
    function exchangeBaseCollateral(
        uint256 quoteIn,
        uint256 minBaseOut,
        address recipient,
        bytes calldata data
    ) external override nonReentrant returns (uint256 baseOut) {
        DebtInfo memory debt = _debtInfo;
        require(debt.totalDebt >= quoteIn, ExceedExchangeable());

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);
        IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);

        baseOut = TradingHelper.convertTokenAmount(
            quoteToken,
            baseToken,
            quoteIn.divPrice(
                oraclePrice.mulPrecision(
                    Constants.INCENTIVE_RATE_PRECISION - poolRiskConfig.exchangeIncentiveRate,
                    Constants.INCENTIVE_RATE_PRECISION
                )
            )
        );
        require(baseOut >= minBaseOut, Errors.ExceedMinOutputAmount());
        require(debt.baseCollateral >= baseOut, ExceedBaseCollateral(debt.baseCollateral, baseOut));

        _debtInfo.totalDebt -= quoteIn;
        _debtInfo.baseCollateral -= baseOut;

        uint256 balanceBefore = IERC20(quoteToken).balanceOf(address(this));
        IExchangeCallback(msg.sender).onExchange(poolId, quoteToken, quoteIn, data);
        uint256 balanceAfter = IERC20(quoteToken).balanceOf(address(this));
        require(balanceAfter - balanceBefore == quoteIn, Errors.InsufficientReturnAmount(quoteIn, balanceAfter - balanceBefore));

        _redeemCollateral();
        IERC20(baseToken).safeTransfer(recipient, baseOut);

        emit BaseCollateralExchanged(poolId, quoteIn, baseOut, oraclePrice, recipient);
    }

    function _depositCollateralFromAccount(PositionId positionId, OrderId orderId, address from, uint256 collateralAmount) internal {
        (uint256 usedFreeAmount, uint256 usedRestrictedAmount) = _getAccount().payWithProfitFirst(
            poolId,
            orderId,
            from,
            quoteToken,
            collateralAmount
        );

        _getRiskController().recordPositionRiskControlData(positionId, poolId, from, int256(usedFreeAmount), int256(usedRestrictedAmount));
        _positionCollaterals[positionId] += collateralAmount;
    }

    function _withdrawCollateral(PositionId positionId, address owner, uint256 collateralAmount) internal {
        require(_positionCollaterals[positionId] >= collateralAmount, Errors.InsufficientCollateral(positionId, collateralAmount));
        uint256 balance = IERC20(quoteToken).balanceOf(address(this));
        require(balance >= collateralAmount, Errors.InsufficientBalance(address(this), balance, collateralAmount));

        _getRiskController().recordPositionRiskControlData(positionId, poolId, owner, -int256(collateralAmount), int256(0));
        _positionCollaterals[positionId] -= collateralAmount;

        IAccount account = _getAccount();
        IERC20(quoteToken).approve(address(account), collateralAmount);
        account.deposit(owner, quoteToken, collateralAmount);
    }

    function _chargeCollateral(PositionId positionId, int256 amount) internal {
        if (amount > 0) {
            _positionCollaterals[positionId] += amount.abs();
        } else {
            require(_positionCollaterals[positionId] >= amount.abs(), Errors.InsufficientCollateral(positionId, amount.abs()));
            _positionCollaterals[positionId] -= amount.abs();
        }
    }

    function _disburseToken(IReservePool reservePool, address token, uint256 amount, bool isLiquidation) internal {
        if (isLiquidation) {
            if (IERC20(token).allowance(address(this), address(reservePool)) < amount) {
                IERC20(token).forceApprove(address(reservePool), type(uint256).max);
            }
            reservePool.depositRiskReserves(poolId, token, amount);
        } else {
            IERC20(token).forceApprove(address(_getAccount()), amount);
        }
    }

    function _distributePoolProfit(PoolProfit memory profit, uint256 price, uint256 exchangedBaseAmount, uint256 exchangedFromProfits) internal {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 profits = profit.profits;
        uint256 genesisProfits = profit.genesisProfits;

        if (exchangedBaseAmount > 0) IERC20(pool.baseToken).safeTransfer(pool.poolVault, exchangedBaseAmount);
        IERC20(pool.quoteToken).safeTransfer(pool.poolVault, profits + genesisProfits - exchangedFromProfits);
        IPoolVault(pool.poolVault).distribute(profits, genesisProfits, exchangedFromProfits, exchangedBaseAmount, price);
    }

    function _exchangeableBaseProfit(uint256 price) internal view returns (uint256 baseIn, uint256 quoteOut) {
        PoolProfit memory profit = _pendingPoolProfitData;
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        uint256 baseProfit = _calculateBaseProfit(IPoolVault(pool.poolVault), profit, price);
        if (baseProfit == 0) return (0, 0);

        IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);
        quoteOut = baseProfit;
        baseIn = TradingHelper.convertTokenAmount(
            pool.quoteToken,
            pool.baseToken,
            quoteOut.divPrice(
                price.mulPrecision(Constants.INCENTIVE_RATE_PRECISION + poolRiskConfig.exchangeIncentiveRate, Constants.INCENTIVE_RATE_PRECISION)
            )
        );
    }

    /// @notice Calculate exchangeable base collateral amounts
    /// @param price Current price for calculations
    /// @return quoteIn Quote amount that can be exchanged
    /// @return baseOut Base amount that can be received
    function _exchangeableBaseCollateral(uint256 price) internal view returns (uint256 quoteIn, uint256 baseOut) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        quoteIn = _debtInfo.totalDebt;
        if (quoteIn == 0) return (0, 0);

        IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);
        baseOut = TradingHelper.convertTokenAmount(
            quoteToken,
            baseToken,
            quoteIn.divPrice(
                price.mulPrecision(Constants.INCENTIVE_RATE_PRECISION - poolRiskConfig.exchangeIncentiveRate, Constants.INCENTIVE_RATE_PRECISION)
            )
        );
    }

    function _distributeTradingFee(
        PoolMetadata memory pool,
        IRiskParameter.RiskParamData memory riskParams,
        uint256 tradingFee,
        address keeper,
        bool isMatchExecution
    ) internal {
        if (tradingFee == 0) return;

        IReservePool reservePool = _getReservePool();
        if (IERC20(pool.quoteToken).allowance(address(this), address(reservePool)) < tradingFee) {
            IERC20(pool.quoteToken).forceApprove(address(reservePool), type(uint256).max);
        }

        if (isMatchExecution) {
            reservePool.collectToTreasury(poolId, pool.quoteToken, tradingFee);
        } else {
            uint256 poolRebate = reservePool.collect(poolId, pool.quoteToken, tradingFee, keeper);
            uint256 genesisRebate = (poolRebate * riskParams.poolConfigParams.genesisRebateRatio) / Constants.GENESIS_REBATE_RATIO_PRECISION;
            _pendingPoolProfitData.profits += (poolRebate - genesisRebate);
            _pendingPoolProfitData.genesisProfits += genesisRebate;
        }
    }

    /// @notice Expend pool profit to cover a required amount
    /// @dev If pool profits are insufficient, the shortfall is disbursed from pool vault
    /// @param pool Pool metadata
    /// @param amount Required amount to expend
    /// @param executePrice Execution price for vault disbursement
    function _expendPoolProfit(PoolMetadata memory pool, uint256 amount, uint256 executePrice) internal {
        if (amount == 0) return;

        uint256 availableProfit = _pendingPoolProfitData.profits;
        uint256 paid = availableProfit >= amount ? amount : availableProfit;
        uint256 shortfall = amount - paid;

        _pendingPoolProfitData.profits -= paid;

        if (shortfall > 0) IPoolVault(pool.poolVault).disburseToTradingVault(shortfall, executePrice);
    }

    /// @notice Transfer token to address
    /// @param token Token address to transfer
    /// @param to Recipient address
    /// @param amount Amount to transfer
    function _transferTokenTo(address token, address to, uint256 amount) internal {
        IERC20(token).safeTransfer(to, amount);
    }

    /// @notice Redeem collateral if debt is fully paid
    function _redeemCollateral() internal returns (uint256 returnCollateral) {
        if (_debtInfo.totalDebt == 0 && (returnCollateral = _debtInfo.baseCollateral) > 0) {
            _redeemCollateral(returnCollateral);
        }
    }

    function _redeemCollateralTo(address performer) internal returns (uint256 returnCollateral) {
        if (_debtInfo.totalDebt == 0 && (returnCollateral = _debtInfo.baseCollateral) > 0) {
            _debtInfo.baseCollateral = 0;
            _transferTokenTo(baseToken, performer, returnCollateral);
        }
    }

    function _redeemCollateral(uint256 redeemAmount) internal {
        require(_debtInfo.baseCollateral >= redeemAmount, Errors.InsufficientRedeemable());

        address poolVault = _getPoolManager().getPoolVault(poolId);
        _debtInfo.baseCollateral -= redeemAmount;
        IERC20(baseToken).forceApprove(poolVault, redeemAmount);
        IPoolVault(poolVault).redeemCollateral(redeemAmount);
    }

    function _calculateFundingFee(
        PoolMetadata memory pool,
        PositionMetadata memory position,
        uint256 price
    ) internal view returns (int256 fundingFee) {
        IFundingRate fundingRate = IFundingRate(_getDependencyAddress(Identifier.FUNDING_RATE));
        return position.pendingFundingFee(pool, fundingRate, price);
    }

    function _calculateTradingFee(
        PoolMetadata memory pool,
        uint8 riskTier,
        IRiskParameter.RiskParamData memory riskParams,
        address user,
        address broker,
        PositionOIChange change,
        uint256 executeSize,
        uint256 executePrice
    ) internal view returns (int256 tradingFee, uint256 baseFee, bool isMaker, int32 feeRate) {
        (uint32 takerFeeRate, int32 makerFeeRate, uint32 baseTakerFeeRate, uint32 baseMakerFeeRate) = IBroker(broker).getUserFeeRate(
            user,
            riskParams.poolConfigParams.assetClass,
            riskTier
        );

        isMaker = change == PositionOIChange.DecreaseLong || change == PositionOIChange.DecreaseShort;
        feeRate = isMaker ? makerFeeRate : int32(takerFeeRate);
        uint256 baseFeeRate = isMaker ? baseMakerFeeRate : baseTakerFeeRate;

        uint256 notional = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, executeSize.mulPrice(executePrice));
        uint256 tradingFeeAbs = notional.mulPrecision(int256(feeRate).abs(), Constants.TRADING_FEE_RATE_PRECISION);
        tradingFee = feeRate < 0 ? -tradingFeeAbs.toInt256() : tradingFeeAbs.toInt256();
        baseFee = notional.mulPrecision(baseFeeRate, Constants.TRADING_FEE_RATE_PRECISION);
    }

    function _calculateBaseProfit(IPoolVault poolVault, PoolProfit memory profit, uint256 price) internal view returns (uint256) {
        if (profit.profits == 0) return 0;

        (uint256 expectedBaseProfit, , ) = poolVault.splitPoolProfits(profit.profits, price);
        return expectedBaseProfit;
    }

    function _onlyPositionManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POSITION_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyFundingRate() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.FUNDING_RATE), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyTradingRouter() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.TRADING_ROUTER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyPool() internal view {
        require(
            msg.sender == _getDependencyAddress(Identifier.BASE_POOL) || msg.sender == _getDependencyAddress(Identifier.QUOTE_POOL),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _onlyPoolVault() internal view {
        require(msg.sender == _getPoolManager().getPoolVault(poolId), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyKeeperOrReservePool() internal view {
        require(
            msg.sender == _getDependencyAddress(Identifier.RESERVE_POOL) ||
                IKeeperRegistry(_getDependencyAddress(Identifier.KEEPER_REGISTRY)).isKeeper(msg.sender),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _getPositionManager() internal view returns (IPositionManager) {
        return IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getRiskParameter() internal view returns (IRiskParameter riskParameter) {
        return IRiskParameter(_getDependencyAddress(Identifier.RISK_PARAMETER));
    }

    function _getFundingRate() internal view returns (IFundingRate fundingRate) {
        return IFundingRate(_getDependencyAddress(Identifier.FUNDING_RATE));
    }

    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getOracle() internal view returns (IOracle oracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }

    function _getAccount() internal view returns (IAccount account) {
        return IAccount(_getDependencyAddress(Identifier.ACCOUNT));
    }

    function _getRiskController() internal view returns (IRiskController riskController) {
        return IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER));
    }

    function _getReservePool() internal view returns (IReservePool reservePool) {
        return IReservePool(_getDependencyAddress(Identifier.RESERVE_POOL));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }
}

