pragma solidity ^0.8.20;

import { CaseId, OrderId, MarketId, PoolId, PositionId, TriggerType } from "./Types.sol";

/// @title Errors
/// @notice Standard error definitions for the protocol
library Errors {
    error PermissionDenied(address caller, address target);

    error ExceedMinOutputAmount();

    error MarketNotExist(MarketId marketId);
    error PoolNotExist(PoolId poolId);
    error PoolExists(PoolId poolId);
    error PoolNotActive(PoolId poolId);
    error PoolNotCompoundable(PoolId poolId);
    error InvalidBaseToken();
    error InvalidQuoteToken();
    error DesignatedTokenMismatch(address collectToken, address designatedToken);

    error NotOrderOwner();
    error NotPositionOwner();

    error InvalidOrder(OrderId orderId);
    error InvalidOrderPair(OrderId triggerOrderId, OrderId matchedOrderId);
    error OrderExpired(OrderId orderId);
    error NotReachedPrice(OrderId orderId, uint256 marketPrice, uint256 triggerPrice, TriggerType triggerType);
    error MatchNotSupported();

    error InvalidPosition(PositionId positionId);
    error PositionRemainsHealthy(PositionId positionId);
    error InvalidADLPosition(OrderId orderId, PositionId positionId);

    error InsufficientBalance(address account, uint256 balance, uint256 needed);

    error OrderNotExist(OrderId orderId);
    error NoADLNeeded(OrderId orderId);
    error PositionNotHealthy(PositionId positionId, uint256 marginRatio);
    error UnhealthyAfterRiskTierApplied(PositionId positionId);
    error PositionNotInitialized(PositionId positionId);
    error InsufficientCollateral(PositionId positionId, uint256 totalCollateral);
    error ExceedMaxLeverage(PositionId positionId);
    error AlreadyMigrated(PositionId from, PositionId to);

    error NotActiveBroker(address broker);
    error NotForwardAllowedTarget(address from);

    error InsufficientOutputAmount();
    error InsufficientLiquidity(uint256 total, uint256 request, uint256 reserved);
    error NotMeetEarlyCloseCriteria(PositionId positionId);
    error PoolNotInPreBenchState(PoolId poolId);
    error TransferFailed();
    error InsufficientSize();
    error InvalidRewindPrice();
    error NoRebateToClaim();

    error MarketNotInitialized();
    error PoolNotInitialized();
    error StalePrice();
    error InvalidPrice();
    error ExceedMaxPriceDeviation();
    error ExcessiveSlippage();
    error PoolFundingFeeNotPositive();

    error InsufficientReturnAmount(uint256 expected, uint256 received);
    error ExceedMaxExchangeableAmount();
    error ConvertAmountMismatch(uint256 convertOut, uint256 exchangeUsed);
    error InvalidParameter();
    error ExceedMaxOrderCount();
    error InvalidTriggerType();
    error OnlyRelayer();
    error ExecutionFeeNotCollected();
    error MismatchExecuteFee(uint256 balanceBefore, uint256 balanceAfter, uint256 expected);

    error AccountInsufficientTradableAmount(uint256 accountTradableAmount, uint256 requiredTradableAmount);
    error AccountInsufficientFreeAmount();
    error AccountInsufficientReservedAmount();

    error InsufficientFreeCollateral(PositionId positionId, uint256 totalFreeCollateral);
    error InsufficientLockedCollateral(PositionId positionId, uint256 totalLockedCollateral);

    error InDisputeMode();
    error NotInDisputeMode();
    error NoActiveDispute();
    error UserProfitFrozen();
    error InvalidProfitLock();
    error PositionHasLockedAmount();

    error InvalidPoolToken();
    error DisputeNotAllowed();
    error UnexpectedCaseState();
    error UnexpectedCaseType();
    error RiskCloseNotAllowed();
    error RiskCloseNotCompleted();
    error AlreadyVoted();
    error CaseNotExist(CaseId caseId);
    error CaseDeadlineReached();
    error CaseDeadlineNotReached();
    error BondNotReleased();
    error BondZeroAmount();
    error CaseNotAccepted();
    error CaseAppealNotFinished();
    error NotCaseRespondent(CaseId caseId, address respondent);
    error CaseRespondentAppealed(CaseId caseId, address respondent);
    error UntrustfulVoting();
    error ResponseCountMismatch();
    error EthCallCountMismatch();
    error StaleEthCall();
    error InvalidSourceChain();
    error SignatureExpired();

    error TreeAlreadySet();
    error ReimbursementValidity(CaseId caseId);
    error AlreadyClaimed(CaseId caseId, address user);
    error AlreadyMinted();
    error InvalidProfitAmount();
    error InvalidAmount(CaseId caseId, address user);
    error MerkleTreeVerificationFailed(CaseId caseId, address user);

    error InsufficientRiskReserves();
    error InsufficientRedeemable();
}

