// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IBasePool } from "./../interfaces/IBasePool.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IExchangeCallback } from "./../interfaces/IExchangeCallback.sol";
import { IPoolToken } from "./../interfaces/IPoolToken.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { LibPoolMetadata } from "./../libraries/Pool.sol";
import { TradingHelper } from "./../libraries/TradingHelper.sol";
import { Constants, Errors, PoolMetadata, PoolId } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";
import { PoolBase } from "./PoolBase.sol";

/**
 * @title BasePool
 * @notice Base pool contract for handling base token liquidity provision and management
 * @dev This contract manages base token deposits/withdrawals, rebate distribution, and LP token minting/burning.
 * It supports profit distribution to liquidity providers through a rebate mechanism and handles exchange rates
 * for LP tokens based on the underlying base token reserves.
 */
contract BasePool is PoolBase, ReentrancyGuardUpgradeable, IBasePool {
    using SafeERC20 for IERC20;
    using LibPoolMetadata for PoolMetadata;
    using PrecisionUtils for uint256;
    using SignedMath for int256;

    // Mapping from pool ID to pool data containing rebate indices
    mapping(PoolId poolId => PoolData poolData) private _poolDatas;
    // Mapping from pool ID and user address to user-specific rebate data
    mapping(PoolId poolId => mapping(address account => UserData userData)) private _userDatas;

    /**
     * @notice Emitted when profits are distributed to the base pool
     * @param poolId The ID of the pool receiving the profit distribution
     * @param baseAmount Amount of base tokens distributed
     * @param quoteAmount Amount of quote tokens distributed
     * @param price Current oracle price used for distribution calculations
     * @param exchangeRate Current exchange rate of LP tokens to base tokens
     * @param rebateIndex Updated global rebate index for quote token rebates
     * @param genesisRebateIndex Updated global rebate index for genesis quote token rebates
     */
    event BasePoolProfitDistributed(
        PoolId indexed poolId,
        uint256 baseAmount,
        uint256 quoteAmount,
        uint256 price,
        uint256 exchangeRate,
        uint256 rebateIndex,
        uint256 genesisRebateIndex
    );

    event PoolRebateIndexUpdated(PoolId indexed poolId, uint256 unexchangedProfits, uint256 oldIndex, uint256 newIndex);

    event PoolProfitExchanged(PoolId indexed poolId, uint256 baseIn, uint256 quoteOut, uint256 price, address recipient);

    error ExceedMaxProfit();

    modifier onlyPoolVault(PoolId poolId) {
        _onlyPoolVault(poolId);
        _;
    }

    modifier onlyPoolManager() {
        _onlyPoolManager();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @inheritdoc IBasePool
    function initialize(address addressManager) external initializer {
        __ReentrancyGuard_init();
        __PoolBase_init(addressManager);
    }

    /// @inheritdoc IBasePool
    function getPoolData(PoolId poolId) external view override returns (PoolData memory) {
        return _poolDatas[poolId];
    }

    /// @inheritdoc IBasePool
    function getUserData(PoolId poolId, address user) external view override returns (UserData memory) {
        return _userDatas[poolId][user];
    }

    /// @inheritdoc IBasePool
    function previewLpAmountOut(PoolId poolId, uint256 baseAmountIn, uint256 price) external view returns (uint256) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 exchangeRate = _getExchangeRate(pool, poolId, price);
        return _getLpAmountOut(pool, baseAmountIn, exchangeRate);
    }

    /// @inheritdoc IBasePool
    function previewBaseAmountOut(PoolId poolId, uint256 lpAmountIn, uint256 price) external view returns (uint256) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 exchangeRate = _getExchangeRate(pool, poolId, price);
        return _getBaseAmountOut(pool, lpAmountIn, exchangeRate);
    }

    /// @inheritdoc IBasePool
    function withdrawableLpAmount(PoolId poolId, uint256 price) external view returns (uint256) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        IPoolVault.PoolReserve memory reserveInfo = IPoolVault(pool.poolVault).reserveInfo();

        uint256 withdrawableBase = reserveInfo.baseTotalAmount - reserveInfo.baseReservedAmount;
        uint256 exchangeRate = _getExchangeRate(pool, poolId, price);
        return _getLpAmountOut(pool, withdrawableBase, exchangeRate);
    }

    /// @inheritdoc IBasePool
    function previewUserWithdrawData(
        PoolId poolId,
        uint256 lpAmountIn,
        address user,
        uint256 price
    ) external view returns (uint256 baseAmountOut, uint256 rebateAmount) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 exchangeRate = _getExchangeRate(pool, poolId, price);
        (uint256 rebates, uint256 genesisRebates) = pendingUserRebates(poolId, user, price);
        return (_getBaseAmountOut(pool, lpAmountIn, exchangeRate), rebates + genesisRebates);
    }

    /// @inheritdoc IBasePool
    function pendingUserRebates(PoolId poolId, address user, uint256 price) public view override returns (uint256 rebates, uint256 genesisRebates) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        (uint256 _rebates, uint256 _genesisRebates) = _pendingUserBaseRebate(pool, poolId, price, user);
        UserData memory userData = _userDatas[poolId][user];

        rebates = userData.accrued + _rebates;
        genesisRebates = userData.genesisAccrued + _genesisRebates;
    }

    /// @inheritdoc IBasePool
    function getExchangeableProfit(PoolId poolId, uint256 price) external view override returns (uint256 baseIn, uint256 quoteOut) {
        return _exchangeableProfit(poolId, price);
    }

    /// @inheritdoc IBasePool
    function previewExchangeableProfit(PoolId poolId) external view override returns (uint256 baseIn, uint256 quoteOut) {
        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);
        return _exchangeableProfit(poolId, oraclePrice);
    }

    /// @inheritdoc IBasePool
    function deposit(
        PoolId poolId,
        uint256 amountIn,
        uint256 minAmountOut,
        address user,
        address recipient
    ) external override nonReentrant returns (uint256 amountOut) {
        require(user == msg.sender || _isLiquidityRouter(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));

        // Get pool metadata and validate deposit conditions
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        _validateDeposit(pool);

        uint256 oraclePrice;
        // Update pool and user data
        if (!pool.isCooked() && !pool.isPrimed() && !pool.isBoosted()) {
            oraclePrice = _getOracle().safeOraclePrice(poolId);
            _updatePool(pool, poolId, oraclePrice);
            _updateUserData(pool, poolId, recipient);
        }

        // Transfer base tokens from user to this contract
        IERC20 baseToken = IERC20(pool.baseToken);
        baseToken.safeTransferFrom(user, address(this), amountIn);

        IPoolVault.PoolReserve memory reserveInfo = IPoolVault(pool.poolVault).reserveInfo();
        // Calculate total reserve and exchange rate for LP token minting
        uint256 totalReserve = _currentTotalReserve(reserveInfo, pool, poolId, oraclePrice);
        uint256 exchangeRate = _calculateExchangeRate(pool, totalReserve);
        amountOut = _getLpAmountOut(pool, amountIn, exchangeRate);

        // Validate minimum output amount
        if (amountOut < minAmountOut) revert Errors.InsufficientOutputAmount();

        // Ensure sufficient allowance for pool vault
        if (baseToken.allowance(address(this), pool.poolVault) < amountIn) {
            baseToken.forceApprove(pool.poolVault, type(uint256).max);
        }
        // Deposit base tokens to pool vault
        IPoolVault(pool.poolVault).depositBaseToken(amountIn);
        // Mint LP tokens to recipient
        IPoolToken(pool.basePoolToken).mint(recipient, amountOut);

        _getEmiter().emitPoolDeposited(
            IEmiter.PoolDepositedParams({
                poolId: poolId,
                user: user,
                recipient: recipient,
                underlyingToken: pool.baseToken,
                poolToken: pool.basePoolToken,
                underlyingIn: amountIn,
                poolTokenOut: amountOut,
                oraclePrice: oraclePrice,
                exchangeRate: exchangeRate,
                poolTokenPrice: _computePoolTokenPrice(pool, poolId, exchangeRate, oraclePrice)
            })
        );
    }

    /// @inheritdoc IBasePool
    function withdraw(
        PoolId poolId,
        uint256 amountIn,
        uint256 minAmountOut,
        address user,
        address recipient
    ) external override nonReentrant returns (uint256 amountOut, uint256 rebateOut) {
        require(user == msg.sender || _isLiquidityRouter(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        uint256 oraclePrice;
        if (pool.isTrench() || pool.isPreBench()) {
            oraclePrice = _getOracle().safeOraclePrice(poolId);
            _updatePool(pool, poolId, oraclePrice);
            _updateUserData(pool, poolId, user);
        } else if (pool.isBench()) {
            _updateUserData(pool, poolId, user);
        }

        // Get current pool reserve information
        IPoolVault.PoolReserve memory reserveInfo = IPoolVault(pool.poolVault).reserveInfo();
        // Calculate total reserve and exchange rate for base token withdrawal
        uint256 totalReserve = _currentTotalReserve(reserveInfo, pool, poolId, oraclePrice);
        uint256 exchangeRate = _calculateExchangeRate(pool, totalReserve);
        uint256 lpSupply = IPoolToken(pool.basePoolToken).totalSupply();
        if (amountIn == lpSupply) {
            amountOut = reserveInfo.baseTotalAmount - reserveInfo.baseReservedAmount;
        } else {
            amountOut = _getBaseAmountOut(pool, amountIn, exchangeRate);
        }

        // Validate minimum output amount against the final amountOut.
        if (amountOut < minAmountOut) revert Errors.InsufficientOutputAmount();

        // Burn LP tokens from user and withdraw base tokens from vault
        IPoolToken(pool.basePoolToken).burnFrom(user, amountIn);
        IPoolVault(pool.poolVault).withdrawBaseToken(amountOut, recipient);

        // Calculate and transfer user rebates
        rebateOut = _claimUserRebates(pool, poolId, user, recipient);

        _getEmiter().emitPoolWithdrawn(
            IEmiter.PoolWithdrawnParams({
                poolId: poolId,
                user: user,
                recipient: recipient,
                underlyingToken: pool.baseToken,
                poolToken: pool.basePoolToken,
                poolTokenIn: amountIn,
                underlyingOut: amountOut,
                rebateOut: rebateOut,
                oraclePrice: oraclePrice,
                exchangeRate: exchangeRate,
                poolTokenPrice: _computePoolTokenPrice(pool, poolId, exchangeRate, oraclePrice)
            })
        );
    }

    /// @inheritdoc IBasePool
    function claimUserRebate(PoolId poolId, address user, address recipient) external override nonReentrant returns (uint256 rebateOut) {
        require(user == msg.sender || _isLiquidityRouter(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
        return _claim(poolId, user, recipient);
    }

    /// @inheritdoc IBasePool
    function claimUserRebates(
        PoolId[] calldata poolIds,
        address user,
        address recipient
    ) external override nonReentrant returns (uint256[] memory rebateOut) {
        require(user == msg.sender || _isLiquidityRouter(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));

        rebateOut = new uint256[](poolIds.length);
        for (uint256 i = 0; i < poolIds.length; ++i) {
            rebateOut[i] = _claim(poolIds[i], user, recipient);
        }
    }

    /// @inheritdoc IBasePool
    function updateWeightedIndexOnTransfer(PoolId poolId, address from, address to, uint256 amount, uint256 toBalanceBefore) external override {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        require(msg.sender == pool.basePoolToken, Errors.PermissionDenied(msg.sender, address(this)));

        // Skip if pool is in these states (no rebates)
        if (pool.isCooked() || pool.isBoosted() || pool.isPrimed()) return;

        // Get sender's current rebate index
        uint256 fromIndex = _userDatas[poolId][from].index;
        UserData storage toUserData = _userDatas[poolId][to];
        if (toBalanceBefore == 0) {
            // Receiver is new user or has zero balance - directly inherit sender's index
            toUserData.index = fromIndex;
        } else {
            // Calculate weighted average index for regular rebates
            toUserData.index = (toUserData.index * toBalanceBefore + fromIndex * amount) / (toBalanceBefore + amount);
        }
    }

    /// @inheritdoc IBasePool
    function exchangeProfit(
        PoolId poolId,
        uint256 baseIn,
        uint256 minQuoteOut,
        address recipient,
        bytes calldata data
    ) external override nonReentrant returns (uint256 quoteOut) {
        // Get pool metadata and validate compound is enabled
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        require(pool.compoundEnabled, Errors.PoolNotCompoundable(poolId));

        // Check if there are available profits to exchange
        uint256 profits = _poolDatas[poolId].exchangeableProfits;
        require(profits > 0, ExceedMaxProfit());

        // Get current oracle price for calculations
        uint256 oraclePrice = _getOracle().safeOraclePrice(poolId);

        // Calculate quote output with incentive rate from risk parameters
        IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);
        uint256 exchangePrice = oraclePrice.mulPrecision(
            Constants.INCENTIVE_RATE_PRECISION + poolRiskConfig.exchangeIncentiveRate,
            Constants.INCENTIVE_RATE_PRECISION
        );
        quoteOut = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, baseIn.mulPrice(exchangePrice));
        // Validate output amounts against limits
        require(quoteOut <= profits, ExceedMaxProfit());
        require(quoteOut >= minQuoteOut, Errors.ExceedMinOutputAmount());

        _poolDatas[poolId].exchangeableProfits -= quoteOut;

        // Transfer quote tokens to recipient
        IERC20(pool.quoteToken).safeTransfer(recipient, quoteOut);

        uint256 balanceBefore = IERC20(pool.baseToken).balanceOf(address(this));
        IExchangeCallback(msg.sender).onExchange(poolId, pool.baseToken, baseIn, data);
        uint256 balanceAfter = IERC20(pool.baseToken).balanceOf(address(this));
        require(balanceAfter - balanceBefore == baseIn, Errors.InsufficientReturnAmount(baseIn, balanceAfter - balanceBefore));

        // Ensure sufficient allowance for pool vault and deposit base tokens
        if (IERC20(pool.baseToken).allowance(address(this), pool.poolVault) < baseIn) {
            IERC20(pool.baseToken).forceApprove(pool.poolVault, type(uint256).max);
        }
        IPoolVault(pool.poolVault).depositBaseToken(baseIn);

        emit PoolProfitExchanged(poolId, baseIn, quoteOut, oraclePrice, recipient);
    }

    /// @inheritdoc IBasePool
    function distribute(
        PoolId poolId,
        uint256 baseAmount,
        uint256 quoteAmount,
        uint256 genesisAmount,
        uint256 price
    ) external override onlyPoolVault(poolId) {
        // Get pool metadata for distribution calculations
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        // Add quote amount to exchangeable profits
        _poolDatas[poolId].exchangeableProfits += quoteAmount;

        // Calculate and update genesis rebate index
        (, uint256 newGenesisIndex) = _calculateGenesisRebateIndex(pool, poolId, genesisAmount);
        _poolDatas[poolId].genesisRebateIndex = newGenesisIndex;

        // Get current oracle price and calculate exchange rate
        uint256 exchangeRate = _getExchangeRate(pool, poolId, price);

        // Emit profit distribution event
        emit BasePoolProfitDistributed(poolId, baseAmount, quoteAmount, price, exchangeRate, _poolDatas[poolId].rebateIndex, newGenesisIndex);
    }

    /**
     * @notice Updates pool data
     * @param poolId Pool ID
     * @param oraclePrice Current oracle price
     */
    function updatePool(PoolId poolId, uint256 oraclePrice) external override onlyPoolManager {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        _updatePool(pool, poolId, oraclePrice);
    }

    /**
     * @notice Updates pool profit distribution
     * @param pool Pool metadata
     * @param poolId Pool ID for updates
     * @param oraclePrice Current oracle price
     */
    function _updatePool(PoolMetadata memory pool, PoolId poolId, uint256 oraclePrice) internal {
        // Distribute pool profits
        ITradingVault(pool.tradingVault).distributePoolProfit(oraclePrice);

        // Get remaining profits and reset to zero
        uint256 unexchangedProfits = _poolDatas[poolId].exchangeableProfits;
        _poolDatas[poolId].exchangeableProfits = 0;

        // Calculate new rebate index based on remaining profits
        (uint256 oldIndex, uint256 newIndex) = _calculateRebateIndex(pool, poolId, unexchangedProfits);
        _poolDatas[poolId].rebateIndex = newIndex;

        emit PoolRebateIndexUpdated(poolId, unexchangedProfits, oldIndex, newIndex);
    }

    /**
     * @notice Updates user's rebate data and accrues pending rebates
     * @param pool Pool metadata
     * @param poolId The pool ID
     * @param user User address to update
     */
    function _updateUserData(PoolMetadata memory pool, PoolId poolId, address user) internal {
        // Get current pool and user data
        PoolData memory poolData = _poolDatas[poolId];
        UserData storage userData = _userDatas[poolId][user];

        // Calculate accrued rebates based on user's LP token balance
        uint256 accrued;
        uint256 tokenBalance = IPoolToken(pool.basePoolToken).balanceOf(user);
        if (tokenBalance > 0) {
            accrued = _getRebates(poolData.rebateIndex, userData.index, tokenBalance);
        }

        // Get user's genesis share for genesis rebates
        uint256 genesisAccrued;
        uint256 genesisShare = IPoolToken(pool.basePoolToken).userGenesisShare(user);
        if (genesisShare > 0) {
            genesisAccrued = _getRebates(poolData.genesisRebateIndex, userData.genesisIndex, genesisShare);
        }

        userData.index = poolData.rebateIndex;
        userData.genesisIndex = poolData.genesisRebateIndex;
        userData.accrued += accrued;
        userData.genesisAccrued += genesisAccrued;
    }

    function _claim(PoolId poolId, address user, address recipient) internal returns (uint256 rebateOut) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        if (pool.isTrench() || pool.isPreBench()) {
            _updatePool(pool, poolId, _getOracle().safeOraclePrice(poolId));
            _updateUserData(pool, poolId, user);
        } else if (pool.isBench()) {
            _updateUserData(pool, poolId, user);
        }

        rebateOut = _claimUserRebates(pool, poolId, user, recipient);
    }

    function _claimUserRebates(PoolMetadata memory pool, PoolId poolId, address user, address recipient) internal returns (uint256 rebateOut) {
        UserData storage userData = _userDatas[poolId][user];
        rebateOut = userData.accrued + userData.genesisAccrued;
        if (rebateOut == 0) return rebateOut;

        userData.accrued = 0;
        userData.genesisAccrued = 0;
        IERC20(pool.quoteToken).safeTransfer(recipient, rebateOut);

        _getEmiter().emitPoolRebateClaimed(IEmiter.PoolRebateClaimedParams({ poolId: poolId, user: user, recipient: recipient, amount: rebateOut }));
    }

    /**
     * @notice Validates that a deposit operation can be performed
     * @param pool Pool metadata to validate
     */
    function _validateDeposit(PoolMetadata memory pool) internal pure {
        require(pool.isPoolInitialized(), Errors.PoolNotExist(pool.poolId));
        require(!pool.isPreBench() && !pool.isBench(), Errors.PoolNotActive(pool.poolId));
    }

    /**
     * @notice Calculates the current total reserve of the pool, including debt collateral
     * @param reserveInfo Pool reserve information
     * @param pool Pool metadata
     * @param poolId Pool ID
     * @return totalReserve Current total reserve of the pool
     */
    function _currentTotalReserve(
        IPoolVault.PoolReserve memory reserveInfo,
        PoolMetadata memory pool,
        PoolId poolId,
        uint256 price
    ) internal view returns (uint256 totalReserve) {
        totalReserve = reserveInfo.baseTotalAmount;

        if (pool.isTrench() || pool.isPreBench()) {
            ITradingVault.DebtInfo memory debtInfo = ITradingVault(pool.tradingVault).debtInfo();
            if (debtInfo.totalDebt > 0) {
                IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);

                uint256 debtBase = TradingHelper.convertTokenAmount(
                    pool.quoteToken,
                    pool.baseToken,
                    debtInfo.totalDebt.divPrice(
                        price.mulPrecision(
                            Constants.INCENTIVE_RATE_PRECISION - poolRiskConfig.exchangeIncentiveRate,
                            Constants.INCENTIVE_RATE_PRECISION
                        )
                    )
                );
                // debtBase is the base token amount that is needed to cover the debt
                // so we need to subtract it from the total reserve
                // Due to the early closing mechanism, debt will not exceed the total reserves
                totalReserve = totalReserve + debtInfo.baseCollateral - debtBase; // / supply
            }

            (, int256 unrealizedPnl, ) = _pendingPoolPNL(pool, poolId, price);
            if (unrealizedPnl != 0) {
                // Clamp to zero if unrealized losses exceed total reserves
                if (unrealizedPnl < 0 && unrealizedPnl.abs() > totalReserve) {
                    return 0;
                }

                totalReserve = unrealizedPnl > 0 ? totalReserve + uint256(unrealizedPnl) : totalReserve - unrealizedPnl.abs();
            }
        }
    }

    /**
     * @notice Calculates pending base rebates for a user
     * @param poolId The pool ID to check rebates for
     * @param price Current oracle price
     * @param user Address of the user
     * @return rebates Regular rebates earned
     * @return genesisRebates Genesis rebates earned
     */
    function _pendingUserBaseRebate(
        PoolMetadata memory pool,
        PoolId poolId,
        uint256 price,
        address user
    ) internal view returns (uint256 rebates, uint256 genesisRebates) {
        if (pool.isCooked() || pool.isPrimed() || pool.isBoosted()) return (0, 0);
        UserData memory userData = _userDatas[poolId][user];

        (uint256 quoteProfits, uint256 genesisQuoteProfits) = _pendingPoolProfits(pool, price);
        uint256 userBalance = IPoolToken(pool.basePoolToken).balanceOf(user);
        if (userBalance > 0) {
            (, uint256 newIndex) = _calculateRebateIndex(pool, poolId, quoteProfits);
            rebates = _getRebates(newIndex, userData.index, userBalance);
        }

        uint256 genesisShare = IPoolToken(pool.basePoolToken).userGenesisShare(user);
        if (genesisShare > 0) {
            (, uint256 newGenesisIndex) = _calculateGenesisRebateIndex(pool, poolId, genesisQuoteProfits);
            genesisRebates = _getRebates(newGenesisIndex, userData.genesisIndex, genesisShare);
        }
    }

    /**
     * @notice Calculates the new rebate index for regular rebates
     * @param poolId The pool ID
     * @param profits Amount of profits to distribute
     * @return oldIndex Previous rebate index
     * @return newIndex New rebate index after adding profits
     */
    function _calculateRebateIndex(
        PoolMetadata memory pool,
        PoolId poolId,
        uint256 profits
    ) internal view returns (uint256 oldIndex, uint256 newIndex) {
        oldIndex = _poolDatas[poolId].rebateIndex;
        uint256 totalSupply = IPoolToken(pool.basePoolToken).totalSupply();
        if (totalSupply == 0) return (oldIndex, oldIndex);

        uint8 decimals = IPoolToken(pool.basePoolToken).decimals();
        newIndex = oldIndex + ((profits * REBATE_INDEX_PRECISION * (10 ** decimals)) / totalSupply);
    }

    /**
     * @notice Calculates the new rebate index for genesis rebates
     * @param poolId The pool ID
     * @param genesisProfits Amount of genesis profits to distribute
     * @return oldIndex Previous genesis rebate index
     * @return newIndex New genesis rebate index after adding profits
     */
    function _calculateGenesisRebateIndex(
        PoolMetadata memory pool,
        PoolId poolId,
        uint256 genesisProfits
    ) internal view returns (uint256 oldIndex, uint256 newIndex) {
        oldIndex = _poolDatas[poolId].genesisRebateIndex;
        uint256 totalGenesisShare = IPoolToken(pool.basePoolToken).totalGenesisShare();
        if (totalGenesisShare == 0) return (oldIndex, oldIndex);

        uint8 decimals = IPoolToken(pool.basePoolToken).decimals();
        newIndex = oldIndex + ((genesisProfits * REBATE_INDEX_PRECISION * (10 ** decimals)) / totalGenesisShare);
    }

    /**
     * @notice Calculates pending pool profits for the pool
     * @param pool Pool metadata
     * @param price Current oracle price
     * @return quoteAmount Amount of quote tokens for regular rebates
     * @return genesisQuoteAmount Amount of quote tokens for genesis rebates
     */
    function _pendingPoolProfits(PoolMetadata memory pool, uint256 price) internal view returns (uint256 quoteAmount, uint256 genesisQuoteAmount) {
        ITradingVault.PoolProfit memory profit = ITradingVault(pool.tradingVault).pendingPoolProfit();
        if (profit.profits == 0 && profit.genesisProfits == 0) return (0, 0);

        (uint256 expectBaseProfit, , ) = IPoolVault(pool.poolVault).splitPoolProfits(profit.profits, price);
        (uint256 expectGenesisBaseProfit, , ) = IPoolVault(pool.poolVault).splitPoolProfits(profit.genesisProfits, price);

        ITradingVault.DebtInfo memory debtInfo = ITradingVault(pool.tradingVault).debtInfo();
        if (debtInfo.totalDebt > 0) {
            expectBaseProfit = expectBaseProfit > debtInfo.totalDebt ? expectBaseProfit - debtInfo.totalDebt : 0;
        }
        return (expectBaseProfit, expectGenesisBaseProfit);
    }

    /// @inheritdoc PoolBase
    function _getExchangeRate(PoolMetadata memory pool, PoolId poolId, uint256 price) internal view override returns (uint256) {
        IPoolVault.PoolReserve memory reserveInfo = IPoolVault(pool.poolVault).reserveInfo();
        uint256 totalReserve = _currentTotalReserve(reserveInfo, pool, poolId, price);
        return _calculateExchangeRate(pool, totalReserve);
    }

    function _computePoolTokenPrice(
        PoolMetadata memory pool,
        PoolId /* poolId */,
        uint256 exchangeRate,
        uint256 price
    ) internal view override returns (uint256) {
        uint256 lpPrice = exchangeRate.mulPrecision(price, EXCHANGE_RATE_PRECISION);

        ITradingVault.PoolProfit memory profit = ITradingVault(pool.tradingVault).pendingPoolProfit();
        if (profit.profits > 0) {
            (uint256 expectBaseProfit, , ) = IPoolVault(pool.poolVault).splitPoolProfits(profit.profits, price);
            uint256 totalSupply = IPoolToken(pool.basePoolToken).totalSupply();
            if (totalSupply > 0) {
                lpPrice +=
                    (TradingHelper.convertTokenToDecimals(pool.quoteToken, POOL_TOKEN_DECIMALS, expectBaseProfit) * Constants.PRICE_PRECISION) /
                    totalSupply;
            }
        }

        return lpPrice;
    }

    /**
     * @notice Calculates exchange rate based on base token amount and total supply
     * @param pool Pool metadata
     * @param baseAmount Total base token amount
     * @return Exchange rate with EXCHANGE_RATE_PRECISION decimals
     */
    function _calculateExchangeRate(PoolMetadata memory pool, uint256 baseAmount) internal view returns (uint256) {
        uint256 totalSupply = IPoolToken(pool.basePoolToken).totalSupply();
        uint256 normalizedBaseAmount = TradingHelper.convertTokenToDecimals(pool.baseToken, POOL_TOKEN_DECIMALS, baseAmount);
        return _virtualizedExchangeRate(normalizedBaseAmount, totalSupply);
    }

    function _exchangeableProfit(PoolId poolId, uint256 price) internal view returns (uint256 baseIn, uint256 quoteOut) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        uint256 exchangeableProfit = _poolDatas[poolId].exchangeableProfits;
        if (exchangeableProfit == 0) return (0, 0);

        IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);
        uint256 exchangePrice = price.mulPrecision(
            Constants.INCENTIVE_RATE_PRECISION + poolRiskConfig.exchangeIncentiveRate,
            Constants.INCENTIVE_RATE_PRECISION
        );
        baseIn = TradingHelper.convertTokenAmount(pool.quoteToken, pool.baseToken, exchangeableProfit.divPrice(exchangePrice));
        quoteOut = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, baseIn.mulPrice(exchangePrice));
    }

    /**
     * @notice Calculates LP token amount for a given base token input
     * @param pool Pool metadata
     * @param amount Amount of base tokens
     * @param exchangeRate Current exchange rate
     * @return Amount of LP tokens to mint
     */
    function _getLpAmountOut(PoolMetadata memory pool, uint256 amount, uint256 exchangeRate) internal view returns (uint256) {
        if (exchangeRate == 0) return 0;
        return TradingHelper.convertTokenToDecimals(pool.baseToken, POOL_TOKEN_DECIMALS, (amount * EXCHANGE_RATE_PRECISION) / exchangeRate);
    }

    /**
     * @notice Calculates base token amount for a given LP token input
     * @param pool Pool metadata
     * @param amount Amount of LP tokens
     * @param exchangeRate Current exchange rate
     * @return Amount of base tokens to withdraw
     */
    function _getBaseAmountOut(PoolMetadata memory pool, uint256 amount, uint256 exchangeRate) internal view returns (uint256) {
        return TradingHelper.convertTokenFromDecimals(POOL_TOKEN_DECIMALS, pool.baseToken, (amount * exchangeRate) / EXCHANGE_RATE_PRECISION);
    }

    function _onlyPoolVault(PoolId poolId) internal view {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        require(msg.sender == pool.poolVault, Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyPoolManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POOL_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }
}

