// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { MarketId, PoolMetadata, PoolId, PoolState } from "./../types/Types.sol";

/// @title Pool
/// @notice Library for managing pool data and operations
library Pool {
    using EnumerableSetLib for EnumerableSetLib.Bytes32Set;
    using EnumerableSetLib for EnumerableSetLib.AddressSet;
    using Pool for Data;

    /// @notice Pool storage data structure
    struct Data {
        mapping(PoolId poolId => PoolMetadata poolMetadata) _pools; // Pool metadata by ID
        EnumerableSetLib.Bytes32Set _poolIds; // Set of all pool IDs
        mapping(MarketId marketId => EnumerableSetLib.AddressSet assets) _marketAssets; // Assets per market
        mapping(MarketId marketId => mapping(address asset => PoolId poolId)) _marketAssetPoolIds; // Asset to pool mapping
    }

    /// @notice Create a new pool with the provided parameters
    /// @param self Pool storage data
    /// @param marketId Market this pool belongs to
    /// @param poolId Unique pool identifier
    /// @param baseToken Base asset token address
    /// @param quoteToken Quote asset token address
    /// @param basePoolToken LP token for base asset
    /// @param quotePoolToken LP token for quote asset
    /// @param poolVault Pool vault contract address
    /// @param tradingVault Trading vault contract address
    function createPool(
        Data storage self,
        MarketId marketId,
        PoolId poolId,
        address baseToken,
        address quoteToken,
        address basePoolToken,
        address quotePoolToken,
        address poolVault,
        address tradingVault
    ) internal {
        self._pools[poolId] = PoolMetadata({
            marketId: marketId,
            poolId: poolId,
            baseToken: baseToken,
            quoteToken: quoteToken,
            basePoolToken: basePoolToken,
            quotePoolToken: quotePoolToken,
            poolVault: poolVault,
            tradingVault: tradingVault,
            riskTier: 0,
            state: PoolState.Cook,
            compoundEnabled: false
        });

        self._poolIds.add(PoolId.unwrap(poolId));
        self._marketAssets[marketId].add(baseToken);
        self._marketAssetPoolIds[marketId][baseToken] = poolId;
    }

    function activatePool(Data storage self, PoolId poolId, uint8 riskTier) internal {
        PoolMetadata storage poolMetadata = self._pools[poolId];

        poolMetadata.riskTier = riskTier;
        poolMetadata.state = PoolState.Trench;
    }

    function updatePoolState(Data storage self, PoolId poolId, PoolState state) internal {
        self._pools[poolId].state = state;
    }

    function updateCompoundEnabled(Data storage self, PoolId poolId, bool compoundEnabled) internal {
        self._pools[poolId].compoundEnabled = compoundEnabled;
    }

    function updateRiskTier(Data storage self, PoolId poolId, uint8 riskTier) internal {
        self._pools[poolId].riskTier = riskTier;
    }

    function poolExists(Data storage self, PoolId poolId) internal view returns (bool) {
        return self._poolIds.contains(PoolId.unwrap(poolId));
    }

    function getPoolIds(Data storage self) internal view returns (bytes32[] memory poolIds) {
        return self._poolIds.values();
    }

    function getPool(Data storage self, PoolId poolId) internal view returns (PoolMetadata memory) {
        return self._pools[poolId];
    }

    function getPoolMarketId(Data storage self, PoolId poolId) internal view returns (MarketId) {
        return self._pools[poolId].marketId;
    }

    function isPoolAddress(Data storage self, PoolId poolId, address addr) internal view returns (bool) {
        return self._pools[poolId].poolVault == addr || self._pools[poolId].tradingVault == addr;
    }

    function getPoolVault(Data storage self, PoolId poolId) internal view returns (address) {
        return self._pools[poolId].poolVault;
    }

    function getTradingVault(Data storage self, PoolId poolId) internal view returns (address) {
        return self._pools[poolId].tradingVault;
    }

    function getPoolRiskTier(Data storage self, PoolId poolId) internal view returns (uint8) {
        return self._pools[poolId].riskTier;
    }

    function getMarketPool(Data storage self, MarketId marketId, address asset) internal view returns (PoolMetadata memory) {
        return self._pools[self._marketAssetPoolIds[marketId][asset]];
    }
}

library LibPoolMetadata {
    function isPoolInitialized(PoolMetadata memory self) internal pure returns (bool) {
        return self.baseToken != address(0);
    }

    function isCooked(PoolMetadata memory self) internal pure returns (bool) {
        return self.state == PoolState.Cook;
    }

    function isBoosted(PoolMetadata memory self) internal pure returns (bool) {
        return self.state == PoolState.Boosted;
    }

    function isPrimed(PoolMetadata memory self) internal pure returns (bool) {
        return self.state == PoolState.Primed;
    }

    function isTrench(PoolMetadata memory self) internal pure returns (bool) {
        return self.state == PoolState.Trench;
    }

    function isPreBench(PoolMetadata memory self) internal pure returns (bool) {
        return self.state == PoolState.PreBench;
    }

    function isBench(PoolMetadata memory self) internal pure returns (bool) {
        return self.state == PoolState.Bench;
    }
}

