pragma solidity ^0.8.30;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IMockERC20Token is IERC20 {
    function mint(address to, uint256 amount) external;

    function mintFor(address to, uint256 amount) external;
}

contract MockSwap {
    function swap(
        address src,
        address dst,
        uint256 amountIn,
        uint256 expectedAmountOut
    ) external returns (uint256 amountOut) {
        IMockERC20Token(src).transferFrom(msg.sender, address(this), amountIn);
        IMockERC20Token(dst).mintFor(msg.sender, expectedAmountOut);
        return expectedAmountOut;
    }
}

