// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IBasePool } from "./../interfaces/IBasePool.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IOracleReserve } from "./../interfaces/IOracleReserve.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IQuotePool } from "./../interfaces/IQuotePool.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { TradingHelper } from "./../libraries/TradingHelper.sol";
import { BaseContract } from "./../misc/base/BaseContract.sol";
import { Constants, Errors, MarketMetadata, PoolMetadata, PoolId } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";

/// @title PoolVault
/// @notice Manages pool liquidity and reserves
contract PoolVault is BaseContract, IPoolVault {
    using SafeERC20 for IERC20;
    using PrecisionUtils for uint256;
    using SignedMath for int256;

    PoolId public poolId;
    address public override baseToken;
    address public override quoteToken;

    PoolReserve private _reserveInfo;

    event BaseTokenDeposited(PoolId poolId, uint256 amount, uint256 totalAmount);
    event BaseTokenWithdrawn(PoolId poolId, uint256 amount, uint256 totalAmount, address to);
    event QuoteTokenDeposited(PoolId poolId, uint256 amount, uint256 totalAmount);
    event QuoteTokenWithdrawn(PoolId poolId, uint256 amount, uint256 totalAmount, address to);
    event ReserveUpdated(
        PoolId poolId,
        uint256 baseAmount,
        uint256 quoteAmount,
        uint256 baseReserved,
        uint256 quoteReserved,
        int256 oiTracker,
        uint256 poolEntryPrice
    );
    event DisbursedToTradingVault(PoolId poolId, uint256 amount, uint256 price, uint256 baseAmount, uint256 quoteAmount, uint256 baseSize);

    error InvalidDistributionAmount();

    modifier onlyPositionManager() {
        _onlyPositionManager();
        _;
    }

    modifier onlyPoolManager() {
        _onlyPoolManager();
        _;
    }

    modifier onlyBasePool() {
        _onlyBasePool();
        _;
    }

    modifier onlyQuotePool() {
        _onlyQuotePool();
        _;
    }

    modifier onlyTradingVault() {
        _onlyTradingVault();
        _;
    }

    modifier onlyOracleReserve() {
        _onlyOracleReserve();
        _;
    }

    modifier onlyRiskAdmin() {
        _onlyRiskAdmin();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the pool vault contract
    /// @param addressManager Address manager contract address
    /// @param _poolId Pool identifier
    /// @param _baseToken Base token address
    /// @param _quoteToken Quote token address
    function initialize(address addressManager, PoolId _poolId, address _baseToken, address _quoteToken) external initializer {
        bytes32[] memory identifiers = new bytes32[](8);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.POSITION_MANAGER;
        identifiers[2] = Identifier.ORACLE_RESERVE;
        identifiers[3] = Identifier.EMITER;
        identifiers[4] = Identifier.RISK_PARAMETER;
        identifiers[5] = Identifier.BASE_POOL;
        identifiers[6] = Identifier.QUOTE_POOL;
        identifiers[7] = Identifier.FUNDING_RATE;
        __BaseContract_init(addressManager, identifiers);

        poolId = _poolId;
        baseToken = _baseToken;
        quoteToken = _quoteToken;
    }

    /// @inheritdoc IPoolVault
    function reserveInfo() external view override returns (PoolReserve memory) {
        return _reserveInfo;
    }

    /// @inheritdoc IPoolVault
    function reservable() public view override returns (uint256 baseReservable, uint256 quoteReservable) {
        PoolReserve memory reserve = _reserveInfo;
        return (_baseReservable(reserve), _quoteReservable(reserve));
    }

    /// @inheritdoc IPoolVault
    function splitPoolProfits(
        uint256 profits,
        uint256 price
    ) external view override returns (uint256 baseAmount, uint256 quoteAmount, uint256 baseSize) {
        return _splitPoolRebates(profits, price);
    }

    /// @inheritdoc IPoolVault
    function depositBaseToken(uint256 amount) external override onlyBasePool {
        // Transfer base tokens from caller to this contract
        IERC20(baseToken).safeTransferFrom(msg.sender, address(this), amount);

        _getFundingRate().updateFundingRate(poolId);
        // Increase base token reserves
        _increaseBase(amount);
        emit BaseTokenDeposited(poolId, amount, _reserveInfo.baseTotalAmount);
    }

    /// @inheritdoc IPoolVault
    function withdrawBaseToken(uint256 amount, address to) external override onlyBasePool {
        PoolReserve memory reserve = _reserveInfo;
        require(
            reserve.baseTotalAmount >= reserve.baseReservedAmount + amount,
            Errors.InsufficientLiquidity(reserve.baseTotalAmount, amount, reserve.baseReservedAmount)
        );

        _getFundingRate().updateFundingRate(poolId);
        // Decrease base token reserves
        _decreaseBase(reserve, amount);
        // Transfer base tokens to recipient
        IERC20(baseToken).safeTransfer(to, amount);

        emit BaseTokenWithdrawn(poolId, amount, reserve.baseTotalAmount, to);
    }

    /// @inheritdoc IPoolVault
    function depositQuoteToken(uint256 amount) external override onlyQuotePool {
        // Transfer quote tokens from caller to this contract
        IERC20(quoteToken).safeTransferFrom(msg.sender, address(this), amount);

        _getFundingRate().updateFundingRate(poolId);
        // Increase quote token reserves
        _increaseQuote(amount);
        emit QuoteTokenDeposited(poolId, amount, _reserveInfo.quoteTotalAmount);
    }

    /// @inheritdoc IPoolVault
    function withdrawQuoteToken(uint256 amount, address to) external override onlyQuotePool {
        PoolReserve memory reserve = _reserveInfo;
        require(
            reserve.quoteTotalAmount >= reserve.quoteReservedAmount + amount,
            Errors.InsufficientLiquidity(reserve.quoteTotalAmount, amount, reserve.quoteReservedAmount)
        );

        _getFundingRate().updateFundingRate(poolId);
        // Decrease quote token reserves
        _decreaseQuote(reserve, amount);
        // Transfer quote tokens to recipient
        IERC20(quoteToken).safeTransfer(to, amount);

        emit QuoteTokenWithdrawn(poolId, amount, reserve.quoteTotalAmount, to);
    }

    /// @inheritdoc IPoolVault
    function updatePoolReserve(int256 oiTracker, uint256 poolEntryPrice) external override onlyPositionManager {
        PoolReserve memory reserve = _reserveInfo;
        (uint256 baseReserved, uint256 quoteReserved) = _calculateReserveTargets(reserve, oiTracker, poolEntryPrice);
        if (reserve.baseReservedAmount == baseReserved && reserve.quoteReservedAmount == quoteReserved) return;

        _reserveInfo.baseReservedAmount = baseReserved;
        _reserveInfo.quoteReservedAmount = quoteReserved;

        emit ReserveUpdated(poolId, reserve.baseTotalAmount, reserve.quoteTotalAmount, baseReserved, quoteReserved, oiTracker, poolEntryPrice);
    }

    /// @inheritdoc IPoolVault
    function distribute(
        uint256 profits,
        uint256 genesisProfits,
        uint256 exchangedProfits,
        uint256 exchangedBaseAmount,
        uint256 price
    ) external override onlyTradingVault {
        // Split profits into base and quote rebates
        (uint256 baseRebates, uint256 quoteRebates, ) = _splitPoolRebates(profits, price);
        (uint256 genesisBaseRebates, uint256 genesisQuoteRebates, ) = _splitPoolRebates(genesisProfits, price);

        // Validate that base rebates cover exchanged profits
        require(baseRebates >= exchangedProfits, InvalidDistributionAmount());

        // Calculate remaining base rebates after accounting for exchanged profits
        uint256 remainingBaseRebates = baseRebates - exchangedProfits;
        remainingBaseRebates -= _repayCollateral(remainingBaseRebates, price);
        IBasePool basePool = _getBasePool();
        IQuotePool quotePool = _getQuotePool();

        // Handle exchanged base amount and remaining rebates
        if (exchangedBaseAmount > 0) _increaseBase(exchangedBaseAmount);
        if (remainingBaseRebates > 0 || genesisBaseRebates > 0) {
            IERC20(quoteToken).safeTransfer(address(basePool), remainingBaseRebates + genesisBaseRebates);
        }
        basePool.distribute(poolId, exchangedBaseAmount, remainingBaseRebates, genesisBaseRebates, price);

        if (quoteRebates > 0) _increaseQuote(quoteRebates);
        if (genesisQuoteRebates > 0) IERC20(quoteToken).safeTransfer(address(quotePool), genesisQuoteRebates);
        quotePool.distribute(poolId, quoteRebates, genesisQuoteRebates, price);

        _getEmiter().emitPoolFundDistributed(
            IEmiter.PoolFundDistributedParams({
                poolId: poolId,
                profits: profits,
                genesisProfits: genesisProfits,
                basePoolAmount: baseRebates,
                quotePoolAmount: quoteRebates,
                genesisBasePoolAmount: genesisBaseRebates,
                genesisQuotePoolAmount: genesisQuoteRebates,
                exchangedBaseFromProfits: exchangedProfits,
                exchangedBaseAmount: exchangedBaseAmount
            })
        );
    }

    function repay(uint256 repayAmount, uint256 price) external override onlyRiskAdmin {
        IERC20(quoteToken).safeTransferFrom(msg.sender, address(this), repayAmount);

        uint256 repaid = _repayCollateral(repayAmount, price);

        if (repayAmount > repaid) IERC20(quoteToken).safeTransfer(msg.sender, repayAmount - repaid);
    }

    function disburseToTradingVault(uint256 amount, uint256 price) external override onlyTradingVault {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        ITradingVault tradingVault = ITradingVault(pool.tradingVault);

        (uint256 baseAmount, uint256 quoteAmount, ) = _splitPoolRebates(amount, price);
        IRiskParameter.PoolConfigParams memory poolRiskConfig = _getRiskParameter().getPoolConfigParams(pool.riskTier);
        ITradingVault.DebtInfo memory debtInfo = tradingVault.debtInfo();
        uint256 totalDebt = debtInfo.totalDebt + baseAmount;
        uint256 needBaseCollateral = TradingHelper.convertTokenAmount(
            quoteToken,
            baseToken,
            totalDebt.mulPrecision(poolRiskConfig.baseTokenCollateralRatio, Constants.COLLATERAL_RATIO_PRECISION).divPrice(price)
        );

        uint256 collateralBase;
        uint256 redeemable;
        if (debtInfo.baseCollateral >= needBaseCollateral) {
            redeemable = debtInfo.baseCollateral - needBaseCollateral;
        } else {
            collateralBase = needBaseCollateral - debtInfo.baseCollateral;
            _approveAndDisburseBaseTo(pool.tradingVault, collateralBase);
        }

        _approveAndDisburseQuoteTo(pool.tradingVault, quoteAmount);
        tradingVault.acceptCollateral(baseAmount, collateralBase, quoteAmount, redeemable);
        emit DisbursedToTradingVault(poolId, amount, price, baseAmount, quoteAmount, collateralBase);
    }

    function disburseToOracleReserve(uint256 amount, uint256 price) external override onlyPoolManager returns (uint256, uint256) {
        (, uint256 quoteAmount, uint256 baseSize) = _splitPoolRebates(amount, price);

        address oracleReserve = address(_getOracleReserve());
        _approveAndDisburseBaseTo(oracleReserve, baseSize);
        _approveAndDisburseQuoteTo(oracleReserve, quoteAmount);

        return (baseSize, quoteAmount);
    }

    function redeemCollateral(uint256 amount) external override onlyTradingVault {
        _redeemCollateral(amount);
    }

    function _splitPoolRebates(uint256 amount, uint256 price) internal view returns (uint256 baseAmount, uint256 quoteAmount, uint256 baseSize) {
        require(price > 0, Errors.InvalidPrice());
        (, uint256 quoteLiquidityRatio) = _poolLiquidityRatio(price);

        quoteAmount = amount.mulPrecision(quoteLiquidityRatio, Constants.LIQUIDITY_RATIO_PRECISION);
        baseAmount = amount - quoteAmount;
        baseSize = TradingHelper.convertTokenAmount(quoteToken, baseToken, baseAmount.divPrice(price));
    }

    function _calculateReserveTargets(
        PoolReserve memory reserve,
        int256 tracker,
        uint256 poolEntryPrice
    ) internal view returns (uint256 baseReserved, uint256 quoteReserved) {
        if (tracker == 0) return (0, 0);

        (, MarketMetadata memory market) = _getPoolManager().getPoolMarket(poolId);
        uint256 size = tracker.abs();
        if (tracker > 0) {
            uint256 baseReservable = reserve.baseTotalAmount;
            baseReserved = Math.min(baseReservable, size);

            if (baseReservable < size) {
                uint256 quoteReserveSize = size - baseReservable;
                quoteReserved = TradingHelper.convertTokenAmount(
                    baseToken,
                    quoteToken,
                    quoteReserveSize.mulPrice(poolEntryPrice).mulPrecision(market.quoteReserveRatio, Constants.RESERVE_RATIO_PRECISION)
                );
                require(quoteReserved <= reserve.quoteTotalAmount, Errors.InsufficientLiquidity(reserve.quoteTotalAmount, quoteReserved, 0));
            }
        } else {
            uint256 quoteReservable = reserve.quoteTotalAmount;
            uint256 notional = TradingHelper.convertTokenAmount(baseToken, quoteToken, size.mulPrice(poolEntryPrice));
            quoteReserved = Math.min(notional, quoteReservable);

            if (quoteReservable < notional) {
                uint256 quoteReservedSize = TradingHelper.convertTokenAmount(quoteToken, baseToken, quoteReservable.divPrice(poolEntryPrice));
                baseReserved = (size - quoteReservedSize).mulPrecision(market.baseReserveRatio, Constants.RESERVE_RATIO_PRECISION);
                require(baseReserved <= reserve.baseTotalAmount, Errors.InsufficientLiquidity(reserve.baseTotalAmount, baseReserved, 0));
            }
        }
    }

    function _repayCollateral(uint256 maxAmount, uint256 price) internal returns (uint256 repaid) {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        ITradingVault.DebtInfo memory debtInfo = ITradingVault(pool.tradingVault).debtInfo();

        repaid = Math.min(maxAmount, debtInfo.totalDebt);
        if (repaid > 0) {
            if (IERC20(quoteToken).allowance(address(this), pool.tradingVault) < repaid) {
                IERC20(quoteToken).forceApprove(pool.tradingVault, type(uint256).max);
            }
            ITradingVault(pool.tradingVault).repayCollateral(repaid, price);
        }
    }

    function _redeemCollateral(uint256 amount) internal {
        IERC20(baseToken).safeTransferFrom(msg.sender, address(this), amount);
        _increaseBase(amount);
    }

    function _increaseBase(uint256 amount) internal {
        _reserveInfo.baseTotalAmount += amount;
        PoolReserve memory reserve = _reserveInfo;

        _getEmiter().emitPoolReserveChanged(
            IEmiter.PoolReserveChangedParams({
                poolId: poolId,
                baseAmountDelta: int256(amount),
                quoteAmountDelta: 0,
                baseTotalAmount: reserve.baseTotalAmount,
                baseReservedAmount: reserve.baseReservedAmount,
                quoteTotalAmount: reserve.quoteTotalAmount,
                quoteReservedAmount: reserve.quoteReservedAmount
            })
        );
    }

    function _decreaseBase(PoolReserve memory reserve, uint256 amount) internal {
        require(reserve.baseTotalAmount >= amount, Errors.InsufficientLiquidity(reserve.baseTotalAmount, amount, reserve.baseReservedAmount));
        _reserveInfo.baseTotalAmount -= amount;
        PoolReserve memory r = _reserveInfo;

        _getEmiter().emitPoolReserveChanged(
            IEmiter.PoolReserveChangedParams({
                poolId: poolId,
                baseAmountDelta: -int256(amount),
                quoteAmountDelta: 0,
                baseTotalAmount: r.baseTotalAmount,
                baseReservedAmount: r.baseReservedAmount,
                quoteTotalAmount: r.quoteTotalAmount,
                quoteReservedAmount: r.quoteReservedAmount
            })
        );
    }

    function _increaseQuote(uint256 amount) internal {
        _reserveInfo.quoteTotalAmount += amount;
        PoolReserve memory reserve = _reserveInfo;

        _getEmiter().emitPoolReserveChanged(
            IEmiter.PoolReserveChangedParams({
                poolId: poolId,
                baseAmountDelta: 0,
                quoteAmountDelta: int256(amount),
                baseTotalAmount: reserve.baseTotalAmount,
                baseReservedAmount: reserve.baseReservedAmount,
                quoteTotalAmount: reserve.quoteTotalAmount,
                quoteReservedAmount: reserve.quoteReservedAmount
            })
        );
    }

    function _decreaseQuote(PoolReserve memory reserve, uint256 amount) internal {
        require(reserve.quoteTotalAmount >= amount, Errors.InsufficientLiquidity(reserve.quoteTotalAmount, amount, reserve.quoteReservedAmount));
        _reserveInfo.quoteTotalAmount -= amount;
        PoolReserve memory r = _reserveInfo;

        _getEmiter().emitPoolReserveChanged(
            IEmiter.PoolReserveChangedParams({
                poolId: poolId,
                baseAmountDelta: 0,
                quoteAmountDelta: -int256(amount),
                baseTotalAmount: r.baseTotalAmount,
                baseReservedAmount: r.baseReservedAmount,
                quoteTotalAmount: r.quoteTotalAmount,
                quoteReservedAmount: r.quoteReservedAmount
            })
        );
    }

    function _poolLiquidityRatio(uint256 price) internal view returns (uint256 baseLiquidityRatio, uint256 quoteLiquidityRatio) {
        PoolReserve memory reserve = _reserveInfo;
        uint8 baseTokenDecimals = IERC20Metadata(baseToken).decimals();
        uint8 quoteTokenDecimals = IERC20Metadata(quoteToken).decimals();

        uint256 baseDeltaWad = reserve.baseTotalAmount.mulPrice(price).toWad(baseTokenDecimals);
        uint256 quoteDeltaWad = reserve.quoteTotalAmount.toWad(quoteTokenDecimals);
        uint256 totalReserveDeltaWad = baseDeltaWad + quoteDeltaWad;

        quoteLiquidityRatio = quoteDeltaWad.divPrecision(totalReserveDeltaWad, Constants.LIQUIDITY_RATIO_PRECISION);
        baseLiquidityRatio = Constants.LIQUIDITY_RATIO_PRECISION - quoteLiquidityRatio;
    }

    function _baseReservable(PoolReserve memory reserve) internal pure returns (uint256) {
        return reserve.baseTotalAmount > reserve.baseReservedAmount ? reserve.baseTotalAmount - reserve.baseReservedAmount : 0;
    }

    function _quoteReservable(PoolReserve memory reserve) internal pure returns (uint256) {
        return reserve.quoteTotalAmount > reserve.quoteReservedAmount ? reserve.quoteTotalAmount - reserve.quoteReservedAmount : 0;
    }

    function _approveAndDisburseBaseTo(address to, uint256 amount) internal {
        IERC20(baseToken).forceApprove(to, amount);
        _decreaseBase(_reserveInfo, amount);
    }

    function _approveAndDisburseQuoteTo(address to, uint256 amount) internal {
        IERC20(quoteToken).forceApprove(to, amount);
        _decreaseQuote(_reserveInfo, amount);
    }

    function _onlyPositionManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POSITION_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyPoolManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POOL_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyBasePool() internal view {
        require(msg.sender == address(_getBasePool()), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyQuotePool() internal view {
        require(msg.sender == address(_getQuotePool()), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyTradingVault() internal view {
        address tradingVault = _getPoolManager().getTradingVault(poolId);
        require(msg.sender == tradingVault, Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyOracleReserve() internal view {
        require(msg.sender == address(_getOracleReserve()), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyRiskAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isRiskAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getPositionManager() internal view returns (IPositionManager) {
        return IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getOracleReserve() internal view returns (IOracleReserve) {
        return IOracleReserve(_getDependencyAddress(Identifier.ORACLE_RESERVE));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }

    function _getRiskParameter() internal view returns (IRiskParameter) {
        return IRiskParameter(_getDependencyAddress(Identifier.RISK_PARAMETER));
    }

    function _getBasePool() internal view returns (IBasePool) {
        return IBasePool(_getDependencyAddress(Identifier.BASE_POOL));
    }

    function _getQuotePool() internal view returns (IQuotePool) {
        return IQuotePool(_getDependencyAddress(Identifier.QUOTE_POOL));
    }

    function _getFundingRate() internal view returns (IFundingRate) {
        return IFundingRate(_getDependencyAddress(Identifier.FUNDING_RATE));
    }
}

