// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ERC721Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { EnumerableMapLib } from "@solady/utils/EnumerableMapLib.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { ICollectFee } from "./interfaces/ICollectFee.sol";
import { IEmiter } from "./interfaces/IEmiter.sol";
import { IFundingRate } from "./interfaces/IFundingRate.sol";
import { IOrderManager } from "./interfaces/IOrderManager.sol";
import { IPoolManager } from "./interfaces/IPoolManager.sol";
import { IPoolVault } from "./interfaces/IPoolVault.sol";
import { IPositionManager } from "./interfaces/IPositionManager.sol";
import { IRiskController } from "./interfaces/IRiskController.sol";
import { IRiskParameter } from "./interfaces/IRiskParameter.sol";
import { ITradingRouter } from "./interfaces/ITradingRouter.sol";
import { ITradingVault } from "./interfaces/ITradingVault.sol";
import { Identifier } from "./libraries/Identifier.sol";
import { Position, LibPositionMetadata } from "./libraries/Position.sol";
import { PositionExternalHelper } from "./libraries/PositionExternalHelper.sol";
import { PositionHelper } from "./libraries/PositionHelper.sol";
import { BaseContractUpgradeable } from "./misc/base/BaseContractUpgradeable.sol";
import {
    Errors,
    OrderMetadata,
    PositionMetadata,
    PoolMetadata,
    NFTPositionKey,
    OrderId,
    PoolId,
    PositionId,
    Operation,
    Direction,
    PositionOIChange
} from "./types/Types.sol";
import { PrecisionUtils } from "./utils/PrecisionUtils.sol";
import { TradeUtils } from "./utils/TradeUtils.sol";

/// @title PositionManager
/// @notice Manages trading positions and their lifecycle
contract PositionManager is BaseContractUpgradeable, ERC721Upgradeable, IPositionManager {
    using EnumerableSetLib for EnumerableSetLib.Bytes32Set;
    using EnumerableMapLib for EnumerableMapLib.Bytes32ToUint256Map;
    using Position for Position.Data;
    using LibPositionMetadata for PositionMetadata;
    using SafeERC20 for IERC20;
    using SignedMath for int256;
    using PrecisionUtils for uint256;

    /// @notice Position storage data
    Position.Data private _positionData;
    /// @notice Mapping of pool ID to open interest tracker
    mapping(PoolId poolId => OITracker oi) private openInterest;
    /// @notice Mapping of user address to pool ID to position IDs
    mapping(address user => mapping(PoolId poolId => EnumerableSetLib.Bytes32Set positionIds)) private userPoolPositionIds;
    /// @notice Mapping of position ID to address owner (for non-NFT positions)
    mapping(PositionId positionId => address owner) private _positionOwners;
    /// @notice Mapping of NFT minted positions (positionId => tokenId)
    EnumerableMapLib.Bytes32ToUint256Map private _nftMintedPositions;
    /// @notice Mapping of NFT tokenId to position ID
    mapping(uint256 tokenId => bytes32 positionId) private _nftPositionIds;
    /// @notice NFT tokenId generation
    uint256 private _tokenId;

    modifier onlyExecutor() {
        _onlyExecutor();
        _;
    }

    modifier onlyMatcher() {
        _onlyMatcher();
        _;
    }

    modifier onlyTradingRouter() {
        _onlyTradingRouter();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the position manager contract
    /// @param addressManager Address of the address manager contract
    function initialize(address addressManager) external initializer {
        bytes32[] memory identifiers = new bytes32[](9);
        identifiers[0] = Identifier.EMITER;
        identifiers[1] = Identifier.POOL_MANAGER;
        identifiers[2] = Identifier.ORDER_MANAGER;
        identifiers[3] = Identifier.FUNDING_RATE;
        identifiers[4] = Identifier.RISK_PARAMETER;
        identifiers[5] = Identifier.EXECUTOR;
        identifiers[6] = Identifier.MATCHER;
        identifiers[7] = Identifier.RISK_CONTROLLER;
        identifiers[8] = Identifier.TRADING_ROUTER;
        __BaseContractUpgradeable_init(addressManager, identifiers);
        __ERC721_init("MYX Finance Position Token", "MYX-POSITION");
    }

    /// @inheritdoc IPositionManager
    function getOITracker(PoolId poolId) public view override returns (OITracker memory) {
        return openInterest[poolId];
    }

    /// @inheritdoc IPositionManager
    function getPosition(PositionId positionId) public view override returns (PositionMetadata memory) {
        return _positionData.getPosition(positionId);
    }

    /// @inheritdoc IPositionManager
    function getPositionByTokenId(uint256 tokenId) public view override returns (PositionMetadata memory) {
        return _positionData.getPosition(PositionId.wrap(_nftPositionIds[tokenId]));
    }

    /// @inheritdoc IPositionManager
    function getPositionOwner(PositionId positionId) public view override returns (address) {
        if (_nftMintedPositions.contains(PositionId.unwrap(positionId))) {
            uint256 tokenId = _nftMintedPositions.get(PositionId.unwrap(positionId));
            return _ownerOf(tokenId);
        } else {
            return _positionOwners[positionId];
        }
    }

    /// @inheritdoc IPositionManager
    function getPositionBroker(PositionId positionId) public view override returns (address) {
        return _positionData.getPositionBroker(positionId);
    }

    /// @inheritdoc IPositionManager
    function isPositionExists(PositionId positionId) external view override returns (bool) {
        return _positionData.isPositionExists(positionId);
    }

    /// @inheritdoc IPositionManager
    function getUserPoolPositionIds(address user, PoolId poolId) external view override returns (bytes32[] memory) {
        return userPoolPositionIds[user][poolId].values();
    }

    /// @inheritdoc IPositionManager
    function preparePosition(
        PositionId positionId,
        PoolMetadata memory pool,
        Direction direction,
        address user,
        uint256 marketPrice,
        address broker,
        bool ensureExists,
        bool requireHealthy
    ) external override onlyExecutor returns (PositionMetadata memory position, bool isHealthy) {
        bool exists = _positionData.isPositionExists(positionId);
        if (ensureExists && !exists) {
            revert Errors.PositionNotInitialized(positionId);
        }

        IFundingRate fundingRate = _getFundingRate();
        if (!exists) {
            IFundingRate.NextFundingRateInfo memory info = fundingRate.nextFundingRateInfo(pool.poolId, marketPrice);
            _positionOwners[positionId] = user;
            userPoolPositionIds[user][pool.poolId].add(PositionId.unwrap(positionId));
            position = _positionData.create(positionId, pool.poolId, direction, info.lastFundingFeeTracker, pool.riskTier, broker);
            return (position, true);
        }

        position = _positionData.getPosition(positionId);

        IRiskParameter.PoolConfigParams memory poolConfig = _getRiskParameter().getPoolConfigParams(position.riskTier);
        uint256 marginRatio;
        (isHealthy, marginRatio) = PositionHelper.checkPositionHealthy(
            position,
            fundingRate,
            ITradingVault(pool.tradingVault),
            _getPoolManager(),
            IPositionManager(address(this)),
            poolConfig,
            pool,
            positionId,
            marketPrice,
            getPositionOwner(positionId)
        );
        if (requireHealthy && !isHealthy) revert Errors.PositionNotHealthy(positionId, marginRatio);
    }

    /// @inheritdoc IPositionManager
    function updatePosition(
        ExecuteUserPositionParams calldata params
    ) external override onlyMatcher returns (int256 tradingFee, int256 fundingFee, int256 realizedPnl, int256 charge) {
        IPoolManager poolManager = _getPoolManager();
        PoolMetadata memory pool = poolManager.getPool(params.poolId);

        PositionOIChange change;
        int256 beforeTracker;
        int256 afterTracker;
        (change, beforeTracker, afterTracker, tradingFee, fundingFee, realizedPnl, charge) = _updateUserPosition(poolManager, pool, params);

        _updatePoolPosition(pool, change, params.orderId, beforeTracker, afterTracker, params.executeSize, params.executePrice);
        if (params.shouldUpdatePoolReserve) _updatePoolReserve(pool);
    }

    /// @inheritdoc IPositionManager
    function updatePoolReserve(PoolId poolId) external override onlyMatcher {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        _updatePoolReserve(pool);
    }

    /// @inheritdoc IPositionManager
    function adjustCollateral(PositionId positionId, int256 adjustAmount) external override onlyTradingRouter {
        PositionMetadata memory position = _positionData.getPosition(positionId);
        if (!position.isInitialized()) revert Errors.PositionNotInitialized(positionId);

        PoolMetadata memory pool = _getPoolManager().getPool(position.poolId);
        address owner = getPositionOwner(positionId);

        _collectForwardFee(position, positionId, owner, pool.quoteToken, pool.tradingVault);
        ITradingVault(pool.tradingVault).adjustPositionCollateral(pool, position, positionId, owner, adjustAmount);
    }

    /// @inheritdoc IPositionManager
    function closePosition(
        PositionId positionId,
        PoolId poolId,
        uint256 price,
        bool isLiquidation,
        address owner
    ) external override onlyMatcher returns (uint256 returnBaseAmount, uint256 returnQuoteAmount) {
        _getOrderManager().removePositionOrders(positionId);

        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        ITradingVault tradingVault = ITradingVault(pool.tradingVault);
        uint256 collateralAmount = tradingVault.getPositionCollateralAmount(positionId);
        if (collateralAmount > 0) {
            (returnBaseAmount, returnQuoteAmount) = tradingVault.disburseCollateral(positionId, collateralAmount, price, isLiquidation);
        }

        if (_nftMintedPositions.contains(PositionId.unwrap(positionId))) {
            uint256 tokenId = _nftMintedPositions.get(PositionId.unwrap(positionId));
            _nftMintedPositions.remove(PositionId.unwrap(positionId));
            _burn(tokenId);
            delete _nftPositionIds[tokenId];
        } else {
            delete _positionOwners[positionId];
        }
        _positionData.remove(positionId);
        userPoolPositionIds[owner][poolId].remove(PositionId.unwrap(positionId));
    }

    /// @inheritdoc IPositionManager
    function mintPositionNFT(PositionId positionId, address recipient) external override returns (PositionId newPositionId, uint256 tokenId) {
        PositionMetadata memory position = _positionData.getPosition(positionId);
        require(position.isInitialized(), Errors.InvalidPosition(positionId));
        require(!_nftMintedPositions.contains(PositionId.unwrap(positionId)), Errors.AlreadyMinted());

        address currentOwner = _positionOwners[positionId];
        require(msg.sender == currentOwner, Errors.NotPositionOwner());

        tokenId = ++_tokenId;
        newPositionId = NFTPositionKey({ poolId: position.poolId, direction: position.direction, tokenId: tokenId }).toId();

        PositionExternalHelper.transferPosition(
            _positionData,
            _getOrderManager(),
            _getRiskController(),
            _getPoolManager(),
            position.poolId,
            positionId,
            newPositionId,
            currentOwner,
            recipient
        );

        _nftPositionIds[tokenId] = PositionId.unwrap(newPositionId);
        _nftMintedPositions.set(PositionId.unwrap(newPositionId), tokenId);
        userPoolPositionIds[currentOwner][position.poolId].remove(PositionId.unwrap(positionId));
        delete _positionOwners[positionId];

        _safeMint(recipient, tokenId);

        _getEmiter().emitPositionNFTMinted(
            IEmiter.PositionNFTMintedParams({
                poolId: position.poolId,
                oldPositionId: positionId,
                newPositionId: newPositionId,
                tokenId: tokenId,
                owner: currentOwner,
                recipient: recipient
            })
        );
    }

    function _updateUserPosition(
        IPoolManager poolManager,
        PoolMetadata memory pool,
        ExecuteUserPositionParams calldata executeParams
    )
        internal
        returns (PositionOIChange change, int256 beforeTracker, int256 afterTracker, int256 tradingFee, int256 fundingFee, int256 realizedPnl, int256 charge)
    {
        ITradingVault tradingVault = ITradingVault(pool.tradingVault);
        OrderMetadata memory order = _getOrderManager().getOrder(executeParams.orderId);
        PositionId positionId = executeParams.positionId;

        PositionMetadata storage position = _positionData.loadPosition(positionId);
        if (!position.isInitialized()) revert Errors.PositionNotInitialized(positionId);

        address owner = getPositionOwner(positionId);
        uint256 beforeCollateralAmount = tradingVault.getPositionCollateralAmount(positionId);
        if (order.filledSize == 0 && order.collateralAmount > 0) {
            tradingVault.depositCollateral(positionId, executeParams.orderId, owner, order.collateralAmount);
        }

        // Update the funding rate before execution
        // and immediately settle the pool's funding fee.
        IFundingRate fundingRate = _getFundingRate();
        int256 fundingRateTracker = fundingRate.updateFundingRate(pool.poolId);
        (beforeTracker, afterTracker) = _updateOpenInterest(pool.poolId, order.operation, position.direction, executeParams.executeSize);

        _updatePositionBrokerIfChanged(position, order.broker);

        change = PositionHelper.getOIChange(beforeTracker, afterTracker);
        (tradingFee, fundingFee, realizedPnl, charge) = tradingVault.chargeUserFees(
            ITradingVault.ChargeUserFeesParams({
                orderId: executeParams.orderId,
                positionId: positionId,
                owner: owner,
                change: change,
                operation: order.operation,
                executeSize: executeParams.executeSize,
                executePrice: executeParams.executePrice,
                keeper: executeParams.keeper,
                isMatchExecution: executeParams.isMatchExecution,
                isLiquidation: executeParams.isLiquidation
            })
        );

        IRiskParameter riskParameter = _getRiskParameter();
        IRiskParameter.PoolConfigParams memory poolConfig = riskParameter.getPoolConfigParams(position.riskTier);
        (uint256 beforeSize, uint256 afterSize) = _updatePositionSize(
            fundingRate,
            tradingVault,
            poolManager,
            poolConfig,
            position,
            pool,
            positionId,
            owner,
            order.operation,
            executeParams.executeSize,
            executeParams.executePrice
        );

        // update position risk tier if position size changed and new risk tier is different from old risk tier
        if (beforeSize != afterSize && afterSize != 0 && pool.riskTier != position.riskTier) {
            PositionExternalHelper.updatePositionRiskTier(
                fundingRate,
                tradingVault,
                riskParameter,
                poolManager,
                IPositionManager(address(this)),
                position,
                pool,
                positionId,
                owner,
                executeParams.executePrice
            );
        }

        uint256 afterCollateralAmount = tradingVault.getPositionCollateralAmount(positionId);
        // After charge user funding fee, update position funding rate index
        position.updateFundingRateIndex(fundingRateTracker);

        _getEmiter().emitPositionUpdated(
            IEmiter.PositionUpdatedParams({
                broker: order.broker,
                owner: owner,
                positionId: positionId,
                poolId: pool.poolId,
                direction: position.direction,
                orderId: executeParams.orderId,
                beforeSize: beforeSize,
                afterSize: afterSize,
                beforeCollateralAmount: beforeCollateralAmount,
                afterCollateralAmount: afterCollateralAmount,
                entryPrice: position.entryPrice,
                fundingRateIndex: position.fundingRateIndex,
                riskTier: position.riskTier,
                earlyClosePrice: position.earlyClosePrice
            })
        );
    }

    function _updatePositionBrokerIfChanged(PositionMetadata storage position, address broker) internal {
        if (broker != address(0) && broker != position.broker) {
            position.updateBroker(broker);
        }
    }

    function _updatePositionSize(
        IFundingRate fundingRate,
        ITradingVault tradingVault,
        IPoolManager poolManager,
        IRiskParameter.PoolConfigParams memory poolConfig,
        PositionMetadata storage position,
        PoolMetadata memory pool,
        PositionId positionId,
        address owner,
        Operation operation,
        uint256 executeSize,
        uint256 executePrice
    ) internal returns (uint256 beforeSize, uint256 afterSize) {
        beforeSize = position.size;
        if (operation == Operation.Increase) {
            uint8 decimals = IERC20Metadata(pool.baseToken).decimals();
            position.increase(executeSize, executePrice, decimals);
            require(
                PositionHelper.checkLeverageHealthy(
                    position,
                    fundingRate,
                    tradingVault,
                    poolManager,
                    IPositionManager(address(this)),
                    poolConfig,
                    pool,
                    positionId,
                    executePrice,
                    owner
                ),
                Errors.ExceedMaxLeverage(positionId)
            );

            // update early close price if opening position causes backup asset reserve
            PositionExternalHelper.updatePositionEarlyClosePrice(poolManager, pool, position, executeSize, executePrice);
        } else if (operation == Operation.Decrease) {
            position.decrease(executeSize);
        }
        afterSize = position.size;
    }

    function _updateOpenInterest(
        PoolId poolId,
        Operation operation,
        Direction direction,
        uint256 executeSize
    ) internal returns (int256 beforeTracker, int256 afterTracker) {
        OITracker storage oi = openInterest[poolId];
        beforeTracker = oi.tracker;
        if (operation == Operation.Increase) {
            if (direction == Direction.Long) oi.longSize += executeSize;
            else oi.shortSize += executeSize;
        } else if (operation == Operation.Decrease) {
            if (direction == Direction.Long) oi.longSize -= executeSize;
            else oi.shortSize -= executeSize;
        }

        afterTracker = int256(oi.longSize) - int256(oi.shortSize);
        oi.tracker = afterTracker;
    }

    function _updatePoolPosition(
        PoolMetadata memory pool,
        PositionOIChange change,
        OrderId orderId,
        int256 beforeTracker,
        int256 afterTracker,
        uint256 executeSize,
        uint256 executePrice
    ) internal {
        if (change == PositionOIChange.IncreaseLong || change == PositionOIChange.IncreaseShort) {
            _updatePoolEntryPrice(pool, beforeTracker, executeSize, executePrice);
        } else if (change == PositionOIChange.DecreaseLong || change == PositionOIChange.DecreaseShort) {
            _settlePoolPNL(pool, orderId, beforeTracker < 0, executeSize, executePrice);
        } else if (change == PositionOIChange.FlipLongToShort || change == PositionOIChange.FlipShortToLong) {
            _settlePoolPNL(pool, orderId, beforeTracker < 0, beforeTracker.abs(), executePrice);
            _updatePoolEntryPrice(pool, 0, afterTracker.abs(), executePrice);
        }
    }

    function _updatePoolEntryPrice(PoolMetadata memory pool, int256 beforeTracker, uint256 executeSize, uint256 executePrice) internal {
        uint8 dec = IERC20Metadata(pool.baseToken).decimals();
        uint256 poolEntryPriceBefore = openInterest[pool.poolId].poolEntryPrice;

        openInterest[pool.poolId].poolEntryPrice = TradeUtils.calculateEntryPrice(
            beforeTracker.abs(),
            poolEntryPriceBefore,
            executeSize,
            executePrice,
            dec
        );
    }

    function _settlePoolPNL(
        PoolMetadata memory pool,
        OrderId orderId,
        bool isLong,
        uint256 size,
        uint256 price
    ) internal returns (int256 realizedPnl) {
        if (size == 0) return 0;

        return ITradingVault(pool.tradingVault).settlePoolPNL(orderId, size, price, isLong, openInterest[pool.poolId].poolEntryPrice);
    }

    function _updatePoolReserve(PoolMetadata memory pool) internal {
        OITracker memory oi = openInterest[pool.poolId];
        IPoolVault(pool.poolVault).updatePoolReserve(oi.tracker, oi.poolEntryPrice);
    }

    function _update(address to, uint256 tokenId, address auth) internal override returns (address) {
        PositionId positionId = PositionId.wrap(_nftPositionIds[tokenId]);
        require(PositionId.unwrap(positionId) != bytes32(0), Errors.InvalidPosition(positionId));

        address from = _ownerOf(tokenId);
        PositionMetadata memory position = _positionData.getPosition(positionId);
        if (from != address(0)) userPoolPositionIds[from][position.poolId].remove(PositionId.unwrap(positionId));
        if (to != address(0)) userPoolPositionIds[to][position.poolId].add(PositionId.unwrap(positionId));

        if (from != to && from != address(0) && to != address(0)) {
            _getOrderManager().removePositionOrders(positionId);
            _getRiskController().migratePositionRiskControlData(
                position.poolId,
                from,
                to,
                positionId,
                positionId
            );
        }

        _getEmiter().emitPositionTransfer(
            IEmiter.PositionTransferParams({ from: from, to: to, positionId: positionId })
        );

        return super._update(to, tokenId, auth);
    }

    function _collectForwardFee(
        PositionMetadata memory position,
        PositionId positionId,
        address user,
        address quoteToken,
        address tradingVault
    ) internal {
        ITradingRouter tradingRouter = _getTradingRouter();
        if (position.isInitialized()) {
            tradingRouter.collectForwardFeeIfNecessary(
                ICollectFee.FeeSource.Position,
                abi.encode(ICollectFee.PositionFeeParams({ positionId: positionId, feeToken: quoteToken, tradingVault: tradingVault }))
            );
        } else {
            tradingRouter.collectForwardFeeIfNecessary(
                ICollectFee.FeeSource.Account,
                abi.encode(ICollectFee.AccountFeeParams({ poolId: position.poolId, feeToken: quoteToken, user: user }))
            );
        }
    }

    function _onlyExecutor() internal view {
        require(
            msg.sender == _getDependencyAddress(Identifier.EXECUTOR) || msg.sender == _getDependencyAddress(Identifier.MATCHER),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _onlyMatcher() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.MATCHER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyTradingRouter() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.TRADING_ROUTER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getOrderManager() internal view returns (IOrderManager orderManager) {
        return IOrderManager(_getDependencyAddress(Identifier.ORDER_MANAGER));
    }

    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getFundingRate() internal view returns (IFundingRate fundingRate) {
        return IFundingRate(_getDependencyAddress(Identifier.FUNDING_RATE));
    }

    function _getRiskParameter() internal view returns (IRiskParameter riskParameter) {
        return IRiskParameter(_getDependencyAddress(Identifier.RISK_PARAMETER));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(_getDependencyAddress(Identifier.EMITER));
    }

    function _getRiskController() internal view returns (IRiskController) {
        return IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER));
    }

    function _getTradingRouter() internal view returns (ITradingRouter) {
        return ITradingRouter(_getDependencyAddress(Identifier.TRADING_ROUTER));
    }
}

