// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { MarketId } from "./Types.sol";

using MarketIdLib for MarketKey global;

struct MarketKey {
    uint64 chainId;
    address quoteToken;
}

library MarketIdLib {
    function toId(MarketKey memory marketKey) internal pure returns (MarketId marketId) {
        assembly ("memory-safe") {
            marketId := keccak256(marketKey, 0x40)
        }
    }
}

