// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IBroker } from "./../interfaces/IBroker.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IMYXBroker } from "./../interfaces/IMYXBroker.sol";
import { CompositeKey } from "./../libraries/CompositeKey.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { Constants, FeeType, AssetClass } from "./../types/Types.sol";
import { Broker } from "./Broker.sol";

/**
 * @title MYXBroker
 * @notice MYX Broker contract that supports negative maker fee rates for special users
 * @dev Inherits from Broker and adds functionality to assign special fee tiers with negative maker rates
 * to specific users, allowing them to earn rebates instead of paying fees for providing liquidity
 */
contract MYXBroker is Broker, UUPSUpgradeable, IMYXBroker {
    using EnumerableSetLib for EnumerableSetLib.Uint256Set;
    using SignedMath for int32;

    // Mapping from user address to their assigned special fee tier
    mapping(address user => uint8 feeTier) private _userSpecialFeeTiers;
    // Mapping from fee tier to the corresponding negative fee rate configuration
    // Key structure: [riskTier (8 bits)][feeTier (8 bits)]
    // riskTier: 0-99 (recommended), feeTier: 0-9 (recommended)
    mapping(AssetClass class => mapping(uint16 compositeKey => NegativeFeeRateTier feeRate)) private _specialFeeTiers;
    // Set of active special fee tiers
    // Key structure: [AssetClass (8 bits)][riskTier (8 bits)]
    mapping(uint16 compositeKey => EnumerableSetLib.Uint256Set tiers) private _activeSpecialFeeTierList;

    struct NegativeFeeRateTier {
        // Maker fee rate (can be negative for rebates)
        int32 makerFeeRate;
        // Taker fee rate (always positive)
        uint32 takerFeeRate;
    }

    error NotProxyAdmin();
    error InvalidFeeTier();

    modifier onlyProxyAdmin() {
        _onlyProxyAdmin();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyProxyAdmin {}

    /**
     * @notice Assigns a special fee tier to a user
     * @param user Address of the user to assign the fee tier to
     * @param feeTier Fee tier to assign (0 = default, >0 = special tier)
     * @dev Only callable by the contract owner
     */
    function setUserSpecialFeeTier(address user, uint8 feeTier) external onlyOwner {
        uint8 oldTier = _userSpecialFeeTiers[user];
        _userSpecialFeeTiers[user] = feeTier;

        IEmiter(_getAddress(Identifier.EMITER)).emitUserSpecialFeeTierUpdated(
            IEmiter.UserSpecialFeeTierUpdatedParams({ broker: address(this), user: user, oldTier: oldTier, newTier: feeTier })
        );
    }

    /**
     * @notice Configures the fee rates for a special fee tier
     * @dev Only callable by the contract owner. Fee tier 0 is reserved for default rates
     */
    function setSpecialFeeTier(UpdateSpecialFeeTierParams calldata params) external onlyOwner {
        _setSpecialFeeTiers(params.assetClass, params.riskTier, params.feeTier, params.makerFeeRate, params.takerFeeRate);
    }

    function batchSetSpecialFeeTiers(UpdateSpecialFeeTierParams[] calldata params) external onlyOwner {
        for (uint256 i = 0; i < params.length; ++i) {
            UpdateSpecialFeeTierParams calldata param = params[i];
            _setSpecialFeeTiers(param.assetClass, param.riskTier, param.feeTier, param.makerFeeRate, param.takerFeeRate);
        }
    }

    function _setSpecialFeeTiers(AssetClass assetClass, uint8 riskTier, uint8 feeTier, int32 makerFeeRate, uint32 takerFeeRate) internal {
        require(feeTier > 0, InvalidFeeTier());
        require(makerFeeRate.abs() <= Constants.TRADING_FEE_RATE_PRECISION && takerFeeRate <= Constants.TRADING_FEE_RATE_PRECISION, InvalidFeeRate());

        uint16 key = CompositeKey.pack(riskTier, feeTier);
        _specialFeeTiers[assetClass][key] = NegativeFeeRateTier({ makerFeeRate: makerFeeRate, takerFeeRate: takerFeeRate });

        key = CompositeKey.pack(uint8(assetClass), riskTier);
        _activeSpecialFeeTierList[key].add(feeTier);

        _emitFeeTierUpdated(assetClass, riskTier, FeeType.SpecialFee, feeTier, takerFeeRate, makerFeeRate, true);
    }

    /// @inheritdoc IMYXBroker
    function activeSpecialFeeTierList(AssetClass assetClass, uint8 riskTier) external view override returns (uint256[] memory) {
        uint16 key = CompositeKey.pack(uint8(assetClass), riskTier);
        return _activeSpecialFeeTierList[key].values();
    }

    /// @inheritdoc IMYXBroker
    function getSpecialFeeTier(
        AssetClass assetClass,
        uint8 riskTier,
        uint8 feeTier
    ) external view override returns (int32 makerFeeRate, uint32 takerFeeRate) {
        uint16 key = CompositeKey.pack(riskTier, feeTier);
        NegativeFeeRateTier memory specialFeeRate = _specialFeeTiers[assetClass][key];
        return (specialFeeRate.makerFeeRate, specialFeeRate.takerFeeRate);
    }

    /**
     * @dev Overrides parent function to provide special rates for users with assigned fee tiers
     */
    function getUserFeeRate(
        address user,
        AssetClass assetClass,
        uint8 riskTier
    ) public view override(IBroker, Broker) returns (uint32 takerFeeRate, int32 makerFeeRate, uint32 baseTakerFeeRate, uint32 baseMakerFeeRate) {
        uint8 userFeeTier = _userSpecialFeeTiers[user];
        uint16 key = CompositeKey.pack(uint8(assetClass), riskTier);
        if (userFeeTier == 0 || !_activeSpecialFeeTierList[key].contains(uint256(userFeeTier))) {
            return super._getUserFeeRate(user, assetClass, riskTier);
        }

        key = CompositeKey.pack(riskTier, userFeeTier);
        NegativeFeeRateTier memory specialFeeRate = _specialFeeTiers[assetClass][key];
        return (specialFeeRate.takerFeeRate, specialFeeRate.makerFeeRate, 0, 0);
    }

    function _emitClaimed(address user, address token, uint256 amount) internal override {
        _getEmiter().emitReferralRebateClaimed(IEmiter.ReferralRebateClaimedParams({ user: user, token: token, amount: amount }));
    }

    function _onlyProxyAdmin() internal view {
        require(msg.sender == _getAddress(Identifier.PROXY_ADMIN), NotProxyAdmin());
    }
}

