// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IChainlinkAggregator } from "./../interfaces/IChainlinkAggregator.sol";
import { IKeeperRegistry } from "./../interfaces/IKeeperRegistry.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IOracleAdapter } from "./../interfaces/IOracleAdapter.sol";
import { IOracleRegistry } from "./../interfaces/IOracleRegistry.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { Oracle } from "./../libraries/Oracle.sol";
import { PoolMetadata } from "./../libraries/Pool.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Constants, Errors, MarketId, PoolId, OracleType } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";
import { TransientPriceCache } from "./lib/TransientPriceCache.sol";
import { TransientRewindPriceCache } from "./lib/TransientRewindPriceCache.sol";

/// @title MYXOracle
/// @notice Oracle for price feeds and market data
contract MYXOracle is BaseContractUpgradeable, ReentrancyGuardUpgradeable, TransientPriceCache, TransientRewindPriceCache, IOracle {
    using PrecisionUtils for uint256;
    using Oracle for Oracle.Data;
    using EnumerableSetLib for EnumerableSetLib.AddressSet;

    /// @notice Oracle data storage
    Oracle.Data private _oracleData;

    /// @notice Allow-list of addresses permitted to call updatePrices
    EnumerableSetLib.AddressSet private _priceUpdaters;

    event PriceUpdaterAdded(address indexed updater);
    event PriceUpdaterRemoved(address indexed updater);

    /// @notice Error thrown when insufficient fee provided for oracle update
    error InvalidUpdateFee();
    error MismatchedPriceWithRewindPair();
    error InvalidDeviationRatio();
    error PriceSourceNotHealthy();
    error PriceDeviationBelowMinimum();
    error PriceDeviationThresholdReached();
    error ExchangeRateAlreadyApplied();
    error ExchangeRateAlreadyDisabled();
    error PublishTimeMismatch();
    error InvalidPriceTimestamp();
    error PriceUpdaterAlreadyAdded(address updater);
    error PriceUpdaterNotFound(address updater);
    error InvalidPriceUpdater();

    modifier onlyOracleAdmin() {
        _onlyOracleAdmin();
        _;
    }

    modifier onlyListingAdmin() {
        _onlyListingAdmin();
        _;
    }

    modifier onlyMarketManager() {
        _onlyMarketManager();
        _;
    }

    modifier onlyPoolConfigurator() {
        _onlyPoolConfigurator();
        _;
    }

    modifier onlyKeeper() {
        _onlyKeeper();
        _;
    }

    modifier onlyPriceUpdater() {
        _onlyPriceUpdater();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the MYX oracle contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) public initializer {
        __ReentrancyGuard_init();

        bytes32[] memory identifiers = new bytes32[](6);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.ORACLE_REGISTRY;
        identifiers[2] = Identifier.POOL_CONFIGURATOR;
        identifiers[3] = Identifier.MARKET_MANAGER;
        identifiers[4] = Identifier.RISK_PARAMETER;
        identifiers[5] = Identifier.KEEPER_REGISTRY;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @inheritdoc IOracle
    function getPriceAge() public view override returns (uint32) {
        return _oracleData.getPriceAge();
    }

    function getOracleFeedId(PoolId poolId, OracleType oracleType) public view returns (bytes32) {
        return _oracleData.getOracleFeedId(poolId, oracleType);
    }

    function getActiveOracleType(PoolId poolId) public view override returns (OracleType) {
        return _oracleData.getActiveOracleType(poolId);
    }

    /// @inheritdoc IOracle
    function getPriceData(PoolId poolId) public view override returns (Price memory) {
        return _oracleData.getPrice(poolId);
    }

    /// @inheritdoc IOracle
    function latestOraclePrice(PoolId poolId) public view override returns (uint256) {
        return _oracleData.getPrice(poolId).oraclePrice;
    }

    /// @inheritdoc IOracle
    function safeOraclePrice(PoolId poolId) public view override returns (uint256) {
        Price memory price = _oracleData.getPrice(poolId);
        require(price.publishTime + _oracleData.getPriceAge() > block.timestamp, Errors.StalePrice());
        return price.oraclePrice;
    }

    /// @inheritdoc IOracle
    function getRewindPrice(PoolId poolId) external view override returns (uint256 price, uint64 publishTime) {
        return _safeRewindPrice(poolId);
    }

    /// @inheritdoc IOracle
    function getMarketPrice(PoolId poolId) external view override returns (uint256 price, uint64 publishTime) {
        Price memory priceData = getPriceData(poolId);
        require(priceData.publishTime + _oracleData.getPriceAge() >= block.timestamp && _hasCachedPrice(poolId), Errors.StalePrice());
        uint256 referencePrice = _getReferencePrice(poolId);

        uint256 diffPrice = priceData.oraclePrice > referencePrice ? priceData.oraclePrice - referencePrice : referencePrice - priceData.oraclePrice;
        uint16 maxPriceDeviation = IRiskParameter(_getDependencyAddress(Identifier.RISK_PARAMETER))
            .getTradeLimitParams(_getPoolManager().getPoolRiskTier(poolId))
            .maxPriceDeviation;
        if (diffPrice > uint256(maxPriceDeviation).mulPrecision(priceData.oraclePrice, Constants.PRICE_DEVIATION_PRECISION)) {
            revert Errors.ExceedMaxPriceDeviation();
        }
        return (priceData.oraclePrice, priceData.publishTime);
    }

    function isPriceUpdater(address updater) external view returns (bool) {
        return _priceUpdaters.contains(updater);
    }

    function getPriceUpdaters() external view returns (address[] memory) {
        return _priceUpdaters.values();
    }

    function addPriceUpdater(address updater) external onlyOracleAdmin {
        if (updater == address(0)) revert InvalidPriceUpdater();
        if (!_priceUpdaters.add(updater)) revert PriceUpdaterAlreadyAdded(updater);
        emit PriceUpdaterAdded(updater);
    }

    function removePriceUpdater(address updater) external onlyOracleAdmin {
        if (!_priceUpdaters.remove(updater)) revert PriceUpdaterNotFound(updater);
        emit PriceUpdaterRemoved(updater);
    }

    function updatePriceAge(uint32 age) external onlyOracleAdmin {
        uint32 oldAge = _oracleData.getPriceAge();
        _oracleData.updatePriceAge(age);
        emit PriceAgeUpdated(oldAge, age);
    }

    function switchActiveOracleType(PoolId poolId, OracleType oracleType) external onlyPoolConfigurator {
        _oracleData.switchActiveOracleType(poolId, oracleType);
        emit ActiveOracleTypeSwitched(poolId, oracleType);
    }

    function setMarketQuoteConfiguration(MarketId marketId, MarketQuoteConfig calldata config) external onlyMarketManager {
        require(config.minDeviationRatio <= Constants.USD_QUOTE_PRECISION, InvalidDeviationRatio());
        require(!config.applyExchangeRate || _checkPriceExceedDeviation(config), PriceDeviationBelowMinimum());
        _oracleData.setMarketQuoteConfiguration(marketId, config.applyExchangeRate, config.minDeviationRatio, config.heartbeat, config.priceContract);
        emit MarketConfigurationUpdated(marketId, config.priceContract, config.applyExchangeRate, config.minDeviationRatio, config.heartbeat);
    }

    function setOracleFeedParameter(OracleFeedParameter calldata param) external onlyPoolConfigurator {
        _oracleData.setOracleFeedId(param.poolId, param.oracleType, param.oracleFeedId);

        if (param.oracleType == OracleType.Chainlink) _getOracleRegistry().setChainlinkPriceDecimals(param.oracleFeedId, param.decimals);
        if (param.active) {
            _oracleData.switchActiveOracleType(param.poolId, param.oracleType);
            emit ActiveOracleTypeSwitched(param.poolId, param.oracleType);
        }

        emit OracleFeedIdUpdated(param.poolId, param.oracleType, param.oracleFeedId);
    }

    function enableExchangeRateOnDeviation(MarketId marketId) external onlyListingAdmin {
        MarketQuoteConfig memory quoteConfig = _oracleData.getMarketQuoteConfig(marketId);
        require(!quoteConfig.applyExchangeRate, ExchangeRateAlreadyApplied());
        require(_checkPriceSourceHealthy(quoteConfig), PriceSourceNotHealthy());
        require(_checkPriceExceedDeviation(quoteConfig), PriceDeviationBelowMinimum());

        _oracleData.switchExchangeRateOnDeviation(marketId, true);
        emit ExchangeRateApplied(marketId);
    }

    function disableExchangeRateOnDeviation(MarketId marketId) external onlyListingAdmin {
        MarketQuoteConfig memory quoteConfig = _oracleData.getMarketQuoteConfig(marketId);
        require(quoteConfig.applyExchangeRate, ExchangeRateAlreadyDisabled());
        require(!_checkPriceExceedDeviation(quoteConfig), PriceDeviationThresholdReached());

        _oracleData.switchExchangeRateOnDeviation(marketId, false);
        emit ExchangeRateDisabled(marketId);
    }

    function updatePrices(UpdateOraclePriceParams[] calldata params) external payable override onlyPriceUpdater {
        _updatePrice(Oracle.resolveUpdatePriceParams(params));
    }

    function updatePrices(UpdateMarketPriceParams[] memory params) external payable override onlyKeeper {
        _updatePrice(params);
    }

    function updatePricesWithRewind(UpdatePriceWithRewindParams[] memory params) external payable override onlyKeeper {
        UpdateMarketPriceParams[] memory livePrices = new UpdateMarketPriceParams[](params.length);
        UpdateMarketPriceParams[] memory rewindPrices = new UpdateMarketPriceParams[](params.length);
        for (uint256 i = 0; i < params.length; ++i) {
            require(
                PoolId.unwrap(params[i].livePrice.poolId) == PoolId.unwrap(params[i].rewindPrice.poolId) &&
                    params[i].livePrice.oracleType == params[i].rewindPrice.oracleType,
                MismatchedPriceWithRewindPair()
            );
            livePrices[i] = params[i].livePrice;
            rewindPrices[i] = params[i].rewindPrice;
        }

        (
            UpdateMarketPriceParams[] memory activeLive,
            uint256[] memory liveFees,
            uint256 liveActiveFee,
            uint256 liveInactiveFee
        ) = _filterAndCalculateFees(livePrices);
        (
            UpdateMarketPriceParams[] memory activeRewind,
            uint256[] memory rewindFees,
            uint256 rewindActiveFee,
            uint256 rewindInactiveFee
        ) = _filterAndCalculateFees(rewindPrices);
        uint256 inactiveFee = liveInactiveFee + rewindInactiveFee;
        require(liveActiveFee + rewindActiveFee + inactiveFee == msg.value, InvalidUpdateFee());
        if (inactiveFee > 0) {
            (bool success, ) = msg.sender.call{ value: inactiveFee }("");
            require(success);
            emit RefundVerifyFee(msg.sender, inactiveFee);
        }

        _updateOraclePrices(activeLive, liveFees);
        _updateRewindPrices(activeRewind, rewindFees);
    }

    function _updatePrice(UpdateMarketPriceParams[] memory params) internal {
        (UpdateMarketPriceParams[] memory activeParams, uint256[] memory fees, uint256 activeFee, uint256 inactiveFee) = _filterAndCalculateFees(
            params
        );
        require(activeFee + inactiveFee == msg.value, InvalidUpdateFee());
        if (inactiveFee > 0) {
            (bool success, ) = msg.sender.call{ value: inactiveFee }("");
            require(success);
            emit RefundVerifyFee(msg.sender, inactiveFee);
        }
        _updateOraclePrices(activeParams, fees);
    }

    function _updateOraclePrices(UpdateMarketPriceParams[] memory params, uint256[] memory fees) internal {
        IOracleRegistry oracleRegistry = _getOracleRegistry();
        IPoolManager poolManager = _getPoolManager();
        for (uint256 i = 0; i < params.length; ++i) {
            Price memory latestPrice = getPriceData(params[i].poolId);

            IOracleAdapter adapter = IOracleAdapter(oracleRegistry.getOracleAdapter(params[i].oracleType));
            MarketQuoteConfig memory quoteConfig = _oracleData.getMarketQuoteConfig(poolManager.getPoolMarketId(params[i].poolId));
            bytes32 oracleFeedId = getOracleFeedId(params[i].poolId, params[i].oracleType);

            IOracleAdapter.PriceInfo memory priceInfo = adapter.verifyPrice{ value: fees[i] }(
                quoteConfig.applyExchangeRate,
                params[i].roundId,
                quoteConfig.priceContract,
                oracleFeedId,
                params[i].oracleUpdateData,
                params[i].publishTime
            );
            uint64 freshPriceTime = priceInfo.publishTime;

            require(params[i].publishTime == freshPriceTime, PublishTimeMismatch());
            require(block.timestamp <= freshPriceTime + getPriceAge(), InvalidPriceTimestamp());

            _cachePrice(params[i].poolId, params[i].referencePrice);
            if (freshPriceTime > latestPrice.publishTime) {
                _oracleData.updatePrice(params[i].poolId, priceInfo.price, priceInfo.publishTime);

                emit PoolPriceUpdated(
                    params[i].poolId,
                    params[i].oracleType,
                    address(adapter),
                    params[i].referencePrice,
                    priceInfo.price,
                    priceInfo.publishTime
                );
            }
        }
    }

    function _updateRewindPrices(UpdateMarketPriceParams[] memory params, uint256[] memory fees) internal {
        IOracleRegistry oracleRegistry = _getOracleRegistry();
        IPoolManager poolManager = _getPoolManager();
        for (uint256 i = 0; i < params.length; ++i) {
            IOracleAdapter adapter = IOracleAdapter(oracleRegistry.getOracleAdapter(params[i].oracleType));
            MarketQuoteConfig memory quoteConfig = _oracleData.getMarketQuoteConfig(poolManager.getPoolMarketId(params[i].poolId));
            bytes32 oracleFeedId = getOracleFeedId(params[i].poolId, params[i].oracleType);

            IOracleAdapter.PriceInfo memory priceInfo = adapter.verifyPrice{ value: fees[i] }(
                quoteConfig.applyExchangeRate,
                params[i].roundId,
                quoteConfig.priceContract,
                oracleFeedId,
                params[i].oracleUpdateData,
                params[i].publishTime
            );

            _setRewindPrice(params[i].poolId, priceInfo.price, priceInfo.publishTime);

            emit PoolRewindPriceUpdated(params[i].poolId, params[i].oracleType, address(adapter), priceInfo.price, priceInfo.publishTime);
        }
    }

    /// @notice Filter out inactive oracle params, compute per-entry fees for active ones,
    ///         and separately tally the fee that would have been spent on inactive entries
    ///         so the caller can refund it to msg.sender.
    function _filterAndCalculateFees(
        UpdateMarketPriceParams[] memory params
    ) internal view returns (UpdateMarketPriceParams[] memory activeParams, uint256[] memory fees, uint256 activeFee, uint256 inactiveFee) {
        IOracleRegistry oracleRegistry = _getOracleRegistry();
        uint256 activeCount;
        for (uint256 i = 0; i < params.length; ++i) {
            if (_oracleData.isOracleTypeActive(params[i].poolId, params[i].oracleType)) ++activeCount;
        }

        activeParams = new UpdateMarketPriceParams[](activeCount);
        fees = new uint256[](activeCount);
        uint256 j;
        for (uint256 i = 0; i < params.length; ++i) {
            IOracleAdapter adapter = IOracleAdapter(oracleRegistry.getOracleAdapter(params[i].oracleType));
            bytes[] memory updateData = new bytes[](1);
            updateData[0] = params[i].oracleUpdateData;
            uint256 fee = adapter.getFee(updateData);

            if (_oracleData.isOracleTypeActive(params[i].poolId, params[i].oracleType)) {
                activeParams[j] = params[i];
                fees[j] = fee;
                activeFee += fee;
                ++j;
            } else {
                inactiveFee += fee;
            }
        }
    }

    function _getReferencePrice(PoolId poolId) internal view returns (uint256 price) {
        return _getCachedPrice(poolId);
    }

    function _safeRewindPrice(PoolId poolId) internal view returns (uint256 price, uint64 publishTime) {
        (price, publishTime) = _getCachedRewindPrice(poolId);
        if (price == 0) revert Errors.InvalidRewindPrice();
    }

    function _checkPriceSourceHealthy(MarketQuoteConfig memory config) internal view returns (bool) {
        (, , , uint256 updatedAt, ) = IChainlinkAggregator(config.priceContract).latestRoundData();
        return (block.timestamp - updatedAt < config.heartbeat);
    }

    function _checkPriceExceedDeviation(MarketQuoteConfig memory config) internal view returns (bool) {
        IOracleAdapter adapter = IOracleAdapter(_getOracleRegistry().getOracleAdapter(OracleType.Chainlink));
        (uint256 price, uint8 decimals) = adapter.getLatestQuotePrice(config.priceContract);
        uint256 usdPrice = Constants.USD_QUOTE_PRICE * (10 ** decimals);
        return
            price > usdPrice.mulPrecision(Constants.USD_QUOTE_PRECISION + config.minDeviationRatio, Constants.USD_QUOTE_PRECISION) ||
            price < usdPrice.mulPrecision(Constants.USD_QUOTE_PRECISION - config.minDeviationRatio, Constants.USD_QUOTE_PRECISION);
    }

    function _onlyOracleAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isOracleAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyPriceUpdater() internal view {
        require(_priceUpdaters.contains(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyListingAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isListingAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyMarketManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.MARKET_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyPoolConfigurator() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POOL_CONFIGURATOR), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyKeeper() internal view {
        require(
            IKeeperRegistry(_getDependencyAddress(Identifier.KEEPER_REGISTRY)).isKeeper(msg.sender),
            Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _getPoolMetadata(PoolId poolId) internal view returns (PoolMetadata memory) {
        return _getPoolManager().getPool(poolId);
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(super._getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getOracleRegistry() internal view returns (IOracleRegistry) {
        return IOracleRegistry(super._getDependencyAddress(Identifier.ORACLE_REGISTRY));
    }
}

