// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { OrderId, PoolId, OrderType, Operation, Direction, TimeInForce, TriggerType } from "./Types.sol";

/// @title OrderTypes
/// @notice Library containing order parameter structures
library OrderTypes {
    struct DepositParams {
        address token;
        uint256 amount;
    }

    /// @notice Parameters for placing a new order
    struct PlaceOrderParams {
        // Order owner address
        address user;
        // Target pool for execution
        PoolId poolId;
        // Collateral provided
        uint256 collateralAmount;
        // Order size in base asset
        uint256 size;
        // Order price
        uint256 price;
        // Type of order (Market, Limit, Stop, Conditional)
        OrderType orderType;
        // Trigger condition (None, GTE, LTE)
        TriggerType triggerType;
        // Increase or decrease position
        Operation operation;
        // Long or short
        Direction direction;
        // Time validity (only IOC supported)
        TimeInForce timeInForce;
        // Maker-only order flag
        bool postOnly;
        // Maximum slippage in basis points
        uint16 slippagePct;
        // Position leverage multiplier
        uint16 leverage;
        // Broker
        address broker;
        // Take profit size
        uint256 tpSize;
        // Take profit trigger price
        uint256 tpPrice;
        // Stop loss size
        uint256 slSize;
        // Stop loss trigger price
        uint256 slPrice;
    }

    /// @notice Parameters for updating an existing order
    struct UpdateOrderParams {
        // Order to update
        OrderId orderId;
        // Broker
        address broker;
        // New order size
        uint256 size;
        // New order price
        uint256 price;
        // Take profit/stop loss parameters
        UpdateOrderTPSLParams tpsl;
    }

    struct UpdateOrderTPSLParams {
        // New take profit size
        uint256 tpSize;
        // New take profit price
        uint256 tpPrice;
        // New stop loss size
        uint256 slSize;
        // New stop loss price
        uint256 slPrice;
    }
}

