// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IAccount } from "./../interfaces/IAccount.sol";
import { IAddressManager } from "./../interfaces/IAddressManager.sol";
import { IBroker } from "./../interfaces/IBroker.sol";
import { IExchange } from "./../interfaces/IExchange.sol";
import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IMYXBroker } from "./../interfaces/IMYXBroker.sol";
import { IPoolBase } from "./../interfaces/IPoolBase.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPoolToken } from "./../interfaces/IPoolToken.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskController } from "./../interfaces/IRiskController.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { LibPositionMetadata } from "./../libraries/Position.sol";
import { PositionHelper } from "./../libraries/PositionHelper.sol";
import { TradingHelper } from "./../libraries/TradingHelper.sol";
import { Constants } from "./../types/Constants.sol";
import {
    AssetClass,
    PoolMetadata,
    PositionMetadata,
    PoolId,
    PositionId,
    Operation,
    Direction,
    MarketMetadata,
    PositionOIChange
} from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";

/// @title DataProvider
/// @notice Contract for providing aggregated pool and market data
contract DataProvider {
    using PrecisionUtils for uint256;
    using SafeCast for uint256;
    using SafeERC20 for IERC20;
    using LibPositionMetadata for PositionMetadata;
    using SignedMath for int256;

    /// @notice Address manager contract address
    address public immutable ADDRESS_MANAGER;

    /// @notice Complete pool information structure
    /// @param basePool Base pool information
    /// @param quotePool Quote pool information
    /// @param fundingInfo Funding rate information
    /// @param oi Open interest information
    struct PoolInfo {
        PoolInfoItem basePool;
        PoolInfoItem quotePool;
        PoolReserveInfo reserveInfo;
        FundingInfo fundingInfo;
        OI oi;
        LiquidityInfo liquidityInfo;
    }

    /// @notice Pool token information structure
    /// @param poolToken Pool token contract address
    /// @param exchangeRate Current exchange rate
    /// @param poolTokenPrice Pool token price in USD
    /// @param poolTokenSupply Total supply of pool tokens
    struct PoolInfoItem {
        address poolToken;
        uint256 exchangeRate;
        uint256 poolTokenPrice;
        uint256 poolTokenSupply;
        uint256 totalDebt;
        uint256 baseCollateral;
    }

    /// @notice Pool reserve information structure
    /// @param baseTotalAmount Total amount of base token
    /// @param baseReservedAmount Reserved amount of base token
    /// @param quoteTotalAmount Total amount of quote token
    /// @param quoteReservedAmount Reserved amount of quote token
    struct PoolReserveInfo {
        uint256 baseTotalAmount;
        uint256 baseReservedAmount;
        uint256 quoteTotalAmount;
        uint256 quoteReservedAmount;
    }

    /// @notice Funding rate information structure
    /// @param nextFundingRate Next funding rate value
    /// @param lastFundingFeeTracker Last funding fee tracker
    /// @param nextEpochTime Next funding epoch time
    struct FundingInfo {
        int256 nextFundingRate;
        int256 lastFundingFeeTracker;
        uint256 nextEpochTime;
    }

    /// @notice Open interest information structure
    /// @param tracker Open interest tracker
    /// @param longSize Long position size
    /// @param shortSize Short position size
    /// @param poolEntryPrice Pool entry price
    struct OI {
        int256 tracker;
        uint256 longSize;
        uint256 shortSize;
        uint256 poolEntryPrice;
    }

    /// @notice Liquidity Info information structure
    /// @param pool window caps
    /// @param Liquidity open interest tracker
    struct LiquidityInfo {
        uint256 windowCaps;
        int256 openInterest;
    }

    /// @notice Pool token price information structure
    /// @param poolId Pool identifier
    /// @param basePoolTokenPrice Base pool token price
    /// @param quotePoolTokenPrice Quote pool token price
    struct PoolTokenPrice {
        PoolId poolId;
        uint256 basePoolTokenPrice;
        uint256 quotePoolTokenPrice;
    }

    struct Exchangeable {
        uint256 maxBaseIn;
        uint256 maxQuoteIn;
        uint256 maxBaseOut;
        uint256 maxQuoteOut;
    }

    struct BrokerFee {
        AssetClass asset;
        TradingFee[] riskTieredBrokerFees;
    }

    struct TradingFee {
        uint8 riskTier;
        AddOnFeeTier[] addOnFeeTiers;
        BaseFee[] baseFeeRate;
        AddOnFeeTier[] specialFeeTiers;
    }

    struct AddOnFeeTier {
        uint8 tier;
        uint32 takerFeeRate;
        int32 makerFeeRate;
    }

    struct BaseFee {
        AssetClass assetClass;
        uint32 makerFeeRate;
        uint32 takerFeeRate;
    }

    struct UserPositionInfo {
        PositionId positionId;
        PoolId poolId;
        uint256 size;
        uint256 entryPrice;
        int256 fundingRateIndex;
        uint256 earlyClosePrice;
        Direction direction;
        uint8 riskTier;
        uint64 lastUpdateTime;
        uint256 collateralAmount;
    }

    struct AccountInfo {
        uint256 freeMargin;
        uint256 walletBalance;
        uint256 freeBaseAmount;
        uint256 baseProfit;
        uint256 quoteProfit;
        uint256 reservedAmount;
        uint64 releaseTime;
    }

    struct AccountRiskLockInfo {
        address account;
        uint256 baseAmount;
        uint256 quoteAmount;
    }

    constructor(address addressManager) {
        ADDRESS_MANAGER = addressManager;
    }

    /// @notice Get comprehensive pool information
    /// @param poolId Pool identifier
    /// @param marketPrice Current market price
    /// @return poolInfo Complete pool information
    function getPoolInfo(PoolId poolId, uint256 marketPrice) public view returns (PoolInfo memory) {
        IPoolManager poolManager = IPoolManager(_getAddress(Identifier.POOL_MANAGER));
        IFundingRate fundingRate = IFundingRate(_getAddress(Identifier.FUNDING_RATE));
        IPositionManager positionManager = IPositionManager(_getAddress(Identifier.POSITION_MANAGER));
        IRiskController riskController = IRiskController(_getAddress(Identifier.RISK_CONTROLLER));
        IRiskParameter riskParameter = IRiskParameter(_getAddress(Identifier.RISK_PARAMETER));

        PoolMetadata memory pool = poolManager.getPool(poolId);

        IPoolVault poolVault = IPoolVault(pool.poolVault);
        IPoolBase basePool = IPoolBase(_getAddress(Identifier.BASE_POOL));
        IPoolBase quotePool = IPoolBase(_getAddress(Identifier.QUOTE_POOL));
        ITradingVault.DebtInfo memory debtInfo = ITradingVault(pool.tradingVault).debtInfo();

        PoolInfo memory poolInfo;
        poolInfo.basePool = PoolInfoItem({
            poolToken: pool.basePoolToken,
            exchangeRate: basePool.getExchangeRate(poolId, marketPrice),
            poolTokenPrice: basePool.getPoolTokenPrice(poolId, marketPrice),
            poolTokenSupply: IPoolToken(pool.basePoolToken).totalSupply(),
            totalDebt: debtInfo.totalDebt,
            baseCollateral: debtInfo.baseCollateral
        });

        poolInfo.quotePool = PoolInfoItem({
            poolToken: pool.quotePoolToken,
            exchangeRate: quotePool.getExchangeRate(poolId, marketPrice),
            poolTokenPrice: quotePool.getPoolTokenPrice(poolId, marketPrice),
            poolTokenSupply: IPoolToken(pool.quotePoolToken).totalSupply(),
            totalDebt: 0,
            baseCollateral: 0
        });

        IPoolVault.PoolReserve memory reserve = poolVault.reserveInfo();
        poolInfo.reserveInfo = PoolReserveInfo({
            baseTotalAmount: reserve.baseTotalAmount,
            baseReservedAmount: reserve.baseReservedAmount,
            quoteTotalAmount: reserve.quoteTotalAmount,
            quoteReservedAmount: reserve.quoteReservedAmount
        });

        IFundingRate.NextFundingRateInfo memory info = fundingRate.nextFundingRateInfo(poolId, marketPrice);
        poolInfo.fundingInfo = FundingInfo({
            nextFundingRate: info.nextFundingRate,
            lastFundingFeeTracker: info.lastFundingFeeTracker,
            nextEpochTime: info.nextEpochTime
        });

        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(poolId);
        poolInfo.oi = OI({
            tracker: oiTracker.tracker,
            longSize: oiTracker.longSize,
            shortSize: oiTracker.shortSize,
            poolEntryPrice: oiTracker.poolEntryPrice
        });

        IRiskController.LiquidityLock memory lock = riskController.getLiquidityLock(poolId);
        IRiskParameter.RiskLockParams memory params = riskParameter.getRiskLockParams(pool.riskTier);
        poolInfo.liquidityInfo = LiquidityInfo({ windowCaps: params.windowCapUsd, openInterest: lock.openInterest });
        return poolInfo;
    }

    function getPoolInfos(PoolId[] memory poolIds, uint256[] memory marketPrices) external view returns (PoolInfo[] memory) {
        PoolInfo[] memory poolInfos = new PoolInfo[](poolIds.length);
        for (uint256 i = 0; i < poolIds.length; ++i) {
            poolInfos[i] = getPoolInfo(poolIds[i], marketPrices[i]);
        }
        return poolInfos;
    }

    function getPoolTokenPrices(PoolId[] memory poolIds, uint256[] memory marketPrices) external view returns (PoolTokenPrice[] memory) {
        PoolTokenPrice[] memory poolTokenPrices = new PoolTokenPrice[](poolIds.length);
        for (uint256 i = 0; i < poolIds.length; ++i) {
            PoolInfo memory poolInfo = getPoolInfo(poolIds[i], marketPrices[i]);
            poolTokenPrices[i] = PoolTokenPrice({
                poolId: poolIds[i],
                basePoolTokenPrice: poolInfo.basePool.poolTokenPrice,
                quotePoolTokenPrice: poolInfo.quotePool.poolTokenPrice
            });
        }
        return poolTokenPrices;
    }

    function getExchangeables(PoolId[] memory poolIds, uint256[] memory marketPrices) external view returns (Exchangeable[] memory exchangeables) {
        IExchange exchange = IExchange(_getAddress(Identifier.EXCHANGE));

        uint256 baseIn;
        uint256 quoteOut;
        uint256 quoteIn;
        uint256 baseOut;
        exchangeables = new Exchangeable[](poolIds.length);
        for (uint256 i = 0; i < poolIds.length; ++i) {
            (baseIn, quoteOut) = exchange.getExchangeableBaseToken(poolIds[i], marketPrices[i]);
            (quoteIn, baseOut) = exchange.getExchangeableQuoteToken(poolIds[i], marketPrices[i]);
            exchangeables[i].maxBaseIn = baseIn;
            exchangeables[i].maxQuoteOut = quoteOut;
            exchangeables[i].maxQuoteIn = quoteIn;
            exchangeables[i].maxBaseOut = baseOut;
        }
    }

    function getBrokerFeeTiers(
        address brokerAddress,
        AssetClass[] calldata assetClasses,
        uint8[] calldata riskTiers,
        bool isMYXBroker
    ) external view returns (BrokerFee[] memory brokerFees) {
        IMYXBroker broker = IMYXBroker(brokerAddress);

        brokerFees = new BrokerFee[](assetClasses.length);
        for (uint256 i = 0; i < assetClasses.length; ++i) {
            AssetClass assetClass = assetClasses[i];

            TradingFee[] memory riskTieredBrokerFees = new TradingFee[](riskTiers.length);
            for (uint256 j = 0; j < riskTiers.length; ++j) {
                TradingFee memory tradingFee = riskTieredBrokerFees[j];
                uint8 riskTier = riskTiers[j];
                tradingFee.riskTier = riskTier;

                uint256[] memory tiers = broker.activeFeeTiers(assetClass, riskTier);
                AddOnFeeTier[] memory addonFeeTiers = new AddOnFeeTier[](tiers.length);
                for (uint256 k = 0; k < tiers.length; ++k) {
                    (uint32 takerFeeRate, uint32 makerFeeRate) = broker.getAddOnFeeTier(assetClass, riskTier, uint8(tiers[k]));
                    addonFeeTiers[k] = AddOnFeeTier({ tier: uint8(tiers[k]), takerFeeRate: takerFeeRate, makerFeeRate: int32(makerFeeRate) });
                }
                tradingFee.addOnFeeTiers = addonFeeTiers;

                if (isMYXBroker) {
                    uint256[] memory specialTiers = broker.activeSpecialFeeTierList(assetClass, riskTier);
                    AddOnFeeTier[] memory specialFeeTiers = new AddOnFeeTier[](specialTiers.length);
                    for (uint256 k = 0; k < specialTiers.length; ++k) {
                        (int32 makerFeeRate, uint32 takerFeeRate) = broker.getSpecialFeeTier(assetClass, riskTier, uint8(specialTiers[k]));
                        specialFeeTiers[k] = AddOnFeeTier({ tier: uint8(specialTiers[k]), takerFeeRate: takerFeeRate, makerFeeRate: makerFeeRate });
                    }
                    tradingFee.specialFeeTiers = specialFeeTiers;
                }

                IBroker.FeeRate memory brokerBaseFeeRate = broker.getBaseFeeRate(assetClass);
                tradingFee.baseFeeRate = new BaseFee[](1);
                tradingFee.baseFeeRate[0] = BaseFee({
                    assetClass: assetClass,
                    makerFeeRate: brokerBaseFeeRate.makerFeeRate,
                    takerFeeRate: brokerBaseFeeRate.takerFeeRate
                });
            }

            BrokerFee memory brokerFee = brokerFees[i];
            brokerFee.asset = assetClasses[i];
            brokerFee.riskTieredBrokerFees = riskTieredBrokerFees;
        }
    }

    function getAvailableLiquiditySize(
        PoolId poolId,
        Operation operation,
        Direction direction,
        uint256 executePrice
    ) external view returns (uint256) {
        IPositionManager positionManager = IPositionManager(_getAddress(Identifier.POSITION_MANAGER));
        IPoolManager poolManager = IPoolManager(_getAddress(Identifier.POOL_MANAGER));
        PoolMetadata memory pool = poolManager.getPool(poolId);
        IPoolVault poolVault = IPoolVault(pool.poolVault);
        (, MarketMetadata memory market) = poolManager.getPoolMarket(poolId);
        return
            TradingHelper.availableLiquiditySize(
                poolId,
                poolVault,
                positionManager,
                market.baseReserveRatio,
                market.quoteReserveRatio,
                operation,
                direction,
                executePrice
            );
    }

    function getLiquidationPrice(PositionId positionId, uint256 marketPrice) external view returns (uint256) {
        IPositionManager positionManager = IPositionManager(_getAddress(Identifier.POSITION_MANAGER));
        PositionMetadata memory position = positionManager.getPosition(positionId);
        IFundingRate fundingRate = IFundingRate(_getAddress(Identifier.FUNDING_RATE));
        IPoolManager poolManager = IPoolManager(_getAddress(Identifier.POOL_MANAGER));

        PoolMetadata memory pool = poolManager.getPool(position.poolId);
        ITradingVault tradingVault = ITradingVault(pool.tradingVault);
        address owner = positionManager.getPositionOwner(positionId);
        return
            PositionHelper.calculateLiquidationPrice(
                position,
                fundingRate,
                tradingVault,
                poolManager,
                positionManager,
                IRiskParameter(_getAddress(Identifier.RISK_PARAMETER)).getPoolConfigParams(position.riskTier),
                pool,
                positionId,
                marketPrice,
                owner
            );
    }

    function getUserPositionInfos(address user, PoolId[] calldata poolIds) external view returns (UserPositionInfo[] memory positions) {
        IPositionManager positionManager = IPositionManager(_getAddress(Identifier.POSITION_MANAGER));
        IPoolManager poolManager = IPoolManager(_getAddress(Identifier.POOL_MANAGER));

        UserPositionInfo[] memory temp = new UserPositionInfo[](256);
        uint256 index = 0;
        for (uint256 i = 0; i < poolIds.length; ) {
            PoolId poolId = poolIds[i];
            PoolMetadata memory pool = poolManager.getPool(poolId);
            ITradingVault tradingVault = ITradingVault(pool.tradingVault);

            bytes32[] memory positionIds = positionManager.getUserPoolPositionIds(user, poolId);
            uint256 len = positionIds.length;
            for (uint256 j = 0; j < len; ) {
                PositionId positionId = PositionId.wrap(positionIds[j]);
                PositionMetadata memory position = positionManager.getPosition(positionId);
                uint256 margin = tradingVault.getPositionCollateralAmount(positionId);

                temp[index] = UserPositionInfo({
                    positionId: positionId,
                    poolId: position.poolId,
                    size: position.size,
                    entryPrice: position.entryPrice,
                    fundingRateIndex: position.fundingRateIndex,
                    earlyClosePrice: position.earlyClosePrice,
                    direction: position.direction,
                    riskTier: position.riskTier,
                    lastUpdateTime: position.lastUpdateTime,
                    collateralAmount: margin
                });
                unchecked {
                    ++index;
                    ++j;
                }
            }
            unchecked {
                ++i;
            }
        }

        positions = new UserPositionInfo[](index);
        for (uint256 k = 0; k < index; ) {
            positions[k] = temp[k];
            unchecked {
                ++k;
            }
        }
    }

    function getPositionFees(
        PositionId positionId,
        address broker,
        uint256 price
    ) external view returns (int256 netCollateral, uint256 collateralAmount, int256 tradingFee, int256 fundingFee, int256 unrealizedPnl) {
        IPositionManager positionManager = IPositionManager(_getAddress(Identifier.POSITION_MANAGER));
        IPoolManager poolManager = IPoolManager(_getAddress(Identifier.POOL_MANAGER));
        IFundingRate fundingRate = IFundingRate(_getAddress(Identifier.FUNDING_RATE));
        IRiskParameter riskParameter = IRiskParameter(_getAddress(Identifier.RISK_PARAMETER));

        PositionMetadata memory position = positionManager.getPosition(positionId);
        address owner = positionManager.getPositionOwner(positionId);
        PoolMetadata memory pool = poolManager.getPool(position.poolId);
        ITradingVault tradingVault = ITradingVault(pool.tradingVault);
        IRiskParameter.PoolConfigParams memory poolConfigParams = riskParameter.getPoolConfigParams(position.riskTier);

        IPositionManager.OITracker memory oi = positionManager.getOITracker(position.poolId);
        PositionOIChange change = PositionHelper.getExecuteOIChange(oi, Operation.Decrease, position.direction, position.size);
        (uint32 takerFeeRate, int32 makerFeeRate, , ) = IBroker(broker).getUserFeeRate(owner, poolConfigParams.assetClass, position.riskTier);
        bool isMaker = change == PositionOIChange.DecreaseLong || change == PositionOIChange.DecreaseShort;
        int32 feeRate = isMaker ? makerFeeRate : int32(takerFeeRate);

        uint256 notional = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, position.size.mulPrice(price));
        uint256 tradingFeeAbs = notional.mulPrecision(int256(feeRate).abs(), Constants.TRADING_FEE_RATE_PRECISION);
        tradingFee = feeRate < 0 ? -tradingFeeAbs.toInt256() : tradingFeeAbs.toInt256();
        fundingFee = position.pendingFundingFee(pool, fundingRate, price);
        unrealizedPnl = position.calculatePnl(pool, position.size, price);
        collateralAmount = tradingVault.getPositionCollateralAmount(positionId);
        netCollateral = collateralAmount.toInt256() - tradingFee + fundingFee;
    }

    function getAccountInfo(PoolId poolId, address user) external view returns (AccountInfo memory accountInfo) {
        IPoolManager poolManager = IPoolManager(_getAddress(Identifier.POOL_MANAGER));
        IAccount account = IAccount(_getAddress(Identifier.ACCOUNT));
        IRiskController riskController = IRiskController(_getAddress(Identifier.RISK_CONTROLLER));

        (, address quoteToken) = poolManager.getPairToken(poolId);
        IRiskController.ProfitLock memory profitLock = riskController.getProfitLock(poolId, user);
        uint256 baseAmount = account.getPoolWithdrawableBaseToken(user, poolId);
        (, uint256 balanceAmount, uint256 tradableProfit, uint256 reservedAmount) = account.getTradableAmount(user, poolId);
        uint256 freeReservedAmount = tradableProfit >= reservedAmount ? 0 : reservedAmount - tradableProfit;

        accountInfo = AccountInfo({
            freeMargin: balanceAmount - freeReservedAmount,
            walletBalance: IERC20(quoteToken).balanceOf(user),
            quoteProfit: tradableProfit,
            freeBaseAmount: baseAmount,
            baseProfit: profitLock.baseAmount,
            reservedAmount: reservedAmount,
            releaseTime: profitLock.releaseTime
        });
    }

    function getSumProfitLock(
        PoolId poolId,
        address[] memory respondents
    ) external view returns (uint256 baseAmount, uint256 quoteAmount, AccountRiskLockInfo[] memory infos) {
        IRiskController riskController = IRiskController(_getAddress(Identifier.RISK_CONTROLLER));

        infos = new AccountRiskLockInfo[](respondents.length);
        for (uint256 i = 0; i < respondents.length; ++i) {
            IRiskController.ProfitLock memory lock = riskController.getProfitLock(poolId, respondents[i]);
            baseAmount += lock.baseAmount;
            quoteAmount += lock.quoteAmount;

            infos[i] = AccountRiskLockInfo({ account: respondents[i], baseAmount: lock.baseAmount, quoteAmount: lock.quoteAmount });
        }
    }

    function getRiskParameters(uint8 maxRiskTier) external view returns (IRiskParameter.RiskParamData[] memory params) {
        IRiskParameter riskParameter = IRiskParameter(_getAddress(Identifier.RISK_PARAMETER));

        params = new IRiskParameter.RiskParamData[](maxRiskTier);
        for (uint8 i = 0; i < maxRiskTier; ++i) {
            params[i] = riskParameter.getRiskParamData(i);
        }
    }

    function _getAddress(bytes32 identifier) internal view returns (address) {
        return IAddressManager(ADDRESS_MANAGER).getAddress(identifier);
    }
}

