// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import {
    MarketId,
    PoolId,
    OrderId,
    PoolType,
    OracleType,
    PositionId,
    OrderType,
    Operation,
    Direction,
    TimeInForce,
    MatchType,
    TriggerType,
    FeeType,
    AssetClass
} from "./../types/Types.sol";
import { IBroker } from "./IBroker.sol";

/// @title IEmiter
/// @notice Interface for event emission functionality
interface IEmiter {
    event BlockHeader(uint256 blockNumber, uint256 blockTimestamp, uint256 sequence);

    event MarketCreated(
        MarketId marketId,
        address deployer,
        address quoteToken,
        uint32 baseReserveRatio,
        uint32 quoteReserveRatio,
        uint64 oracleFeeUsd,
        uint64 boostFeeUsd,
        uint64 boostRefundFeeUsd,
        uint128 poolPrimeThreshold,
        uint128 executionFee,
        uint128 maxExecutionFee,
        uint128 forwardFee,
        uint128 maxForwardFee
    );

    event PoolDeployed(
        MarketId marketId,
        PoolId poolId,
        address deployer,
        address baseToken,
        address quoteToken,
        address basePoolToken,
        address quotePoolToken
    );

    event PoolPrimed(PoolId poolId, address baseToken, address quoteToken, uint256 baseAmount, uint256 quoteAmount);

    event PoolBoosted(PoolId poolId, address proposer, address token, uint256 amount);

    event PoolUnboosted(PoolId poolId, address proposer, address token, uint256 refundFee);

    event PoolReprimed(PoolId poolId, address primer, address token, uint256 amount);

    event PoolTrenchFailed(PoolId poolId, string remark);

    event PoolActivated(PoolId poolId, address baseToken, address quoteToken, OracleType oracleType, bytes32 oracleFeedId);

    event PoolPreDeactivated(PoolId poolId, string remark);

    event PoolDeactivated(PoolId poolId, address baseToken, address quoteToken, string remark);

    event PoolDeposited(
        PoolId poolId,
        address user,
        address recipient,
        address underlyingToken,
        address poolToken,
        uint256 underlyingIn,
        uint256 poolTokenOut,
        uint256 oraclePrice,
        uint256 exchangeRate,
        uint256 poolTokenPrice
    );

    event PoolWithdrawn(
        PoolId poolId,
        address user,
        address recipient,
        address underlyingToken,
        address poolToken,
        uint256 poolTokenIn,
        uint256 underlyingOut,
        uint256 rebateOut,
        uint256 oraclePrice,
        uint256 exchangeRate,
        uint256 poolTokenPrice
    );

    event LiquidityStopOrderCreated(
        uint256 orderId,
        address user,
        PoolId poolId,
        PoolType poolType,
        uint256 amount,
        uint256 triggerPrice,
        TriggerType triggerType,
        uint256 minQuoteOut
    );

    event LiquidityStopOrderCancelled(uint256 orderId, PoolId poolId, string reason);

    event LiquidityStopOrderExecuted(uint256 orderId, PoolId poolId, address executor, uint256 oraclePrice, uint256 poolTokenPrice);

    event LiquidityMigrated(address user, PoolId fromPoolId, PoolId toPoolId, uint256 lpAmountIn, uint256 lpAmountOut);

    event OrderPlaced(
        address broker,
        address user,
        PoolId poolId,
        PositionId positionId,
        OrderId orderId,
        OrderType orderType,
        Operation operation,
        Direction direction,
        TriggerType triggerType,
        uint256 collateralAmount,
        uint256 size,
        uint256 price,
        TimeInForce tif,
        bool postOnly,
        uint16 slippagePct,
        uint16 userLeverage
    );

    event OrderFilled(
        address broker,
        address user,
        PoolId poolId,
        PositionId positionId,
        OrderId orderId,
        OrderType orderType,
        uint256 orderSize,
        uint256 fillSize,
        uint256 filledSize,
        uint256 orderPrice,
        uint256 fillPrice,
        int256 realizedPnl,
        int256 tradingFee,
        int256 fundingFee,
        address keeper
    );

    event OrderCancelled(address broker, address user, PoolId poolId, OrderId orderId, string remark);

    event OrderUpdated(
        address broker,
        address user,
        PoolId poolId,
        OrderId orderId,
        uint256 size,
        uint256 price,
        uint256 tpSize,
        uint256 tpPrice,
        uint256 slSize,
        uint256 slPrice
    );

    event CollateralAdjusted(
        address user,
        PoolId poolId,
        PositionId positionId,
        Direction direction,
        uint256 beforeCollateralAmount,
        uint256 afterCollateralAmount
    );

    event OrderMarkedADL(address broker, address user, PoolId poolId, OrderId orderId, PositionId positionId);

    event PositionNFTMinted(PoolId poolId, PositionId oldPositionId, PositionId newPositionId, uint256 tokenId, address owner, address recipient);

    event PositionTransfer(address from, address to, PositionId positionId);

    event PositionUpdated(
        address broker,
        address owner,
        PositionId positionId,
        PoolId poolId,
        Direction direction,
        OrderId orderId,
        uint256 beforeSize,
        uint256 afterSize,
        uint256 beforeCollateralAmount,
        uint256 afterCollateralAmount,
        uint256 entryPrice,
        int256 fundingRateIndex,
        uint8 riskTier,
        uint256 earlyClosePrice
    );

    event FundingRateUpdated(
        uint64 epochs,
        uint64 duration,
        uint64 previousEpochTime,
        uint64 lastEpochTime,
        PoolId poolId,
        int256 fundingRate,
        int256 fundingRateTracker,
        uint256 price
    );

    event PoolFundingFeeSettled(
        PoolId poolId,
        int256 prevFundingRateTracker,
        int256 nextFundingRateTracker,
        uint256 price,
        Direction direction,
        uint256 positionSize,
        uint256 fundingFee
    );

    event PoolFundDistributed(
        PoolId poolId,
        uint256 profits,
        uint256 genesisProfits,
        uint256 basePoolAmount,
        uint256 quotePoolAmount,
        uint256 genesisBasePoolAmount,
        uint256 genesisQuotePoolAmount,
        uint256 exchangedBaseFromProfits,
        uint256 exchangedBaseAmount
    );

    event CollateralAccepted(
        PoolId poolId,
        uint256 quoteDebt,
        uint256 baseCollateral,
        uint256 quoteCollateral,
        uint256 redeemable,
        uint256 totalQuoteDebt,
        uint256 totalBaseCollateral
    );

    event FeeDistributed(
        address user,
        OrderId orderId,
        PoolId poolId,
        int32 tradingFeeRate,
        bool isMaker,
        int256 tradingFee,
        uint256 baseTradingFee,
        uint256 brokerTradingFee,
        address broker,
        uint256 referralRebate,
        uint256 referrerRebate,
        address referrer,
        int256 reserveFee
    );

    event UserSettlementRecorded(
        address user,
        PoolId poolId,
        OrderId orderId,
        int256 charge,
        int256 realizedPnl,
        int256 tradingFee,
        int256 fundingFee
    );

