// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IBroker } from "./../interfaces/IBroker.sol";
import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import {
    AssetClass,
    Constants,
    PositionMetadata,
    PoolMetadata,
    PoolId,
    PositionId,
    Direction,
    PositionOIChange,
    Operation
} from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";
import { TradeUtils } from "./../utils/TradeUtils.sol";
import { PositionHelper } from "./PositionHelper.sol";
import { TradingHelper } from "./TradingHelper.sol";

/// @title Position
/// @notice Library for managing position data and operations
library Position {
    using SignedMath for int256;

    /// @notice Position storage data
    struct Data {
        mapping(PositionId positionId => PositionMetadata metadata) _positions;
    }

    /// @notice Thrown when trying to initialize an already initialized position
    error PositionAlreadyInitialized();

    /// @notice Create a new position
    /// @param self Position storage reference
    /// @param positionId Position ID
    /// @param poolId Pool ID
    /// @param direction Position direction
    /// @param fundingRateIndex Initial funding rate index
    /// @param riskTier Risk tier level
    /// @return metadata Created position metadata
    function create(
        Data storage self,
        PositionId positionId,
        PoolId poolId,
        Direction direction,
        int256 fundingRateIndex,
        uint8 riskTier,
        address broker
    ) internal returns (PositionMetadata memory metadata) {
        metadata = PositionMetadata({
            poolId: poolId,
            size: 0,
            entryPrice: 0,
            fundingRateIndex: fundingRateIndex,
            direction: direction,
            riskTier: riskTier,
            lastUpdateTime: uint64(block.timestamp),
            earlyClosePrice: 0,
            broker: broker
        });
        self._positions[positionId] = metadata;
    }

    /// @notice Remove a position from storage
    function remove(Data storage self, PositionId positionId) internal {
        delete self._positions[positionId];
    }

    /// @notice Transfer a position from one position ID to another
    function transfer(Data storage self, PositionId from, PositionId to) internal {
        self._positions[to] = self._positions[from];
        delete self._positions[from];
    }

    /// @notice Load position storage reference for modification
    /// @return position Position storage reference
    function loadPosition(Data storage self, PositionId positionId) internal view returns (PositionMetadata storage position) {
        return self._positions[positionId];
    }

    /// @notice Get position metadata copy
    /// @return position Position metadata copy
    function getPosition(Data storage self, PositionId positionId) internal view returns (PositionMetadata memory position) {
        return self._positions[positionId];
    }

    function getPositionBroker(Data storage self, PositionId positionId) internal view returns (address) {
        return self._positions[positionId].broker;
    }

    function isPositionExists(Data storage self, PositionId positionId) internal view returns (bool) {
        return PoolId.unwrap(self._positions[positionId].poolId) != bytes32(0);
    }
}

/// @title LibPositionMetadata
/// @notice Library for position metadata operations and calculations
library LibPositionMetadata {
    using LibPositionMetadata for PositionMetadata;
    using SafeCast for uint256;
    using PrecisionUtils for uint256;
    using SignedMath for int256;

    /// @notice Thrown when trying to decrease position by more than current size
    error ExceedPositionSize();

    /// @notice Check if position is initialized
    /// @param self Position metadata
    /// @return initialized Whether position is initialized
    function isInitialized(PositionMetadata memory self) internal pure returns (bool initialized) {
        return PoolId.unwrap(self.poolId) != bytes32(0);
    }

    /// @notice Increase position size and update entry price
    /// @param self Position storage reference
    /// @param size Size to add to position
    /// @param price Price of the increase
    /// @param decimals Decimals of the base token
    function increase(PositionMetadata storage self, uint256 size, uint256 price, uint8 decimals) internal {
        self.lastUpdateTime = uint64(block.timestamp);
        self.entryPrice = TradeUtils.calculateEntryPrice(self.size, self.entryPrice, size, price, decimals);
        self.size += size;
    }

    /// @notice Decrease position size
    /// @param self Position storage reference
    /// @param size Size to remove from position
    function decrease(PositionMetadata storage self, uint256 size) internal {
        require(self.size >= size, ExceedPositionSize());
        self.size -= size;
        self.lastUpdateTime = uint64(block.timestamp);
    }

    /// @notice Update position funding rate index
    /// @param self Position storage reference
    /// @param fundingRateIndex New funding rate index
    function updateFundingRateIndex(PositionMetadata storage self, int256 fundingRateIndex) internal {
        self.fundingRateIndex = fundingRateIndex;
    }

    /// @notice Update position risk tier
    /// @param self Position storage reference
    /// @param riskTier New risk tier
    function updateRiskTier(PositionMetadata storage self, uint8 riskTier) internal {
        self.riskTier = riskTier;
    }

    /// @notice Update position early close price
    /// @param earlyClosePrice New early close price
    function updateEarlyClosePrice(PositionMetadata storage self, uint256 earlyClosePrice) internal {
        self.earlyClosePrice = earlyClosePrice;
    }

    /// @notice Update position broker
    /// @param broker New broker
    function updateBroker(PositionMetadata storage self, address broker) internal {
        self.broker = broker;
    }

    function computeEquity(
        PositionMetadata memory self,
        IFundingRate fundingRate,
        ITradingVault tradingVault,
        IPositionManager positionManager,
        PoolMetadata memory pool,
        PositionId positionId,
        AssetClass assetClass,
        uint256 price,
        address owner
    ) internal view returns (int256) {
        IPositionManager.OITracker memory oi = positionManager.getOITracker(pool.poolId);
        PositionOIChange change = PositionHelper.getExecuteOIChange(oi, Operation.Decrease, self.direction, self.size);

        int256 unrealizedPnl = self.calculatePnl(pool, self.size, price);
        int256 netCollateral = self.computeNetCollateral(fundingRate, tradingVault, pool, positionId, assetClass, change, price, owner);
        return netCollateral + unrealizedPnl;
    }

    function computeNetCollateral(
        PositionMetadata memory self,
        IFundingRate fundingRate,
        ITradingVault tradingVault,
        PoolMetadata memory pool,
        PositionId positionId,
        AssetClass assetClass,
        PositionOIChange change,
        uint256 price,
        address owner
    ) internal view returns (int256) {
        (uint32 takerFeeRate, int32 makerFeeRate, , ) = IBroker(self.broker).getUserFeeRate(owner, assetClass, self.riskTier);
        bool isMaker = change == PositionOIChange.DecreaseLong || change == PositionOIChange.DecreaseShort;
        int32 feeRate = isMaker ? makerFeeRate : int32(takerFeeRate);

        uint256 notional = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, self.size.mulPrice(price));
        uint256 tradingFeeAbs = notional.mulPrecision(int256(feeRate).abs(), Constants.TRADING_FEE_RATE_PRECISION);
        int256 tradingFee = feeRate < 0 ? -tradingFeeAbs.toInt256() : tradingFeeAbs.toInt256();
        int256 fundingFee = self.pendingFundingFee(pool, fundingRate, price);
        uint256 collateralAmount = tradingVault.getPositionCollateralAmount(positionId);

        return collateralAmount.toInt256() - tradingFee + fundingFee;
    }

    function computeMaintenanceMargin(
        PositionMetadata memory self,
        PoolMetadata memory pool,
        uint16 maintainMarginRate,
        uint256 price
    ) internal view returns (uint256) {
        return
            TradingHelper.convertTokenAmount(
                pool.baseToken,
                pool.quoteToken,
                self.size.mulPrice(price).mulPrecision(maintainMarginRate, Constants.MARGIN_RATIO_PRECISION)
            );
    }

    function pendingFundingFee(
        PositionMetadata memory self,
        PoolMetadata memory poolMetadata,
        IFundingRate fundingRate,
        uint256 price
    ) internal view returns (int256) {
        IFundingRate.NextFundingRateInfo memory info = fundingRate.nextFundingRateInfo(self.poolId, price);
        return TradingHelper.calculateFundingFee(poolMetadata, info.lastFundingFeeTracker - self.fundingRateIndex, self.size, self.direction);
    }

    function calculatePnl(
        PositionMetadata memory self,
        PoolMetadata memory poolMetadata,
        uint256 size,
        uint256 price
    ) internal view returns (int256) {
        return TradingHelper.calculatePNL(poolMetadata, self.entryPrice, price, size, self.direction == Direction.Long);
    }
}

