// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { IProxyAdmin } from "../interfaces/IProxyAdmin.sol";
import { BaseContractUpgradeable } from "../misc/base/BaseContractUpgradeable.sol";

contract ProxyAdmin is Ownable2StepUpgradeable, BaseContractUpgradeable, IProxyAdmin {
    event ContractUpgraded(bytes32 identifier, address proxy, address newImplementation);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, address initialOwner) public initializer {
        __Ownable2Step_init();
        __BaseContractUpgradeable_init(addressManager, new bytes32[](0));

        _transferOwnership(initialOwner);
    }

    function upgrade(bytes32 identifier, address newImplementation, bytes calldata data) external payable override onlyOwner {
        IUUPSUpgradeableProxy proxy = IUUPSUpgradeableProxy(_getAddressManager().getAddress(identifier));
        _upgrade(identifier, proxy, newImplementation, data);
    }

    function upgradeProxy(address proxyAddress, address newImplementation, bytes calldata data) external payable onlyOwner {
        IUUPSUpgradeableProxy proxy = IUUPSUpgradeableProxy(proxyAddress);
        _upgrade("0x", proxy, newImplementation, data);
    }

    function upgradeBeacon(bytes32 identifier, address newImplementation) external payable onlyOwner {
        IUpgradeableBeacon proxy = IUpgradeableBeacon(_getAddressManager().getAddress(identifier));
        _upgradeBeacon(identifier, proxy, newImplementation);
    }

    function _upgrade(bytes32 identifier, IUUPSUpgradeableProxy proxy, address newImplementation, bytes calldata data) internal {
        proxy.upgradeToAndCall(newImplementation, data);
        emit ContractUpgraded(identifier, address(proxy), newImplementation);
    }

    function _upgradeBeacon(bytes32 identifier, IUpgradeableBeacon proxy, address newImplementation) internal {
        proxy.upgradeTo(newImplementation);
        emit ContractUpgraded(identifier, address(proxy), newImplementation);
    }
}

interface IUUPSUpgradeableProxy {
    function upgradeToAndCall(address newImplementation, bytes calldata data) external payable;
}

interface IUpgradeableBeacon {
    function upgradeTo(address newImplementation) external;
}

