// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IStaker } from "../interfaces/IStaker.sol";

/// @title ValidatorView
/// @notice A read-only helper contract for querying validator state from the Staker contract.
/// @dev Intended as a convenience view layer; contains no state-mutating logic.
contract ValidatorView {

    /// @notice The Staker contract used to query epoch and validator data.
    IStaker public constant STAKER = IStaker(0x36f4b2e82355020181a4583507375F0c606d61F9);

    constructor() {}

    /// @notice Returns the list of active validators for the current epoch.
    /// @return An array of validator addresses that are active in the current epoch.
    function getCurrentActiveValidators() external view returns (address[] memory) {
        return STAKER.getActiveValidators(STAKER.currentEpoch());
    }
}

