// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { PoolId, OrderId, PoolMetadata, PositionId } from "../types/Types.sol";

interface IAccount {
    struct AssetInfo {
        address asset;
        uint256 amount;
    }

    struct OrderReserve {
        address reservedToken;
        uint256 reservedAmount;
    }

    event ReleaseProfit(address account, address token, uint256 amount);
    event SettleToAccount(
        address account,
        PositionId positionId,
        address baseToken,
        address quoteToken,
        uint256 freeBase,
        uint256 profitBase,
        uint256 freeAmount,
        uint256 profitAmount
    );
    event DepositToAccount(address account, address token, uint256 amount);
    event WithdrawFromAccount(address account, address token, uint256 amount);
    event PayWithProfitFirst(address account, address receiver, PoolId poolId, address token, uint256 usedFreeAmount, uint256 usedRestrictedAmount);
    event PayWithPrincipal(address account, address receiver, address token, uint256 amount);
    event ReserveForOrder(PoolId poolId, OrderId orderId, address account, address token, uint256 amount);
    event ReleaseForOrder(PoolId poolId, OrderId orderId, address account, address token, uint256 amount);
    event ExecuteCompensation(PoolId poolId, uint256 baseAmount, uint256 quoteAmount);

    function releaseFromProfitUnlock(address user, PoolId poolId, uint256 baseAmount, uint256 quoteAmount) external;

    function getUserAsset(address account, address token) external view returns (uint256);

    function getPoolWithdrawableBaseToken(address account, PoolId poolId) external view returns (uint256);

    function getUserAssets(address account) external view returns (AssetInfo[] memory);

    function getTradableAmount(address account, PoolId poolId) external view returns (bool, uint256, uint256, uint256);

    function deposit(address account, address token, uint256 amount) external;

    function settlementDeposit(
        PositionId positionId,
        address account,
        PoolMetadata memory pool,
        uint256 freeBaseAmount,
        uint256 freeQuoteAmount,
        uint256 receivedBaseAmount,
        uint256 receivedQuoteAmount
    ) external;

    function updateAndWithdraw(address receiver, PoolId poolId, bool isQuoteToken, uint256 amount) external;

    function payWithProfitFirst(
        PoolId poolId,
        OrderId orderId,
        address account,
        address token,
        uint256 amount
    ) external returns (uint256 usedFreeAmount, uint256 usedRestrictedAmount);

