// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { OrderMetadata, OrderTPSLData, OrderId, PoolId } from "./../types/Types.sol";

/// @title OrderBook
/// @notice Library for managing order data and operations
library OrderBook {
    struct Data {
        uint256 _orderIdSequencer;
        mapping(OrderId orderId => OrderMetadata order) _orders;
        mapping(OrderId orderId => OrderTPSLData tpsl) _orderTPSLs;
    }

    /// @notice Add a new order to the order book
    /// @return orderId Generated order ID
    function addOrder(Data storage self, OrderMetadata memory order) internal returns (OrderId orderId) {
        orderId = OrderId.wrap(++self._orderIdSequencer);
        self._orders[orderId] = order;
    }

    /// @notice Remove an order from the order book
    function removeOrder(Data storage self, OrderId orderId) internal {
        delete self._orders[orderId];
        delete self._orderTPSLs[orderId];
    }

    /// @notice Set take profit and stop loss data for an order
    function setOrderTPSL(Data storage self, OrderId orderId, OrderTPSLData memory tpsl) internal {
        self._orderTPSLs[orderId] = tpsl;
    }

    /// @notice Remove take profit and stop loss data for an order
    function removeOrderTPSL(Data storage self, OrderId orderId) internal {
        delete self._orderTPSLs[orderId];
    }

    /// @notice Fill size for an order
    function fillOrder(Data storage self, OrderId orderId, uint256 fill) internal returns (uint256 filled) {
        self._orders[orderId].filledSize += fill;
        return self._orders[orderId].filledSize;
    }

    /// @notice Check if an order exists in the order book
    function checkOrderExists(Data storage self, OrderId orderId) internal view returns (bool exists) {
        return PoolId.unwrap(self._orders[orderId].poolId) != bytes32(0);
    }

    /// @notice Load order storage reference for modification
    /// @return order Order storage reference
    function loadOrder(Data storage self, OrderId orderId) internal view returns (OrderMetadata storage order) {
        return self._orders[orderId];
    }

    /// @notice Get order metadata copy
    /// @return order Order metadata copy
    function getOrder(Data storage self, OrderId orderId) internal view returns (OrderMetadata memory order) {
        return self._orders[orderId];
    }

    /// @notice Get TP/SL data for an order
    /// @return tpsl TP/SL data
    function getOrderTPSL(Data storage self, OrderId orderId) internal view returns (OrderTPSLData memory tpsl) {
        return self._orderTPSLs[orderId];
    }

    /// @notice Get order metadata and TP/SL data together
    /// @return order Order metadata
    /// @return tpsl TP/SL data
    function getOrderWithTPSL(Data storage self, OrderId orderId) internal view returns (OrderMetadata memory order, OrderTPSLData memory tpsl) {
        return (self._orders[orderId], self._orderTPSLs[orderId]);
    }
}

/// @title LibOrderMetadata
/// @notice Library for order metadata utility functions
library LibOrderMetadata {
    /// @notice Check if caller is the order owner
    /// @return isOwner Whether caller is the owner
    function isOrderOwner(OrderMetadata memory self, address caller) internal pure returns (bool isOwner) {
        return caller == self.user;
    }

    /// @notice Check if caller is the order broker
    /// @return isBroker Whether caller is the broker
    function isOrderBroker(OrderMetadata memory self, address caller) internal pure returns (bool isBroker) {
        return caller == self.broker;
    }

    /// @notice Update order metadata
    function updateMetadata(OrderMetadata storage self, uint256 size, uint256 price) internal {
        self.size = size;
        self.price = price;
    }

    /// @notice Update order broker
    function updateOrderBroker(OrderMetadata storage self, address broker) internal {
        self.broker = broker;
    }
}

