    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, address admin) public initializer {
        __AccessControl_init();
        __BaseContractUpgradeable_init(addressManager, new bytes32[](0));
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
