// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { BeaconProxy } from "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";
import { IBroker } from "./../interfaces/IBroker.sol";
import { IBrokerFactory } from "./../interfaces/IBrokerFactory.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors, AssetClass } from "./../types/Types.sol";

/**
 * @title BrokerFactory
 * @notice Factory contract for creating broker instances using beacon proxy pattern
 * @dev This contract creates new broker instances as beacon proxies, allowing for upgradeable broker contracts
 * while maintaining individual broker state and ownership
 */
contract BrokerFactory is BaseContractUpgradeable, IBrokerFactory {
    modifier onlyBrokerManager() {
        _onlyBrokerManager();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializes the BrokerFactory contract
     * @param addressManager Address of the address manager contract
     */
    function initialize(address addressManager) external initializer {
        bytes32[] memory dependencies = new bytes32[](3);
        dependencies[0] = Identifier.BROKER_BEACON;
        dependencies[1] = Identifier.BROKER_MANAGER;
        dependencies[2] = Identifier.EMITER;
        __BaseContractUpgradeable_init(addressManager, dependencies);
    }

    /// @inheritdoc IBrokerFactory
    function createBroker(
        address owner,
        string calldata name,
        address[] calldata brokerSigners,
        AssetClass[] memory assetClasses,
        IBroker.FeeRate[] memory baseFeeRates
    ) external override onlyBrokerManager returns (address) {
        address beacon = getBrokerBeacon();

        bytes memory initData = abi.encodeWithSelector(
            IBroker.initialize.selector,
            address(_getAddressManager()),
            owner,
            name,
            brokerSigners,
            assetClasses,
            baseFeeRates
        );

        BeaconProxy proxy = new BeaconProxy(beacon, initData);

        IEmiter(_getDependencyAddress(Identifier.EMITER)).emitBrokerCreated(
            IEmiter.BrokerCreatedParams({
                broker: address(proxy),
                beacon: beacon,
                name: name,
                assetClasses: assetClasses,
                baseFeeRates: baseFeeRates
            })
        );
        return address(proxy);
    }

    /**
     * @notice Gets the address of the broker beacon contract
     * @return Address of the broker beacon contract
     */
    function getBrokerBeacon() public view returns (address) {
        return _getDependencyAddress(Identifier.BROKER_BEACON);
    }

    function _onlyBrokerManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.BROKER_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }
}

