// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IBroker } from "./../interfaces/IBroker.sol";
import { IBrokerFactory } from "./../interfaces/IBrokerFactory.sol";
import { IBrokerManager } from "./../interfaces/IBrokerManager.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { AssetClass } from "./../types/Types.sol";

/**
 * @title BrokerManager
 * @notice Manages the lifecycle and registry of broker contracts in the system
 * @dev This contract handles broker creation, registration, deactivation, and provides broker status queries
 */
contract BrokerManager is BaseContractUpgradeable, IBrokerManager {
    using EnumerableSetLib for EnumerableSetLib.AddressSet;

    // Set of all registered broker addresses
    EnumerableSetLib.AddressSet private _brokerList;

    // Default asset classes for new brokers
    AssetClass[] private _defaultAssetClasses;

    // Default base fee rates for new brokers
    mapping(AssetClass => IBroker.FeeRate) private _defaultBaseFeeRates;

    /**
     * @notice Emitted when a new broker is registered
     * @param broker Address of the registered broker
     * @param name Name of the broker
     */
    event BrokerRegistered(address broker, string name);

    /**
     * @notice Emitted when a broker is deactivated
     * @param broker Address of the deactivated broker
     */
    event BrokerDeactivated(address indexed broker);

    /**
     * @notice Emitted when default broker configuration is updated
     * @param assetClasses Updated default asset classes
     */
    event DefaultConfigUpdated(AssetClass[] assetClasses);

    error NotBrokerAdmin();
    error BrokerAlreadyExists();
    error BrokerNotFound();
    error InvalidFeeRateLength();

    modifier onlyBrokerAdmin() {
        _onlyBrokerAdmin();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializes the BrokerManager contract
     * @param addressManager Address of the address manager contract
     */
    function initialize(address addressManager) external initializer {
        bytes32[] memory dependencies = new bytes32[](1);
        dependencies[0] = Identifier.BROKER_FACTORY;
        __BaseContractUpgradeable_init(addressManager, dependencies);
    }

    /**
     * @notice Creates and registers a new broker in one transaction
     * @param owner Address that will own the new broker
     * @param name Human-readable name for the broker
     * @param signers Array of signers that can sign fee data
     * @return broker Address of the newly created and registered broker
     * @dev Permissionless — anyone can create a broker with default fee configuration
     */
    function createBroker(address owner, string calldata name, address[] calldata signers) external returns (address broker) {
        AssetClass[] memory assetClasses = _defaultAssetClasses;
        uint256 len = assetClasses.length;
        IBroker.FeeRate[] memory baseFeeRates = new IBroker.FeeRate[](len);
        for (uint256 i; i < len; ++i) {
            baseFeeRates[i] = _defaultBaseFeeRates[assetClasses[i]];
        }

        IBrokerFactory factory = IBrokerFactory(_getDependencyAddress(Identifier.BROKER_FACTORY));
        broker = factory.createBroker(owner, name, signers, assetClasses, baseFeeRates);
        _registerBroker(broker);
    }

    /**
     * @notice Registers an existing broker in the system
     * @param broker Address of the broker to register
     * @dev Only callable by broker admin. Activates the broker and adds it to the registry
     */
    function registerBroker(address broker) external onlyBrokerAdmin {
        _registerBroker(broker);
    }

    /**
     * @notice Deactivates and removes a broker from the system
     * @param broker Address of the broker to deactivate
     * @dev Only callable by contract configurator. Deactivates the broker and removes it from the registry
     */
    function deactivateBroker(address broker) external onlyBrokerAdmin {
        if (!_brokerList.contains(broker)) revert BrokerNotFound();

        IBroker(broker).updateBrokerStatus(false);
        _brokerList.remove(broker);

        emit BrokerDeactivated(broker);
    }

    function updateBrokerBaseFeeRates(address broker, IBroker.UpdateBaseFeeRateParams[] calldata params) external onlyBrokerAdmin {
        if (!_brokerList.contains(broker)) revert BrokerNotFound();
        IBroker(broker).updateBaseFeeRates(params);
    }

    /**
     * @notice Returns an array of all registered broker addresses
     * @return Array of broker addresses
     */
    function brokerList() external view returns (address[] memory) {
        return _brokerList.values();
    }

    /// @inheritdoc IBrokerManager
    function isBroker(address broker) external view override returns (bool) {
        return _brokerList.contains(broker);
    }

    /// @inheritdoc IBrokerManager
    function isActiveBroker(address broker) external view override returns (bool) {
        return _brokerList.contains(broker) && IBroker(broker).isActive();
    }

    /**
     * @notice Sets default asset classes and base fee rates for new brokers
     * @param assetClasses Array of asset classes
     * @param baseFeeRates Array of base fee rates corresponding to each asset class
     * @dev Only callable by broker admin
     */
    function setDefaultConfig(AssetClass[] calldata assetClasses, IBroker.FeeRate[] calldata baseFeeRates) external onlyBrokerAdmin {
        if (assetClasses.length != baseFeeRates.length) revert InvalidFeeRateLength();

        _defaultAssetClasses = assetClasses;
        for (uint256 i; i < assetClasses.length; ++i) {
            _defaultBaseFeeRates[assetClasses[i]] = baseFeeRates[i];
        }

        emit DefaultConfigUpdated(assetClasses);
    }

    /**
     * @notice Returns the default asset classes and base fee rates
     */
    function getDefaultConfig() external view returns (AssetClass[] memory assetClasses, IBroker.FeeRate[] memory baseFeeRates) {
        assetClasses = _defaultAssetClasses;
        uint256 len = assetClasses.length;
        baseFeeRates = new IBroker.FeeRate[](len);
        for (uint256 i; i < len; ++i) {
            baseFeeRates[i] = _defaultBaseFeeRates[assetClasses[i]];
        }
    }

    function getDefaultBaseFeeRate(AssetClass assetClass) external view returns (IBroker.FeeRate memory) {
        return _defaultBaseFeeRates[assetClass];
    }

    function _registerBroker(address broker) internal {
        if (_brokerList.contains(broker)) revert BrokerAlreadyExists();

        IBroker(broker).updateBrokerStatus(true);
        _brokerList.add(broker);

        emit BrokerRegistered(broker, IBroker(broker).name());
    }

    function _onlyBrokerAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isBrokerAdmin(msg.sender), NotBrokerAdmin());
    }
}

