// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { ERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import { IAddressManager } from "./../../interfaces/IAddressManager.sol";
import { IPoolManager } from "./../../interfaces/IPoolManager.sol";
import { IPoolToken } from "./../../interfaces/IPoolToken.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { LibPoolMetadata } from "./../../libraries/Pool.sol";
import { Errors, PoolMetadata, PoolId } from "./../../types/Types.sol";

/// @title PoolTokenBase
/// @notice ERC20 token representing pool shares with genesis share tracking
abstract contract TokenBase is Initializable, ERC20Upgradeable, IPoolToken {
    using LibPoolMetadata for PoolMetadata;

    /// @notice Address manager contract
    address public addressManager;
    /// @notice Pool identifier
    PoolId public poolId;
    /// @notice Underlying token address
    address public underlyingToken;

    /// @notice Total genesis shares across all users
    uint256 private _totalGenesisShares;
    /// @notice Mapping from user address to genesis share amount
    mapping(address account => uint256 share) private _userGenesisShares;

    event GenesisShareMinted(address account, uint256 amount);
    event GenesisShareBurned(address account, uint256 amount);
    event GenesisShareTransferred(address from, address to, uint256 amount);

    modifier onlyPool() {
        _ensurePool();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the pool token contract
    /// @param _addressManager Address manager contract address
    /// @param _poolId Pool identifier
    /// @param _underlyingToken Underlying token address
    /// @param name Token name
    /// @param symbol Token symbol
    function initialize(
        address _addressManager,
        PoolId _poolId,
        address _underlyingToken,
        string memory name,
        string memory symbol
    ) external initializer {
        __ERC20_init(name, symbol);

        // Set contract configuration
        addressManager = _addressManager;
        poolId = _poolId;
        underlyingToken = _underlyingToken;
    }

    /// @inheritdoc IPoolToken
    function userGenesisShare(address account) external view override returns (uint256) {
        return _userGenesisShares[account];
    }

    /// @inheritdoc IPoolToken
    function totalGenesisShare() external view override returns (uint256) {
        return _totalGenesisShares;
    }

    /// @inheritdoc IPoolToken
    function mint(address to, uint256 amount) external onlyPool {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);
        // Mint genesis shares if pool is in cooked state
        if (pool.isCooked()) {
            _mintGenesisShare(to, amount);
        }
        // Mint regular pool tokens
        _mint(to, amount);
    }

    /// @inheritdoc IPoolToken
    function burnFrom(address from, uint256 amount) external onlyPool {
        PoolMetadata memory pool = _getPoolManager().getPool(poolId);

        // Burn regular pool tokens
        _burn(from, amount);

        // Handle genesis share burning based on pool state
        if (pool.isCooked()) {
            // In cooked state: burn genesis shares proportionally
            _burnGenesisShare(from, amount);
        } else {
            // In non-cooked state: burn excess genesis shares
            uint256 share = _userGenesisShares[from];
            uint256 balance = balanceOf(from);
            if (balance < share) _burnGenesisShare(from, share - balance);
        }
    }

    function _update(address from, address to, uint256 amount) internal virtual override {
        if (from != address(0) && to != address(0) && from != to) {
            PoolMetadata memory pool = _getPoolManager().getPool(poolId);
            if (pool.isCooked()) {
                uint256 fromShare = _userGenesisShares[from];
                uint256 moved = amount < fromShare ? amount : fromShare;
                if (moved > 0) {
                    _userGenesisShares[from] = fromShare - moved;
                    _userGenesisShares[to] += moved;
                    emit GenesisShareTransferred(from, to, moved);
                }
            }
        }

        super._update(from, to, amount);
    }

    function _mintGenesisShare(address account, uint256 amount) internal {
        _userGenesisShares[account] += amount;
        _totalGenesisShares += amount;

        emit GenesisShareMinted(account, amount);
    }

    function _burnGenesisShare(address account, uint256 amount) internal {
        uint256 balance = _userGenesisShares[account];
        require(balance >= amount, Errors.InsufficientBalance(account, balance, amount));

        _userGenesisShares[account] -= amount;
        _totalGenesisShares -= amount;

        emit GenesisShareBurned(account, amount);
    }

    function _ensurePool() internal view {
        address basePool = IAddressManager(addressManager).getAddress(Identifier.BASE_POOL);
        address quotePool = IAddressManager(addressManager).getAddress(Identifier.QUOTE_POOL);

        require(msg.sender == basePool || msg.sender == quotePool, Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(IAddressManager(addressManager).getAddress(Identifier.POOL_MANAGER));
    }
}

