// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IAccount } from "./../interfaces/IAccount.sol";
import { IBrokerManager } from "./../interfaces/IBrokerManager.sol";
import { ICollectFee } from "./../interfaces/ICollectFee.sol";
import { IForwarder } from "./../interfaces/IForwarder.sol";
import { IMarketManager } from "./../interfaces/IMarketManager.sol";
import { IOrderManager } from "./../interfaces/IOrderManager.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskController } from "./../interfaces/IRiskController.sol";
import { ITradingRouter } from "./../interfaces/ITradingRouter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors } from "./../types/Types.sol";
import { PositionId, OrderTypes, OrderId } from "./../types/Types.sol";
import { ERC2771ContextUpgradeable } from "./ERC2771ContextUpgradeable.sol";

contract TradingRouter is BaseContractUpgradeable, ERC2771ContextUpgradeable, ReentrancyGuardUpgradeable, ITradingRouter {
    using SafeERC20 for IERC20;

    event CollectExecutionFee(ICollectFee.FeeSource source, PositionId positionId, address account, uint256 executionFee, address token);
    event CollectForwardFee(ICollectFee.FeeSource source, PositionId positionId, address account, uint256 forwardFee, address token);

    modifier onlyExecutor() {
        _onlyExecutor();
        _;
    }

    modifier onlyActiveBroker(address broker) {
        _onlyActiveBroker(broker);
        _;
    }

    modifier onlyAllowedTarget() {
        _onlyAllowedTarget();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) external initializer {
        bytes32[] memory dependencies = new bytes32[](9);
        dependencies[0] = Identifier.EXECUTOR;
        dependencies[1] = Identifier.ACCOUNT;
        dependencies[2] = Identifier.FORWARDER;
        dependencies[3] = Identifier.MARKET_MANAGER;
        dependencies[4] = Identifier.BROKER_MANAGER;
        dependencies[5] = Identifier.ORDER_MANAGER;
        dependencies[6] = Identifier.POSITION_MANAGER;
        dependencies[7] = Identifier.RISK_CONTROLLER;
        dependencies[8] = Identifier.PAYMASTER;
        __BaseContractUpgradeable_init(addressManager, dependencies);

        __ERC2771ContextUpgradeable_init(_getDependencyAddress(Identifier.FORWARDER));
    }

    /// @inheritdoc ITradingRouter
    function depositToAccount(address recipient, address token, uint256 amount) external override nonReentrant {
        _enforceForwardedRecipient(recipient);
        address user = _msgOrigin();

        _collectForwardFeeIfNecessary(ICollectFee.FeeSource.Direct, abi.encode(ICollectFee.AddressFeeParams({ feeToken: token, user: user })));
        _depositFor(user, token, amount, recipient);
    }

    /**
     * @notice Places a new trading order using position salt
     * @param userPositionSalt Unique salt value used to compute position ID
     * @param orderParams Parameters for the order to be placed
     * @dev Only callable when broker is active and by the order owner.
     *      The PositionId is computed from PositionKey(poolId, user, direction, salt).
     *      Use this function for new positions or when you know your position salt.
     */
    function placeOrderWithSalt(
        uint64 userPositionSalt,
        OrderTypes.DepositParams calldata depositParams,
        OrderTypes.PlaceOrderParams calldata orderParams
    ) external payable onlyActiveBroker(orderParams.broker) nonReentrant {
        if (orderParams.user != _msgOrigin()) revert Errors.NotOrderOwner();

        _handleDeposit(depositParams, orderParams.user);
        _getOrderManager().placeOrderWithSalt(userPositionSalt, orderParams);
    }

    /**
     * @notice Places a new trading order for an existing position
     * @param positionId Position ID of the existing position to operate on
     * @param orderParams Parameters for the order to be placed
     * @dev Only callable when broker is active and by the order owner.
     *      Use this function when you already have the PositionId (e.g., for transferred positions
     *      or when querying existing positions). The position must already exist.
     *      For new positions, use placeOrderWithSalt instead.
     */
    function placeOrderWithPosition(
        PositionId positionId,
        OrderTypes.DepositParams calldata depositParams,
        OrderTypes.PlaceOrderParams calldata orderParams
    ) external payable onlyActiveBroker(orderParams.broker) nonReentrant {
        if (orderParams.user != _msgOrigin()) revert Errors.NotOrderOwner();

        _handleDeposit(depositParams, orderParams.user);
        _getOrderManager().placeOrderWithPosition(positionId, orderParams);
    }

    /**
     * @notice Places multiple trading orders in a single transaction
     * @param orderParams Array of order parameters
     * @dev Only callable when broker is active and by the order owner
     */
    function placeOrdersWithSalt(
        OrderTypes.DepositParams calldata depositParams,
        uint64[] calldata userPositionSalts,
        OrderTypes.PlaceOrderParams[] calldata orderParams
    ) external payable nonReentrant {
        address user = _msgOrigin();
        _handleDeposit(depositParams, user);

        IOrderManager orderManager = _getOrderManager();
        for (uint256 i = 0; i < orderParams.length; ++i) {
            if (orderParams[i].user != user) revert Errors.NotOrderOwner();
            _onlyActiveBroker(orderParams[i].broker);

            orderManager.placeOrderWithSalt(userPositionSalts[i], orderParams[i]);
        }
    }

    function placeOrdersWithPosition(
        OrderTypes.DepositParams calldata depositParams,
        PositionId[] calldata positionIds,
        OrderTypes.PlaceOrderParams[] calldata orderParams
    ) external payable nonReentrant {
        address user = _msgOrigin();
        _handleDeposit(depositParams, user);

        IOrderManager orderManager = _getOrderManager();
        for (uint256 i = 0; i < orderParams.length; ++i) {
            if (orderParams[i].user != user) revert Errors.NotOrderOwner();
            _onlyActiveBroker(orderParams[i].broker);

            orderManager.placeOrderWithPosition(positionIds[i], orderParams[i]);
        }
    }

    /**
     * @notice Cancels a single trading order
     * @param orderId ID of the order to cancel
     * @dev Only callable when broker is active and by the order owner
     */
    function cancelOrder(OrderId orderId) external nonReentrant {
        IOrderManager orderManager = _getOrderManager();
        if (!orderManager.isOrderOwner(orderId, _msgOrigin())) revert Errors.NotOrderOwner();

        orderManager.cancelOrder(orderId);
    }

    /**
     * @notice Cancels multiple trading orders in a single transaction
     * @param orderIds Array of order IDs to cancel
     * @dev Only callable when broker is active and by the owner of all orders
     */
    function cancelOrders(OrderId[] calldata orderIds) external nonReentrant {
        IOrderManager orderManager = _getOrderManager();
        if (!orderManager.isAllOrderOwner(orderIds, _msgOrigin())) revert Errors.NotOrderOwner();

        orderManager.cancelOrders(orderIds);
    }

    /**
     * @notice Updates an existing trading order
     * @param params Parameters for updating the order
     * @dev Only callable when broker is active and by the order owner
     */
    function updateOrder(
        OrderTypes.DepositParams calldata depositParams,
        OrderTypes.UpdateOrderParams calldata params
    ) external onlyActiveBroker(params.broker) nonReentrant {
        IOrderManager orderManager = _getOrderManager();
        address user = _msgOrigin();
        if (!orderManager.isOrderOwner(params.orderId, user)) revert Errors.NotOrderOwner();

        _handleDeposit(depositParams, user);
        orderManager.updateOrder(params);
    }

    /**
     * @notice Adjusts the collateral of a trading position
     * @param positionId ID of the position to adjust
     * @param adjustAmount Amount to adjust (positive to add, negative to remove)
     * @dev Only callable when broker is active and by the position owner
     */
    function adjustCollateral(
        OrderTypes.DepositParams calldata depositParams,
        PositionId positionId,
        int256 adjustAmount
    ) external payable nonReentrant {
        IPositionManager positionManager = _getPositionManager();
        address owner = positionManager.getPositionOwner(positionId);
        if (owner != _msgOrigin()) revert Errors.NotPositionOwner();

        _handleDeposit(depositParams, owner);
        positionManager.adjustCollateral(positionId, adjustAmount);
    }

    /// @inheritdoc ITradingRouter
    function collectExecutionFee(ICollectFee.FeeSource source, bytes memory data, address feeRecipient) external override onlyExecutor {
        address executeFeeToken;
        uint256 executionFee;
        PositionId positionId;
        address account;

        if (source == ICollectFee.FeeSource.Position) {
            ICollectFee.PositionFeeParams memory params = abi.decode(data, (ICollectFee.PositionFeeParams));
            executeFeeToken = params.feeToken;
            executionFee = _getMarketManager().getExecutionFeeByToken(params.feeToken);
            if (executionFee > 0) {
                ITradingVault(params.tradingVault).chargePositionFees(params.positionId, executeFeeToken, executionFee, feeRecipient);
                _chargeRiskControllerData(params.positionId, executionFee);
                positionId = params.positionId;
            }
        } else if (source == ICollectFee.FeeSource.Account) {
            ICollectFee.AccountFeeParams memory params = abi.decode(data, (ICollectFee.AccountFeeParams));
            executeFeeToken = params.feeToken;
            executionFee = _getMarketManager().getExecutionFeeByToken(params.feeToken);
            if (executionFee > 0) {
                IAccount(_getDependencyAddress(Identifier.ACCOUNT)).payWithPrincipal(
                    params.poolId,
                    params.user,
                    params.feeToken,
                    executionFee,
                    feeRecipient
                );
                account = params.user;
            }
        } else if (source == ICollectFee.FeeSource.Direct) {
            ICollectFee.AddressFeeParams memory params = abi.decode(data, (ICollectFee.AddressFeeParams));
            executeFeeToken = params.feeToken;
            executionFee = _getMarketManager().getExecutionFeeByToken(params.feeToken);
            if (executionFee > 0) {
                IERC20(params.feeToken).safeTransferFrom(params.user, feeRecipient, executionFee);
                account = params.user;
            }
        }

        address designatedToken = ICollectFee(feeRecipient).getDesignatedToken();
        require(executeFeeToken == designatedToken, Errors.DesignatedTokenMismatch(executeFeeToken, designatedToken));
        emit CollectExecutionFee(source, positionId, account, executionFee, executeFeeToken);
    }

    /// @inheritdoc ITradingRouter
    function collectForwardFeeIfNecessary(ICollectFee.FeeSource source, bytes memory data) external override onlyAllowedTarget {
        _collectForwardFeeIfNecessary(source, data);
    }

    /**
     * @notice Handles the deposit of tokens from the broker
     * @param depositParams Parameters for the deposit
     * @param user Address of the user making the deposit
     * @dev Only deposits if the token is not the zero address and the amount is greater than zero
     */
    function _handleDeposit(OrderTypes.DepositParams calldata depositParams, address user) internal {
        if (depositParams.token != address(0) && depositParams.amount > 0) {
            _depositFor(user, depositParams.token, depositParams.amount, user);
        }
    }

    function _depositFor(address user, address token, uint256 amount, address recipient) internal {
        address account = _getDependencyAddress(Identifier.ACCOUNT);

        IERC20(token).safeTransferFrom(user, address(this), amount);
        IERC20(token).forceApprove(account, amount);
        IAccount(account).deposit(recipient, token, amount);
    }

    function _collectForwardFeeIfNecessary(ICollectFee.FeeSource source, bytes memory data) internal {
        IForwarder forwarder = _getForwarder();
        if (!forwarder.inForwardMode()) return;

        address to = _getPayMasterAddress();
        address designatedToken = ICollectFee(address(forwarder)).getDesignatedToken();
        address forwardFeeToken;
        uint256 forwardFee;
        PositionId positionId;
        address account;

        if (source == ICollectFee.FeeSource.Position) {
            ICollectFee.PositionFeeParams memory params = abi.decode(data, (ICollectFee.PositionFeeParams));
            forwardFeeToken = params.feeToken;
            forwardFee = _getMarketManager().getForwardFeeByToken(forwardFeeToken);
            if (forwardFee > 0) {
                ITradingVault(params.tradingVault).chargePositionFees(params.positionId, forwardFeeToken, forwardFee, to);
                _chargeRiskControllerData(params.positionId, forwardFee);
                positionId = params.positionId;
            }
        } else if (source == ICollectFee.FeeSource.Account) {
            ICollectFee.AccountFeeParams memory params = abi.decode(data, (ICollectFee.AccountFeeParams));
            forwardFeeToken = params.feeToken;
            forwardFee = _getMarketManager().getForwardFeeByToken(forwardFeeToken);
            if (forwardFee > 0) {
                IAccount(_getDependencyAddress(Identifier.ACCOUNT)).payWithPrincipal(params.poolId, params.user, params.feeToken, forwardFee, to);
                account = params.user;
            }
        } else if (source == ICollectFee.FeeSource.Direct) {
            ICollectFee.AddressFeeParams memory params = abi.decode(data, (ICollectFee.AddressFeeParams));
            forwardFeeToken = params.feeToken == address(0) ? designatedToken : params.feeToken;
            forwardFee = _getMarketManager().getForwardFeeByToken(forwardFeeToken);
            if (forwardFee > 0) {
                IERC20(forwardFeeToken).safeTransferFrom(params.user, to, forwardFee);
                account = params.user;
            }
        }

        // Make sure only charge once fee per tx;
        forwarder.exitForwardMode();
        require(forwardFeeToken == designatedToken, Errors.DesignatedTokenMismatch(forwardFeeToken, designatedToken));
        emit CollectForwardFee(source, positionId, account, forwardFee, forwardFeeToken);
    }

    function _chargeRiskControllerData(PositionId positionId, uint256 fee) internal {
        IPositionManager positionManager = _getPositionManager();

        IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER)).chargePositionRiskControlData(
            positionManager.getPosition(positionId),
            positionId,
            positionManager.getPositionOwner(positionId),
            -int256(fee)
        );
    }

    function _onlyExecutor() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.EXECUTOR), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyActiveBroker(address broker) internal view {
        require(IBrokerManager(_getDependencyAddress(Identifier.BROKER_MANAGER)).isActiveBroker(broker), Errors.NotActiveBroker(broker));
    }

    function _onlyAllowedTarget() internal view {
        require(
            IForwarder(_getDependencyAddress(Identifier.FORWARDER)).isAllowedTargets(msg.sender) ||
                msg.sender == _getDependencyAddress(Identifier.ORDER_MANAGER) ||
                msg.sender == _getDependencyAddress(Identifier.POSITION_MANAGER),
            Errors.NotForwardAllowedTarget(msg.sender)
        );
    }

    function _getPayMasterAddress() internal view returns (address) {
        return _getDependencyAddress(Identifier.PAYMASTER);
    }

    function _getForwarder() internal view returns (IForwarder) {
        return IForwarder(_getDependencyAddress(Identifier.FORWARDER));
    }

    function _getMarketManager() internal view returns (IMarketManager) {
        return IMarketManager(_getDependencyAddress(Identifier.MARKET_MANAGER));
    }

    function _getOrderManager() internal view returns (IOrderManager) {
        return IOrderManager(_getDependencyAddress(Identifier.ORDER_MANAGER));
    }

    function _getPositionManager() internal view returns (IPositionManager) {
        return IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER));
    }
}

