// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { TxId } from "../types/Types.sol";
import { IOracle } from "./IOracle.sol";

interface IForwarder {
    struct ForwardRequestData {
        address from;
        address to;
        uint256 value;
        uint256 gas;
        uint48 deadline;
        bytes data;
        bytes signature;
    }

    event ChargeForwardFee(address account, address feeToken, uint256 relayFee);
    event AddAllowedTarget(address target);
    event RemoveAllowedTarget(address target);
    event UpdateMaxRelayFee(address sender, uint256 oldMaxRelayFee, uint256 newMaxRelayFee);
    event UpdateAcquiescentFeeToken(
        address sender,
        address oldRelayGas,
        address newRelayGas
    );
    event UpdateEquilibriumGas(
        address sender,
        uint256 oldRelayGas,
        uint256 newRelayGas
    );
    event SetUserRelayer(address account, address relayer, bool enable);
    event ERC20PermitFailed(address token, string reason);
    event ERC20PermitLowLevelFailed(bytes data);

    error RemoveRelayerFailed();
    error ExceedsMaximumRelayFee();
    error InconsistentParamsLength();
    error RelayerRegistered(address relayer);
    error NotAllowedTarget(address target);
    error MismatchedSender(address sender);
    error InsufficientFeeBalance(address user, uint256 balance, uint256 required);
    error InsufficientFeeAllowance(address user, uint256 allowance, uint256 required);

    struct ERC20PermitParams {
        address token;
        address owner;
        address spender;
        uint256 value;
        uint256 deadline;
        uint8 v;
        bytes32 r;
        bytes32 s;
    }

    function exitForwardMode() external;

    function addAllowedTarget(address target) external;

    function removeAllowedTarget(address target) external;

    function inForwardMode() external view returns (bool);

    function isAllowedTargets(address contractAddr) external view returns (bool);

    function getAllowedTargets() external view returns (address[] memory);

    function getEquilibriumGas() external view returns (uint256);

    function getUserRelayers(address account) external view returns (address[] memory);

    function isUserRelayerEnabled(address account, address relayer) external view returns (bool);

    function permitAndApproveForwarder(address relayer, bool enable, ERC20PermitParams[] calldata permitParams) external;

    function executeForwarderTx(
        TxId txId,
        address operator,
        IOracle.UpdateOraclePriceParams[] calldata params
    ) external payable;

    function batchExecuteForwarderTx(
        TxId[] calldata txIds,
        IOracle.UpdateOraclePriceParams[] calldata params
    ) external payable;

    function batchExecuteForwarder(address forwardFeeToken, ForwardRequestData[] calldata bundleParams) external payable;

    function executeForwarder(address forwardFeeToken, ForwardRequestData calldata params) external payable;
}

