 */
interface IMYXBroker is IBroker {
    struct UpdateSpecialFeeTierParams {
        AssetClass assetClass;
        uint8 riskTier;
        uint8 feeTier;
        int32 makerFeeRate;
        uint32 takerFeeRate;
    }

    /**
     * @notice Gets the list of active special fee tiers
