     */
    function activeSpecialFeeTierList(AssetClass assetClass, uint8 riskTier) external view returns (uint256[] memory);

    /**
     * @notice Gets the fee rates for a special fee tier
     * @param assetClass Asset class for the fee tier
     * @param riskTier Risk tier for the fee tier
     * @param feeTier The fee tier to get the rates for
     * @return makerFeeRate Maker fee rate for the tier (can be negative for rebates)
     * @return takerFeeRate Taker fee rate for the tier (always positive)
     */
    function getSpecialFeeTier(AssetClass assetClass, uint8 riskTier, uint8 feeTier) external view returns (int32 makerFeeRate, uint32 takerFeeRate);
}

