// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IRiskController } from "./../interfaces/IRiskController.sol";
import { Constants, PoolId } from "./../types/Types.sol";
import { Errors, PositionId } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";

library RiskControl {
    using RiskControl for Data;
    using PrecisionUtils for uint256;
    using SignedMath for int256;
    using Math for uint256;
    using SafeCast for int256;

    struct Data {
        mapping(PoolId => uint256 caseCounter) _poolDisputeCaseCounter;
        mapping(PoolId => IRiskController.LiquidityLock) _poolLiquidityLock;
        mapping(PoolId => mapping(address user => IRiskController.ProfitLock)) _poolProfitLock;
        mapping(PositionId positionId => IRiskController.PositionRiskControlData data) _positionRiskControlData;
    }

    function recordDisputeCase(Data storage self, PoolId poolId, bool dispute) internal {
        if (dispute) {
            self._poolDisputeCaseCounter[poolId]++;
        } else {
            require(self._poolDisputeCaseCounter[poolId] > 0, Errors.NoActiveDispute());
            self._poolDisputeCaseCounter[poolId]--;
        }
    }

    function updateLiquidityLock(
        Data storage self,
        PoolId poolId,
        uint64 windowAnchor,
        uint64 liquidityWindowSize,
        uint16 priceRangePct,
        uint256 orderPrice,
        int256 orderUsedOI
    ) internal returns (IRiskController.LiquidityLock memory) {
        uint64 lastWindowAnchor = self.getLiquidityWindowAnchor(poolId);
        (uint256 floor, uint256 ceiling) = self.getLiquidityPriceRange(poolId);

        if (orderPrice >= floor && orderPrice <= ceiling && lastWindowAnchor + liquidityWindowSize > windowAnchor) {
            self._poolLiquidityLock[poolId].openInterest += orderUsedOI;
        } else {
            self._poolLiquidityLock[poolId] = _refreshLiquidityLock(windowAnchor, orderPrice, priceRangePct, orderUsedOI);
        }
        return self._poolLiquidityLock[poolId];
    }

    function updateProfitLock(
        Data storage self,
        PoolId poolId,
        address user,
        uint64 releaseTime,
        uint256 baseAmount,
        int256 quoteAmount,
        int256 profitChange
    ) internal returns (IRiskController.ProfitLock memory) {
        IRiskController.ProfitLock storage profitLock = self._poolProfitLock[poolId][user];

        profitLock.baseAmount += baseAmount;
        profitLock.quoteAmount = SafeCast.toUint256(int256(profitLock.quoteAmount) + quoteAmount);
        profitLock.usedQuoteAmount = SafeCast.toUint256(int256(profitLock.usedQuoteAmount) + profitChange);
        profitLock.releaseTime = releaseTime;
        return profitLock;
    }

    function releaseProfitLock(Data storage self, PoolId poolId, address user) internal returns (uint256, uint256) {
        IRiskController.ProfitLock memory profitLock = self._poolProfitLock[poolId][user];
        require(profitLock.quoteAmount >= profitLock.usedQuoteAmount, Errors.InvalidProfitLock());

        uint256 baseAmount = profitLock.baseAmount;
        uint256 quoteAmount = profitLock.quoteAmount - profitLock.usedQuoteAmount;

        delete self._poolProfitLock[poolId][user];
        return (baseAmount, quoteAmount);
    }

    function freezeProfits(Data storage self, PoolId poolId, address[] calldata users) internal {
        for (uint256 i = 0; i < users.length; ++i) {
            self._poolProfitLock[poolId][users[i]].frozen = true;
        }
    }

    function unfreezeProfits(Data storage self, PoolId poolId, address user) internal {
        self._poolProfitLock[poolId][user].frozen = false;
    }

    function confiscateProfits(Data storage self, PoolId poolId, address[] calldata users) internal {
        for (uint256 i = 0; i < users.length; ++i) {
            delete self._poolProfitLock[poolId][users[i]];
        }
    }

    function getFrozen(Data storage self, PoolId poolId, address user) internal view returns (bool) {
        return self._poolProfitLock[poolId][user].frozen;
    }

    function createPositionRiskControlData(
        Data storage self,
        PositionId positionId,
        PoolId poolId,
        address user,
        int256 freeAmount,
        int256 lockedAmount
    ) internal returns (IRiskController.PositionRiskControlData memory) {
        IRiskController.PositionRiskControlData storage collateralInfo = self._positionRiskControlData[positionId];
        IRiskController.ProfitLock storage profitLock = self._poolProfitLock[poolId][user];

        collateralInfo.freeAmount = SafeCast.toUint256(int256(collateralInfo.freeAmount) + freeAmount);
        collateralInfo.lockedAmount = SafeCast.toUint256(int256(collateralInfo.lockedAmount) + lockedAmount);
        profitLock.usedQuoteAmount = SafeCast.toUint256(int256(profitLock.usedQuoteAmount) + lockedAmount);
        return collateralInfo;
    }

    function updatePositionRiskControlData(
        Data storage self,
        PositionId positionId,
        int256 freeAmount,
        int256 lockedAmount
    ) internal returns (IRiskController.PositionRiskControlData memory) {
        IRiskController.PositionRiskControlData storage collateralInfo = self._positionRiskControlData[positionId];

        collateralInfo.freeAmount = SafeCast.toUint256(int256(collateralInfo.freeAmount) + freeAmount);
        collateralInfo.lockedAmount = SafeCast.toUint256(int256(collateralInfo.lockedAmount) + lockedAmount);
        return collateralInfo;
    }

    function closePositionRiskControlData(Data storage self, PositionId positionId, PoolId poolId, address user, uint256 lockedAmount) internal {
        if (lockedAmount != 0) {
            IRiskController.ProfitLock storage profitLock = self._poolProfitLock[poolId][user];
            profitLock.usedQuoteAmount -= lockedAmount;
        }
        delete self._positionRiskControlData[positionId];
    }

    function releasePositionCollateralProfit(Data storage self, bytes32[] memory positionIds) internal {
        for (uint256 i = 0; i < positionIds.length; ++i) {
            IRiskController.PositionRiskControlData storage collateralInfo = self._positionRiskControlData[PositionId.wrap(positionIds[i])];
            collateralInfo.freeAmount += collateralInfo.lockedAmount;
            collateralInfo.lockedAmount = 0;
        }
    }

    function migratePositionRiskControlData(Data storage self, PositionId fromId, PositionId toId) internal {
        IRiskController.PositionRiskControlData memory data = self._positionRiskControlData[fromId];

        if (PositionId.unwrap(fromId) != PositionId.unwrap(toId)) {
            self._positionRiskControlData[toId] = data;
            delete self._positionRiskControlData[fromId];
        }
    }

    function getPositionRiskControlData(
        Data storage self,
        PositionId positionId
    ) internal view returns (IRiskController.PositionRiskControlData memory) {
        return self._positionRiskControlData[positionId];
    }

    function _refreshLiquidityLock(
        uint64 windowAnchor,
        uint256 orderOpenPrice,
        uint16 priceRangePct,
        int256 orderUsedUsd
    ) internal pure returns (IRiskController.LiquidityLock memory) {
        uint256 riskPricePrecision = Constants.RISK_PRICE_RANGE_PRECISION;
        uint256 priceFloor = orderOpenPrice.mulPrecision(riskPricePrecision - priceRangePct, riskPricePrecision);
        uint256 priceCeiling = orderOpenPrice.mulPrecision(riskPricePrecision + priceRangePct, riskPricePrecision);

        return
            IRiskController.LiquidityLock({
                windowAnchor: windowAnchor,
                priceFloor: priceFloor,
                priceCeiling: priceCeiling,
                openInterest: orderUsedUsd
            });
    }

    function getLiquidityWindowAnchor(Data storage self, PoolId poolId) internal view returns (uint64) {
        return self._poolLiquidityLock[poolId].windowAnchor;
    }

    function getLiquidityPriceRange(Data storage self, PoolId poolId) internal view returns (uint256 floor, uint256 ceiling) {
        floor = self._poolLiquidityLock[poolId].priceFloor;
        ceiling = self._poolLiquidityLock[poolId].priceCeiling;
    }

    function getDisputeCaseCount(Data storage self, PoolId poolId) internal view returns (uint256) {
        return self._poolDisputeCaseCounter[poolId];
    }

    function getDisputeMode(Data storage self, PoolId poolId) internal view returns (bool) {
        return self._poolDisputeCaseCounter[poolId] > 0;
    }

    function getLiquidityLock(Data storage self, PoolId poolId) internal view returns (IRiskController.LiquidityLock memory) {
        return self._poolLiquidityLock[poolId];
    }

    function getProfitLock(Data storage self, PoolId poolId, address account) internal view returns (IRiskController.ProfitLock memory) {
        return self._poolProfitLock[poolId][account];
    }

    function isProfitLockExpired(Data storage self, PoolId poolId, address user, uint64 blockTimestamp) internal view returns (bool) {
        return self._poolProfitLock[poolId][user].releaseTime <= blockTimestamp;
    }

    function isProfitLocked(Data storage self, PoolId poolId, address user) internal view returns (bool) {
        return self._poolProfitLock[poolId][user].releaseTime != 0;
    }
}

