// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IAddressManager } from "./../interfaces/IAddressManager.sol";
import { IKeeperRegistry } from "./../interfaces/IKeeperRegistry.sol";
import { IOracle } from "./../interfaces/IOracle.sol";
import { IPoolConfigurator } from "./../interfaces/IPoolConfigurator.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IRoleManager } from "./../interfaces/IRoleManager.sol";
import { Identifier } from "./../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";
import { Errors, PoolId, OracleType } from "./../types/Types.sol";

/// @title PoolConfigurator
/// @notice Contract for configuring pool parameters and managing pool lifecycle
contract PoolConfigurator is BaseContractUpgradeable, IPoolConfigurator {
    modifier onlyListingAdmin() {
        _onlyListingAdmin();
        _;
    }

    modifier onlyListingAdminOrKeeper() {
        _onlyListingAdminOrKeeper();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the pool configurator contract
    /// @param addressManager Address manager contract address
    function initialize(address addressManager) external initializer {
        bytes32[] memory identifiers = new bytes32[](3);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.ORACLE;
        identifiers[2] = Identifier.KEEPER_REGISTRY;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    /// @notice Prime a pool from boost to activate it for trading
    /// @param params Pool priming parameters
    function primePoolFromBoost(IPoolManager.PrimePoolFromBoostedParams calldata params) external onlyListingAdmin {
        _getPoolManager().primePoolFromBoost(params);
    }

    /// @notice Prime a pool to activate it for trading
    /// @param params Pool priming parameters
    function primePool(IPoolManager.PrimePoolParams calldata params) external onlyListingAdmin {
        _getPoolManager().primePool(params);
    }

    /// @notice Trench a pool to make it active for trading
    /// @param params Pool trenching parameters
    function trenchPool(IPoolManager.TrenchPoolParams calldata params) external onlyListingAdmin {
        _getPoolManager().trenchPool(params);
        _getOracle().setOracleFeedParameter(
            IOracle.OracleFeedParameter({
                poolId: params.poolId,
                oracleType: params.oracleType,
                oracleFeedId: params.oracleFeedId,
                decimals: params.oracleDecimals,
                active: true
            })
        );
    }

    /// @notice Move a pool to pre-bench state
    /// @param params Pool pre-bench parameters
    function perBenchPool(IPoolManager.PerBenchPoolParams calldata params) external onlyListingAdmin {
        _getPoolManager().perBenchPool(params);
    }

    /// @notice Move a pool to bench state
    /// @param params Pool bench parameters
    function benchPool(
        IOracle.UpdateOraclePriceParams[] calldata prices,
        IPoolManager.BenchPoolParams calldata params
    ) external payable onlyListingAdmin {
        _getPoolManager().benchPool{ value: msg.value }(prices, params);
    }

    /// @notice Set the oracle feed id for a pool
    /// @param params Oracle feed id update parameters
    function setOracleFeedParameters(IOracle.OracleFeedParameter[] calldata params) external onlyListingAdmin {
        for (uint256 i = 0; i < params.length; ++i) {
            if (!_getPoolManager().checkPoolExists(params[i].poolId)) revert Errors.PoolNotExist(params[i].poolId);
            _getOracle().setOracleFeedParameter(params[i]);
        }
    }

    /// @notice Switch the active oracle type for a pool
    /// @param poolId Pool to switch active oracle type for
    /// @param oracleType New active oracle type
    function switchActiveOracleType(PoolId poolId, OracleType oracleType) external onlyListingAdmin {
        if (!_getPoolManager().checkPoolExists(poolId)) revert Errors.PoolNotExist(poolId);
        _getOracle().switchActiveOracleType(poolId, oracleType);
    }

    /// @notice Update pool risk tiers for multiple pools
    /// @param params Array of pool risk tier update parameters
    function updatePoolRiskTiers(UpdatePoolRiskTierParams[] calldata params) external onlyListingAdminOrKeeper {
        _getPoolManager().updatePoolRiskTiers(params);
        emit PoolRiskTiersUpdated(params);
    }

    /// @notice Update pool compound enabled status for multiple pools
    /// @param params Array of pool compound enabled update parameters
    function updatePoolCompoundEnabled(UpdatePoolCompoundEnabledParams[] calldata params) external onlyListingAdmin {
        _getPoolManager().updatePoolCompoundEnabled(params);
        emit PoolCompoundEnabledUpdated(params);
    }

    function _onlyListingAdmin() internal view {
        require(_isListingAdmin(_getAddressManager()), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyListingAdminOrKeeper() internal view {
        IAddressManager addressManager = _getAddressManager();
        require(_isListingAdmin(addressManager) || isKeeper(), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _isListingAdmin(IAddressManager addressManager) internal view returns (bool) {
        return IRoleManager(addressManager.getRoleManager()).isListingAdmin(msg.sender);
    }

    function isKeeper() internal view returns (bool) {
        return IKeeperRegistry(_getDependencyAddress(Identifier.KEEPER_REGISTRY)).isKeeper(msg.sender);
    }

    function _getPoolManager() internal view returns (IPoolManager poolManager) {
        return IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getOracle() internal view returns (IOracle oracle) {
        return IOracle(_getDependencyAddress(Identifier.ORACLE));
    }
}

