// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

/**
 * @title CompositeKey
 * @notice Generic library for packing two uint8 values into a single uint16 using bitwise operations
 * @dev Provides utilities to pack and unpack two uint8 values (high byte and low byte) into/from a uint16 key.
 *      Key structure: [high byte (8 bits)][low byte (8 bits)]
 *      - High byte: 0-255 (bits 8-15)
 *      - Low byte: 0-255 (bits 0-7)
 */
library CompositeKey {
    /// @notice Bit shift amount for high byte (8 bits)
    uint8 internal constant HIGH_BYTE_SHIFT = 8;
    /// @notice Mask for extracting low byte (lower 8 bits: 0xFF)
    uint16 internal constant LOW_BYTE_MASK = 0xFF;

    /**
     * @notice Pack two uint8 values into a single uint16 key
     * @dev Uses bit shifting and OR: (highByte << 8) | lowByte
     * @param highByte First value (stored in high byte, bits 8-15)
     * @param lowByte Second value (stored in low byte, bits 0-7)
     * @return key Packed uint16 key containing both values
     */
    function pack(uint8 highByte, uint8 lowByte) internal pure returns (uint16 key) {
        return (uint16(highByte) << HIGH_BYTE_SHIFT) | uint16(lowByte);
    }

    /**
     * @notice Extract high byte from packed key
     * @dev Uses right shift: key >> 8
     * @param key Packed key
     * @return highByte First value from high byte (bits 8-15)
     */
    function unpackHigh(uint16 key) internal pure returns (uint8 highByte) {
        return uint8(key >> HIGH_BYTE_SHIFT);
    }

    /**
     * @notice Extract low byte from packed key
     * @dev Uses masking: key & 0xFF
     * @param key Packed key
     * @return lowByte Second value from low byte (bits 0-7)
     */
    function unpackLow(uint16 key) internal pure returns (uint8 lowByte) {
        return uint8(key & LOW_BYTE_MASK);
    }
}

