// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { OwnableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IKeeperRegistry } from "./../interfaces/IKeeperRegistry.sol";
import { BaseContractUpgradeable } from "./../misc/base/BaseContractUpgradeable.sol";

/// @title KeeperRegistry
/// @notice Maintains the whitelist of authorized Keeper contracts.
contract KeeperRegistry is BaseContractUpgradeable, OwnableUpgradeable, IKeeperRegistry {
    using EnumerableSetLib for EnumerableSetLib.AddressSet;

    EnumerableSetLib.AddressSet private _keepers;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, address initialOwner) external initializer {
        __BaseContractUpgradeable_init(addressManager, new bytes32[](0));
        __Ownable_init(initialOwner);
    }

    /// @inheritdoc IKeeperRegistry
    function addKeeper(address keeper) external onlyOwner {
        _keepers.add(keeper);
        emit KeeperAdded(keeper);
    }

    /// @inheritdoc IKeeperRegistry
    function removeKeeper(address keeper) external onlyOwner {
        _keepers.remove(keeper);
        emit KeeperRemoved(keeper);
    }

    /// @inheritdoc IKeeperRegistry
    function isKeeper(address addr) external view returns (bool) {
        return _keepers.contains(addr);
    }

    /// @inheritdoc IKeeperRegistry
    function getKeepers() external view returns (address[] memory) {
        return _keepers.values();
    }
}

