// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { IAddressManager } from "./../../interfaces/IAddressManager.sol";

abstract contract BaseContract is Initializable {
    /// @custom:storage-location erc7201:myx.storage.Context
    struct ContextStorage {
        address addressManager;
        // Map of dependency contract addresses (identifier => contractAddress)
        mapping(bytes32 identifier => address contractAddress) _dependencyAddresses;
    }

    error NotProxyAdmin();
    error NotDependencyManager();
    error NotAddressManager();

    // keccak256(abi.encode(uint256(keccak256("myx.storage.Context")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant CONTEXT_STORAGE_LOCATION = 0x37a638a97105990ccbf07e915d5cb44d12d4fab43160743b7bf94b2fc57a6c00;

    function __BaseContract_init(address addressManager, bytes32[] memory initDependencies) internal onlyInitializing {
        ContextStorage storage $ = _getContextStorage();
        $.addressManager = addressManager;
        _registerDependencies($, initDependencies);
    }

    function getAddressManager() external view returns (IAddressManager) {
        return _getAddressManager();
    }

    function getDependencyAddress(bytes32 identifier) external view returns (address) {
        return _getDependencyAddress(identifier);
    }

    function _getAddressManager() internal view returns (IAddressManager) {
        return IAddressManager(_getContextStorage().addressManager);
    }

    function _getDependencyAddress(bytes32 identifier) internal view returns (address) {
        return _getContextStorage()._dependencyAddresses[identifier];
    }

    function _registerDependencies(bytes32[] memory identifiers) internal {
        ContextStorage storage $ = _getContextStorage();
        _registerDependencies($, identifiers);
    }

    function _registerDependencies(ContextStorage storage $, bytes32[] memory identifiers) private {
        if (identifiers.length == 0) return;

        IAddressManager addressManager = IAddressManager($.addressManager);
        address[] memory contractAddresses = addressManager.getAddresses(identifiers);
        for (uint256 i = 0; i < identifiers.length; ++i) {
            $._dependencyAddresses[identifiers[i]] = contractAddresses[i];
        }
    }

    function _getContextStorage() private pure returns (ContextStorage storage $) {
        assembly {
            $.slot := CONTEXT_STORAGE_LOCATION
        }
        return $;
    }
}

