// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { CaseId, VotingOption, Resolution } from "./../types/Types.sol";

interface ICourtVoting {

    struct ReimbursementProposal {
        bytes32 merkleRoot;
        uint256 totalBaseAmount;
        uint256 totalQuoteAmount;
    }

    struct VoteSession {
        bool opened;
        EnumerableSetLib.AddressSet votedValidators;
        mapping(address validator => VotingOption option) validatorOptions;
    }

    /// @notice Emitted when vote configuration is updated.
    event VoteConfigUpdated(uint32 voteCountRate, uint32 effectiveVoteRate);

    /// @notice Emitted when a dispute-vote session is opened for a case.
    event DisputeVoteOpened(CaseId indexed caseId);

    /// @notice Emitted when a validator casts a dispute vote.
    event DisputeVoteSubmitted(CaseId indexed caseId, address indexed validator, VotingOption option);

    /// @notice Emitted when a reimbursement-vote session is opened for a case.
    event ReimbursementVoteOpened(CaseId indexed caseId, bytes32 merkleRoot, uint256 totalBaseAmount, uint256 totalQuoteAmount);

    /// @notice Emitted when a validator casts a reimbursement vote.
    event ReimbursementVoteSubmitted(CaseId indexed caseId, address indexed validator, VotingOption option);

    function voteCountRate() external view returns (uint32);

    function effectiveVoteRate() external view returns (uint32);

    function updateVoteConfig(uint32 voteCountRate, uint32 effectiveVoteRate) external;

    function openDisputeVote(CaseId caseId) external;

    function submitDisputeVote(
        CaseId caseId,
        address validator,
        VotingOption option,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external;

    function submitReimbursementVote(
        CaseId caseId,
        address validator,
        VotingOption option,
        bytes32 marketRoot,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external;

    function countDisputeVotes(
        CaseId caseId,
        address[] calldata validators
    ) external view returns (Resolution resolution);

    function openReimbursementVote(
        CaseId caseId,
        bytes32 merkleRoot,
        uint256 totalBaseAmount,
        uint256 totalQuoteAmount
    ) external;

    function countReimbursementVotes(
        CaseId caseId,
        address[] calldata validators
    ) external view returns (Resolution resolution);

    function resetReimbursementVote(CaseId caseId) external;

    function hasDisputeVoted(CaseId caseId, address validator) external view returns (bool);

    function getDisputeVoteOption(CaseId caseId, address validator) external view returns (VotingOption);

    function hasReimbursementVoted(CaseId caseId, address validator) external view returns (bool);

    function getReimbursementVoteOption(CaseId caseId, address validator) external view returns (VotingOption);

    function getReimbursementProposal(CaseId caseId) external view returns (ReimbursementProposal memory);
}

