// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { MarketMetadata } from "./../libraries/Market.sol";
import { PoolMetadata } from "./../libraries/Pool.sol";
import { MarketId, OracleType, PoolId } from "./../types/Types.sol";
import { IOracle } from "./IOracle.sol";
import { IPoolConfigurator } from "./IPoolConfigurator.sol";

/// @title IPoolManager
/// @notice Interface for pool lifecycle management and configuration
interface IPoolManager {
    /// @notice Parameters for deploying a new pool
    struct DeployPoolParams {
        // Market to deploy pool in
        MarketId marketId;
        // Base asset token address
        address baseToken;
    }

    /// @notice Parameters for priming a pool with initial liquidity
    struct PrimePoolParams {
        // Pool to prime
        PoolId poolId;
        // Reference price for the pool
        uint256 referencePrice;
    }

    /// @notice Parameters for boost a pool
    struct BoostPoolParams {
        // Pool to boost
        PoolId poolId;
    }

    /// @notice Parameters for unboost a pool
    struct UnboostPoolParams {
        // Pool to unboost
        PoolId poolId;
    }

    /// @notice Parameters for priming a pool with initial liquidity
    struct PrimePoolFromBoostedParams {
        // Pool to prime
        PoolId poolId;
    }

    /// @notice Parameters for re-priming a pool
    struct RePrimePoolParams {
        // Pool to re-prime
        PoolId poolId;
    }

    /// @notice Parameters for activating a pool (trench phase)
    struct TrenchPoolParams {
        // Pool to activate
        PoolId poolId;
        // Oracle feed identifier
        bytes32 oracleFeedId;
        // Oracle Price Decimals (Chainlink)
        uint32 oracleDecimals;
        // Type of oracle (Chainlink, Pyth, etc.)
        OracleType oracleType;
        // Risk tier level (0-255)
        uint8 riskTier;
    }

    /// @notice Parameters for pre-deactivating a pool (per-bench phase)
    struct PerBenchPoolParams {
        // Pool to pre-deactivate
        PoolId poolId;
        // Reason for pre-deactivation
        string remark;
    }

    /// @notice Parameters for deactivating a pool (bench phase)
    struct BenchPoolParams {
        // Pool to deactivate
        PoolId poolId;
        // Reason for deactivation
        string remark;
    }

    /// @notice Thrown when LP tokens are not fully minted
    error LPNotFullyMinted();
    /// @notice Thrown when pool still has open positions
    error PositionNotEmpty();
    /// @notice Thrown when pool is in unexpected state for operation
    error UnexpectedPoolState();
    /// @notice Thrown when base fees are not sold out
    error BaseFeeNotSoldOut();
    /// @notice Thrown when pool debt are not cleared
    error PoolDebtNotCleared();
    /// @notice Thrown when user unauthorized to unboost pool
    error UnauthorizedUnboost();

    /// @notice Check if a pool exists
    /// @param poolId Pool ID to check
    /// @return exists Whether the pool exists
    function checkPoolExists(PoolId poolId) external view returns (bool exists);

    /// @notice Get all pool IDs
    /// @return pools Array of pool ID bytes
    function getPools() external view returns (bytes32[] memory pools);

    /// @notice Get pool metadata by ID
    /// @param poolId Pool ID to query
    /// @return pool Pool metadata
    function getPool(PoolId poolId) external view returns (PoolMetadata memory pool);

    /// @notice Get pool for specific market and asset
    /// @param marketId Market ID
    /// @param asset Asset address
    /// @return pool Pool metadata
    function getMarketPool(MarketId marketId, address asset) external view returns (PoolMetadata memory pool);

    /// @notice Get market id for a pool
    /// @param poolId Pool ID
    /// @return marketId Market ID
    function getPoolMarketId(PoolId poolId) external view returns (MarketId marketId);

    /// @notice Get market metadata for a pool
    /// @param poolId Pool ID
    /// @return marketId Market ID
    /// @return market Market metadata
    function getPoolMarket(PoolId poolId) external view returns (MarketId marketId, MarketMetadata memory market);

    function getPoolMarketExecutionFee(PoolId poolId) external view returns (uint256 executionFee);

    function getPoolMarketForwardFee(PoolId poolId) external view returns (uint256 forwardFee);

    function getPairToken(PoolId poolId) external view returns (address baseToken, address quoteToken);

    function isPoolAddress(PoolId poolId, address addr) external view returns (bool);

    function getPoolVault(PoolId poolId) external view returns (address);

    function getTradingVault(PoolId poolId) external view returns (address);

    function getPoolRiskTier(PoolId poolId) external view returns (uint8);

    /// @notice Prime a pool from boost with initial liquidity
    /// @param params Priming parameters
    function primePoolFromBoost(PrimePoolFromBoostedParams calldata params) external;

    /// @notice Prime a pool with initial liquidity
    /// @param params Priming parameters
    function primePool(PrimePoolParams calldata params) external;

    /// @notice Activate a pool for trading (trench phase)
    /// @param params Activation parameters
    function trenchPool(TrenchPoolParams calldata params) external;

    /// @notice Pre-deactivate a pool (per-bench phase)
    /// @param params Pre-deactivation parameters
    function perBenchPool(PerBenchPoolParams calldata params) external;

    /// @notice Deactivate a pool (bench phase)
    /// @param prices Oracle price update parameters
    /// @param params Deactivation parameters
    function benchPool(IOracle.UpdateOraclePriceParams[] calldata prices, BenchPoolParams calldata params) external payable;

    /// @notice Update risk tiers for multiple pools
    /// @param params Array of risk tier update parameters
    function updatePoolRiskTiers(IPoolConfigurator.UpdatePoolRiskTierParams[] calldata params) external;

    /// @notice Update compound enabled status for multiple pools
    /// @param params Array of compound enabled update parameters
    function updatePoolCompoundEnabled(IPoolConfigurator.UpdatePoolCompoundEnabledParams[] calldata params) external;
}

