// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IEmiter } from "./../interfaces/IEmiter.sol";
import { IExecutor } from "./../interfaces/IExecutor.sol";
import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IOrderManager } from "./../interfaces/IOrderManager.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { LibPositionMetadata } from "./../libraries/Position.sol";
import { PositionHelper } from "./../libraries/PositionHelper.sol";
import {
    Errors,
    OrderMetadata,
    PositionMetadata,
    MarketMetadata,
    PoolMetadata,
    PoolId,
    OrderId,
    PositionId,
    Operation,
    OrderType,
    TriggerType,
    Direction,
    Constants
} from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";
import { TradeUtils } from "./../utils/TradeUtils.sol";
import { LibPoolMetadata } from "./Pool.sol";
import { TradingHelper } from "./TradingHelper.sol";

/// @title ExecuteHelper
/// @notice Helper library for order execution and validation logic
library ExecuteHelper {
    using PrecisionUtils for uint256;
    using LibPoolMetadata for PoolMetadata;
    using LibPositionMetadata for PositionMetadata;
    using Math for uint256;

    /// @notice ADL position execution parameters
    struct ADLPositionExecute {
        PositionId positionId;
        Direction direction;
        address owner;
        uint256 executeSize;
        uint256 executePrice;
        bool isLiquidation;
    }

    struct CalculateADLExecuteParams {
        IPositionManager positionManager;
        IFundingRate fundingRate;
        IPoolManager poolManager;
        IRiskParameter riskParameter;
        PoolMetadata pool;
        Direction orderDirection;
        OrderId orderId;
        uint256 needAdlNotional;
        uint256 marketPrice;
    }

    /// @notice Check if order execution should be interrupted due to various conditions
    /// @param orderManager Order manager contract
    /// @param positionManager Position manager contract
    /// @param order Order metadata to validate
    /// @param orderId Order ID being executed
    /// @param pool Pool metadata
    /// @param tradeLimit Risk parameter configuration
    /// @param marketPrice Current market price
    /// @return interrupt True if order execution should be interrupted
    function checkOrderInterrupt(
        IOrderManager orderManager,
        IPositionManager positionManager,
        OrderMetadata memory order,
        OrderId orderId,
        PoolMetadata memory pool,
        IRiskParameter.TradeLimitParams memory tradeLimit,
        PositionMetadata memory position,
        uint256 marketPrice
    ) internal returns (bool interrupt) {
        require(
            pool.isPoolInitialized() && (pool.isTrench() || (order.operation == Operation.Decrease && pool.isPreBench())),
            Errors.PoolNotActive(order.poolId)
        );
        require(order.size > 0, Errors.InvalidOrder(orderId));
        if (position.isInitialized() && order.user != positionManager.getPositionOwner(order.positionId)) {
            orderManager.uncompleteOrder(orderId, "Not position owner");
            return true;
        }

        bool marketOrderExpired = order.orderType == OrderType.Market && block.timestamp > order.createdAt + Constants.MAX_MARKET_ORDER_LIFETIME;
        if (marketOrderExpired) {
            orderManager.uncompleteOrder(orderId, "Order expired");
            return true;
        }

        if (order.operation == Operation.Increase && !TradingHelper.validateOrderSize(pool, tradeLimit.minTradeUsd, order.size, marketPrice)) {
            orderManager.uncompleteOrder(orderId, "Order size out of range");
            return true;
        }

        return checkPriceExecutableInterrupt(orderManager, order, orderId, marketPrice);
    }

    function checkPriceExecutableInterrupt(
        IOrderManager orderManager,
        OrderMetadata memory order,
        OrderId orderId,
        uint256 price
    ) internal returns (bool interrupt) {
        if (
            order.orderType == OrderType.Market &&
            !TradeUtils.validateOrderSlippage(order.operation, order.direction, order.price, price, order.slippagePct)
        ) {
            orderManager.uncompleteOrder(orderId, "Slippage exceeded");
            return true;
        } else if (order.orderType == OrderType.Limit || order.orderType == OrderType.Stop || order.orderType == OrderType.Conditional) {
            if (order.triggerType == TriggerType.GTE) {
                require(price >= order.price, Errors.NotReachedPrice(orderId, price, order.price, order.triggerType));
            } else if (order.triggerType == TriggerType.LTE) {
                require(price <= order.price, Errors.NotReachedPrice(orderId, price, order.price, order.triggerType));
            } else {
                orderManager.uncompleteOrder(orderId, "Invalid Order");
                return true;
            }
        }
    }

    function checkADLInterrupt(
        IEmiter emiter,
        IPositionManager positionManager,
        OrderMetadata memory order,
        OrderId orderId,
        PoolMetadata memory pool,
        PositionMetadata memory position,
        PositionId positionId,
        uint256 executeSize,
        uint256 executePrice
    ) internal returns (bool interrupt) {
        if (order.operation == Operation.Increase) return false;

        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(pool.poolId);
        if (hasEarlyClosePrice(position, oiTracker.tracker)) return false;

        if (!needADL(positionManager, pool, position.direction, executeSize, executePrice)) return false;

        emiter.emitOrderMarkedADL(
            IEmiter.OrderMarkedADLParams({ broker: order.broker, user: order.user, poolId: order.poolId, orderId: orderId, positionId: positionId })
        );
        return true;
    }

    function needADL(
        IPositionManager positionManager,
        PoolMetadata memory pool,
        Direction direction,
        uint256 executeSize,
        uint256 executePrice
    ) internal view returns (bool) {
        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(pool.poolId);
        (uint256 baseReservable, uint256 quoteReservable) = IPoolVault(pool.poolVault).reservable();

        if (direction == Direction.Long) {
            uint256 notional = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, executeSize.mulPrice(executePrice));
            return oiTracker.tracker < 0 && quoteReservable < notional;
        } else {
            return oiTracker.tracker > 0 && baseReservable < executeSize;
        }
    }

    function calculateExecutePrice(OrderMetadata memory order, uint256 marketPrice) internal pure returns (uint256) {
        if (order.orderType != OrderType.Limit) return marketPrice;

        bool isIncrease = order.operation == Operation.Increase;
        bool isLong = order.direction == Direction.Long;
        bool prefersLower = isIncrease == isLong && order.triggerType == TriggerType.LTE;
        return prefersLower ? Math.min(order.price, marketPrice) : Math.max(order.price, marketPrice);
    }

    function calculateExecuteSize(
        IPositionManager positionManager,
        IPoolVault poolVault,
        OrderMetadata memory order,
        MarketMetadata memory market,
        uint256 positionSize,
        uint256 executePrice
    ) internal view returns (uint256 executeSize, uint256 availableLiquiditySize) {
        executeSize = order.size - order.filledSize;
        availableLiquiditySize = TradingHelper.availableLiquiditySize(
            order.poolId,
            poolVault,
            positionManager,
            market.baseReserveRatio,
            market.quoteReserveRatio,
            order.operation,
            order.direction,
            executePrice
        );
        if (executeSize == 0) return (0, availableLiquiditySize);

        if (order.operation == Operation.Increase) {
            executeSize = Math.min(executeSize, availableLiquiditySize);
        } else if (order.operation == Operation.Decrease) {
            executeSize = Math.min(executeSize, positionSize);
        }

        if (order.postOnly) {
            uint256 makeableSize = TradingHelper.makeableSize(positionManager, order.poolId, order.operation, order.direction);
            executeSize = Math.min(executeSize, makeableSize);
        }
    }

    function calculateADLPositionExecute(
        CalculateADLExecuteParams memory params,
        IExecutor.ADLPositionParams[] memory adlPositions
    ) internal returns (ADLPositionExecute[] memory adlPositionExecutes, uint256 adlTotalNotional) {
        ADLPositionExecute[] memory tmpExecutes = new ADLPositionExecute[](adlPositions.length);
        uint256 adlExecuteCount;
        uint256 remaining = params.needAdlNotional;

        for (uint256 i = 0; i < adlPositions.length; ++i) {
            if (remaining == 0) break;

            IExecutor.ADLPositionParams memory adlPositionParams = adlPositions[i];

            (PositionMetadata memory position, bool isHealthy) = params.positionManager.preparePosition(
                adlPositionParams.positionId,
                params.pool,
                params.orderDirection,
                address(0),
                params.marketPrice,
                address(0),
                true,
                false
            );
            if (
                PoolId.unwrap(position.poolId) != PoolId.unwrap(params.pool.poolId) ||
                position.direction == params.orderDirection ||
                position.size == 0
            ) revert Errors.InvalidADLPosition(params.orderId, adlPositionParams.positionId);

            uint256 taken;
            (tmpExecutes[adlExecuteCount++], taken) = _solveADLExecute(params, adlPositionParams.positionId, position, isHealthy, remaining);
            adlTotalNotional += taken;
            remaining -= taken;
        }

        adlPositionExecutes = new ADLPositionExecute[](adlExecuteCount);
        for (uint256 i = 0; i < adlExecuteCount; ++i) {
            adlPositionExecutes[i] = tmpExecutes[i];
        }
    }

    function _solveADLExecute(
        CalculateADLExecuteParams memory params,
        PositionId positionId,
        PositionMetadata memory position,
        bool isHealthy,
        uint256 remaining
    ) private view returns (ADLPositionExecute memory exec, uint256 taken) {
        address owner = params.positionManager.getPositionOwner(positionId);
        uint256 executePrice =
            isHealthy
                ? params.marketPrice
                : PositionHelper.calculateLiquidationPrice(
                    position,
                    params.fundingRate,
                    ITradingVault(params.pool.tradingVault),
                    params.poolManager,
                    params.positionManager,
                    params.riskParameter.getPoolConfigParams(position.riskTier),
                    params.pool,
                    positionId,
                    params.marketPrice,
                    owner
                );
        taken = Math.min(position.size.mulPrice(executePrice), remaining);
        uint256 executeSize = taken == remaining ? remaining.divPriceCeil(executePrice) : position.size;
        exec = ADLPositionExecute({
            positionId: positionId,
            direction: position.direction,
            owner: owner,
            executeSize: executeSize,
            executePrice: executePrice,
            isLiquidation: !isHealthy
        });
    }

    /// @notice Check if position has early close price
    /// @return hasEarlyClosePrice Whether position has early close price
    function hasEarlyClosePrice(PositionMetadata memory position, int256 tracker) internal pure returns (bool) {
        // Early return if no early close price is set
        if (position.earlyClosePrice == 0) return false;

        // Check if tracker direction matches position direction
        return (position.direction == Direction.Long && tracker > 0) || (position.direction == Direction.Short && tracker < 0);
    }
}

