// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IAddressManager } from "./../interfaces/IAddressManager.sol";
import { Errors } from "./../types/Errors.sol";

/// @title TokenConverter
/// @notice Library for token conversion and swapping operations
library TokenConverter {
    using SafeERC20 for IERC20;

    /// @notice Parameters for token conversion
    /// @param src Source token address (address(0) for ETH)
    /// @param target Target contract address for conversion
    /// @param amount Amount of source token to convert
    /// @param minOut Minimum amount of output token expected
    /// @param data Encoded function call data for the target contract
    struct ConvertInParams {
        address src;
        address target;
        uint256 amount;
        uint256 minOut;
        bytes data;
    }

    function transferInAndConvert(
        IAddressManager /* addressManager */,
        ConvertInParams memory params,
        address tokenOut
    ) internal returns (uint256 amountOut) {
        transferTokenIn(params.src, address(this), params.amount);
        return convert(params, tokenOut);
    }

    function convert(ConvertInParams memory params, address tokenOut) internal returns (uint256 amountOut) {
        amountOut = IERC20(tokenOut).balanceOf(address(this));
        bool success;

        if (params.src == address(0)) {
            (success, ) = params.target.call{ value: params.amount }(params.data);
        } else {
            IERC20(params.src).forceApprove(params.target, params.amount);
            (success, ) = params.target.call(params.data);
        }

        if (!success) {
            assembly {
                let ptr := mload(0x40)
                let size := returndatasize()
                returndatacopy(ptr, 0, size)
                revert(ptr, size)
            }
        }

        amountOut = IERC20(tokenOut).balanceOf(address(this)) - amountOut;
        require(params.minOut <= amountOut, Errors.InsufficientOutputAmount());
    }

    function convertToETH(ConvertInParams memory params) internal returns (uint256 ethOut) {
        ethOut = address(this).balance;
        bool success;

        if (params.src == address(0)) {
            (success, ) = params.target.call{ value: params.amount }(params.data);
        } else {
            IERC20(params.src).forceApprove(params.target, params.amount);
            (success, ) = params.target.call(params.data);
        }

        if (!success) {
            assembly {
                let ptr := mload(0x40)
                let size := returndatasize()
                returndatacopy(ptr, 0, size)
                revert(ptr, size)
            }
        }

        ethOut = address(this).balance - ethOut;
    }

    function transferTokenIn(address token, address receiver, uint256 amount) internal returns (uint256) {
        IERC20(token).safeTransferFrom(msg.sender, receiver, amount);
        return amount;
    }
}

