pragma solidity ^0.8.30;

import { IAddressManager } from "./../../interfaces/IAddressManager.sol";
import { IBasePool } from "./../../interfaces/IBasePool.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { TokenBase } from "./TokenBase.sol";

contract BasePoolToken is TokenBase {
    /**
     * @notice Hook called before token transfer to update rebate indices
     * @param from Address tokens are transferred from
     * @param to Address tokens are transferred to
     * @param amount Amount of tokens being transferred
     */
    function _update(address from, address to, uint256 amount) internal override {
        // Only handle actual transfers (not mint/burn, not self-transfer)
        if (from != address(0) && to != address(0) && from != to) {
            address basePool = IAddressManager(addressManager).getAddress(Identifier.BASE_POOL);
            // Update receiver's weighted average index
            IBasePool(basePool).updateWeightedIndexOnTransfer(poolId, from, to, amount, balanceOf(to));
        }

        super._update(from, to, amount);
    }
}

