// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// ============================================================
//  TransientMapLib
//  Single-level mapping, supports any key type (unified via abi.encode)
//
//  Namespace: each logical mapping corresponds to a bytes32 ID,
//  preventing slot conflicts between different mappings in the same contract.
//
//  Slot calculation: slot = keccak256(namespace, key)
//  Consistent with Solidity storage mapping logic, safe and collision-free.
// ============================================================
library TransientMapLib {
    // ---- uint256 mapping ----

    function set(bytes32 namespace, bytes32 key, uint256 value) internal {
        bytes32 slot = _slot(namespace, key);
        assembly {
            tstore(slot, value)
        }
    }

    function get(bytes32 namespace, bytes32 key) internal view returns (uint256 value) {
        bytes32 slot = _slot(namespace, key);
        assembly {
            value := tload(slot)
        }
    }

    function del(bytes32 namespace, bytes32 key) internal {
        bytes32 slot = _slot(namespace, key);
        assembly {
            tstore(slot, 0)
        }
    }

    // ---- address mapping ----

    function setAddr(bytes32 namespace, bytes32 key, address value) internal {
        bytes32 slot = _slot(namespace, key);
        assembly {
            tstore(slot, value)
        }
    }

    function getAddr(bytes32 namespace, bytes32 key) internal view returns (address value) {
        bytes32 slot = _slot(namespace, key);
        assembly {
            value := tload(slot)
        }
    }

    // ---- bool mapping ----

    function setBool(bytes32 namespace, bytes32 key, bool value) internal {
        bytes32 slot = _slot(namespace, key);
        assembly {
            tstore(slot, value)
        }
    }

    function getBool(bytes32 namespace, bytes32 key) internal view returns (bool value) {
        bytes32 slot = _slot(namespace, key);
        assembly {
            value := tload(slot)
        }
    }

    // ---- bytes32 mapping ----

    function setBytes32(bytes32 namespace, bytes32 key, bytes32 value) internal {
        bytes32 slot = _slot(namespace, key);
        assembly {
            tstore(slot, value)
        }
    }

    function getBytes32(bytes32 namespace, bytes32 key) internal view returns (bytes32 value) {
        bytes32 slot = _slot(namespace, key);
        assembly {
            value := tload(slot)
        }
    }

    // ---- Convenience: address key direct conversion ----

    function set(bytes32 namespace, address key, uint256 value) internal {
        set(namespace, bytes32(uint256(uint160(key))), value);
    }

    function get(bytes32 namespace, address key) internal view returns (uint256 value) {
        return get(namespace, bytes32(uint256(uint160(key))));
    }

    function setAddr(bytes32 namespace, address key, address value) internal {
        setAddr(namespace, bytes32(uint256(uint160(key))), value);
    }

    function getAddr(bytes32 namespace, address key) internal view returns (address value) {
        return getAddr(namespace, bytes32(uint256(uint160(key))));
    }

    function setBool(bytes32 namespace, address key, bool value) internal {
        setBool(namespace, bytes32(uint256(uint160(key))), value);
    }

    function getBool(bytes32 namespace, address key) internal view returns (bool value) {
        return getBool(namespace, bytes32(uint256(uint160(key))));
    }

    // ---- Convenience: uint256 key ----

    function set(bytes32 namespace, uint256 key, uint256 value) internal {
        set(namespace, bytes32(key), value);
    }

    function get(bytes32 namespace, uint256 key) internal view returns (uint256 value) {
        return get(namespace, bytes32(key));
    }

    // ---- Internal slot calculation ----

    function _slot(bytes32 namespace, bytes32 key) internal pure returns (bytes32) {
        return keccak256(abi.encode(namespace, key));
    }
}

