// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { NoncesUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/NoncesUpgradeable.sol";
import { EIP712Upgradeable } from "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { ICourtVoting } from "./../../interfaces/ICourtVoting.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../../misc/base/BaseContractUpgradeable.sol";
import { CaseId, VotingOption, Resolution, Errors, Constants } from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";

contract CourtVoting is BaseContractUpgradeable, EIP712Upgradeable, NoncesUpgradeable, ICourtVoting {
    using EnumerableSetLib for EnumerableSetLib.AddressSet;
    using PrecisionUtils for uint256;
    using ECDSA for bytes32;

    bytes32 private constant VOTE_TYPEHASH = keccak256("Vote(uint256 caseId,address validator,uint8 voteOption,uint256 nonce,uint256 deadline)");

    bytes32 private constant REIMBURSEMENT_VOTE_TYPEHASH = keccak256(
        "ReimbursementVote(uint256 caseId,address validator,uint8 voteOption,bytes32 merkleRoot,uint256 nonce,uint256 deadline)"
    );

    uint32 public voteCountRate;
    uint32 public effectiveVoteRate;
    mapping(CaseId caseId => VoteSession) private _disputeVotes;
    mapping(CaseId caseId => VoteSession) private _reimbursementVotes;
    mapping(CaseId caseId => ReimbursementProposal) private _reimbursementProposals;

    modifier onlyDisputeCourt() {
        _onlyDisputeCourt();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        bytes32[] memory identifiers = new bytes32[](1);
        identifiers[0] = Identifier.DISPUTE_COURT;
        __BaseContractUpgradeable_init(addressManager, identifiers);
        __EIP712_init("CourtVoting", "1");
    }

    function initializeEIP712() public reinitializer(2) {
        __EIP712_init("CourtVoting", "1");
    }

    /// @inheritdoc ICourtVoting
    function hasDisputeVoted(CaseId caseId, address validator) external view returns (bool) {
        return _disputeVotes[caseId].votedValidators.contains(validator);
    }

    /// @inheritdoc ICourtVoting
    function getDisputeVoteOption(CaseId caseId, address validator) external view returns (VotingOption) {
        return _disputeVotes[caseId].validatorOptions[validator];
    }

    /// @inheritdoc ICourtVoting
    function hasReimbursementVoted(CaseId caseId, address validator) external view returns (bool) {
        return _reimbursementVotes[caseId].votedValidators.contains(validator);
    }

    /// @inheritdoc ICourtVoting
    function getReimbursementVoteOption(CaseId caseId, address validator) external view returns (VotingOption) {
        return _reimbursementVotes[caseId].validatorOptions[validator];
    }

    /// @inheritdoc ICourtVoting
    function getReimbursementProposal(CaseId caseId) external view returns (ReimbursementProposal memory) {
        return _reimbursementProposals[caseId];
    }

    /// @inheritdoc ICourtVoting
    function updateVoteConfig(uint32 countRate, uint32 effectiveRate) external onlyDisputeCourt {
        voteCountRate = countRate;
        effectiveVoteRate = effectiveRate;
        emit VoteConfigUpdated(countRate, effectiveRate);
    }

    /// @inheritdoc ICourtVoting
    function openDisputeVote(CaseId caseId) external onlyDisputeCourt {
        require(!_disputeVotes[caseId].opened, Errors.UnexpectedCaseState());
        _disputeVotes[caseId].opened = true;
        emit DisputeVoteOpened(caseId);
    }

    /// @inheritdoc ICourtVoting
    function submitDisputeVote(
        CaseId caseId,
        address validator,
        VotingOption option,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external onlyDisputeCourt {
        _submitVote(_disputeVotes[caseId], VOTE_TYPEHASH, caseId, validator, option, bytes32(0), deadline, v, r, s);
        emit DisputeVoteSubmitted(caseId, validator, option);
    }

    /// @inheritdoc ICourtVoting
    function submitReimbursementVote(
        CaseId caseId,
        address validator,
        VotingOption option,
        bytes32 marketRoot,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external onlyDisputeCourt {
        _submitVote(_reimbursementVotes[caseId], REIMBURSEMENT_VOTE_TYPEHASH, caseId, validator, option, marketRoot, deadline, v, r, s);
        emit ReimbursementVoteSubmitted(caseId, validator, option);
    }

    /// @inheritdoc ICourtVoting
    function countDisputeVotes(CaseId caseId, address[] calldata validators) external view returns (Resolution) {
        return _countVotes(_disputeVotes[caseId], validators);
    }

    /// @inheritdoc ICourtVoting
    function openReimbursementVote(CaseId caseId, bytes32 merkleRoot, uint256 totalBaseAmount, uint256 totalQuoteAmount) external onlyDisputeCourt {
        require(!_reimbursementVotes[caseId].opened, Errors.UnexpectedCaseState());
        require(merkleRoot != bytes32(0), Errors.InvalidParameter());

        _reimbursementProposals[caseId] = ReimbursementProposal({
            merkleRoot: merkleRoot,
            totalBaseAmount: totalBaseAmount,
            totalQuoteAmount: totalQuoteAmount
        });
        _reimbursementVotes[caseId].opened = true;

        emit ReimbursementVoteOpened(caseId, merkleRoot, totalBaseAmount, totalQuoteAmount);
    }

    /// @inheritdoc ICourtVoting
    function countReimbursementVotes(CaseId caseId, address[] calldata validators) external view returns (Resolution) {
        return _countVotes(_reimbursementVotes[caseId], validators);
    }

    /// @inheritdoc ICourtVoting
    function resetReimbursementVote(CaseId caseId) external onlyDisputeCourt {
        VoteSession storage session = _reimbursementVotes[caseId];
        require(session.opened, Errors.UnexpectedCaseState());

        address[] memory voters = session.votedValidators.values();
        for (uint256 i = 0; i < voters.length; ++i) {
            session.votedValidators.remove(voters[i]);
            delete session.validatorOptions[voters[i]];
        }

        delete _reimbursementVotes[caseId];
        delete _reimbursementProposals[caseId];
    }

    /// @dev Shared vote counting logic for both dispute and reimbursement sessions.
    function _countVotes(VoteSession storage session, address[] calldata validators) internal view returns (Resolution) {
        uint256 voterCount = validators.length;
        if (voterCount == 0) return Resolution.Rejected;

        uint256 voteCountThreshold = voterCount.mulPrecision(voteCountRate, Constants.VOTE_CONFIG_PRECISION);

        uint256 totalVotes;
        uint256 forVotes;
        for (uint256 i = 0; i < voterCount; ++i) {
            if (!session.votedValidators.contains(validators[i])) continue;
            ++totalVotes;
            if (session.validatorOptions[validators[i]] == VotingOption.For) ++forVotes;
        }

        if (totalVotes == 0) return Resolution.Rejected;
        uint256 needEffectiveVotes = totalVotes.mulPrecision(effectiveVoteRate, Constants.VOTE_CONFIG_PRECISION);
        if (totalVotes < voteCountThreshold || forVotes < needEffectiveVotes) {
            return Resolution.Rejected;
        }
        return Resolution.Accepted;
    }

    function _submitVote(
        VoteSession storage session,
        bytes32 typeHash,
        CaseId caseId,
        address validator,
        VotingOption option,
        bytes32 marketRoot,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) internal {
        require(validator != address(0), Errors.UntrustfulVoting());
        require(session.opened, Errors.UnexpectedCaseState());
        require(!session.votedValidators.contains(validator), Errors.AlreadyVoted());

        // Verify marketRoot matches stored merkleRoot for reimbursement votes
        if (typeHash == REIMBURSEMENT_VOTE_TYPEHASH) {
            require(marketRoot == _reimbursementProposals[caseId].merkleRoot, Errors.InvalidParameter());
        }

        require(_verifyVoteSignature(typeHash, caseId, validator, option, marketRoot, deadline, v, r, s), Errors.UntrustfulVoting());

        session.votedValidators.add(validator);
        session.validatorOptions[validator] = option;
    }

    /// @dev Shared EIP-712 signature verification for both vote types.
    ///      Consumes a nonce for `validator` to prevent replay across calls.
    /// @param typeHash The TYPEHASH to use (VOTE_TYPEHASH or REIMBURSEMENT_VOTE_TYPEHASH).
    function _verifyVoteSignature(
        bytes32 typeHash,
        CaseId caseId,
        address validator,
        VotingOption option,
        bytes32 marketRoot,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) internal returns (bool) {
        require(block.timestamp <= deadline, Errors.SignatureExpired());

        bytes32 structHash;
        if (typeHash == REIMBURSEMENT_VOTE_TYPEHASH) {
            structHash = keccak256(abi.encode(typeHash, CaseId.unwrap(caseId), validator, uint8(option), marketRoot, _useNonce(validator), deadline));
        } else {
            structHash = keccak256(abi.encode(typeHash, CaseId.unwrap(caseId), validator, uint8(option), _useNonce(validator), deadline));
        }

        bytes32 digest = _hashTypedDataV4(structHash);
        return validator == digest.recover(v, r, s);
    }

    function _onlyDisputeCourt() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.DISPUTE_COURT), Errors.PermissionDenied(msg.sender, address(this)));
    }
}

