// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { EnumerableMapLib } from "@solady/utils/EnumerableMapLib.sol";
import { EnumerableSetLib } from "@solady/utils/EnumerableSetLib.sol";
import { IAccount } from "./../../interfaces/IAccount.sol";
import { IBasePool } from "./../../interfaces/IBasePool.sol";
import { ICourtVoting } from "./../../interfaces/ICourtVoting.sol";
import { IDisputeCourt } from "./../../interfaces/IDisputeCourt.sol";
import { IPoolManager } from "./../../interfaces/IPoolManager.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { IQuotePool } from "./../../interfaces/IQuotePool.sol";
import { IReimbursement } from "./../../interfaces/IReimbursement.sol";
import { IRiskController } from "./../../interfaces/IRiskController.sol";
import { IRoleManager } from "./../../interfaces/IRoleManager.sol";
import { IValidatorView } from "./../../interfaces/IValidatorView.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { TradingHelper } from "./../../libraries/TradingHelper.sol";
import { BaseContractUpgradeable } from "./../../misc/base/BaseContractUpgradeable.sol";
import { ERC2771ContextUpgradeable } from "./../../router/ERC2771ContextUpgradeable.sol";
import { Errors, Constants, PoolMetadata, PoolId, CaseId, CaseState, BondState, VotingOption, Resolution } from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";

contract DisputeCourt is BaseContractUpgradeable, ERC2771ContextUpgradeable, ReentrancyGuardUpgradeable, IDisputeCourt {
    using EnumerableSetLib for EnumerableSetLib.AddressSet;
    using EnumerableSetLib for EnumerableSetLib.Uint256Set;
    using EnumerableMapLib for EnumerableMapLib.AddressToUint256Map;
    using SafeERC20 for IERC20;
    using PrecisionUtils for uint256;

    uint256 public caseIdSequencer;
    WormholeConfiguration private _wormholeConfiguration;
    DisputeConfiguration private _disputeConfiguration;

    EnumerableMapLib.AddressToUint256Map private _forfeitedBonds;
    mapping(address user => mapping(CaseId caseId => BondInfo bondInfo)) private _userBondInfos;

    mapping(CaseId caseId => CaseInfo caseInfo) private _caseInfos;
    mapping(CaseId caseId => CaseDetailInfo caseDetailInfo) private _caseDetailInfos;

    EnumerableSetLib.AddressSet private _relayers;

    event RelayerAdded(address relayer);
    event RelayerRemoved(address relayer);

    modifier onlyRelayer() {
        _onlyRelayer();
        _;
    }

    modifier onlyRiskAdmin() {
        _onlyRiskAdmin();
        _;
    }

    modifier onlyFinanceAdmin() {
        _onlyFinanceAdmin();
        _;
    }

    modifier ensureCaseExists(CaseId caseId) {
        _ensureCaseExists(caseId);
        _;
    }

    modifier ensureAppealable(CaseId caseId) {
        _ensureAppealable(caseId);
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        bytes32[] memory identifiers = new bytes32[](11);
        identifiers[0] = Identifier.POOL_MANAGER;
        identifiers[1] = Identifier.ROLE_MANAGER;
        identifiers[2] = Identifier.BASE_POOL;
        identifiers[3] = Identifier.QUOTE_POOL;
        identifiers[4] = Identifier.RISK_CONTROLLER;
        identifiers[5] = Identifier.REIMBURSEMENT;
        identifiers[6] = Identifier.ACCOUNT;
        identifiers[7] = Identifier.POSITION_MANAGER;
        identifiers[8] = Identifier.ORACLE;
        identifiers[9] = Identifier.COURT_VOTING;
        identifiers[10] = Identifier.FORWARDER;
        __BaseContractUpgradeable_init(addressManager, identifiers);

        __ERC2771ContextUpgradeable_init(_getDependencyAddress(Identifier.FORWARDER));
    }

    function getDisputeConfiguration() external view returns (DisputeConfiguration memory, uint32, uint32) {
        return (_disputeConfiguration, _getCourtVoting().voteCountRate(), _getCourtVoting().effectiveVoteRate());
    }

    function canRiskControlClose(CaseId caseId) external view returns (bool) {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        return
            !caseInfo.isAppealCase &&
            caseInfo.status == CaseState.Resolved &&
            caseInfo.deadline <= block.timestamp &&
            _caseDetailInfos[caseId].appealCaseIds.length() == 0 &&
            caseInfo.resolution == Resolution.Accepted;
    }

    function isCaseRespondents(CaseId caseId, address account) external view returns (bool) {
        return _caseDetailInfos[caseId].respondents.contains(account);
    }

    function getRelayers() external view returns (address[] memory) {
        return _relayers.values();
    }

    function addRelayers(address[] calldata relayers) external onlyRiskAdmin {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.add(relayers[i]);
            emit RelayerAdded(relayers[i]);
        }
    }

    function removeRelayers(address[] calldata relayers) external onlyRiskAdmin {
        for (uint256 i; i < relayers.length; ++i) {
            _relayers.remove(relayers[i]);
            emit RelayerRemoved(relayers[i]);
        }
    }

    function updateWormholeConfiguration(WormholeConfiguration calldata wormholeConfiguration) external onlyRiskAdmin {
        _wormholeConfiguration = wormholeConfiguration;
        emit WormholeConfigurationUpdated(wormholeConfiguration);
    }

    function updateDisputeConfiguration(
        DisputeConfiguration calldata disputeConfiguration,
        uint32 voteCountRate,
        uint32 effectiveVoteRate
    ) external onlyRiskAdmin {
        require(
            voteCountRate <= Constants.VOTE_CONFIG_PRECISION &&
                effectiveVoteRate <= Constants.VOTE_CONFIG_PRECISION,
            Errors.InvalidParameter()
        );
        _disputeConfiguration = disputeConfiguration;
        _getCourtVoting().updateVoteConfig(voteCountRate, effectiveVoteRate);
        emit DisputeConfigurationUpdated(disputeConfiguration);
    }

    function fileDispute(PoolId poolId, address poolToken) external nonReentrant{
        PoolMetadata memory pool = IPoolManager(_getDependencyAddress(Identifier.POOL_MANAGER)).getPool(poolId);
        require(_verifyFileDisputePermission(pool, _msgOrigin()), Errors.DisputeNotAllowed());

        (CaseId caseId, uint64 deadline) = _createCase(poolId);
        uint256 poolTokenPrice = _getPoolTokenPrice(pool, poolToken);

        uint256 disputeBond = TradingHelper.convertTokenAmount(
            Constants.USD_DECIMALS,
            Constants.POOL_TOKEN_DECIMALS,
            uint256(_disputeConfiguration.disputeBondUsd).divPrice(poolTokenPrice)
        );

        IERC20(poolToken).safeTransferFrom(_msgOrigin(), address(this), disputeBond);
        _userBondInfos[_msgOrigin()][caseId] = BondInfo({ token: poolToken, amount: disputeBond, state: BondState.Locked });

        _getRiskController().enterDispute(poolId);
        emit DisputeFiled(caseId, poolId, _msgOrigin(), poolToken, disputeBond, deadline);
    }

    function fileDisputeFromStaker(PoolId poolId) external {
        address[] memory validators = IValidatorView(_wormholeConfiguration.validatorView).getCurrentActiveValidators();
        require(_verifyStaker(msg.sender, validators), Errors.DisputeNotAllowed());

        (CaseId caseId, uint64 deadline) = _createCase(poolId);

        _getRiskController().enterDispute(poolId);
        emit DisputeFiled(caseId, poolId, msg.sender, address(0), 0, deadline);
    }

    function cancelDispute(CaseId caseId, bool isMalicious) external ensureCaseExists(caseId) onlyRelayer {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(!caseInfo.isAppealCase, Errors.UnexpectedCaseType());
        require(caseInfo.status == CaseState.Initialized, Errors.UnexpectedCaseState());

        BondInfo memory bondInfo = _userBondInfos[caseInfo.complainant][caseId];
        if (isMalicious && bondInfo.token != address(0)) {
            (, uint256 currentAmount) = _forfeitedBonds.tryGet(bondInfo.token);
            _forfeitedBonds.set(bondInfo.token, currentAmount + bondInfo.amount);

            delete _userBondInfos[caseInfo.complainant][caseId];
        } else {
            _checkAndReleaseBond(caseInfo.complainant, caseId);
        }

        _caseInfos[caseId].status = CaseState.Closed;
        _caseInfos[caseId].resolution = Resolution.Rejected;

        _getRiskController().exitDispute(caseInfo.poolId);
        emit DisputeCanceled(caseId, caseInfo.complainant, isMalicious);
    }

    function openVoting(CaseId caseId, uint256 evidenceId, address[] calldata respondents) external ensureCaseExists(caseId) onlyRelayer {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(caseInfo.status == CaseState.Initialized, Errors.UnexpectedCaseState());

        uint64 deadline = uint64(block.timestamp + _disputeConfiguration.voteDuration);
        _caseInfos[caseId].status = CaseState.Voting;
        _caseInfos[caseId].deadline = deadline;

        for (uint256 i = 0; i < respondents.length; ++i) {
            _caseDetailInfos[caseId].respondents.add(respondents[i]);
        }

        _getCourtVoting().openDisputeVote(caseId);
        emit VotingOpened(caseId, evidenceId, deadline, respondents);
    }

    function vote(
        CaseId caseId,
        address validator,
        VotingOption voteOption,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external ensureCaseExists(caseId) onlyRelayer {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(caseInfo.status == CaseState.Voting, Errors.UnexpectedCaseState());
        require(caseInfo.deadline > block.timestamp, Errors.CaseDeadlineReached());

        _getCourtVoting().submitDisputeVote(caseId, validator, voteOption, deadline, v, r, s);
        emit Voted(caseId, validator, voteOption);
    }

    function resolveDispute(
        CaseId caseId
    ) external ensureCaseExists(caseId) onlyRelayer {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(!caseInfo.isAppealCase, Errors.UnexpectedCaseType());
        require(caseInfo.status == CaseState.Voting, Errors.UnexpectedCaseState());
        require(caseInfo.deadline <= block.timestamp, Errors.CaseDeadlineNotReached());

        address[] memory validators = IValidatorView(_wormholeConfiguration.validatorView).getCurrentActiveValidators();
        Resolution resolution = _getCourtVoting().countDisputeVotes(
            caseId,
            validators
        );

        _caseInfos[caseId].resolution = resolution;
        _caseInfos[caseId].status = CaseState.Resolved;
        _caseInfos[caseId].deadline = uint64(block.timestamp + _disputeConfiguration.resolveDuration);

        IRiskController riskController = _getRiskController();
        if (resolution == Resolution.Accepted) {
            riskController.freezeProfits(caseInfo.poolId, _caseDetailInfos[caseId].respondents.values());
        }

        riskController.exitDispute(caseInfo.poolId);
        _checkAndReleaseBond(caseInfo.complainant, caseId);
        emit DisputeResolved(caseId, resolution, _caseInfos[caseId].deadline);
    }

    function appeal(CaseId caseId) external ensureAppealable(caseId) {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(!caseInfo.isAppealCase, Errors.UnexpectedCaseType());
        require(caseInfo.status == CaseState.Resolved || caseInfo.status == CaseState.Appealed, Errors.UnexpectedCaseState());
        require(caseInfo.deadline > block.timestamp, Errors.CaseDeadlineReached());

        if (caseInfo.status == CaseState.Resolved) {
            _caseInfos[caseId].status = CaseState.Appealed;
            _caseInfos[caseId].deadline = uint64(block.timestamp + _disputeConfiguration.resolveDuration);
        }
        (CaseId appealCaseId, uint64 deadline) = _createAppealCase(caseId);
        _caseDetailInfos[caseId].appealCaseIds.add(CaseId.unwrap(appealCaseId));

        address appealToken = _disputeConfiguration.appealToken;
        uint256 appealBondUsd = _disputeConfiguration.appealBondUsd;
        uint256 appealBond = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, appealToken, appealBondUsd);

        IERC20(appealToken).safeTransferFrom(msg.sender, address(this), appealBond);
        _userBondInfos[msg.sender][appealCaseId] = BondInfo({ token: appealToken, amount: appealBond, state: BondState.Locked });

        _caseDetailInfos[caseId].isRespondentAppealed[msg.sender] = true;

        emit AppealFiled(caseId, appealCaseId, msg.sender, appealToken, appealBond, deadline);
    }

    function cancelAppeal(CaseId caseId, CaseId appealCaseId, bool isMalicious) external ensureCaseExists(caseId) onlyRelayer {
        CaseInfo memory appealCaseInfo = _caseInfos[appealCaseId];
        require(appealCaseInfo.isAppealCase, Errors.UnexpectedCaseType());
        require(appealCaseInfo.status == CaseState.Initialized, Errors.UnexpectedCaseState());

        BondInfo memory bondInfo = _userBondInfos[appealCaseInfo.complainant][appealCaseId];
        if (isMalicious) {
            (, uint256 currentAmount) = _forfeitedBonds.tryGet(bondInfo.token);
            _forfeitedBonds.set(bondInfo.token, currentAmount + bondInfo.amount);

            delete _userBondInfos[appealCaseInfo.complainant][appealCaseId];
        } else {
            _checkAndReleaseBond(appealCaseInfo.complainant, appealCaseId);
        }

        _caseInfos[appealCaseId].status = CaseState.Closed;
        _caseDetailInfos[caseId].isRespondentAppealed[appealCaseInfo.complainant] = false;
        _caseDetailInfos[caseId].appealCaseIds.remove(CaseId.unwrap(appealCaseId));

        emit AppealCanceled(caseId, appealCaseId, appealCaseInfo.complainant, isMalicious);
    }

    function resolveCaseAppeals(
        CaseId caseId,
        uint256 limit
    ) external ensureCaseExists(caseId) onlyRelayer {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(!caseInfo.isAppealCase, Errors.UnexpectedCaseType());
        require(caseInfo.status == CaseState.Appealed, Errors.UnexpectedCaseState());
        require(caseInfo.deadline <= block.timestamp, Errors.CaseDeadlineNotReached());

        address[] memory validators = IValidatorView(_wormholeConfiguration.validatorView).getCurrentActiveValidators();

        uint256[] memory appealCaseIds = _caseDetailInfos[caseId].appealCaseIds.values();
        uint256 count = limit < appealCaseIds.length ? limit : appealCaseIds.length;
        for (uint256 i = 0; i < count; ++i) {
            CaseId appealCaseId = CaseId.wrap(appealCaseIds[i]);
            CaseInfo memory appealCaseInfo = _caseInfos[appealCaseId];
            require(appealCaseInfo.status == CaseState.Voting, Errors.UnexpectedCaseState());
            require(appealCaseInfo.deadline <= block.timestamp, Errors.CaseDeadlineNotReached());

            Resolution resolution = _getCourtVoting().countDisputeVotes(
                appealCaseId,
                validators
            );

            _caseInfos[appealCaseId].resolution = resolution;
            _caseInfos[appealCaseId].status = CaseState.Closed;

            if (resolution == Resolution.Accepted) {
                _getRiskController().unfreezeProfit(caseInfo.poolId, appealCaseInfo.complainant);
                _caseDetailInfos[caseId].respondents.remove(appealCaseInfo.complainant);
            }

            _caseDetailInfos[caseId].appealCaseIds.remove(CaseId.unwrap(appealCaseId));
            delete _caseDetailInfos[caseId].isRespondentAppealed[appealCaseInfo.complainant];
            _checkAndReleaseBond(appealCaseInfo.complainant, appealCaseId);

            emit AppealResolved(caseId, appealCaseId, resolution, appealCaseInfo.complainant);
        }
        uint256 remaining = appealCaseIds.length - count;
        if (remaining == 0) _caseInfos[caseId].status = CaseState.Resolved;
        emit CaseAppealsResolved(caseId, remaining);
    }

    function checkRiskControlCloseCompleted(CaseId caseId) external {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(!caseInfo.isAppealCase, Errors.UnexpectedCaseType());
        require(caseInfo.status == CaseState.Resolved, Errors.UnexpectedCaseState());
        require(caseInfo.deadline <= block.timestamp, Errors.CaseDeadlineNotReached());
        require(_caseDetailInfos[caseId].appealCaseIds.length() == 0, Errors.CaseAppealNotFinished());
        require(caseInfo.resolution == Resolution.Accepted, Errors.CaseNotAccepted());

        address[] memory respondents = _caseDetailInfos[caseId].respondents.values();
        bytes32[] memory positionIds;
        for (uint256 i = 0; i < respondents.length; ++i) {
            positionIds = IPositionManager(_getDependencyAddress(Identifier.POSITION_MANAGER)).getUserPoolPositionIds(
                respondents[i],
                caseInfo.poolId
            );
            require(positionIds.length == 0, Errors.RiskCloseNotCompleted());
        }
        _caseInfos[caseId].status = CaseState.RiskClosed;
        emit CaseRiskClosed(caseId);
    }

    function openReimbursementVote(
        CaseId caseId,
        bytes32 merkleRoot,
        uint256 totalBaseAmount,
        uint256 totalQuoteAmount
    ) external ensureCaseExists(caseId) onlyRelayer {
        require(_caseInfos[caseId].status == CaseState.RiskClosed, Errors.UnexpectedCaseState());

        uint64 deadline = uint64(block.timestamp + _disputeConfiguration.voteDuration);
        _caseInfos[caseId].status = CaseState.Reimbursing;
        _caseInfos[caseId].deadline = deadline;

        _getCourtVoting().openReimbursementVote(caseId, merkleRoot, totalBaseAmount, totalQuoteAmount);
        emit ReimbursementVoteOpened(caseId, merkleRoot, totalBaseAmount, totalQuoteAmount, deadline);
    }

    function voteReimbursement(
        CaseId caseId,
        address validator,
        VotingOption voteOption,
        bytes32 marketRoot,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external ensureCaseExists(caseId) onlyRelayer {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(caseInfo.status == CaseState.Reimbursing, Errors.UnexpectedCaseState());
        require(caseInfo.deadline > block.timestamp, Errors.CaseDeadlineReached());

        _getCourtVoting().submitReimbursementVote(caseId, validator, voteOption, marketRoot, deadline, v, r, s);
        emit ReimbursementVoteSubmitted(caseId, validator, voteOption);
    }

    function processReimbursement(
        CaseId caseId,
        IReimbursement.ReimbursementInfo calldata reimbursementInfo,
        bytes32[] calldata zeroMerkleProof
    ) external onlyRelayer {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        require(caseInfo.status == CaseState.Reimbursing, Errors.UnexpectedCaseState());
        require(caseInfo.deadline <= block.timestamp, Errors.CaseDeadlineNotReached());

        IRiskController riskController = _getRiskController();
        address[] memory validators = IValidatorView(_wormholeConfiguration.validatorView).getCurrentActiveValidators();
        Resolution resolution = _getCourtVoting().countReimbursementVotes(
            caseId,
            validators
        );

        if (resolution != Resolution.Accepted) {
            _caseInfos[caseId].status = CaseState.RiskClosed;
            _getCourtVoting().resetReimbursementVote(caseId);
            emit ReimbursementVoteRejected(caseId);
            return;
        }

        ICourtVoting.ReimbursementProposal memory proposal = _getCourtVoting().getReimbursementProposal(caseId);
        require(reimbursementInfo.merkleRoot == proposal.merkleRoot, Errors.InvalidParameter());
        require(reimbursementInfo.totalBaseAmount == proposal.totalBaseAmount, Errors.InvalidParameter());
        require(reimbursementInfo.totalQuoteAmount == proposal.totalQuoteAmount, Errors.InvalidParameter());

        address[] memory respondents = _caseDetailInfos[caseId].respondents.values();
        (uint256 baseAmount, uint256 quoteAmount) = riskController.getRespondentProfits(caseInfo.poolId, respondents);
        require(baseAmount >= reimbursementInfo.totalBaseAmount && quoteAmount >= reimbursementInfo.totalQuoteAmount, Errors.InvalidProfitAmount());

        IReimbursement reimbursement = IReimbursement(_getDependencyAddress(Identifier.REIMBURSEMENT));
        reimbursement.setReimbursementInfo(caseId, reimbursementInfo, zeroMerkleProof);

        riskController.confiscateProfits(caseInfo.poolId, respondents);

        IAccount(_getDependencyAddress(Identifier.ACCOUNT)).executeCompensation(
            caseInfo.poolId,
            address(reimbursement),
            reimbursementInfo.totalBaseAmount,
            reimbursementInfo.totalQuoteAmount
        );

        _caseInfos[caseId].status = CaseState.Closed;
        delete _caseDetailInfos[caseId];
        emit ReimbursementProcessed(caseId, reimbursementInfo);
    }

    function claimBond(CaseId caseId) external {
        BondInfo memory bondInfo = _userBondInfos[msg.sender][caseId];
        require(bondInfo.state == BondState.Released, Errors.BondNotReleased());
        require(bondInfo.amount > 0, Errors.BondZeroAmount());

        IERC20(bondInfo.token).safeTransfer(msg.sender, bondInfo.amount);
        delete _userBondInfos[msg.sender][caseId];
        emit BondClaimed(caseId, msg.sender, bondInfo.token, bondInfo.amount);
    }

    function claimForfeitBonds(address receiver) external onlyFinanceAdmin {
        address[] memory tokens = _forfeitedBonds.keys();
        for (uint256 i = 0; i < tokens.length; ++i) {
            (, uint256 amount) = _forfeitedBonds.tryGet(tokens[i]);
            IERC20(tokens[i]).safeTransfer(receiver, amount);
            _forfeitedBonds.remove(tokens[i]);
            emit ForfeitBondsClaimed(receiver, tokens[i], amount);
        }
    }

    function _createCase(PoolId poolId) internal returns (CaseId caseId, uint64 deadline) {
        caseId = CaseId.wrap(++caseIdSequencer);
        deadline = uint64(block.timestamp + _disputeConfiguration.caseDuration);

        CaseInfo storage caseInfo = _caseInfos[caseId];
        caseInfo.poolId = poolId;
        caseInfo.complainant = msg.sender;
        caseInfo.status = CaseState.Initialized;
        caseInfo.deadline = deadline;
    }

    function _createAppealCase(CaseId caseId) internal returns (CaseId appealCaseId, uint64 deadline) {
        CaseInfo memory caseInfo = _caseInfos[caseId];
        deadline = caseInfo.deadline;

        appealCaseId = CaseId.wrap(++caseIdSequencer);

        CaseInfo storage appealCaseInfo = _caseInfos[appealCaseId];
        appealCaseInfo.poolId = caseInfo.poolId;
        appealCaseInfo.complainant = msg.sender;
        appealCaseInfo.status = CaseState.Initialized;
        appealCaseInfo.isAppealCase = true;
        appealCaseInfo.deadline = deadline;
    }

    function _checkAndReleaseBond(address complainant, CaseId caseId) internal {
        if (_userBondInfos[complainant][caseId].amount == 0) {
            delete _userBondInfos[complainant][caseId];
        } else {
            _userBondInfos[complainant][caseId].state = BondState.Released;
        }
    }

    function _getPoolTokenPrice(PoolMetadata memory pool, address poolToken) internal view returns (uint256) {
        require(poolToken == pool.basePoolToken || poolToken == pool.quotePoolToken, Errors.InvalidPoolToken());
        return
            (poolToken == pool.basePoolToken)
                ? _getBasePool().previewPoolTokenPrice(pool.poolId)
                : _getQuotePool().previewPoolTokenPrice(pool.poolId);
    }

    function _verifyStaker(address sender, address[] memory validators) internal pure returns (bool) {
        for (uint256 i = 0; i < validators.length; ++i) {
            if (sender == validators[i]) return true;
        }
        return false;
    }

    function _verifyFileDisputePermission(PoolMetadata memory pool, address user) internal view returns (bool) {
        uint256 disputeThresholdUsd = _disputeConfiguration.disputeThresholdUsd;
        if (disputeThresholdUsd == 0) return true;
        uint256 disputeThreshold = TradingHelper.convertTokenFromDecimals(Constants.USD_DECIMALS, pool.quoteToken, disputeThresholdUsd);

        uint256 basePoolTokenBalance = IERC20(pool.basePoolToken).balanceOf(user);
        uint256 quotePoolTokenBalance = IERC20(pool.quotePoolToken).balanceOf(user);

        uint256 basePoolTokenPrice = _getBasePool().previewPoolTokenPrice(pool.poolId);
        uint256 quotePoolTokenPrice = _getQuotePool().previewPoolTokenPrice(pool.poolId);

        uint256 basePoolTokenValue = TradingHelper.convertTokenFromDecimals(
            Constants.POOL_TOKEN_DECIMALS,
            pool.quoteToken,
            basePoolTokenBalance.mulPrice(basePoolTokenPrice)
        );
        uint256 quotePoolTokenValue = quotePoolTokenBalance.mulPrice(quotePoolTokenPrice);

        return basePoolTokenValue + quotePoolTokenValue >= disputeThreshold;
    }

    function _onlyRelayer() internal view {
        require(_relayers.contains(msg.sender), Errors.OnlyRelayer());
    }

    function _onlyRiskAdmin() internal view {
        require(_getRoleManager().isRiskAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyFinanceAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isFinanceAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _ensureCaseExists(CaseId caseId) internal view {
        require(_caseInfos[caseId].complainant != address(0), Errors.CaseNotExist(caseId));
    }

    function _ensureAppealable(CaseId caseId) internal view {
        require(_caseDetailInfos[caseId].respondents.contains(msg.sender), Errors.NotCaseRespondent(caseId, msg.sender));
        require(!_caseDetailInfos[caseId].isRespondentAppealed[msg.sender], Errors.CaseRespondentAppealed(caseId, msg.sender));
    }

    function _getRoleManager() internal view returns (IRoleManager) {
        return IRoleManager(_getDependencyAddress(Identifier.ROLE_MANAGER));
    }

    function _getBasePool() internal view returns (IBasePool) {
        return IBasePool(_getDependencyAddress(Identifier.BASE_POOL));
    }

    function _getQuotePool() internal view returns (IQuotePool) {
        return IQuotePool(_getDependencyAddress(Identifier.QUOTE_POOL));
    }

    function _getRiskController() internal view returns (IRiskController) {
        return IRiskController(_getDependencyAddress(Identifier.RISK_CONTROLLER));
    }

    function _getCourtVoting() internal view returns (ICourtVoting) {
        return ICourtVoting(_getDependencyAddress(Identifier.COURT_VOTING));
    }
}

