// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import { PoolId, PoolType, TriggerType } from "./../types/Types.sol";

/**
 * @title ILiquidityRouter
 * @notice Interface for liquidity router defining pool deposit/withdrawal and TPSL order management functionality
 */
interface ILiquidityRouter {
    struct TpslData {
        // Address of the order owner
        address user;
        // Associated pool ID
        PoolId poolId;
        // Pool type (Base or Quote)
        PoolType poolType;
        // Amount of LP tokens to operate on
        uint256 amount;
        // Price that triggers the order execution
        uint256 triggerPrice;
        // Trigger type (greater than or equal, or less than or equal)
        TriggerType triggerType;
        // Minimum quote token output amount (for slippage protection)
        uint256 minQuoteOut;
    }

    struct DepositParams {
        // Target pool ID
        PoolId poolId;
        // Deposit amount
        uint256 amountIn;
        // Minimum expected LP token output amount
        uint256 minAmountOut;
        // LP token recipient address
        address recipient;
        // Optional TPSL order parameters array
        TpslParams[] tpslParams;
    }

    struct WithdrawParams {
        // Target pool ID
        PoolId poolId;
        // Amount of LP tokens to burn
        uint256 amountIn;
        // Minimum expected underlying token output amount
        uint256 minAmountOut;
        // Underlying token recipient address
        address recipient;
    }

    struct AddTpslParams {
        // Target pool ID
        PoolId poolId;
        // Pool type (Base or Quote)
        PoolType poolType;
        // TPSL order parameters array
        TpslParams[] tpslParams;
    }

    struct TpslParams {
        // Amount of LP tokens to operate on
        uint256 amount;
        // Price that triggers the order execution
        uint256 triggerPrice;
        // Trigger type (greater than or equal, or less than or equal)
        TriggerType triggerType;
        // Minimum quote token output amount (for slippage protection)
        uint256 minQuoteOut;
    }

    struct MigrateLiquidityParams {
        // Source pool ID
        PoolId fromPoolId;
        // Target pool ID
        PoolId toPoolId;
        // Amount of LP tokens to migrate
        uint256 amount;
        // Minimum expected LP token output amount
        uint256 minLpOut;
    }

    /**
     * @notice Deposits base tokens into the base pool
     * @param params Deposit parameters, including optional TPSL orders
     */
    function depositBase(DepositParams memory params) external;

    /**
     * @notice Withdraws base tokens from the base pool
     * @param params Withdrawal parameters
     */
    function withdrawBase(WithdrawParams memory params) external;

    /**
     * @notice Deposits quote tokens into the quote pool
     * @param params Deposit parameters, including optional TPSL orders
     */
    function depositQuote(DepositParams memory params) external;

    /**
     * @notice Withdraws quote tokens from the quote pool
     * @param params Withdrawal parameters
     */
    function withdrawQuote(WithdrawParams memory params) external;

    /**
     * @notice Adds TPSL (Take Profit Stop Loss) orders
     * @param params TPSL order parameters
     */
    function addTpsl(AddTpslParams calldata params) external;

    /**
     * @notice Executes a TPSL order
     * @param orderId Order ID to execute
     * @param quoteInIfNecessary Amount of quote tokens for Base pool exchange (ignored for Quote pool orders)
     * @param minOut Minimum base/quote token output amount
     * @return baseOut Base token output amount
     * @return quoteOut Quote token output amount
     * @dev Anyone can execute TPSL orders that meet trigger conditions
     */
    function executeTpsl(uint256 orderId, uint256 quoteInIfNecessary, uint256 minOut) external returns (uint256 baseOut, uint256 quoteOut);

    /**
     * @notice Migrates liquidity from one quote pool to another
     * @param params Migration parameters including source pool, target pool, amounts and slippage protection
     * @dev Withdraws LP tokens from source pool and deposits into target pool in a single transaction
     */
    function migrateLiquidity(MigrateLiquidityParams calldata params) external;

    /**
     * @notice Claims rebates for a user
     * @param poolId The pool ID to claim rebates from
     * @param recipient Address to receive the rebates
     */
    function claimBasePoolRebate(PoolId poolId, address recipient) external;

    /**
     * @notice Claims rebates for a user
     * @param poolIds The pool IDs to claim rebates from
     * @param recipient Address to receive the rebates
     */
    function claimBasePoolRebates(PoolId[] memory poolIds, address recipient) external;

    /**
     * @notice Claims rebates for a user
     * @param poolId The pool ID to claim rebates from
     * @param recipient Address to receive the rebates
     */
    function claimQuotePoolRebate(PoolId poolId, address recipient) external;

    /**
     * @notice Claims rebates for a user
     * @param poolIds The pool IDs to claim rebates from
     * @param recipient Address to receive the rebates
     */
    function claimQuotePoolRebates(PoolId[] memory poolIds, address recipient) external;
}

