// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { MerkleProof } from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import { IReimbursement } from "./../../interfaces/IReimbursement.sol";
import { IRoleManager } from "./../../interfaces/IRoleManager.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../../misc/base/BaseContractUpgradeable.sol";
import { Errors, CaseId } from "./../../types/Types.sol";

contract Reimbursement is BaseContractUpgradeable, ReentrancyGuardUpgradeable, IReimbursement {
    using SafeERC20 for IERC20;

    mapping(CaseId caseId => ReimbursementInfo reimbursementInfo) private _reimbursementInfo;
    mapping(CaseId caseId => mapping(address user => bool isClaimed)) private _isClaimedReimbursement;

    modifier onlyFinanceAdmin() {
        _onlyFinanceAdmin();
        _;
    }

    modifier onlyDisputeCourt() {
        _onlyDisputeCourt();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        bytes32[] memory identifiers = new bytes32[](1);
        identifiers[0] = Identifier.DISPUTE_COURT;

        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    function getReimbursementInfo(CaseId caseId) external view returns (ReimbursementInfo memory) {
        return _reimbursementInfo[caseId];
    }

    function setReimbursementInfo(
        CaseId caseId,
        ReimbursementInfo memory reimbursementInfo,
        bytes32[] calldata zeroMerkleProof
    ) external onlyDisputeCourt {
        require(_reimbursementInfo[caseId].merkleRoot == bytes32(0), Errors.TreeAlreadySet());
        require(
            _verify(address(0), reimbursementInfo.totalBaseAmount, reimbursementInfo.totalQuoteAmount, reimbursementInfo.merkleRoot, zeroMerkleProof),
            Errors.MerkleTreeVerificationFailed(caseId, address(0))
        );

        _reimbursementInfo[caseId] = reimbursementInfo;

        emit ReimbursementInfoSet(
            caseId,
            reimbursementInfo.merkleRoot,
            reimbursementInfo.baseToken,
            reimbursementInfo.quoteToken,
            reimbursementInfo.totalBaseAmount,
            reimbursementInfo.totalQuoteAmount,
            reimbursementInfo.claimedBaseAmount,
            reimbursementInfo.claimedQuoteAmount,
            reimbursementInfo.expireTime
        );
    }

    function claimReimbursement(CaseId caseId, uint256 baseAmount, uint256 quoteAmount, bytes32[] calldata merkleProof) external nonReentrant {
        ReimbursementInfo storage reimbursementInfo = _reimbursementInfo[caseId];
        require(reimbursementInfo.expireTime > block.timestamp, Errors.ReimbursementValidity(caseId));
        require(!_isClaimedReimbursement[caseId][msg.sender], Errors.AlreadyClaimed(caseId, msg.sender));
        require(
            baseAmount <= reimbursementInfo.totalBaseAmount - reimbursementInfo.claimedBaseAmount &&
                quoteAmount <= reimbursementInfo.totalQuoteAmount - reimbursementInfo.claimedQuoteAmount,
            Errors.InvalidAmount(caseId, msg.sender)
        );
        require(
            _verify(msg.sender, baseAmount, quoteAmount, reimbursementInfo.merkleRoot, merkleProof),
            Errors.MerkleTreeVerificationFailed(caseId, msg.sender)
        );

        _isClaimedReimbursement[caseId][msg.sender] = true;
        reimbursementInfo.claimedQuoteAmount += quoteAmount;
        IERC20(reimbursementInfo.quoteToken).safeTransfer(msg.sender, quoteAmount);
        if (baseAmount > 0) {
            reimbursementInfo.claimedBaseAmount += baseAmount;
            IERC20(reimbursementInfo.baseToken).safeTransfer(msg.sender, baseAmount);
        }

        emit ReimbursementClaimed(caseId, msg.sender, reimbursementInfo.baseToken, reimbursementInfo.quoteToken, baseAmount, quoteAmount);
    }

    function claimExpiredCases(CaseId[] calldata caseIds, address receiver) external nonReentrant onlyFinanceAdmin {
        require(receiver != address(0), Errors.InvalidParameter());

        for (uint256 i = 0; i < caseIds.length; i++) {
            ReimbursementInfo storage reimbursementInfo = _reimbursementInfo[caseIds[i]];
            require(reimbursementInfo.expireTime < block.timestamp, Errors.ReimbursementValidity(caseIds[i]));
            require(!_isClaimedReimbursement[caseIds[i]][address(0)], Errors.AlreadyClaimed(caseIds[i], address(0)));

            uint256 baseAmount = reimbursementInfo.totalBaseAmount - reimbursementInfo.claimedBaseAmount;
            uint256 quoteAmount = reimbursementInfo.totalQuoteAmount - reimbursementInfo.claimedQuoteAmount;

            _isClaimedReimbursement[caseIds[i]][address(0)] = true;

            reimbursementInfo.claimedQuoteAmount += quoteAmount;
            IERC20(reimbursementInfo.quoteToken).safeTransfer(receiver, quoteAmount);

            if (baseAmount > 0) {
                reimbursementInfo.claimedBaseAmount += baseAmount;
                IERC20(reimbursementInfo.baseToken).safeTransfer(receiver, baseAmount);
            }
            emit ReimbursementClaimExpired(caseIds[i], receiver, reimbursementInfo.baseToken, reimbursementInfo.quoteToken, baseAmount, quoteAmount);
        }
    }

    function _verify(
        address sender,
        uint256 baseAmount,
        uint256 quoteAmount,
        bytes32 merkleRoot,
        bytes32[] calldata merkleProof
    ) private pure returns (bool canClaim) {
        bytes32 node = keccak256(abi.encodePacked(sender, baseAmount, quoteAmount));
        canClaim = MerkleProof.verify(merkleProof, merkleRoot, node);
    }

    function _onlyFinanceAdmin() internal view {
        require(IRoleManager(_getAddressManager().getRoleManager()).isFinanceAdmin(msg.sender), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyDisputeCourt() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.DISPUTE_COURT), Errors.PermissionDenied(msg.sender, address(this)));
    }
}

