// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IMatcher } from "./../../interfaces/IMatcher.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { ExecuteHelper } from "./../../libraries/ExecuteHelper.sol";
import { Errors, PoolMetadata, PositionMetadata, OrderId, PoolId, PoolState, PositionId } from "./../../types/Types.sol";
import { IPoolCloseFacet } from "./../interfaces/IPoolCloseFacet.sol";
import { ExecutorBaseFacet } from "./ExecutorBaseFacet.sol";

/// @title PoolCloseFacet
/// @notice Facet for closing positions when pool is in PreBench state
contract PoolCloseFacet is ExecutorBaseFacet, IPoolCloseFacet {
    /// @inheritdoc IPoolCloseFacet
    function poolCloseExecute(ClosePoolPositionsParams calldata params) external override onlyKeeper {
        PoolMetadata memory pool = _getPoolManager().getPool(params.poolId);
        require(pool.state == PoolState.PreBench, Errors.PoolNotInPreBenchState(params.poolId));

        IPositionManager positionManager = _getPositionManager();
        (uint256 marketPrice, ) = _getOracle().getMarketPrice(params.poolId);
        for (uint256 i = 0; i < params.positionIds.length; ++i) {
            PositionId positionId = PositionId.wrap(params.positionIds[i]);

            PositionMetadata memory position = positionManager.getPosition(positionId);
            positionManager.preparePosition(positionId, pool, position.direction, address(0), marketPrice, position.broker, true, true);

            // Skip invalid positions
            if (PoolId.unwrap(position.poolId) != PoolId.unwrap(params.poolId) || position.size == 0) continue;

            _closePosition(positionManager, pool, position, positionId, marketPrice);
        }
    }

    /// @notice Internal function to close a single position
    function _closePosition(
        IPositionManager positionManager,
        PoolMetadata memory pool,
        PositionMetadata memory position,
        PositionId positionId,
        uint256 marketPrice
    ) internal {
        address owner = positionManager.getPositionOwner(positionId);
        uint256 executeSize = position.size;

        IEmiter emiter = _getEmiter();
        if (_checkADL(emiter, positionManager, pool, position, positionId, executeSize, marketPrice, position.broker, owner)) return;

        (OrderId closeOrderId, , ) = _getMatcher().createAndMatchPool(
            IMatcher.CreateOrderParams({
                poolId: position.poolId,
                positionId: positionId,
                owner: owner,
                direction: position.direction,
                isLiquidation: false
            }),
            executeSize,
            marketPrice,
            msg.sender
        );

        // Emit force close event
        _getEmiter().emitPositionForceClosed(
            IEmiter.PositionForceClosedParams({
                broker: position.broker,
                user: owner,
                poolId: position.poolId,
                positionId: positionId,
                orderId: closeOrderId,
                positionSize: position.size,
                executePrice: marketPrice,
                reason: "Unlisted"
            })
        );
    }

    function _checkADL(
        IEmiter emiter,
        IPositionManager positionManager,
        PoolMetadata memory pool,
        PositionMetadata memory position,
        PositionId positionId,
        uint256 executeSize,
        uint256 executePrice,
        address broker,
        address owner
    ) internal returns (bool interrupt) {
        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(pool.poolId);
        if (ExecuteHelper.hasEarlyClosePrice(position, oiTracker.tracker)) return false;

        if (!ExecuteHelper.needADL(positionManager, pool, position.direction, executeSize, executePrice)) return false;

        emiter.emitOrderMarkedADL(
            IEmiter.OrderMarkedADLParams({ broker: broker, user: owner, poolId: pool.poolId, orderId: OrderId.wrap(0), positionId: positionId })
        );
        return true;
    }
}

