// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { ICollectFee } from "./../../interfaces/ICollectFee.sol";
import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IMatcher } from "./../../interfaces/IMatcher.sol";
import { IOrderManager } from "./../../interfaces/IOrderManager.sol";
import { IPoolManager } from "./../../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { IRiskController } from "./../../interfaces/IRiskController.sol";
import { IRiskParameter } from "./../../interfaces/IRiskParameter.sol";
import { ITradingRouter } from "./../../interfaces/ITradingRouter.sol";
import { ExecuteHelper } from "./../../libraries/ExecuteHelper.sol";
import { LibPoolMetadata } from "./../../libraries/Pool.sol";
import { LibPositionMetadata } from "./../../libraries/Position.sol";
import { RiskHelper } from "./../../manager/risk-control/RiskHelper.sol";
import { Errors, OrderMetadata, PositionMetadata, MarketMetadata, PoolMetadata, OrderId, Operation, MatchType } from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";
import { IADLExecuteFacet } from "./../interfaces/IADLExecuteFacet.sol";
import { ExecutorBaseFacet } from "./ExecutorBaseFacet.sol";

/// @title ADLExecuteFacet
/// @notice Facet for handling ADL (Auto-Deleveraging) execution
contract ADLExecuteFacet is ExecutorBaseFacet, IADLExecuteFacet {
    using LibPoolMetadata for PoolMetadata;
    using LibPositionMetadata for PositionMetadata;
    using PrecisionUtils for uint256;

    /// @inheritdoc IADLExecuteFacet
    function adlExecute(ADLExecuteParams calldata params) external override onlyKeeper {
        IOrderManager orderManager = _getOrderManager();
        OrderMetadata memory order = orderManager.getOrder(params.orderId);
        require(order.operation == Operation.Decrease, Errors.InvalidOrder(params.orderId));

        IPositionManager positionManager = _getPositionManager();
        IPoolManager poolManager = _getPoolManager();
        PoolMetadata memory pool = poolManager.getPool(order.poolId);
        (uint256 marketPrice, ) = _getOracle().getMarketPrice(order.poolId);

        PositionMetadata memory triggerPosition = positionManager.getPosition(order.positionId);
        _collectExecutionFee(order, triggerPosition, pool.quoteToken, pool.tradingVault, msg.sender);

        IPositionManager.OITracker memory oiTracker = positionManager.getOITracker(triggerPosition.poolId);
        bool hasEarlyClosePrice = ExecuteHelper.hasEarlyClosePrice(triggerPosition, oiTracker.tracker);
        require(!hasEarlyClosePrice, Errors.NoADLNeeded(params.orderId));

        IRiskParameter.RiskParamData memory riskParams = _getRiskParameter().getRiskParamData(triggerPosition.riskTier);
        if (
            ExecuteHelper.checkOrderInterrupt(
                orderManager,
                positionManager,
                order,
                params.orderId,
                pool,
                riskParams.tradeLimitParams,
                triggerPosition,
                marketPrice
            )
        ) return;

        IPoolVault poolVault = IPoolVault(pool.poolVault);
        (, MarketMetadata memory market) = poolManager.getPoolMarket(order.poolId);
        uint256 executePrice = ExecuteHelper.calculateExecutePrice(order, marketPrice);
        (uint256 executeSize, uint256 availableLiquiditySize) = ExecuteHelper.calculateExecuteSize(
            positionManager,
            poolVault,
            order,
            market,
            triggerPosition.size,
            executePrice
        );
        if (executeSize == 0) {
            orderManager.uncompleteOrder(params.orderId, "No execute size");
            return;
        }

        if (!ExecuteHelper.needADL(positionManager, pool, order.direction, executeSize, executePrice)) {
            revert Errors.NoADLNeeded(params.orderId);
        }

        uint256 needAdlNotional = executeSize.mulPrice(executePrice);
        (ExecuteHelper.ADLPositionExecute[] memory adlPositionExecutes, uint256 adlTotalNotional) = ExecuteHelper.calculateADLPositionExecute(
            ExecuteHelper.CalculateADLExecuteParams({
                positionManager: positionManager,
                fundingRate: _getFundingRate(),
                poolManager: poolManager,
                riskParameter: _getRiskParameter(),
                pool: pool,
                orderDirection: order.direction,
                orderId: params.orderId,
                needAdlNotional: needAdlNotional,
                marketPrice: marketPrice
            }),
            params.adlPositions
        );
        uint256 adlTotalSize = adlTotalNotional.divPrice(executePrice);
        uint256 matchExecuteSize = Math.min(adlTotalSize, executeSize);
        uint256 matchExecutePrice = executePrice;

        IMatcher.MatchPoolExecuteParams memory matchPoolExecuteParams;
        if (adlTotalSize < executeSize) {
            matchPoolExecuteParams = _needPoolExecute(order, pool, riskParams, availableLiquiditySize, executeSize - matchExecuteSize, executePrice);
        }

        positionManager.preparePosition(order.positionId, pool, order.direction, order.user, marketPrice, order.broker, true, true);

        (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) = _getMatcher().matchAdlPositions(
            IMatcher.MatchAdlPositionsParams({
                triggerOrderId: params.orderId,
                adlPositionExecutes: adlPositionExecutes,
                executeSize: matchExecuteSize,
                executePrice: matchExecutePrice,
                keeper: msg.sender,
                matchPoolExecuteParams: matchPoolExecuteParams
            })
        );

        _getEmiter().emitExecutionMatched(
            IEmiter.ExecutionMatchedParams({
                poolId: order.poolId,
                triggerOrderIds: triggerOrderIds,
                matchedOrderIds: matchedOrderIds,
                matchType: MatchType.ADL,
                price: matchExecutePrice
            })
        );
    }

    function _needPoolExecute(
        OrderMetadata memory order,
        PoolMetadata memory pool,
        IRiskParameter.RiskParamData memory riskParams,
        uint256 availableLiquiditySize,
        uint256 executeSize,
        uint256 executePrice
    ) internal view returns (IMatcher.MatchPoolExecuteParams memory matchPoolExecuteParams) {
        uint256 poolExecuteSize = Math.min(availableLiquiditySize, executeSize);
        if (poolExecuteSize == 0) return matchPoolExecuteParams;

        uint256 poolExecutePrice = executePrice;

        IRiskController.LiquidityLock memory liquidityLock = _getRiskController().getLiquidityLock(order.poolId);
        (bool hasSlipExec, uint256 slippagePrice, uint256 actualExecSize) = RiskHelper.calculateOrderSlippage(
            pool,
            riskParams.riskLockParams,
            liquidityLock,
            order.operation,
            order.direction,
            poolExecuteSize,
            executePrice,
            order.slippagePct
        );
        if (hasSlipExec) {
            if (actualExecSize == 0) return matchPoolExecuteParams;

            uint256 availableLiquidityValue = availableLiquiditySize.mulPrice(executePrice);
            uint256 orderValue = poolExecuteSize.mulPrice(slippagePrice);

            poolExecuteSize = actualExecSize;
            poolExecutePrice = slippagePrice;
            if (availableLiquidityValue < orderValue) {
                poolExecuteSize = Math.min(availableLiquidityValue.divPrice(slippagePrice), poolExecuteSize);
            }
        }

        matchPoolExecuteParams.needPoolExecute = true;
        matchPoolExecuteParams.isTriggerOrder = true;
        matchPoolExecuteParams.executeSize = poolExecuteSize;
        matchPoolExecuteParams.executePrice = poolExecutePrice;
        return matchPoolExecuteParams;
    }

    function _collectExecutionFee(
        OrderMetadata memory order,
        PositionMetadata memory position,
        address quoteToken,
        address tradingVault,
        address feeRecipient
    ) internal {
        ITradingRouter tradingRouter = _getTradingRouter();
        if (position.isInitialized()) {
            tradingRouter.collectExecutionFee(
                ICollectFee.FeeSource.Position,
                abi.encode(ICollectFee.PositionFeeParams({ positionId: order.positionId, feeToken: quoteToken, tradingVault: tradingVault })),
                feeRecipient
            );
        } else {
            tradingRouter.collectExecutionFee(
                ICollectFee.FeeSource.Account,
                abi.encode(ICollectFee.AccountFeeParams({ poolId: order.poolId, feeToken: quoteToken, user: order.user })),
                feeRecipient
            );
        }
    }
}

