// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { FixedPointMathLib } from "@solady/utils/FixedPointMathLib.sol";
import { IRiskController } from "./../../interfaces/IRiskController.sol";
import { IRiskParameter } from "./../../interfaces/IRiskParameter.sol";
import { Constants, Errors, PoolMetadata, Operation, Direction } from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";
import { TradeUtils } from "./../../utils/TradeUtils.sol";

library RiskHelper {
    using SignedMath for int256;
    using PrecisionUtils for uint256;
    using PrecisionUtils for int256;

    function calculateOrderOpenInterest(
        Operation operation,
        Direction direction,
        uint256 executeSize,
        uint256 executePrice
    ) internal pure returns (int256 orderOpenInterest) {
        bool isBuy = TradeUtils.getOrderSide(operation, direction);
        orderOpenInterest = isBuy ? int256(executeSize.mulPrice(executePrice)) : -int256(executeSize.mulPrice(executePrice));
    }

    function calculateOrderSlippage(
        PoolMetadata memory pool,
        IRiskParameter.RiskLockParams memory riskLockParams,
        IRiskController.LiquidityLock memory liquidityLock,
        Operation operation,
        Direction direction,
        uint256 orderSize,
        uint256 orderPrice,
        uint256 orderSlippage
    ) internal view returns (bool hasSlipExec, uint256 slippagePrice, uint256 actualExecSize) {
        uint8 baseDec = IERC20Metadata(pool.baseToken).decimals();
        bool isBuy = TradeUtils.getOrderSide(operation, direction);
        uint256 orderValueWad = orderSize.mulPrice(orderPrice).toWad(baseDec);
        int256 orderOIWad = isBuy ? int256(orderValueWad) : -int256(orderValueWad);

        bool inLiquidityWindow =
            liquidityLock.windowAnchor + riskLockParams.liquidityWindowSize > block.timestamp &&
                orderPrice <= liquidityLock.priceCeiling &&
                orderPrice >= liquidityLock.priceFloor;
        int256 lockOIWad = liquidityLock.openInterest.toWad(baseDec);
        uint256 totalOIWadAbs = inLiquidityWindow ? (orderOIWad + lockOIWad).abs() : orderValueWad;
        // Out-of-window: stale lockOI must not affect maxOpenWad calculation.
        // In-window but order reduces net OI imbalance (totalOIWadAbs < |lockOI|): order benefits LP, should not be penalized by lockOI.
        int256 effectiveLockOIWad = (inLiquidityWindow && totalOIWadAbs >= lockOIWad.abs()) ? lockOIWad : int256(0);
        uint256 windowCapUsdWad = uint256(riskLockParams.windowCapUsd).toWad(Constants.USD_DECIMALS);
        if (totalOIWadAbs <= windowCapUsdWad) {
            return (false, orderPrice, orderSize);
        }

        uint256 totalExcessOIWad = totalOIWadAbs - windowCapUsdWad;
        uint256 maxOrderSlippageOIWad = Math.min(totalExcessOIWad, orderValueWad);
        uint256 noSlippageOIWad = orderValueWad - maxOrderSlippageOIWad;
        uint256 closeSlippageLimit = operation == Operation.Decrease ? riskLockParams.maxCloseSlippage : type(uint256).max;
        uint256 effectiveOrderSlippage = Math.min(orderSlippage, closeSlippageLimit);

        uint256 orderSlippageOIWad;
        if (closeSlippageLimit <= orderSlippage) {
            orderSlippageOIWad = maxOrderSlippageOIWad;
        } else {
            uint256 maxOpenWad = _withSlipMaxOpenWad(effectiveLockOIWad, int256(windowCapUsdWad), riskLockParams.baseSlippage, orderSlippage);
            orderSlippageOIWad = maxOpenWad > noSlippageOIWad ? Math.min(maxOpenWad, orderValueWad) - noSlippageOIWad : 0;
        }

        uint256 applySlippagePrice;
        uint256 actualExecOIWad = noSlippageOIWad;
        if (orderSlippageOIWad < maxOrderSlippageOIWad) {
            uint256 factor = isBuy ? Constants.SLIPPAGE_PRECISION + effectiveOrderSlippage : Constants.SLIPPAGE_PRECISION - effectiveOrderSlippage;
            applySlippagePrice = orderPrice.mulPrecision(factor, Constants.SLIPPAGE_PRECISION);
            actualExecOIWad += orderSlippageOIWad;
            // No-slippage portion is always executable; slippage portion is capped by user tolerance.
            uint256 execSizeWad = noSlippageOIWad.divPriceCeil(orderPrice);
            if (orderSlippageOIWad > 0) {
                execSizeWad += orderSlippageOIWad.divPriceCeil(applySlippagePrice);
            }
            actualExecSize = Math.min(execSizeWad.fromWad(baseDec), orderSize);
        } else {
            actualExecOIWad += maxOrderSlippageOIWad;
            actualExecSize = orderSize;
            uint256 maxSlippage =
                closeSlippageLimit == type(uint256).max
                    ? type(uint256).max
                    : (closeSlippageLimit * Constants.RISK_SLIPPAGE_PRECISION) / Constants.SLIPPAGE_PRECISION;
            applySlippagePrice = _applySlippage(orderPrice, isBuy, windowCapUsdWad, totalExcessOIWad, riskLockParams.baseSlippage, maxSlippage);
        }

        if (actualExecOIWad == 0) return (true, orderPrice, 0);

        slippagePrice = ((actualExecOIWad - noSlippageOIWad).mulPrice(applySlippagePrice) + noSlippageOIWad.mulPrice(orderPrice)).divPrecision(
            actualExecOIWad,
            Constants.PRICE_PRECISION
        );

        return (true, slippagePrice, actualExecSize);
    }

    function _applySlippage(
        uint256 orderPrice,
        bool penaltySide,
        uint256 windowCapUsdWad,
        uint256 excessOpenOIWad,
        uint256 baseSlippage,
        uint256 maxSlippage
    ) internal pure returns (uint256 slippagePrice) {
        uint256 actualSlippage = _computeSlippage(windowCapUsdWad, excessOpenOIWad, baseSlippage, maxSlippage);
        if (penaltySide) {
            return orderPrice.mulPrecision(Constants.RISK_SLIPPAGE_PRECISION + actualSlippage, Constants.RISK_SLIPPAGE_PRECISION);
        } else {
            require(actualSlippage <= Constants.RISK_SLIPPAGE_PRECISION, Errors.ExcessiveSlippage());
            return orderPrice.mulPrecision(Constants.RISK_SLIPPAGE_PRECISION - actualSlippage, Constants.RISK_SLIPPAGE_PRECISION);
        }
    }

    function _computeSlippage(
        uint256 windowCapUsdWad,
        uint256 excessOpenOIWad,
        uint256 baseSlippage,
        uint256 maxSlippage
    ) internal pure returns (uint256 actualSlippage) {
        if (baseSlippage == 0 || maxSlippage == 0) {
            return 0;
        }
        if (excessOpenOIWad == 0 || windowCapUsdWad == 0) {
            return Math.min(baseSlippage, maxSlippage);
        }

        uint256 baseSlippageWad = baseSlippage.toWad(Constants.RISK_SLIPPAGE_DECIMALS);
        uint256 R = FixedPointMathLib.divWad(excessOpenOIWad, windowCapUsdWad);

        if (maxSlippage < type(uint256).max) {
            uint256 capRatio = (maxSlippage.toWad(Constants.RISK_SLIPPAGE_DECIMALS) * 1e18) / baseSlippageWad;
            int256 capR = FixedPointMathLib.lnWad(int256(capRatio)) + int256(1e18);
            if (int256(R) >= capR) {
                return maxSlippage;
            }
        }

        int256 R_minus_1 = int256(R) - int256(1e18);
        require(R_minus_1 < 135e18, Errors.ExcessiveSlippage());
        uint256 expR = SafeCast.toUint256(FixedPointMathLib.expWad(R_minus_1));
        actualSlippage = FixedPointMathLib.mulWad(expR, baseSlippageWad).fromWad(Constants.RISK_SLIPPAGE_DECIMALS);
        return Math.min(actualSlippage, maxSlippage);
    }

    function _withSlipMaxOpenWad(int256 lockOIWad, int256 windowCapWad, uint256 baseSlippage, uint256 userSlippage) internal pure returns (uint256) {
        if (userSlippage == 0) {
            return windowCapWad > lockOIWad ? SafeCast.toUint256(windowCapWad - lockOIWad) : 0;
        }
        uint256 x = (userSlippage.toWad(Constants.SLIPPAGE_DECIMALS) * 1e18) / baseSlippage.toWad(Constants.RISK_SLIPPAGE_DECIMALS);
        int256 r = FixedPointMathLib.lnWad(int256(x)) + int256(1e18);
        if (r <= 0) {
            return windowCapWad > lockOIWad ? SafeCast.toUint256(windowCapWad - lockOIWad) : 0;
        }

        int256 slipCapWad = (windowCapWad * r) / int256(1e18);
        return windowCapWad + slipCapWad > lockOIWad ? SafeCast.toUint256(windowCapWad + slipCapWad - lockOIWad) : 0;
    }
}

