// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IChainlinkAdapter } from "./../../interfaces/IChainlinkAdapter.sol";
import { IChainlinkFeeManager, IChainlinkOracle } from "./../../interfaces/IChainlinkOracle.sol";
import { IChainlinkOracle } from "./../../interfaces/IChainlinkOracle.sol";
import { BaseOracleAdapter } from "./BaseOracleAdapter.sol";

contract ChainlinkAdapter is BaseOracleAdapter, IChainlinkAdapter {
    IChainlinkOracle public chainlink;
    mapping(bytes32 priceId => uint32 decimals) private _priceIdDecimals;

    error NotSupportVersion();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager, address _chainlink) public initializer {
        __OracleAdapter_init(addressManager);

        chainlink = IChainlinkOracle(_chainlink);
    }

    function getOraclePriceDecimals(bytes32 priceId) external view returns (uint32) {
        return _priceIdDecimals[priceId];
    }

    function updateVerifyAddress(address newAddress) external onlyPriceAdapterRegistry {
        address oldAddress = address(chainlink);
        chainlink = IChainlinkOracle(newAddress);
        emit VerifyAddressUpdated(oldAddress, newAddress);
    }

    function setOraclePriceDecimals(bytes32 priceId, uint32 decimals) external onlyPriceAdapterRegistry {
        _priceIdDecimals[priceId] = decimals;
        emit ChainlinkPriceDecimalsUpdated(priceId, decimals);
    }

    function _getFee(bytes[] memory updateData) internal view override returns (uint256 fee) {
        if (chainlink.s_feeManager() == address(0)) return 0;

        IChainlinkFeeManager feeManager = IChainlinkFeeManager(chainlink.s_feeManager());
        address feeTokenAddress = feeManager.i_nativeAddress();
        fee = _getFeeAndRewards(updateData, feeTokenAddress, feeManager);
    }

    function _verify(
        bytes32[] memory priceIds,
        bytes[] memory updatePayloads,
        uint64[] memory /* publishTimes */
    ) internal override returns (VerifiedPrice[] memory) {
        uint256 totalFee;
        address feeTokenAddress;
        if (chainlink.s_feeManager() != address(0)) {
            IChainlinkFeeManager feeManager = IChainlinkFeeManager(chainlink.s_feeManager());

            feeTokenAddress = feeManager.i_nativeAddress();
            totalFee = _getFeeAndRewards(updatePayloads, feeTokenAddress, feeManager);
        }

        if (msg.value != totalFee) revert IncorrectFee(totalFee);

        bytes[] memory verifiedReportData;
        try chainlink.verifyBulk{ value: totalFee }(updatePayloads, abi.encode(feeTokenAddress)) returns (bytes[] memory _data) {
            verifiedReportData = _data;
        } catch {
            revert VerifyPriceFailed();
        }
        VerifiedPrice[] memory verifiedPrices = new VerifiedPrice[](verifiedReportData.length);
        for (uint256 i = 0; i < verifiedReportData.length; ++i) {
            uint16 reportVersion = _checkReportVersion(updatePayloads[i]);
            uint256 decimals = uint256(_priceIdDecimals[priceIds[i]]);

            if (reportVersion == 2) {
                IChainlinkOracle.ReportV2 memory verifiedReport = abi.decode(verifiedReportData[i], (IChainlinkOracle.ReportV2));

                verifiedPrices[i] = VerifiedPrice({
                    priceId: verifiedReport.feedId,
                    price: _returnPriceWithDecimals(int256(verifiedReport.price), decimals),
                    publishTime: uint64(verifiedReport.validFromTimestamp)
                });
            } else {
                IChainlinkOracle.ReportV3 memory verifiedReport = abi.decode(verifiedReportData[i], (IChainlinkOracle.ReportV3));

                verifiedPrices[i] = VerifiedPrice({
                    priceId: verifiedReport.feedId,
                    price: _returnPriceWithDecimals(int256(verifiedReport.price), decimals),
                    publishTime: uint64(verifiedReport.validFromTimestamp)
                });
            }
        }
        return verifiedPrices;
    }

    function _getFeeAndRewards(
        bytes[] memory updateData,
        address feeToken,
        IChainlinkFeeManager feeManager
    ) internal view returns (uint256 totalFee) {
        for (uint256 i = 0; i < updateData.length; ++i) {
            (, bytes memory reportData) = abi.decode(updateData[i], (bytes32[3], bytes));

            (IChainlinkFeeManager.Asset memory fee, , ) = feeManager.getFeeAndReward(address(this), reportData, feeToken);

            totalFee += fee.amount;
        }
        return totalFee;
    }

    function _checkReportVersion(bytes memory updateData) internal pure returns (uint16) {
        (, bytes memory reportData) = abi.decode(updateData, (bytes32[3], bytes));

        uint16 reportVersion = (uint16(uint8(reportData[0])) << 8) | uint16(uint8(reportData[1]));

        if (reportVersion != 2 && reportVersion != 3) revert NotSupportVersion();

        return reportVersion;
    }
}

