// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IFundingRate } from "./../interfaces/IFundingRate.sol";
import { IOrderManager } from "./../interfaces/IOrderManager.sol";
import { IPoolManager } from "./../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../interfaces/IPositionManager.sol";
import { IRiskController } from "./../interfaces/IRiskController.sol";
import { IRiskParameter } from "./../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../interfaces/ITradingVault.sol";
import { Constants, PoolMetadata, MarketMetadata, Direction, PositionMetadata, PositionId, PoolId, Errors } from "./../types/Types.sol";
import { PrecisionUtils } from "./../utils/PrecisionUtils.sol";
import { LibPositionMetadata, Position } from "./Position.sol";
import { PositionHelper } from "./PositionHelper.sol";
import { TradingHelper } from "./TradingHelper.sol";

library PositionExternalHelper {
    using Position for Position.Data;
    using LibPositionMetadata for PositionMetadata;
    using PrecisionUtils for uint256;

    /// @notice update early close price if opening position causes backup asset reserve
    function updatePositionEarlyClosePrice(
        IPoolManager poolManager,
        PoolMetadata memory pool,
        PositionMetadata storage position,
        uint256 executeSize,
        uint256 executePrice
    ) external {
        IPoolVault poolVault = IPoolVault(pool.poolVault);
        bool causedReserve = _causedBackupAssetReserve(pool, poolVault, position.direction, executeSize, executePrice);
        if (causedReserve || position.earlyClosePrice > 0) {
            (, MarketMetadata memory market) = poolManager.getPoolMarket(position.poolId);
            uint256 earlyClosePrice = _calculateEarlyClosePrice(
                position.entryPrice,
                position.direction,
                market.quoteReserveRatio,
                market.baseReserveRatio
            );
            position.updateEarlyClosePrice(earlyClosePrice);
        }
    }

    /// @notice update position risk tier
    function updatePositionRiskTier(
        IFundingRate fundingRate,
        ITradingVault tradingVault,
        IRiskParameter riskParameter,
        IPoolManager poolManager,
        IPositionManager positionManager,
        PositionMetadata storage position,
        PoolMetadata memory pool,
        PositionId positionId,
        address owner,
        uint256 executePrice
    ) external {
        position.updateRiskTier(pool.riskTier);
        // Re-check position health after applying updated risk tier
        IRiskParameter.PoolConfigParams memory poolConfig = riskParameter.getPoolConfigParams(pool.riskTier);
        (bool isHealthy, ) = PositionHelper.checkPositionHealthy(
            position,
            fundingRate,
            tradingVault,
            poolManager,
            positionManager,
            poolConfig,
            pool,
            positionId,
            executePrice,
            owner
        );
        require(isHealthy, Errors.UnhealthyAfterRiskTierApplied(positionId));
    }

    function transferPosition(
        Position.Data storage positionData,
        IOrderManager orderManager,
        IRiskController riskController,
        IPoolManager poolManager,
        PoolId poolId,
        PositionId positionId,
        PositionId newPositionId,
        address from,
        address to
    ) external {
        address tradingVault = poolManager.getTradingVault(poolId);

        positionData.transfer(positionId, newPositionId);
        orderManager.removePositionOrders(positionId);
        ITradingVault(tradingVault).migratePositionCollateral(positionId, newPositionId);
        riskController.migratePositionRiskControlData(poolId, from, to, positionId, newPositionId);
    }

    /// @notice Simulate reserve operation to determine if backup assets would be reserved
    /// @dev Long positions use _reserveBasePriority (BASE first, QUOTE backup)
    /// @dev Short positions use _reserveQuotePriority (QUOTE first, BASE backup)
    function _causedBackupAssetReserve(
        PoolMetadata memory pool,
        IPoolVault poolVault,
        Direction direction,
        uint256 executeSize,
        uint256 executePrice
    ) private view returns (bool) {
        (uint256 baseReservable, uint256 quoteReservable) = poolVault.reservable();

        if (direction == Direction.Long) {
            // Long: insufficient BASE would trigger backup QUOTE reserve
            return baseReservable < executeSize;
        } else {
            // Short: insufficient QUOTE would trigger backup BASE reserve
            uint256 notional = TradingHelper.convertTokenAmount(pool.baseToken, pool.quoteToken, executeSize.mulPrice(executePrice));
            return quoteReservable < notional;
        }
    }

    /// @notice Calculate early close price using reserve ratios
    /// @dev Long: P_close = P_avg × (1 + kQ), Short: P_close = P_avg / (1 + kI)
    /// @param entryPrice Position entry price
    /// @param direction Position direction
    /// @param kQ Quote reserve ratio coefficient (%)
    /// @param kI Index reserve ratio coefficient (%)
    /// @return earlyClosePrice Calculated early close price
    function _calculateEarlyClosePrice(
        uint256 entryPrice,
        Direction direction,
        uint256 kQ,
        uint256 kI
    ) private pure returns (uint256 earlyClosePrice) {
        if (direction == Direction.Long) {
            // Long: P_close = P_avg × (1 + kQ)
            earlyClosePrice = entryPrice.mulPrecision(Constants.RESERVE_RATIO_PRECISION + kQ, Constants.RESERVE_RATIO_PRECISION);
        } else {
            // Short: P_close = P_avg / (1 + kI)
            earlyClosePrice = entryPrice.divPrecision(Constants.RESERVE_RATIO_PRECISION + kI, Constants.RESERVE_RATIO_PRECISION);
        }
    }
}

