// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { ICoreBridge, GuardianSignature } from "wormhole-sdk/interfaces/ICoreBridge.sol";
import {
    QueryResponseLib,
    QueryResponse,
    PerChainQueryResponse,
    EthCallQueryResponse,
    EthCallRecord
} from "wormhole-sdk/libraries/QueryResponse.sol";
import { Errors } from "../../../types/Errors.sol";

/// @title WormholeCCQLib
/// @notice Handles Wormhole Cross-Chain Query (CCQ) message decoding and verification.
///      reference: https://wormhole.com/docs/products/reference/chain-ids/
library WormholeCCQLib {

    /// Wormhole chain ID for BNB Smart Chain (BSC)
    uint16 private constant BSC_CHAIN_ID = 4;

    function verifyValidatorsCCQMessage(
        address wormhole,
        address validatorView,
        bytes4 selector,
        uint32 maxAge,
        bytes memory response,
        GuardianSignature[] memory guardianSignatures
    ) external view returns (address[] memory validators) {
        address[] memory contracts = new address[](1);
        bytes4[] memory selectors = new bytes4[](1);
        contracts[0] = validatorView;
        selectors[0] = selector;

        QueryResponse memory ret = QueryResponseLib.decodeAndVerifyQueryResponseMem(
            wormhole,
            response,
            guardianSignatures,
            ICoreBridge(wormhole).getCurrentGuardianSetIndex()
        );
        require(ret.responses.length == 1, Errors.ResponseCountMismatch());

        PerChainQueryResponse memory chainResp = ret.responses[0];
        require(chainResp.chainId == BSC_CHAIN_ID, Errors.InvalidSourceChain());

        EthCallQueryResponse memory ethData = QueryResponseLib.decodeEthCallQueryResponse(chainResp);
        require(block.timestamp - ethData.blockTime <= maxAge ,Errors.StaleEthCall());

        EthCallRecord[] memory ethCalls = ethData.results;
        require(ethCalls.length == 1, Errors.EthCallCountMismatch());

        EthCallRecord memory ethCall = ethCalls[0];
        QueryResponseLib.validateEthCallRecord(ethCall, contracts, selectors);
        validators = abi.decode(ethCall.result, (address[]));
    }
}

