// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { IChainlinkAggregator } from "./../../interfaces/IChainlinkAggregator.sol";
import { IOracleAdapter } from "./../../interfaces/IOracleAdapter.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { BaseContractUpgradeable } from "./../../misc/base/BaseContractUpgradeable.sol";
import { Constants, Errors } from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";

abstract contract BaseOracleAdapter is BaseContractUpgradeable, IOracleAdapter {
    using PrecisionUtils for uint256;

    modifier onlyPriceAdapterRegistry() {
        _onlyPriceAdapterRegistry();
        _;
    }

    function __OracleAdapter_init(address addressManager) internal onlyInitializing {
        bytes32[] memory identifiers = new bytes32[](1);
        identifiers[0] = Identifier.ORACLE_REGISTRY;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    function verifyPrice(
        bool applyExchangeRate,
        uint80 roundId,
        address quotePriceContract,
        bytes32 priceId,
        bytes calldata payload,
        uint64 publishTime
    ) external payable virtual returns (PriceInfo memory) {
        (bytes32[] memory priceIds, bytes[] memory payloads, uint64[] memory publishTimes) = _wrapPriceInfo(priceId, payload, publishTime);
        VerifiedPrice[] memory verifiedPrices = _verify(priceIds, payloads, publishTimes);
        require(priceId == verifiedPrices[0].priceId, PriceIdMismatch());
        if (!applyExchangeRate) {
            return PriceInfo({ price: verifiedPrices[0].price, publishTime: verifiedPrices[0].publishTime });
        } else {
            (uint256 quotePrice, uint8 decimals) = _getQuotePrice(roundId, quotePriceContract);
            uint256 price = verifiedPrices[0].price.divPrecision(quotePrice, 10 ** decimals);
            return PriceInfo({ price: price, publishTime: verifiedPrices[0].publishTime });
        }
    }

    function getFee(bytes[] calldata updateData) external view virtual returns (uint256) {
        return _getFee(updateData);
    }

    function getLatestQuotePrice(address quoteContract) external view virtual returns (uint256, uint8) {
        return _getQuotePrice(0, quoteContract);
    }

    function _getQuotePrice(uint80 roundId, address quoteContract) internal view virtual returns (uint256, uint8) {
        int256 answer;
        if (roundId == 0) {
            (, answer, , , ) = IChainlinkAggregator(quoteContract).latestRoundData();
        } else {
            (, answer, , , ) = IChainlinkAggregator(quoteContract).getRoundData(roundId);
        }
        require(answer >= 0, InvalidPrice());
        uint8 decimals = IChainlinkAggregator(quoteContract).decimals();
        return (uint256(answer), decimals);
    }

    function _verify(
        bytes32[] memory priceIds,
        bytes[] memory updatePayloads,
        uint64[] memory publishTimes
    ) internal virtual returns (VerifiedPrice[] memory);

    function _getFee(bytes[] memory updateData) internal view virtual returns (uint256);

    function _wrapPriceInfo(
        bytes32 priceId,
        bytes memory payload,
        uint64 publishTime
    ) internal pure returns (bytes32[] memory, bytes[] memory, uint64[] memory) {
        bytes32[] memory priceIds = new bytes32[](1);
        priceIds[0] = priceId;
        bytes[] memory updateData = new bytes[](1);
        updateData[0] = payload;
        uint64[] memory publishTimes = new uint64[](1);
        publishTimes[0] = publishTime;
        return (priceIds, updateData, publishTimes);
    }

    function _returnPriceWithDecimals(int256 price, uint256 decimals) internal pure returns (uint256) {
        require(price >= 0, InvalidPrice());
        return uint256(price) * (10 ** (Constants.PRICE_DECIMALS - decimals));
    }

    function _onlyPriceAdapterRegistry() internal view {
        if (msg.sender != _getDependencyAddress(Identifier.ORACLE_REGISTRY)) revert Errors.PermissionDenied(msg.sender, address(this));
    }
}

