pragma solidity ^0.8.30;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { ICollectFee } from "./../../interfaces/ICollectFee.sol";
import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IMatcher } from "./../../interfaces/IMatcher.sol";
import { IOrderManager } from "./../../interfaces/IOrderManager.sol";
import { IPoolManager } from "./../../interfaces/IPoolManager.sol";
import { IPoolVault } from "./../../interfaces/IPoolVault.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { IRiskController } from "./../../interfaces/IRiskController.sol";
import { IRiskParameter } from "./../../interfaces/IRiskParameter.sol";
import { ITradingRouter } from "./../../interfaces/ITradingRouter.sol";
import { ExecuteHelper } from "./../../libraries/ExecuteHelper.sol";
import { LibPoolMetadata } from "./../../libraries/Pool.sol";
import { LibPositionMetadata } from "./../../libraries/Position.sol";
import { TradingHelper } from "./../../libraries/TradingHelper.sol";
import { RiskHelper } from "./../../manager/risk-control/RiskHelper.sol";
import {
    Errors,
    PoolMetadata,
    PositionMetadata,
    OrderMetadata,
    MarketMetadata,
    PoolId,
    OrderId,
    OrderType,
    Operation,
    MatchType
} from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";
import { TradeUtils } from "./../../utils/TradeUtils.sol";
import { IMatchExecuteFacet } from "./../interfaces/IMatchExecuteFacet.sol";
import { ExecutorBaseFacet } from "./ExecutorBaseFacet.sol";

/// @title MatchExecuteFacet
/// @notice Facet for handling match order execution
contract MatchExecuteFacet is ExecutorBaseFacet, IMatchExecuteFacet {
    using LibPoolMetadata for PoolMetadata;
    using LibPositionMetadata for PositionMetadata;
    using PrecisionUtils for uint256;

    /// @notice Match execution result
    struct MatchResult {
        uint256 executePrice; // Execution price
        uint256 executeSize; // Execution size (minimum of both orders' effective sizes)
        uint256 triggerEffectiveSize; // Trigger order's effective size
        uint256 matchedEffectiveSize; // Matched order's effective size
        bool isTriggerDeterminesFillSize; // True if the trigger order determines the fill size.
    }

    /// @inheritdoc IMatchExecuteFacet
    function matchExecute(MatchExecuteParams calldata params) external override onlyKeeper {
        address keeper = msg.sender;
        IOrderManager orderManager = _getOrderManager();
        IPositionManager positionManager = _getPositionManager();
        IPoolManager poolManager = _getPoolManager();

        OrderMetadata memory triggerOrder = orderManager.getOrder(params.triggerOrderId);
        OrderMetadata memory matchedOrder = orderManager.getOrder(params.matchedOrderId);

        // Verify that the orders are from the same pool
        bool isSamePool = PoolId.unwrap(triggerOrder.poolId) == PoolId.unwrap(matchedOrder.poolId);
        require(isSamePool, Errors.InvalidOrderPair(params.triggerOrderId, params.matchedOrderId));
        // Verify that one order is buy and one order is sell
        bool triggerIsBuy = TradeUtils.getOrderSide(triggerOrder.operation, triggerOrder.direction);
        bool matchedIsBuy = TradeUtils.getOrderSide(matchedOrder.operation, matchedOrder.direction);
        require(triggerIsBuy != matchedIsBuy, Errors.InvalidOrderPair(params.triggerOrderId, params.matchedOrderId));

        PoolId poolId = triggerOrder.poolId;
        PoolMetadata memory pool = poolManager.getPool(poolId);
        (uint256 marketPrice, ) = _getOracle().getMarketPrice(poolId);
        ITradingRouter tradingRouter = _getTradingRouter();

        bool interrupt;
        PositionMetadata memory triggerPosition;
        PositionMetadata memory matchedPosition;
        IRiskParameter.RiskParamData memory triggerRiskParams;
        IRiskParameter.RiskParamData memory matchedRiskParams;
        // Check order interrupts and get positions
        (interrupt, triggerPosition, triggerRiskParams) = _checkOrderInterrupt(
            orderManager,
            positionManager,
            tradingRouter,
            triggerOrder,
            params.triggerOrderId,
            pool,
            marketPrice,
            keeper
        );
        if (interrupt) return;
        // Check matched order interrupts and get position
        (interrupt, matchedPosition, matchedRiskParams) = _checkOrderInterrupt(
            orderManager,
            positionManager,
            tradingRouter,
            matchedOrder,
            params.matchedOrderId,
            pool,
            marketPrice,
            keeper
        );
        if (interrupt) return;

        // Calculate execution price and size
        MatchResult memory matchResult = _calculateMatchResult(
            orderManager,
            triggerOrder,
            params.triggerOrderId,
            triggerPosition,
            matchedOrder,
            params.matchedOrderId,
            matchedPosition,
            marketPrice
        );
        if (matchResult.executeSize == 0) return;

        // Validate slippage for both orders
        if (!_validateOrderSlippage(orderManager, triggerOrder, params.triggerOrderId, matchResult.executePrice)) return;
        if (!_validateOrderSlippage(orderManager, matchedOrder, params.matchedOrderId, matchResult.executePrice)) return;

        // Prepare positions for both orders
        _prepareOrderPosition(positionManager, triggerOrder, pool, marketPrice);
        _prepareOrderPosition(positionManager, matchedOrder, pool, marketPrice);

        IMatcher.MatchPoolExecuteParams memory matchPoolExecuteParams;
        if (matchResult.isTriggerDeterminesFillSize) {
            matchPoolExecuteParams = _needPoolExecute(
                positionManager,
                poolManager,
                matchedOrder,
                pool,
                matchedRiskParams,
                matchResult.matchedEffectiveSize - matchResult.executeSize,
                marketPrice
            );
        } else {
            matchPoolExecuteParams = _needPoolExecute(
                positionManager,
                poolManager,
                triggerOrder,
                pool,
                triggerRiskParams,
                matchResult.triggerEffectiveSize - matchResult.executeSize,
                marketPrice
            );
        }
        matchPoolExecuteParams.isTriggerOrder = !matchResult.isTriggerDeterminesFillSize;

        // Emit execution matched event
        (OrderId[] memory triggerOrderIds, OrderId[] memory matchedOrderIds) = _getMatcher().hybridMatchOrder(
            IMatcher.HybridMatchOrderParams({
                triggerOrderId: params.triggerOrderId,
                triggerOrder: triggerOrder,
                matchedOrderId: params.matchedOrderId,
                matchedOrder: matchedOrder,
                matchSize: matchResult.executeSize,
                matchPrice: matchResult.executePrice,
                keeper: msg.sender,
                matchPoolExecuteParams: matchPoolExecuteParams
            })
        );
        _getEmiter().emitExecutionMatched(
            IEmiter.ExecutionMatchedParams({
                poolId: poolId,
                triggerOrderIds: triggerOrderIds,
                matchedOrderIds: matchedOrderIds,
                matchType: MatchType.Match,
                price: matchResult.executePrice
            })
        );
    }

    function _checkOrderInterrupt(
        IOrderManager orderManager,
        IPositionManager positionManager,
        ITradingRouter tradingRouter,
        OrderMetadata memory order,
        OrderId orderId,
        PoolMetadata memory pool,
        uint256 marketPrice,
        address feeRecipient
    ) internal returns (bool interrupt, PositionMetadata memory position, IRiskParameter.RiskParamData memory riskParams) {
        position = positionManager.getPosition(order.positionId);
        _collectExecutionFee(tradingRouter, order, position, pool.quoteToken, pool.tradingVault, feeRecipient);

        uint8 riskTier = position.isInitialized() ? position.riskTier : pool.riskTier;
        riskParams = _getRiskParameter().getRiskParamData(riskTier);
        interrupt = ExecuteHelper.checkOrderInterrupt(
            orderManager,
            positionManager,
            order,
            orderId,
            pool,
            riskParams.tradeLimitParams,
            position,
            marketPrice
        );
    }

    /// @notice Validate order slippage
    /// @param orderManager Order manager contract
    /// @param order Order metadata
    /// @param orderId Order ID
    /// @param executePrice Execution price
    /// @return valid True if slippage is valid, false otherwise
    function _validateOrderSlippage(
        IOrderManager orderManager,
        OrderMetadata memory order,
        OrderId orderId,
        uint256 executePrice
    ) internal returns (bool valid) {
        valid = TradeUtils.validateOrderSlippage(order.operation, order.direction, order.price, executePrice, order.slippagePct);
        if (!valid) {
            orderManager.uncompleteOrder(orderId, "Slippage exceeded");
        }
    }

    function _collectExecutionFee(
        ITradingRouter tradingRouter,
        OrderMetadata memory order,
        PositionMetadata memory position,
        address quoteToken,
        address tradingVault,
        address feeRecipient
    ) internal {
        if (position.isInitialized()) {
            tradingRouter.collectExecutionFee(
                ICollectFee.FeeSource.Position,
                abi.encode(ICollectFee.PositionFeeParams({ positionId: order.positionId, feeToken: quoteToken, tradingVault: tradingVault })),
                feeRecipient
            );
        } else {
            tradingRouter.collectExecutionFee(
                ICollectFee.FeeSource.Account,
                abi.encode(ICollectFee.AccountFeeParams({ poolId: order.poolId, feeToken: quoteToken, user: order.user })),
                feeRecipient
            );
        }
    }

    /// @notice Prepare position for order execution
    /// @param positionManager Position manager contract
    /// @param order Order metadata
    /// @param pool Pool metadata
    /// @param marketPrice Current market price
    function _prepareOrderPosition(
        IPositionManager positionManager,
        OrderMetadata memory order,
        PoolMetadata memory pool,
        uint256 marketPrice
    ) internal {
        bool ensureExists = order.operation == Operation.Decrease;
        positionManager.preparePosition(order.positionId, pool, order.direction, order.user, marketPrice, order.broker, ensureExists, true);
    }

    function _needPoolExecute(
        IPositionManager positionManager,
        IPoolManager poolManager,
        OrderMetadata memory order,
        PoolMetadata memory pool,
        IRiskParameter.RiskParamData memory riskParams,
        uint256 executeSize,
        uint256 marketPrice
    ) internal view returns (IMatcher.MatchPoolExecuteParams memory matchPoolExecuteParams) {
        if (executeSize == 0) return matchPoolExecuteParams;

        (, MarketMetadata memory market) = poolManager.getPoolMarket(pool.poolId);
        uint256 executePrice = ExecuteHelper.calculateExecutePrice(order, marketPrice);
        uint256 availableLiquiditySize = TradingHelper.availableLiquiditySize(
            pool.poolId,
            IPoolVault(pool.poolVault),
            positionManager,
            market.baseReserveRatio,
            market.quoteReserveRatio,
            order.operation,
            order.direction,
            executePrice
        );
        executeSize = Math.min(availableLiquiditySize, executeSize);

        IRiskController.LiquidityLock memory liquidityLock = _getRiskController().getLiquidityLock(order.poolId);
        (bool hasSlipExec, uint256 slippagePrice, uint256 actualExecSize) = RiskHelper.calculateOrderSlippage(
            pool,
            riskParams.riskLockParams,
            liquidityLock,
            order.operation,
            order.direction,
            executeSize,
            executePrice,
            order.slippagePct
        );
        if (hasSlipExec) {
            if (actualExecSize == 0) {
                matchPoolExecuteParams.needPoolExecute = false;
                return matchPoolExecuteParams;
            }
            uint256 availableLiquidityValue = availableLiquiditySize.mulPrice(executePrice);
            uint256 orderValue = executeSize.mulPrice(slippagePrice);

            executePrice = slippagePrice;
            executeSize = actualExecSize;
            if (availableLiquidityValue < orderValue) {
                executeSize = Math.min(availableLiquidityValue.divPrice(slippagePrice), executeSize);
            }
        }

        matchPoolExecuteParams.needPoolExecute = true;
        matchPoolExecuteParams.executeSize = executeSize;
        matchPoolExecuteParams.executePrice = executePrice;
        return matchPoolExecuteParams;
    }

    /// @notice Calculate match result (price and size) for matched orders
    /// @dev Calculates both execution price and size for matched orders
    ///      Price: Both Market orders use oracle price; One Limit/Stop + One Market use oracle price if condition met
    ///      Size: Minimum of both orders' effective sizes
    /// @param orderManager Order manager contract
    /// @param triggerOrder Trigger order metadata
    /// @param triggerOrderId Trigger order ID
    /// @param triggerPosition Trigger position metadata
    /// @param matchedOrder Matched order metadata
    /// @param matchedOrderId Matched order ID
    /// @param matchedPosition Matched position metadata
    /// @param oraclePrice Current oracle price
    /// @return result Match result with price and size details
    function _calculateMatchResult(
        IOrderManager orderManager,
        OrderMetadata memory triggerOrder,
        OrderId triggerOrderId,
        PositionMetadata memory triggerPosition,
        OrderMetadata memory matchedOrder,
        OrderId matchedOrderId,
        PositionMetadata memory matchedPosition,
        uint256 oraclePrice
    ) internal returns (MatchResult memory result) {
        // Calculate execution price
        result.executePrice = _calculateMatchExecutePrice(triggerOrder, matchedOrder, oraclePrice);

        // Calculate execution size
        result.triggerEffectiveSize = _calculateOrderEffectiveSize(triggerOrder, triggerPosition);
        result.matchedEffectiveSize = _calculateOrderEffectiveSize(matchedOrder, matchedPosition);

        if (result.triggerEffectiveSize == 0) {
            orderManager.uncompleteOrder(triggerOrderId, "No execute size");
            return result;
        }

        if (result.matchedEffectiveSize == 0) {
            orderManager.uncompleteOrder(matchedOrderId, "No execute size");
            return result;
        }

        // Determine which order limits the execution size
        result.executeSize = Math.min(result.triggerEffectiveSize, result.matchedEffectiveSize);
        result.isTriggerDeterminesFillSize = result.triggerEffectiveSize <= result.matchedEffectiveSize;
    }

    /// @notice Calculate execution price for matched orders
    /// @dev Both Market orders: use oracle price
    ///      One Limit/Stop + One Market: use oracle price if price condition met
    ///      Both Limit/Stop orders: revert (cannot match)
    /// @param triggerOrder Trigger order metadata
    /// @param matchedOrder Matched order metadata
    /// @param oraclePrice Current oracle price
    /// @return executePrice Execution price
    function _calculateMatchExecutePrice(
        OrderMetadata memory triggerOrder,
        OrderMetadata memory matchedOrder,
        uint256 oraclePrice
    ) internal pure returns (uint256 executePrice) {
        bool triggerIsMarket = triggerOrder.orderType == OrderType.Market;
        bool matchedIsMarket = matchedOrder.orderType == OrderType.Market;

        // Both Market orders: use oracle price
        if (triggerIsMarket && matchedIsMarket) {
            return oraclePrice;
        }

        // One Limit/Stop + One Market order
        if (_isLimitType(triggerOrder.orderType) && matchedIsMarket) {
            return _calculateLimitMarketPrice(triggerOrder, oraclePrice);
        }
        if (triggerIsMarket && _isLimitType(matchedOrder.orderType)) {
            return _calculateLimitMarketPrice(matchedOrder, oraclePrice);
        }

        // Both Limit/Stop orders cannot match
        revert Errors.MatchNotSupported();
    }

    function _calculateOrderEffectiveSize(
        OrderMetadata memory order,
        PositionMetadata memory position
    ) internal pure returns (uint256 effectiveSize) {
        uint256 remainingSize = order.size - order.filledSize;
        if (order.operation == Operation.Increase) {
            return remainingSize;
        } else {
            uint256 positionSize = position.isInitialized() ? position.size : 0;
            return Math.min(remainingSize, positionSize);
        }
    }

    /// @notice Calculate execution price for Limit/Stop + Market order match
    /// @dev Limit buy + Market sell: oracle price <= limit price, use oracle price
    ///      Limit sell + Market buy: oracle price >= limit price, use oracle price
    /// @param limitOrder Limit/Stop order metadata
    /// @param oraclePrice Current oracle price
    /// @return executePrice Execution price
    function _calculateLimitMarketPrice(OrderMetadata memory limitOrder, uint256 oraclePrice) internal pure returns (uint256 executePrice) {
        bool limitIsBuy = TradeUtils.getOrderSide(limitOrder.operation, limitOrder.direction);
        uint256 limitPrice = limitOrder.price;

        // Limit buy: oracle price must <= limit price
        // Limit sell: oracle price must >= limit price
        bool priceConditionMet = limitIsBuy ? oraclePrice <= limitPrice : oraclePrice >= limitPrice;
        if (!priceConditionMet) {
            revert Errors.MatchNotSupported();
        }

        return oraclePrice;
    }

    /// @notice Check if order type is Limit or Stop
    /// @param orderType Order type to check
    /// @return isLimitType True if order type is Limit or Stop
    function _isLimitType(OrderType orderType) internal pure returns (bool isLimitType) {
        return orderType == OrderType.Limit || orderType == OrderType.Stop;
    }
}

