// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.30;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { IAccount } from "./../../interfaces/IAccount.sol";
import { IDisputeCourt } from "./../../interfaces/IDisputeCourt.sol";
import { IEmiter } from "./../../interfaces/IEmiter.sol";
import { IPoolManager } from "./../../interfaces/IPoolManager.sol";
import { IPositionManager } from "./../../interfaces/IPositionManager.sol";
import { IReservePool } from "./../../interfaces/IReservePool.sol";
import { IRiskController } from "./../../interfaces/IRiskController.sol";
import { IRiskParameter } from "./../../interfaces/IRiskParameter.sol";
import { ITradingVault } from "./../../interfaces/ITradingVault.sol";
import { Identifier } from "./../../libraries/Identifier.sol";
import { RiskControl } from "./../../libraries/RiskControl.sol";
import { TradingHelper } from "./../../libraries/TradingHelper.sol";
import { BaseContractUpgradeable } from "./../../misc/base/BaseContractUpgradeable.sol";
import { Errors, PoolMetadata, PositionMetadata, PoolId, PositionId } from "./../../types/Types.sol";
import { PrecisionUtils } from "./../../utils/PrecisionUtils.sol";

contract RiskController is BaseContractUpgradeable, IRiskController {
    using PrecisionUtils for uint256;
    using RiskControl for RiskControl.Data;
    using SignedMath for int256;
    using Math for uint256;

    RiskControl.Data private _riskControlData;

    modifier onlyDisputeCourt() {
        _onlyDisputeCourt();
        _;
    }

    modifier notDispute(PoolId poolId) {
        _notDispute(poolId);
        _;
    }

    modifier inDispute(PoolId poolId) {
        _inDispute(poolId);
        _;
    }

    modifier onlyTradingVault(PoolId poolId) {
        _onlyTradingVault(poolId);
        _;
    }

    modifier onlyOrderManager() {
        _onlyOrderManager();
        _;
    }

    modifier onlyPositionManager() {
        _onlyPositionManager();
        _;
    }

    modifier onlyMatcher() {
        _onlyMatcher();
        _;
    }

    modifier onlyMatcherOrTradingRouter() {
        _onlyMatcherOrTradingRouter();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address addressManager) public initializer {
        bytes32[] memory identifiers = new bytes32[](10);
        identifiers[0] = Identifier.RISK_PARAMETER;
        identifiers[1] = Identifier.POOL_MANAGER;
        identifiers[2] = Identifier.POSITION_MANAGER;
        identifiers[3] = Identifier.DISPUTE_COURT;
        identifiers[4] = Identifier.ACCOUNT;
        identifiers[5] = Identifier.ORDER_MANAGER;
        identifiers[6] = Identifier.MATCHER;
        identifiers[7] = Identifier.RESERVE_POOL;
        identifiers[8] = Identifier.EMITER;
        identifiers[9] = Identifier.TRADING_ROUTER;
        __BaseContractUpgradeable_init(addressManager, identifiers);
    }

    function isDisputeMode(PoolId poolId) external view returns (bool) {
        return _riskControlData.getDisputeMode(poolId);
    }

    function getLiquidityLock(PoolId poolId) external view returns (LiquidityLock memory) {
        return _riskControlData.getLiquidityLock(poolId);
    }

    function getProfitLock(PoolId poolId, address user) external view returns (ProfitLock memory) {
        return _riskControlData.getProfitLock(poolId, user);
    }

    function getFrozen(PoolId poolId, address user) external view returns (bool) {
        return _riskControlData.getFrozen(poolId, user);
    }

    function checkUserProfitAvailable(PoolId poolId, address user) external view returns (bool) {
        return _checkUserProfitAvailable(poolId, user);
    }

    function getTradableProfit(PoolId poolId, address user) external view returns (bool profitIsReleased, uint256 tradableProfit) {
        (bool isReleased, ProfitLock memory lock) = _checkProfitLock(poolId, user);
        profitIsReleased = isReleased;
        tradableProfit = lock.quoteAmount - lock.usedQuoteAmount;
    }

    function getPositionRiskControlData(PositionId positionId) external view returns (PositionRiskControlData memory) {
        return _riskControlData.getPositionRiskControlData(positionId);
    }

    function getRespondentProfits(
        PoolId poolId,
        address[] memory respondents
    ) external view returns (uint256 totalBaseProfit, uint256 totalQuoteProfit) {
        for (uint256 i = 0; i < respondents.length; ++i) {
            ProfitLock memory lock = _riskControlData.getProfitLock(poolId, respondents[i]);
            totalBaseProfit += lock.baseAmount;
            totalQuoteProfit += lock.quoteAmount;
        }
    }

    function recordLiquidityLock(PoolId poolId, uint256 triggerPrice, int256 orderUsedOI) external onlyOrderManager {
        IRiskParameter.RiskLockParams memory riskLockParams = _getPoolRiskLockParamData(poolId);

        IRiskController.LiquidityLock memory liquidityLock = _riskControlData.updateLiquidityLock(
            poolId,
            SafeCast.toUint64(block.timestamp),
            riskLockParams.liquidityWindowSize,
            riskLockParams.priceRangePct,
            triggerPrice,
            orderUsedOI
        );

        _getEmiter().emitLiquidityLockUpdated(
            IEmiter.LiquidityLockUpdatedParams(
                poolId,
                liquidityLock.windowAnchor,
                liquidityLock.priceFloor,
                liquidityLock.priceCeiling,
                liquidityLock.openInterest
            )
        );
    }

    function checkAndReleaseProfitLock(PoolId poolId, address user) public returns (uint256) {
        if (!_checkUserProfitAvailable(poolId, user)) return 0;

        (bool isReleased, ProfitLock memory lock) = _checkProfitLock(poolId, user);
        if (isReleased && (lock.baseAmount > 0 || lock.quoteAmount > 0)) {
            (uint256 baseAmount, uint256 quoteAmount) = _releaseProfitLock(poolId, user);
            _getAccount().releaseFromProfitUnlock(user, poolId, baseAmount, quoteAmount);
            return 0;
        }
        return lock.quoteAmount - lock.usedQuoteAmount;
    }

    function recordPositionRiskControlData(
        PositionId positionId,
        PoolId poolId,
        address owner,
        int256 freeAmount,
        int256 lockedAmount
    ) external onlyTradingVault(poolId) {
        IRiskController.PositionRiskControlData memory collateralInfo = _riskControlData.getPositionRiskControlData(positionId);
        if (freeAmount < 0) {
            require(collateralInfo.freeAmount >= freeAmount.abs(), Errors.InsufficientFreeCollateral(positionId, collateralInfo.freeAmount));
        }
        if (lockedAmount < 0) {
            require(collateralInfo.lockedAmount >= lockedAmount.abs(), Errors.InsufficientLockedCollateral(positionId, collateralInfo.lockedAmount));
        }

        collateralInfo = _riskControlData.createPositionRiskControlData(positionId, poolId, owner, freeAmount, lockedAmount);
        emit ProfitUsedQuoteUpdated(poolId, owner, lockedAmount);
        _getEmiter().emitPositionRiskControlDataUpdated(
            IEmiter.PositionRiskControlDataUpdatedParams(poolId, positionId, collateralInfo.freeAmount, collateralInfo.lockedAmount)
        );
    }

    function chargePositionRiskControlData(
        PositionMetadata memory position,
        PositionId positionId,
        address owner,
        int256 charge
    ) external override onlyMatcherOrTradingRouter returns (IRiskController.PositionRiskControlData memory, int256 profitChange) {
        PoolId poolId = position.poolId;
        checkAndReleaseProfitLock(poolId, owner);

        IRiskController.PositionRiskControlData memory collateralInfo = _riskControlData.getPositionRiskControlData(positionId);
        uint256 chargeAbs = charge.abs();
        if (charge < 0 && collateralInfo.lockedAmount < chargeAbs) {
            require(
                collateralInfo.freeAmount + collateralInfo.lockedAmount >= chargeAbs,
                Errors.InsufficientCollateral(positionId, collateralInfo.freeAmount + collateralInfo.lockedAmount)
            );

            profitChange = -int256(collateralInfo.lockedAmount);
            collateralInfo = _riskControlData.updatePositionRiskControlData(
                positionId,
                // forge-lint: disable-next-line(unsafe-typecast)
                -int256(chargeAbs - collateralInfo.lockedAmount),
                -int256(collateralInfo.lockedAmount)
            );
        } else {
            profitChange = charge;
            collateralInfo = _riskControlData.updatePositionRiskControlData(positionId, 0, charge);
        }

        if (position.size != 0) _recordProfitLock(poolId, owner, 0, profitChange, profitChange);

        _getEmiter().emitPositionRiskControlDataUpdated(
            IEmiter.PositionRiskControlDataUpdatedParams(poolId, positionId, collateralInfo.freeAmount, collateralInfo.lockedAmount)
        );
        return (collateralInfo, profitChange);
    }

    function closePositionRiskControlData(
        PositionRiskControlData memory collateralInfo,
        PositionMetadata memory position,
        PositionId positionId,
        bool isLiquidation,
        address owner,
        uint256 baseAmount,
        uint256 quoteAmount,
        uint256 price,
        int256 profitChange
    ) external override onlyMatcher {
        uint256 profitBaseAmount;
        int256 profitQuoteAmount;
        uint256 freeBaseAmount;
        uint256 freeQuoteAmount;
        if (baseAmount > 0 || quoteAmount > 0) {
            PoolMetadata memory pool = _getPoolManager().getPool(position.poolId);
            freeQuoteAmount = Math.min(quoteAmount, collateralInfo.freeAmount);
            profitQuoteAmount = profitChange < 0 ? profitChange: int256(quoteAmount - freeQuoteAmount);

            if (quoteAmount < collateralInfo.freeAmount) {
                uint256 shortfall = collateralInfo.freeAmount - quoteAmount;
                freeBaseAmount = TradingHelper.convertTokenAmount(pool.quoteToken, pool.baseToken, shortfall.divPrice(price));
                profitBaseAmount = baseAmount > freeBaseAmount ? baseAmount - freeBaseAmount : 0;
            } else {
                freeBaseAmount = 0;
                profitBaseAmount = baseAmount;
            }

            if (!isLiquidation) {
                _getAccount().settlementDeposit(positionId, owner, pool, freeBaseAmount, freeQuoteAmount, baseAmount, quoteAmount);
                _recordProfitLock(position.poolId, owner, profitBaseAmount, profitQuoteAmount, profitChange);
            } else {
                _recordProfitLock(position.poolId, owner, 0, profitChange, profitChange);
            }
        }
        _riskControlData.closePositionRiskControlData(positionId, position.poolId, owner, collateralInfo.lockedAmount);
        emit ProfitUsedQuoteUpdated(position.poolId, owner, -int256(collateralInfo.lockedAmount));
    }

    function migratePositionRiskControlData(
        PoolId poolId,
        address from,
        address to,
        PositionId fromId,
        PositionId toId
    ) external onlyPositionManager {
        require(!_riskControlData.getDisputeMode(poolId), Errors.InDisputeMode());
        require(!_riskControlData.getFrozen(poolId, from), Errors.UserProfitFrozen());
        require(_riskControlData.getPositionRiskControlData(fromId).lockedAmount == 0, Errors.PositionHasLockedAmount());
        _riskControlData.migratePositionRiskControlData(fromId, toId);

        _getEmiter().emitPositionRiskControlDataMigrated(IEmiter.PositionRiskControlDataMigratedParams(from, to, fromId, toId));
    }

    function enterDispute(PoolId poolId) external payable onlyDisputeCourt {
        _riskControlData.recordDisputeCase(poolId, true);
        _getEmiter().emitEnterDispute(poolId, _riskControlData.getDisputeCaseCount(poolId));
    }

    function exitDispute(PoolId poolId) external onlyDisputeCourt {
        _riskControlData.recordDisputeCase(poolId, false);
        _getEmiter().emitExitDispute(poolId, _riskControlData.getDisputeCaseCount(poolId));
    }

    function freezeProfits(PoolId poolId, address[] calldata users) external onlyDisputeCourt {
        _riskControlData.freezeProfits(poolId, users);
        emit FreezeProfits(poolId, users);
    }

    function unfreezeProfit(PoolId poolId, address user) external onlyDisputeCourt {
        _riskControlData.unfreezeProfits(poolId, user);
        emit UnfreezeProfits(poolId, user);
    }

    function confiscateProfits(PoolId poolId, address[] calldata respondents) external onlyDisputeCourt {
        _riskControlData.confiscateProfits(poolId, respondents);
        emit ConfiscateProfit(poolId, respondents);
    }

    function _checkUserProfitAvailable(PoolId poolId, address user) internal view returns (bool) {
        return !_riskControlData.getDisputeMode(poolId) && !_riskControlData.getFrozen(poolId, user);
    }

    function _recordProfitLock(PoolId poolId, address owner, uint256 profitBaseAmount, int256 profitQuoteAmount, int256 profitChange) internal {
        IRiskParameter.RiskLockParams memory riskLockParams = _getPoolRiskLockParamData(poolId);

        // profit lock was released, no need to record
        if (
            (profitBaseAmount == 0 && profitQuoteAmount == 0 && profitChange == 0) ||
            (profitChange < 0 && !_riskControlData.isProfitLocked(poolId, owner))
        ) return;

        uint64 releaseTime = profitChange <= 0
            ? _riskControlData.getProfitLock(poolId, owner).releaseTime
            : SafeCast.toUint64(block.timestamp) + riskLockParams.profitWindowSize;

        IRiskController.ProfitLock memory profitLock = _riskControlData.updateProfitLock(
            poolId,
            owner,
            releaseTime,
            profitBaseAmount,
            profitQuoteAmount,
            profitChange
        );

        emit ProfitLockUpdated(poolId, owner, profitLock.baseAmount, profitLock.quoteAmount, profitLock.usedQuoteAmount, profitLock.releaseTime);
    }

    function _releaseProfitLock(PoolId poolId, address user) internal returns (uint256, uint256) {
        (uint256 baseAmount, uint256 quoteAmount) = _riskControlData.releaseProfitLock(poolId, user);
        bytes32[] memory positionIds = _getPositionManager().getUserPoolPositionIds(user, poolId);
        _riskControlData.releasePositionCollateralProfit(positionIds);

        _getEmiter().emitProfitLockReleased(IEmiter.ProfitLockReleasedParams(poolId, user, baseAmount, quoteAmount, positionIds));
        return (baseAmount, quoteAmount);
    }

    function _checkProfitLock(PoolId poolId, address user) internal view returns (bool isExpired, IRiskController.ProfitLock memory profitLock) {
        isExpired = _riskControlData.isProfitLockExpired(poolId, user, SafeCast.toUint64(block.timestamp));
        profitLock = _riskControlData.getProfitLock(poolId, user);
    }

    function _getPoolRiskLockParamData(PoolId poolId) internal view returns (IRiskParameter.RiskLockParams memory) {
        uint8 riskTier = _getPoolManager().getPoolRiskTier(poolId);
        return _getRiskParameter().getRiskLockParams(riskTier);
    }

    function _getPool(PoolId poolId) internal view returns (PoolMetadata memory) {
        return _getPoolManager().getPool(poolId);
    }

    function _onlyDisputeCourt() internal view {
        require(address(_getDisputeCourt()) == msg.sender, Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _notDispute(PoolId poolId) internal view {
        require(!_riskControlData.getDisputeMode(poolId), Errors.InDisputeMode());
    }

    function _inDispute(PoolId poolId) internal view {
        require(_riskControlData.getDisputeMode(poolId), Errors.NotInDisputeMode());
    }

    function _onlyTradingVault(PoolId poolId) internal view {
        require(msg.sender == _getPoolManager().getTradingVault(poolId), Errors.PermissionDenied(msg.sender, address(this)));

        require(PoolId.unwrap(poolId) == PoolId.unwrap(ITradingVault(msg.sender).poolId()), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyOrderManager() internal view {
        require(msg.sender == super._getDependencyAddress(Identifier.ORDER_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyPositionManager() internal view {
        require(msg.sender == _getDependencyAddress(Identifier.POSITION_MANAGER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyMatcher() internal view {
        require(msg.sender == super._getDependencyAddress(Identifier.MATCHER), Errors.PermissionDenied(msg.sender, address(this)));
    }

    function _onlyMatcherOrTradingRouter() internal view {
        require(
            msg.sender == super._getDependencyAddress(Identifier.MATCHER)
            || msg.sender == super._getDependencyAddress(Identifier.TRADING_ROUTER)
            , Errors.PermissionDenied(msg.sender, address(this))
        );
    }

    function _getRiskParameter() internal view returns (IRiskParameter) {
        return IRiskParameter(super._getDependencyAddress(Identifier.RISK_PARAMETER));
    }

    function _getPoolManager() internal view returns (IPoolManager) {
        return IPoolManager(super._getDependencyAddress(Identifier.POOL_MANAGER));
    }

    function _getPositionManager() internal view returns (IPositionManager) {
        return IPositionManager(super._getDependencyAddress(Identifier.POSITION_MANAGER));
    }

    function _getDisputeCourt() internal view returns (IDisputeCourt) {
        return IDisputeCourt(super._getDependencyAddress(Identifier.DISPUTE_COURT));
    }

    function _getAccount() internal view returns (IAccount) {
        return IAccount(super._getDependencyAddress(Identifier.ACCOUNT));
    }

    function _getReservePool() internal view returns (IReservePool) {
        return IReservePool(super._getDependencyAddress(Identifier.RESERVE_POOL));
    }

    function _getEmiter() internal view returns (IEmiter) {
        return IEmiter(super._getDependencyAddress(Identifier.EMITER));
    }
}

