import { TransientMapLib } from "../../libraries/TransientMapLib.sol";
import { PoolId } from "../../types/Types.sol";

abstract contract TransientRewindPriceCache {
    using TransientMapLib for *;

    bytes32 private constant _REWIND_PRICE_NS = keccak256("rewind.price.transient.v1");
    bytes32 private constant _REWIND_PUBLISH_NS = keccak256("rewind.publishTime.transient.v1");

    /// @notice Cache rewind price for a pool within current transaction.
    function _setRewindPrice(PoolId poolId, uint256 rewindPrice, uint64 publishTime) internal {
        TransientMapLib.set(_REWIND_PRICE_NS, PoolId.unwrap(poolId), rewindPrice);
        TransientMapLib.set(_REWIND_PUBLISH_NS, PoolId.unwrap(poolId), uint256(publishTime));
    }

    function _getCachedRewindPrice(PoolId poolId) internal view returns (uint256 rewindPrice, uint64 publishTime) {
        rewindPrice = TransientMapLib.get(_REWIND_PRICE_NS, PoolId.unwrap(poolId));
        publishTime = uint64(TransientMapLib.get(_REWIND_PUBLISH_NS, PoolId.unwrap(poolId)));
    }
}

